        ["Buff_Content_100"] = {
            ["ContentFR"] = "Lorsqu’un ennemi de menace majeure tombe sous #1 de PV, il devient invincible pendant #2 s et appelle des renforts. Chaque ennemi vaincu confère à tous les alliés un bonus de #3 aux dégâts infligés, cumulable jusqu’à #4 fois. L’invincibilité prend fin prématurément après la défaite d’un certain nombre d’ennemis.",
            ["TextMapId"] = "Buff_Content_100",
            },
        ["Buff_Content_101"] = {
            ["ContentFR"] = "Les ennemis se voient attribuer l’Attribut élémentaire sélectionné. Les dégâts reçus provenant des attributs <H>avantagés</> sont augmentés de <H>400 %</>, tandis que ceux issus des attributs <W>désavantagés</> sont réduits de <W>50 %</>.",
            ["TextMapId"] = "Buff_Content_101",
            },
        ["Buff_Content_11111"] = {
            ["ContentFR"] = "Les ennemis subissent #1 de dégâts en moins. Chaque fois qu’ils reçoivent des dégâts d’une unité alliée différente de la précédente, cette réduction diminue de #2.",
            ["TextMapId"] = "Buff_Content_11111",
            },
        ["Buff_Content_11113"] = {
            ["ContentFR"] = "Lorsqu’un allié reçoit des soins d’un autre allié, il gagne 1 cumul de Vitesse d’attaque +#1 et de Vitesse de compétence +#2 pendant #3 s, cumulable jusqu’à #4 fois. À plein cumul, il devient immunisé aux interruptions.",
            ["TextMapId"] = "Buff_Content_11113",
            },
        ["Buff_Content_11121"] = {
            ["ContentFR"] = "Toutes les #1 de PV max perdus par un allié confèrent un cumul de Taux CRIT +#2 pendant #3 s, jusqu’à un maximum de #4 cumuls.",
            ["TextMapId"] = "Buff_Content_11121",
            },
        ["Buff_Content_11122"] = {
            ["ContentFR"] = "Les alliés infligent #1 de DGT d’arme en moins, mais leurs DGT CRIT augmentent de #2.",
            ["TextMapId"] = "Buff_Content_11122",
            },
        ["Buff_Content_11211"] = {
            ["ContentFR"] = "Lorsque le pourcentage de PV d’un allié est supérieur à #1, la Puissance de compétence augmente de #2 et il devient immunisé aux interruptions.",
            ["TextMapId"] = "Buff_Content_11211",
            },
        ["Buff_Content_11212"] = {
            ["ContentFR"] = "Les alliés infligent #1 de DGT CRIT en moins, mais leurs Dégâts sur la durée augmentent de #2.",
            ["TextMapId"] = "Buff_Content_11212",
            },
        ["Buff_Content_11221"] = {
            ["ContentFR"] = "Après chaque attaque de mêlée, un allié gagne un cumul de DGT d’arme +#1 pendant #2 s, jusqu’à un maximum de #3 cumuls. À plein cumul, il devient immunisé aux interruptions.",
            ["TextMapId"] = "Buff_Content_11221",
            },
        ["Buff_Content_11222"] = {
            ["ContentFR"] = "Les alliés infligent #1 de dégâts en moins, mais leur Taux CRIT augmente de #2.",
            ["TextMapId"] = "Buff_Content_11222",
            },
        ["Buff_Content_12111"] = {
            ["ContentFR"] = "Lorsqu’un allié utilise une Compétence de combat ou une Compétence ultime, il obtient #1 de Vigueur, pendant #2 s.",
            ["TextMapId"] = "Buff_Content_12111",
            },
        ["Buff_Content_12112"] = {
            ["ContentFR"] = "Les dégâts infligés par les alliés sont réduits de #1, mais leurs DGT d’arme sont augmentés de #2.",
            ["TextMapId"] = "Buff_Content_12112",
            },
        ["Buff_Content_12121"] = {
            ["ContentFR"] = "Lorsqu’un allié utilise une Compétence de combat ou une Compétence ultime, il obtient +#1 de Dégâts de compétence pendant #2 s, cumulable jusqu’à #3 fois. À plein cumul, il devient immunisé aux interruptions lorsqu’il subit des dégâts.",
            ["TextMapId"] = "Buff_Content_12121",
            },
        ["Buff_Content_12211"] = {
            ["ContentFR"] = "Lorsqu’un allié utilise une Compétence de combat ou une Compétence ultime, il confère à lui-même et à ses alliés +#1 de Puissance de compétence pendant #2 s. Les effets appliqués par des alliés différents peuvent se cumuler.",
            ["TextMapId"] = "Buff_Content_12211",
            },
        ["Buff_Content_12221"] = {
            ["ContentFR"] = "Toutes les #1 instances de dégâts infligées par un allié confèrent 1 cumul de +#2 de dégâts infligés pendant #3 s, cumulable jusqu’à #4 fois.",
            ["TextMapId"] = "Buff_Content_12221",
            },
        ["Buff_Content_201"] = {
            ["ContentFR"] = "Les ennemis subissent #1 de dégâts en moins, mais cette réduction diminue de #2 à chaque fois qu’ils reçoivent des dégâts.",
            ["TextMapId"] = "Buff_Content_201",
            },
        ["Buff_Content_202"] = {
            ["ContentFR"] = "Les ennemis subissent #1 de dégâts en moins. Chaque coup critique réduit cet effet de #2.",
            ["TextMapId"] = "Buff_Content_202",
            },
        ["Buff_Content_203"] = {
            ["ContentFR"] = "Les ennemis subissent #1 de dégâts en moins. Chaque fois qu’ils reçoivent des DGT d’arme à distance, cette réduction diminue de #2.",
            ["TextMapId"] = "Buff_Content_203",
            },
        ["Buff_Content_204"] = {
            ["ContentFR"] = "Les ennemis subissent #1 de dégâts en moins. Chaque fois qu’ils reçoivent des DGT d’arme, cette réduction diminue de #2.",
            ["TextMapId"] = "Buff_Content_204",
            },
        ["Buff_Content_205"] = {
            ["ContentFR"] = "Les ennemis subissent #1 de dégâts en moins. Chaque fois qu’ils reçoivent des DGT d’arme de mêlée, cette réduction diminue de #2.",
            ["TextMapId"] = "Buff_Content_205",
            },
        ["Buff_Content_206"] = {
            ["ContentFR"] = "Les ennemis subissent #1 de dégâts en moins. Chaque fois qu’ils reçoivent des Dégâts sur la durée réduit cet effet de #2.",
            ["TextMapId"] = "Buff_Content_206",
            },
        ["Buff_Content_207"] = {
            ["ContentFR"] = "Les ennemis subissent une réduction des dégâts de #1. Chaque fois qu’ils reçoivent des Dégâts de compétence, l’effet de réduction diminue de #2.",
            ["TextMapId"] = "Buff_Content_207",
            },
        ["Buff_Content_211"] = {
            ["ContentFR"] = "Les ennemis restaurent #1 de leur bouclier maximal toutes les 3 s. Cette régénération est interrompue lorsqu’un Effet supplémentaire élémentaire est actif.",
            ["TextMapId"] = "Buff_Content_211",
            },
        ["Buff_Content_30"] = {
            ["ContentFR"] = "Toutes les #1 attaques infligeant des dégâts par un allié confèrent un cumul de +#2 d’ATQ pendant #3 s, jusqu’à un maximum de #4 cumuls.",
            ["TextMapId"] = "Buff_Content_30",
            },
        ["Buff_Content_301"] = {
            ["ContentFR"] = "Tous les alliés gagnent 1 cumul de bonus de #2 à la Puissance de compétence toutes les #1 attaques, pendant #3 s, jusqu’à #4 cumuls.",
            ["TextMapId"] = "Buff_Content_301",
            },
        ["Buff_Content_302"] = {
            ["ContentFR"] = "Augmente les Dégâts infligés par les armes à distance de tous les alliés de #1.",
            ["TextMapId"] = "Buff_Content_302",
            },
        ["Buff_Content_303"] = {
            ["ContentFR"] = "Quand un allié inflige des DGT d’arme, le taux de critique de cette attaque augmente de #1 par Effet supplémentaire élémentaire présent sur la cible (jusqu’à 4 cumuls).",
            ["TextMapId"] = "Buff_Content_303",
            },
        ["Buff_Content_304"] = {
            ["ContentFR"] = "Pour chaque #1 points de Lucidité dépensés au total par les alliés, ceux-ci gagnent +#2 de Puissance de compétence pendant #3 s, cumulable jusqu’à #4 fois. À plein cumul, ils deviennent immunisés aux interruptions.",
            ["TextMapId"] = "Buff_Content_304",
            },
        ["Buff_Content_401"] = {
            ["ContentFR"] = "Tant qu’un Ordonnateur est présent, les ennemis proches subissent #1 de dégâts en moins.",
            ["TextMapId"] = "Buff_Content_401",
            },
        ["Buff_Content_402"] = {
            ["ContentFR"] = "Les ennemis subissent #1 de dégâts en moins provenant des armes de mêlée.",
            ["TextMapId"] = "Buff_Content_402",
            },
        ["Buff_Content_511"] = {
            ["ContentFR"] = "Les alliés infligent #1 de Dégâts sur la durée en moins, mais leurs DGT d’arme augmentent de #2.",
            ["TextMapId"] = "Buff_Content_511",
            },
        ["Buff_Content_512"] = {
            ["ContentFR"] = "Les alliés voient leurs DGT CRIT réduits de #1. Leurs Dégâts de compétence ont #2 de chances d’activer un Effet supplémentaire élémentaire.",
            ["TextMapId"] = "Buff_Content_512",
            },
        ["Buff_Content_905"] = {
            ["ContentFR"] = "Les dégâts subis par les ennemis lors d’un coup unique ne peuvent excéder #1 de leurs PV max.",
            ["TextMapId"] = "Buff_Content_905",
            },
        ["Buff_Content_920"] = {
