        ["Condition_Toast_PlayerLv_ModGuideBook_35"] = {
            ["ContentFR"] = "Se débloque au Niveau d’Aventure 35",
            ["TextMapId"] = "Condition_Toast_PlayerLv_ModGuideBook_35",
            },
        ["Condition_Toast_PlayerLv_ModGuideBook_40"] = {
            ["ContentFR"] = "Se débloque au Niveau d’Aventure 40",
            ["TextMapId"] = "Condition_Toast_PlayerLv_ModGuideBook_40",
            },
        ["Content_110101_1"] = {
            ["ContentFR"] = "Une voix vous appelle, lointaine et voilée, quelque part au-delà du sable...",
            ["TextMapId"] = "Content_110101_1",
            },
        ["Content_110101_2"] = {
            ["ContentFR"] = "Ne vous laissez pas tromper par cette voix étrangère. Avancez — quittez ce cauchemar.",
            ["TextMapId"] = "Content_110101_2",
            },
        ["Content_110102_1"] = {
            ["ContentFR"] = "Vous sortez en sursaut du cauchemar — face à vous, les crocs acérés d’un Souillé.",
            ["TextMapId"] = "Content_110102_1",
            },
        ["Content_110102_2"] = {
            ["ContentFR"] = "Votre escouade a été prise d’assaut par de puissants Souillés. Vainquez-les et rejoignez vos compagnons.",
            ["TextMapId"] = "Content_110102_2",
            },
        ["Content_110103_1"] = {
            ["ContentFR"] = "Vous avez éliminé les Souillés apparus soudainement, rétablissant un court répit. Rejoignez le poste de secours pour retrouver votre unité.",
            ["TextMapId"] = "Content_110103_1",
            },
        ["Content_110103_2"] = {
            ["ContentFR"] = "Votre escouade a subi de lourdes pertes. L’infirmière Daphne vous demande de soutenir les survivants tandis qu’elle s’apprête à chercher des fournitures médicales dans l’entrepôt.\
Par mesure de sécurité, vous décidez d’y aller à sa place.",
            ["TextMapId"] = "Content_110103_2",
            },
        ["Content_110103_3"] = {
            ["ContentFR"] = "Une horde de Souillés déferle depuis le couloir. Les blessés sont incapables de se battre : en tant que capitaine, vous êtes leur dernier rempart.\
Tenez la ligne et protégez-les.",
            ["TextMapId"] = "Content_110103_3",
            },
        ["Content_110103_3_2"] = {
            ["ContentFR"] = "Avar arrive en renfort et renverse le cours du combat. Profitez de cette occasion pour vaincre le chef des Souillés et mettre fin à la bataille !",
            ["TextMapId"] = "Content_110103_3_2",
            },
        ["Content_110103_4"] = {
            ["ContentFR"] = "Vous et Avar avez repoussé les Souillés. Revenez au poste de secours pour planifier la suite des opérations.",
            ["TextMapId"] = "Content_110103_4",
            },
        ["Content_110104_1"] = {
            ["ContentFR"] = "Avar ordonne à Daphne et aux blessés de rester en arrière, sous la protection de l’escouade des Loups Blancs.\
Quant à vous, vous l’accompagnez vers l’intérieur de la forteresse pour poursuivre la mission.",
            ["TextMapId"] = "Content_110104_1",
            },
        ["Content_110104_2"] = {
            ["ContentFR"] = "Après avoir analysé la situation, Avar conclut que les Déchus ont anticipé les mouvements de l’Empire.\
Pour renverser la situation, il décide de saboter le réservoir de Phoxichor dans la salle des machines afin de désactiver les mécanismes de la forteresse et faciliter le sauvetage des soldats piégés.",
            ["TextMapId"] = "Content_110104_2",
            },
        ["Content_110104_3"] = {
            ["ContentFR"] = "Après avoir analysé la situation, Avar conclut que les Déchus ont anticipé les mouvements de l’Empire.\
Pour renverser la situation, il décide de saboter le réservoir de Phoxichor dans la salle des machines afin de désactiver les mécanismes de la forteresse et faciliter le sauvetage des soldats piégés.",
            ["TextMapId"] = "Content_110104_3",
            },
        ["Content_110105_1"] = {
            ["ContentFR"] = "Vous retrouvez deux membres de l’escouade des Loups Blancs mais l’un d’eux, Vic, est piégé dans la salle des machines. Coopérez avec Avar pour couper l’alimentation et secourir votre camarade.",
            ["TextMapId"] = "Content_110105_1",
            },
        ["Content_110105_2"] = {
            ["ContentFR"] = "Vous avez atteint l’intérieur de la salle des machines. Coupez l’alimentation.",
            ["TextMapId"] = "Content_110105_2",
            },
        ["Content_110105_3"] = {
            ["ContentFR"] = "Vous avez coupé trois sources d’alimentation — mais une alarme retentit soudain depuis le réservoir de Phoxichor de la salle des machines...",
            ["TextMapId"] = "Content_110105_3",
            },
        ["Content_110105_4"] = {
            ["ContentFR"] = "Avar vous informe par radio que si la fermeture standard échoue, il est possible de provoquer une surcharge pour détruire totalement le réservoir.",
            ["TextMapId"] = "Content_110105_4",
            },
        ["Content_110106_1"] = {
            ["ContentFR"] = "Vic est tombé au combat. Le champ de bataille est impitoyable, mais la mission doit se poursuivre. Avec Avar, désactivez les dispositifs de la salle des machines, tout en restant vigilant face aux Souillés qui rôdent.",
            ["TextMapId"] = "Content_110106_1",
            },
        ["Content_110106_2"] = {
            ["ContentFR"] = "Vous avez détruit le noyau énergétique, mais cela a déclenché la séquence d’autodestruction du réservoir de Phoxichor. Le compte à rebours est lancé — fuyez la salle des machines avant qu’il ne soit trop tard !",
            ["TextMapId"] = "Content_110106_2",
            },
        ["Content_110106_3"] = {
            ["ContentFR"] = "Le commandant Fulvis ordonne de poursuivre l’assaut, mais au vu de la situation, une attaque frontale serait suicidaire.\
Faites confiance au jugement d’Avar : partez d’abord secourir vos alliés de l’escouade des Griffons.",
            ["TextMapId"] = "Content_110106_3",
            },
        ["Content_110106_4"] = {
            ["ContentFR"] = "Vous retrouvez Simon, encerclé par des Souillés. Éliminez-les avant qu’il ne soit trop tard.",
            ["TextMapId"] = "Content_110106_4",
            },
        ["Content_110106_5"] = {
            ["ContentFR"] = "Vous trouvez Simon encerclé par les Souillés — son état semble critique.",
            ["TextMapId"] = "Content_110106_5",
            },
        ["Content_110107_1"] = {
            ["ContentFR"] = "Vous arrivez trop tard — Simon n’a pas survécu. Ses derniers mots vous révèlent que d’autres camarades sont encore piégés dans la zone ferroviaire.\
Avancez, sauvez ceux qu’il reste à sauver.",
            ["TextMapId"] = "Content_110107_1",
            },
        ["Content_110107_2"] = {
            ["ContentFR"] = "Des Souillés surgissent sur la route ! Éliminez-les rapidement, ne perdez pas de temps.",
            ["TextMapId"] = "Content_110107_2",
            },
        ["Content_110107_3"] = {
            ["ContentFR"] = "Un bref contact radio avec Daphne vous rassure un instant. Continuez d’avancer.",
            ["TextMapId"] = "Content_110107_3",
            },
        ["Content_110108_1"] = {
            ["ContentFR"] = "La voix de Daphne au communicateur vous redonne courage. Avancez sans faiblir.",
            ["TextMapId"] = "Content_110108_1",
            },
        ["Content_110108_2"] = {
            ["ContentFR"] = "Vous entendez vos coéquipiers vous appeler, mais les Souillés bloquent la voie.\
Éliminez-les pour pouvoir les rejoindre au plus vite.",
            ["TextMapId"] = "Content_110108_2",
            },
        ["Content_110108_3"] = {
            ["ContentFR"] = "Les Souillés sont tombés. Rejoignez vos coéquipiers sans tarder.",
            ["TextMapId"] = "Content_110108_3",
            },
        ["Content_110108_4"] = {
            ["ContentFR"] = "Votre équipe rencontre deux Charons.\
La jeune femme affirme qu’ils ne sont que de simples villageois réduits en esclavage par les Déchus, tandis que l’aîné vous propose un raccourci.\
Bien que vous ne puissiez vérifier leurs dires, vous décidez de suivre les indications de l’homme avec prudence, espérant rejoindre Avar au plus vite.",
            ["TextMapId"] = "Content_110108_4",
            },
        ["Content_110108_6"] = {
            ["ContentFR"] = "Votre équipe rencontre deux Charons.\
La jeune femme affirme qu’ils ne sont que de simples villageois réduits en esclavage par les Déchus, tandis que l’aîné vous propose un raccourci.\
Bien que vous ne puissiez vérifier leurs dires, vous décidez de suivre les indications de l’homme avec prudence, espérant rejoindre Avar au plus vite.",
            ["TextMapId"] = "Content_110108_6",
            },
        ["Content_110109_1"] = {
            ["ContentFR"] = "Avar prévoit de faire sauter la porte de la salle de commande centrale à l’aide d’une tourelle. Comme l’alimentation de la salle des machines est coupée, vous devez réactiver le champ de bataille simulé via l’énergie d’urgence afin d’acheminer la tourelle jusqu’à la porte.",
            ["TextMapId"] = "Content_110109_1",
            },
        ["Content_110109_2"] = {
            ["ContentFR"] = "La tourelle se met en mouvement sur les rails. Protégez-la aux côtés d’Avar contre les Souillés jusqu’à ce qu’elle atteigne sa position.",
            ["TextMapId"] = "Content_110109_2",
            },
        ["Content_110109_2_1"] = {
            ["ContentFR"] = "Pour ouvrir la porte de la salle de commande centrale, vous devez déplacer la tourelle. Activez le mécanisme pour la faire glisser le long des rails.",
            ["TextMapId"] = "Content_110109_2_1",
            },
        ["Content_110109_3"] = {
            ["ContentFR"] = "Avar prévoit de faire sauter la porte de la salle de commande centrale à l’aide d’une tourelle. Comme l’alimentation de la salle des machines est coupée, vous devez réactiver le champ de bataille simulé via l’énergie d’urgence afin d’acheminer la tourelle jusqu’à la porte.",
            ["TextMapId"] = "Content_110109_3",
            },
        ["Content_110110_1"] = {
            ["ContentFR"] = "Utilisez la tourelle pour ouvrir la voie vers la salle de commande centrale.",
            ["TextMapId"] = "Content_110110_1",
            },
        ["Content_110110_2"] = {
            ["ContentFR"] = "Après le bombardement, la porte secondaire de la salle de commande centrale s’ouvre. Rejoignez Avar pour enquêter.",
            ["TextMapId"] = "Content_110110_2",
            },
        ["Content_110110_3"] = {
            ["ContentFR"] = "Katya tente soudain de vous poignarder dans le dos, mais Avar réagit à temps et déjoue sa manœuvre. Discutez avec lui de la situation.",
            ["TextMapId"] = "Content_110110_3",
            },
        ["Content_110110_4"] = {
            ["ContentFR"] = "Vous marquez une courte pause pour souffler.\
Pendant qu’Avar se repose, interrogez Katya pour découvrir les raisons de son attaque. Il semblerait aussi qu’Avar ait perdu une photo durant la lutte — peut-être pourriez-vous la retrouver.",
            ["TextMapId"] = "Content_110110_4",
            },
        ["Content_110110_5"] = {
            ["ContentFR"] = "Vous interrogez Katya, mais elle refuse obstinément de dire la vérité.\
Ses provocations font résonner cette voix familière dans votre tête... Vous peinez à garder le contrôle.\
Allez retrouver Avar pour décider de la suite.",
            ["TextMapId"] = "Content_110110_5",
            },
        ["Content_110110_6"] = {
            ["ContentFR"] = "Avar comptait affronter seul le danger dans la salle de commande, mais vos camarades refusent de le laisser partir seul.\
Sous votre insistance, il accepte finalement d’y aller avec vous.",
            ["TextMapId"] = "Content_110110_6",
            },
        ["Content_110110_7"] = {
            ["ContentFR"] = "Sur le chemin, un Souillé d’une puissance inouïe, surnommé le Maître de guerre, vous barre la route.\
Faites confiance à votre mentor — ensemble, vous le vaincrez.",
            ["TextMapId"] = "Content_110110_7",
            },
        ["Content_110110_8"] = {
            ["ContentFR"] = "Le monstre est tombé. Avancez vers la salle de commande centrale.",
            ["TextMapId"] = "Content_110110_8",
            },
        ["Content_110111_1"] = {
            ["ContentFR"] = "Vous atteignez la salle de commande centrale — vide. Ni ennemis, ni pièges.\
Inspectez les lieux et cherchez des indices.",
            ["TextMapId"] = "Content_110111_1",
            },
        ["Content_110111_2"] = {
            ["ContentFR"] = "Avar lève soudain son arme dans votre direction.",
            ["TextMapId"] = "Content_110111_2",
            },
        ["Content_110111_3"] = {
            ["ContentFR"] = "Vous reprenez connaissance. Vous êtes {性别:vivant|vivante}.\
Examinez les alentours et tentez de comprendre ce qui s’est passé.",
            ["TextMapId"] = "Content_110111_3",
            },
        ["Content_110111_4"] = {
            ["ContentFR"] = "Avar... ne respire plus.\
À la radio, la Légion annonce la mise en accusation de Daphne pour espionnage — une accusation que vous savez fausse.\
Fuyez la salle de contrôle et retrouvez-la au plus vite.",
            ["TextMapId"] = "Content_110111_4",
            },
        ["Content_110111_5"] = {
            ["ContentFR"] = "Vous retrouvez Daphne — mais, étrangement, elle vous met en joue.",
            ["TextMapId"] = "Content_110111_5",
            },
        ["Content_110111_6"] = {
            ["ContentFR"] = "Vous avez retrouvé Daphne. Malgré la panique, elle garde son calme et agit en professionnelle. La forteresse n’est plus sûre.\
Évadez-vous avec elle par les égouts.",
            ["TextMapId"] = "Content_110111_6",
            },
        ["Content_110111_7"] = {
            ["ContentFR"] = "Récupérer la clé",
            ["TextMapId"] = "Content_110111_7",
            },
        ["Content_110112_1"] = {
            ["ContentFR"] = "Le réseau d’égouts est un labyrinthe. Progressez prudemment et trouvez une issue.",
            ["TextMapId"] = "Content_110112_1",
            },
        ["Content_110112_2"] = {
            ["ContentFR"] = "L’ennemi tente de noyer les tunnels pour vous piéger. Activez les systèmes d’évacuation et continuez vers la sortie.",
            ["TextMapId"] = "Content_110112_2",
            },
        ["Content_110113_1"] = {
            ["ContentFR"] = "À la Forteresse de Lonza, vous et Daphne cherchez un espoir de survie en approchant la Commandante Sibylle. Mais vous êtes bientôt arrêtés et transférés à la Prison Militaire Royale d’Hyperborea, accusés d’espionnage.\
Pour protéger Daphne, et pour que la justice défendue par Avar ne s’éteigne pas, vous devez convaincre la Geôlière de votre innocence.",
            ["TextMapId"] = "Content_110113_1",
            },
        ["Content_110113_2"] = {
            ["ContentFR"] = "La Geôlière vous administre un sédatif étrange. Le monde se brouille... Vous vous réveillez dans un espace irréel, semblable à la Forteresse de Lonza.\
L’interrogatoire ne fait que commencer.",
            ["TextMapId"] = "Content_110113_2",
            },
        ["Content_110113_3"] = {
            ["ContentFR"] = "Affrontez les flammes de la Geôlière et prouvez votre innocence.",
            ["TextMapId"] = "Content_110113_3",
            },
        ["Content_110113_4"] = {
            ["ContentFR"] = "Vous racontez à la Geôlière ce qui s’est réellement passé dans la salle de commande : Avar a feint sa trahison pour protéger les preuves, au prix de sa vie. Mais ces preuves ont été emportées par Falsi, l’adjudante de Fulvis.\
Convaincu par votre récit, la Geôlière accepte d’enquêter plus avant.",
            ["TextMapId"] = "Content_110113_4",
            },
        ["Content_120001_1"] = {
            ["ContentFR"] = "L’affaire de la Traque aux Charons est close, et la paix est revenue. Il ne reste plus qu’à attendre, vingt jours durant, des nouvelles concernant le \"prisonnier d’importance\".\
En attendant, pourquoi ne pas passer aux Asphodèles pour voir si de nouvelles missions vous attendent ?",
            ["TextMapId"] = "Content_120001_1",
            },
        ["Content_120001_2"] = {
            ["ContentFR"] = "Le billet d’opéra offert par Camilla ravive en vous les souvenirs de la Traque aux Charons — un récit cruel et douloureux, auquel <I>Né du blizzard </>reste intimement lié.\
Puisque la pièce est rejouée, autant aller la voir.",
            ["TextMapId"] = "Content_120001_2",
            },
        ["Content_120001_3"] = {
            ["ContentFR"] = "Devant le Théâtre Galea, la foule se presse dans un brouhaha plein d’enthousiasme.\
Prenez un instant pour écouter ce que les spectateurs racontent.",
            ["TextMapId"] = "Content_120001_3",
            },
        ["Content_120001_4"] = {
            ["ContentFR"] = "L’heure d’ouverture approche. Rendez-vous sans tarder au contrôle d’entrée : manquer l’ouverture du spectacle serait bien dommage.",
            ["TextMapId"] = "Content_120001_4",
            },
        ["Content_120002_1"] = {
            ["ContentFR"] = "Le garçon à l’air d’un revendeur à la sauvette a échoué à écouler sa place ; dépité, il vous bouscule en partant. Oubliez cette altercation et rejoignez le contrôle d’entrée.",
            ["TextMapId"] = "Content_120002_1",
            },
        ["Content_120002_2"] = {
            ["ContentFR"] = "Malgré quelques contretemps, et grâce à l’intervention opportune d’une étrangère nommée Zhiliu, vous entrez dans la salle d’opéra... et même dans une loge de premier ordre, inaccessible au public ordinaire. Profitez du temps avant l’ouverture pour remercier votre bienfaitrice.",
            ["TextMapId"] = "Content_120002_2",
            },
        ["Content_120002_3"] = {
            ["ContentFR"] = "L’opéra va commencer. Asseyez-vous et laissez monter l’attente.",
            ["TextMapId"] = "Content_120002_3",
            },
        ["Content_120002_4"] = {
            ["ContentFR"] = "Même si la magie du spectacle résonne encore en vous, les lumières se rallument — l’enchantement touche à sa fin. Il est temps de suivre le mouvement et de sortir.",
            ["TextMapId"] = "Content_120002_4",
            },
        ["Content_120002_5"] = {
            ["ContentFR"] = "Au moment de quitter les lieux, un inconnu vous barre la route. Le contact que Zhiliu attendait depuis longtemps se présente enfin... mais ses intentions sont tout sauf bienveillantes. Restez sur vos gardes.",
            ["TextMapId"] = "Content_120002_5",
            },
        ["Content_120002_6"] = {
            ["ContentFR"] = "Zhiliu n’a aucun mal à remettre à leur place ces marchands clandestins qui voulaient la flouer.\
Apportez-lui le Phoxichor pour qu’elle puisse en vérifier l’authenticité.",
            ["TextMapId"] = "Content_120002_6",
            },
        ["Content_120002_7"] = {
            ["ContentFR"] = "Le tumulte s’apaise, et comme prévu, le Phoxichor apporté par les marchands clandestins n’était qu’une imitation. Mais cette étrange fumée attirée vers vous... que présage-t-elle ? Quoi qu’il en soit, il est temps de partir.",
            ["TextMapId"] = "Content_120002_7",
            },
        ["Content_120002_8"] = {
            ["ContentFR"] = "Vous alliez vous séparer de Zhiliu devant le théâtre... mais il se trouve qu’elle se rend elle aussi aux Asphodèles. Autant prolonger ce début d’amitié et lui montrer la route.",
            ["TextMapId"] = "Content_120002_8",
            },
        ["Content_120002_9"] = {
            ["ContentFR"] = "Quelle journée mouvementée... Retournez voir Camilla aux Asphodèles : vous avez sans doute plus à lui raconter que prévu.",
            ["TextMapId"] = "Content_120002_9",
            },
        ["Content_120003_1"] = {
            ["ContentFR"] = "Une nouvelle journée commence. Comme toujours, passez par les Asphodèles pour découvrir ce que le jour apporte de neuf.",
            ["TextMapId"] = "Content_120003_1",
            },
        ["Content_120003_2"] = {
            ["ContentFR"] = "Le calme se brise soudain sous l’effet d’un message étrange. Est-ce le signe que Berry essaie d’entrer en contact... ou un piège tendu par quelqu’un d’autre ?\
Afin de ne pas mêler Snow à cette affaire, vous trouvez un prétexte pour vous éclipser discrètement. Retournez au Sanctuaire et attendez la tombée de la nuit.",
            ["TextMapId"] = "Content_120003_2",
            },
        ["Content_120003_3"] = {
            ["ContentFR"] = "Si ce message vient vraiment de Berry, vous devez le vérifier — et s’il est faux, il est encore plus urgent de le découvrir. Une fois la nuit installée, dirigez-vous vers la cabine téléphonique rouge indiquée dans le message.",
            ["TextMapId"] = "Content_120003_3",
            },
        ["Content_120003_4"] = {
            ["ContentFR"] = "À peine sorti du Sanctuaire, vous croisez Snow — qui avait déjà deviné vos intentions. Déterminée à affronter les risques à vos côtés, elle part avec vous, sans hésitation.",
            ["TextMapId"] = "Content_120003_4",
            },
        ["Content_120003_5"] = {
            ["ContentFR"] = "Cette silhouette blanche... serait-ce Berry ? Celle que vous cherchez depuis tant de nuits semble à portée de main. Avancez prudemment pour en avoir le cœur net.",
            ["TextMapId"] = "Content_120003_5",
            },
        ["Content_120003_6"] = {
            ["ContentFR"] = "Comme vous le redoutiez, la femme près de la cabine n’était qu’un leurre posé par la Légion — mais vous étiez préparé, et Snow également.\
Discutez ensemble de la suite à donner à cette découverte.",
            ["TextMapId"] = "Content_120003_6",
            },
        ["Content_120003_7"] = {
            ["ContentFR"] = "Même si vous avez évité le pire, la Légion a remarqué votre présence et renforcé les patrouilles. Il faut filer avant d’être repéré. Avancez discrètement et échappez à la zone.",
            ["TextMapId"] = "Content_120003_7",
            },
        ["Content_120003_8"] = {
            ["ContentFR"] = "Zhiliu apparaît au moment le plus critique, vous offrant une échappatoire inespérée.\
Montez à ses côtés dans la petite automobile et quittez les lieux sans tarder.",
            ["TextMapId"] = "Content_120003_8",
            },
        ["Content_120003_9"] = {
            ["ContentFR"] = "Voici votre dernier obstacle pour fuir Givrelac cette nuit. Traversez la porte de la cité sans éveiller les soupçons des gardes et franchissez la frontière.",
            ["TextMapId"] = "Content_120003_9",
            },
        ["Content_120101_1"] = {
            ["ContentFR"] = "Après une longue traversée, vous accostez enfin sur les rivages de Huaxu.\
Le paysage paisible qui s’étend à perte de vue vous rappelle que vous êtes bien loin de chez vous.\
Discutez avec Zhiliu pour en apprendre davantage sur ce royaume.",
            ["TextMapId"] = "Content_120101_1",
            },
        ["Content_120101_10"] = {
            ["ContentFR"] = "Après avoir découvert les Neuf Chapitres, vous avez franchi la première étape de votre intégration à Huaxu.\
Suivez Luno, la carpe, jusqu’à la guilde marchande Éternel Printemps pour retrouver Zhiliu.",
            ["TextMapId"] = "Content_120101_10",
            },
        ["Content_120101_11"] = {
            ["ContentFR"] = "En route, le sol se met soudain à trembler. Un Exécuteur rencontré plus tôt vous attaque sans raison apparente. Sa silhouette, altérée, diffère de celle des Bi’an ordinaires. Grâce à l’aide d’une marchande itinérante, vous parvenez à le neutraliser.\
Discutez avec elle pour comprendre ce qu’il s’est passé.",
            ["TextMapId"] = "Content_120101_11",
            },
        ["Content_120101_12"] = {
            ["ContentFR"] = "D’après Yusheng, la protection qui vous a {性别:sauvé|sauvée} serait liée à une substance appelée Encens, que l’on peut raviver au Temple du Dragon d’Argent, près d’Éternel Printemps.\
Rejoignez Luno, la carpe, et rendez-vous à la guilde pour retrouver Zhiliu.",
            ["TextMapId"] = "Content_120101_12",
            },
        ["Content_120101_13"] = {
            ["ContentFR"] = "En route, le sol se met soudain à trembler. Un Exécuteur rencontré plus tôt vous attaque sans raison apparente. Sa silhouette, altérée, diffère de celle des Bi’an ordinaires.\
Vous n’avez pas le temps de réfléchir : il vous faut répondre à l’attaque dans la précipitation.",
            ["TextMapId"] = "Content_120101_13",
            },
        ["Content_120101_2"] = {
            ["ContentFR"] = "À peine le navire a-t-il accosté qu’une voix appelle Zhiliu depuis le quai.\
Descendez pour voir de quoi il s’agit.",
            ["TextMapId"] = "Content_120101_2",
            },
        ["Content_120101_3"] = {
            ["ContentFR"] = "À Huaxu, tout semble nouveau, étrangement vivant. Les quais résonnent de cris de marchands et de voyageurs.\
Prenez un moment pour explorer les environs avant de poursuivre.",
            ["TextMapId"] = "Content_120101_3",
            },
        ["Content_120101_4"] = {
            ["ContentFR"] = "À Huaxu, tout semble nouveau, étrangement vivant. Les quais résonnent de cris de marchands et de voyageurs.\
Prenez un moment pour explorer les environs avant de poursuivre.",
            ["TextMapId"] = "Content_120101_4",
            },
        ["Content_120101_5"] = {
            ["ContentFR"] = "Snow a disparu l’espace d’un instant — partez vite à sa recherche !",
            ["TextMapId"] = "Content_120101_5",
            },
        ["Content_120101_6"] = {
            ["ContentFR"] = "Vous arrivez juste à temps pour interrompre les vantardises de Snow devant Luno, la carpe.\
Le Roi Démon s’est visiblement trouvé une admiratrice, et son ego frôle déjà les nuages. Rattrapez-la avant qu’elle ne s’envole et rejoignez Zhiliu.",
            ["TextMapId"] = "Content_120101_6",
            },
        ["Content_120101_7"] = {
            ["ContentFR"] = "Alors que tout semblait paisible à Huaxu, un tumulte éclate sur les quais.\
Une tentative de vol, vite réprimée par l’apparition soudaine d’un Bi’an, bête divine des vents. Zhiliu vous explique que le royaume vit sous la protection des Neuf Chapitres de Dafeng, où le crime est depuis longtemps éradiqué.\
Mais à peine a-t-elle fini qu’un de ses agents accourt, essoufflé.\
Pourquoi un criminel se risquerait-il ici ? Allez le découvrir.",
            ["TextMapId"] = "Content_120101_7",
            },
        ["Content_120101_8"] = {
            ["ContentFR"] = "Rappelée à ses obligations, Zhiliu doit partir précipitamment.\
Avant de s’éloigner, elle vous avertit : quiconque entre dans le royaume de Huaxu doit respecter les Neuf Chapitres de Dafeng.\
Pour faire preuve de civisme, suivez Luno, la carpe, jusqu’à la stèle des préceptes.",
            ["TextMapId"] = "Content_120101_8",
            },
        ["Content_120101_9"] = {
            ["ContentFR"] = "Tandis que Luno, la carpe, vous expose les Neuf Chapitres de Dafeng, une vibration subtile résonne dans votre esprit... comme si la stèle cherchait à vous parler.",
            ["TextMapId"] = "Content_120101_9",
            },
        ["Content_120102_1"] = {
            ["ContentFR"] = "Après avoir pris congé de Luno, la carpe, votre destination se trouve au sommet des marches d’Éternel Printemps. Rejoignez Zhiliu et prenez connaissance des détails de la mission.",
            ["TextMapId"] = "Content_120102_1",
            },
        ["Content_120102_10"] = {
            ["ContentFR"] = "Sans doute épuisé jusqu’à la moelle, Yuming s’endort en plein milieu de votre conversation. Trouvez un endroit sûr où l’installer pour qu’il puisse se reposer.",
            ["TextMapId"] = "Content_120102_10",
            },
        ["Content_120102_11"] = {
            ["ContentFR"] = "Cet intermède inattendu touche à sa fin. Quittez le Chant-des-Marées et poursuivez votre route vers votre destination initiale.",
            ["TextMapId"] = "Content_120102_11",
            },
        ["Content_120102_14"] = {
            ["ContentFR"] = "Lorsque vous arrivez sur place, le Magistrat de Yingtian peine à contenir une meute de Bi’an obscurs, nettement supérieure en nombre.\
Rejoignez le combat et renversez la situation.",
            ["TextMapId"] = "Content_120102_14",
            },
        ["Content_120102_1_1"] = {
            ["ContentFR"] = "/",
            ["TextMapId"] = "Content_120102_1_1",
            },
        ["Content_120102_1_2"] = {
            ["ContentFR"] = "/",
            ["TextMapId"] = "Content_120102_1_2",
            },
        ["Content_120102_1_3"] = {
            ["ContentFR"] = "Après avoir pris congé de Luno, la carpe, votre destination se trouve au sommet des marches d’Éternel Printemps. Rejoignez Zhiliu et prenez connaissance des détails de la mission.",
            ["TextMapId"] = "Content_120102_1_3",
            },
        ["Content_120102_2"] = {
            ["ContentFR"] = "Vous arrivez juste à temps pour assister à la façon dont Zhiliu désamorce, avec une autorité foudroyante, un conflit entre Tisse-Étoiles. À les entendre, la menace du Fléau de Zhuyin ne souffre plus aucun délai.\
Rejoignez Zhiliu et discutez avec elle des détails de la mission.",
            ["TextMapId"] = "Content_120102_2",
            },
        ["Content_120102_3"] = {
            ["ContentFR"] = "Zhiliu vous confie une tâche précise : vous rendre dans la Mer de Poussière pour y recueillir trois Écailles de Zhuyin, première étape pour contenir le Fléau.\
Remplir une mission fait partie des devoirs d’un bon Chasseur de Phoxène — surtout lorsque l’employeuse se montre aussi généreuse.",
            ["TextMapId"] = "Content_120102_3",
            },
        ["Content_120102_3_1"] = {
            ["ContentFR"] = "/",
            ["TextMapId"] = "Content_120102_3_1",
            },
        ["Content_120102_4"] = {
            ["ContentFR"] = "Selon les instructions de Zhiliu, vous devez d’abord emprunter le Chant-des-Marées afin de rejoindre le marché noir, où vous attend un outil spécialement conçu pour extraire les Écailles de Zhuyin.",
            ["TextMapId"] = "Content_120102_4",
            },
        ["Content_120102_5"] = {
            ["ContentFR"] = "Selon les instructions de Zhiliu, vous devez d’abord traverser le Chant-des-Marées pour gagner le marché noir, où vous attend un outil spécialement conçu pour extraire les Écailles de Zhuyin.\
Le murmure de l’eau résonnant dans cette grotte obscure vous arrache une pensée fugace : pourquoi tant d’aventures commencent-elles dans des cavernes ?\
Mais ce n’est pas le moment de rêvasser. Ici aussi, des Bi’an obscurs ont pris possession des lieux. Chassez-les.",
            ["TextMapId"] = "Content_120102_5",
            },
        ["Content_120102_6"] = {
            ["ContentFR"] = "Le Magistrat de Yingtian surgit au dernier moment et intercepte l’assaut des Bi’an obscurs. Le malentendu dissipé, il propose de vous escorter jusqu’à la sortie de la caverne.",
            ["TextMapId"] = "Content_120102_6",
            },
        ["Content_120102_7"] = {
            ["ContentFR"] = "Après vous avoir accompagnés jusqu’à la sortie, le Magistrat de Yingtian repart seul.\
Votre destination se trouve droit devant, mais les bruits inquiétants qui résonnent derrière vous ne vous laissent pas en paix.\
Vous le connaissez à peine, mais il vous a prêté main-forte. Allez vérifier s’il va bien.",
            ["TextMapId"] = "Content_120102_7",
            },
        ["Content_120102_8"] = {
            ["ContentFR"] = "Lorsque vous arrivez sur place, le Magistrat de Yingtian peine à contenir une meute de Bi’an obscurs, nettement supérieure en nombre.\
Rejoignez le combat et renversez la situation.",
            ["TextMapId"] = "Content_120102_8",
            },
        ["Content_120102_9"] = {
            ["ContentFR"] = "Après un rude affrontement, vous finissez par éliminer le dernier Bi’an obscur qui hantait ces lieux.\
Le Magistrat de Yingtian semble gravement blessé. Allez lui parler.",
            ["TextMapId"] = "Content_120102_9",
            },
        ["Content_120103_1"] = {
            ["ContentFR"] = "Comme Zhiliu vous l’a expliqué, ceux qui se rendent pour la première fois au marché noir doivent en sortir par une grotte côtière, un pendentif bien en vue à la ceinture, afin de répondre au \"mot de passe\".",
            ["TextMapId"] = "Content_120103_1",
            },
        ["Content_120103_10"] = {
            ["ContentFR"] = "Alors que vous cueillez les Écailles de Zhuyin, une voix lointaine semble vous appeler. Une vision d’Éternel Printemps en proie aux flammes s’impose brutalement à votre esprit. Vous le sentez : ce n’est pas un simple cauchemar, mais une prophétie.\
Dépêchez-vous de retourner voir ce qui se passe à Éternel Printemps.",
            ["TextMapId"] = "Content_120103_10",
            },
        ["Content_120103_11_1"] = {
            ["ContentFR"] = "Vos craintes se sont révélées fondées. Heureusement, les gens d’Éternel Printemps se sont déjà organisés : armes en main, prêts à défendre leur foyer.\
La situation reste contenue — trouvez Zhiliu et voyez comment lui prêter main-forte.",
            ["TextMapId"] = "Content_120103_11_1",
            },
        ["Content_120103_11_2"] = {
            ["ContentFR"] = "Rejoignez les habitants d’Éternel Printemps et repoussez le Bi’an obscur.",
            ["TextMapId"] = "Content_120103_11_2",
            },
        ["Content_120103_11_3"] = {
            ["ContentFR"] = "Vous assistez à la manière sèche dont Zhiliu renvoie un homme récalcitrant — un geste pour ramener le calme. Elle vous envoie soutenir le front devant le Temple du Dragon d’Argent.\
Tenez bon encore un instant : l’Officiant de l’Encens pourra alors dissiper la menace.",
            ["TextMapId"] = "Content_120103_11_3",
            },
        ["Content_120103_12"] = {
            ["ContentFR"] = "Les préparatifs sont achevés. La silhouette radieuse de Taihao descend, balayant toute malveillance. Le danger est écarté — retournez rendre compte à Zhiliu.",
            ["TextMapId"] = "Content_120103_12",
            },
        ["Content_120103_13"] = {
            ["ContentFR"] = "Vous confiez les Écailles de Zhuyin à Zhiliu. Mais lorsqu’à demi-mot vous mentionnez l’avertissement entendu plus tôt, son attitude se ferme soudain — est-ce votre imagination ? Plus aucune tâche pour l’instant : quittez Éternel Printemps.",
            ["TextMapId"] = "Content_120103_13",
            },
        ["Content_120103_14_1"] = {
            ["ContentFR"] = "Se rendre au Pavillon de l’Éphémère",
            ["TextMapId"] = "Content_120103_14_1",
            },
        ["Content_120103_14_2"] = {
            ["ContentFR"] = "Parler à Maître Qiu",
            ["TextMapId"] = "Content_120103_14_2",
            },
        ["Content_120103_2"] = {
            ["ContentFR"] = "Comme Zhiliu vous l’a expliqué, ceux qui se rendent pour la première fois au marché noir doivent en sortir par une grotte côtière, un pendentif bien en vue à la ceinture, afin de répondre au \"mot de passe\".\
Un marchand du marché noir vous attend un peu plus loin. Allez lui parler.",
            ["TextMapId"] = "Content_120103_2",
            },
        ["Content_120103_3"] = {
            ["ContentFR"] = "Vous avez égaré le pendentif sans même vous en apercevoir, et la prise de contact avec le marchand tombe à l’eau.\
Alors que vous cherchez une solution, des éclats de voix retentissent au loin. Autant aller voir ce qui se passe.",
            ["TextMapId"] = "Content_120103_3",
            },
        ["Content_120103_4"] = {
            ["ContentFR"] = "En écoutant leur dispute, vous comprenez que le marchand du marché noir a exploité une faille dans les Neuf Chapitres de Dafeng pour dépouiller une jeune fille des biens de sa famille. À présent, il a même lâché un Bi’an sur elle, sous prétexte de \"punition\". Sans votre intervention, l’affaire aurait pu tourner bien plus mal.\
Allez maintenant examiner les blessures de la jeune fille.",
            ["TextMapId"] = "Content_120103_4",
            },
        ["Content_120103_5"] = {
            ["ContentFR"] = "Alors que la tension atteint son comble, un inconnu intervient et met fin à la scène. Il vous traite en invité de marque et vous informe que son maître, Maître Qiu, souhaite vous recevoir.",
            ["TextMapId"] = "Content_120103_5",
            },
        ["Content_120103_5_1"] = {
            ["ContentFR"] = "Votre entretien avec le maître du marché noir n’a rien eu d’agréable. Il vous a pourtant remis les outils destinés à récolter les Écailles de Zhuyin.\
Sans envie de vous attarder ici, vous prenez aussitôt la route.",
            ["TextMapId"] = "Content_120103_5_1",
            },
        ["Content_120103_6"] = {
            ["ContentFR"] = "Inquiet pour la jeune fille blessée, vous décidez de retourner voir comment elle se porte — et si le marchand du marché noir a tenu ses promesses.",
            ["TextMapId"] = "Content_120103_6",
            },
        ["Content_120103_7"] = {
            ["ContentFR"] = "Une femme aux cheveux blancs surgit soudain, apaise les blessures de la jeune fille grâce à un art mystérieux... et dissipe au passage une bonne partie de votre fatigue.\
Qui est donc cette guérisseuse énigmatique ? Parlez-lui.",
            ["TextMapId"] = "Content_120103_7",
            },
        ["Content_120103_8"] = {
            ["ContentFR"] = "Après avoir convenu d’aller rendre visite à la malade au Pavillon de l’Éphémère, vous prenez congé de Fushu.\
Il est temps de vous concentrer sur la tâche du moment : vous rendre à l’entrée de la Mer de Poussière pour y rencontrer Maître Gongshang et apprendre à manier l’outil.",
            ["TextMapId"] = "Content_120103_8",
            },
        ["Content_120103_8_1"] = {
            ["ContentFR"] = "Après un quiproquo inattendu autour de votre apprentissage, Maître Gongshang reprend ses esprits et entreprend de vous enseigner l’usage du Nexus mécanique.\
Parlez à Maître Gongshang et écoutez attentivement ses explications.",
            ["TextMapId"] = "Content_120103_8_1",
            },
        ["Content_120103_8_2"] = {
            ["ContentFR"] = "Après un quiproquo inattendu autour de votre apprentissage, Maître Gongshang reprend ses esprits et entreprend de vous enseigner l’usage du Nexus mécanique.\
Essayez d’utiliser le Nexus mécanique pour absorber la Rune de Taixu désignée.",
            ["TextMapId"] = "Content_120103_8_2",
            },
        ["Content_120103_8_3"] = {
            ["ContentFR"] = "Après un quiproquo inattendu autour de votre apprentissage, Maître Gongshang reprend ses esprits et entreprend de vous enseigner l’usage du Nexus mécanique.\
Essayez d’utiliser le Nexus mécanique pour absorber la Poussière-corrompue.",
            ["TextMapId"] = "Content_120103_8_3",
            },
        ["Content_120103_8_4"] = {
            ["ContentFR"] = "Après un quiproquo inattendu autour de votre apprentissage, Maître Gongshang reprend ses esprits et entreprend de vous enseigner l’usage du Nexus mécanique.\
Utilisez le Nexus mécanique pour déverrouiller le mécanisme devant vous.",
            ["TextMapId"] = "Content_120103_8_4",
            },
        ["Content_120103_8_5"] = {
            ["ContentFR"] = "Après un quiproquo inattendu autour de votre apprentissage, Maître Gongshang reprend ses esprits et entreprend de vous enseigner l’usage du Nexus mécanique.\
Vous avez brillamment achevé l’ensemble de l’enseignement. À présent, Maître Gongshang souhaite vous adresser quelques mots.",
            ["TextMapId"] = "Content_120103_8_5",
            },
        ["Content_120103_9"] = {
            ["ContentFR"] = "Après un quiproquo digne d’une comédie — Maître Gongshang vous ayant pris pour des apprentis potentiels — vous maîtrisez désormais l’usage du Nexus mécanique, capable d’absorber la Poussière-corrompue. Vous recevez même le titre d’apprentis d’honneur de la Secte Jishu.\
Rendez-vous à présent sur les hauteurs de la Mer de Poussière et récoltez les trois Écailles de Zhuyin réclamées par Zhiliu.",
            ["TextMapId"] = "Content_120103_9",
            },
        ["Content_120104_1"] = {
            ["ContentFR"] = "Par l’intermédiaire de Zhiliu, Fushu vous fait savoir que l’état de la jeune fille sauvée au marché noir s’est aggravé.\
Rendez-vous au Pavillon de l’Éphémère pour voir comment elle va.",
            ["TextMapId"] = "Content_120104_1",
            },
        ["Content_120104_10"] = {
            ["ContentFR"] = "Le dernier, espiègle, refuse obstinément de vous suivre tant que vous n’aurez pas résolu l’énigme qu’il vous propose.",
            ["TextMapId"] = "Content_120104_10",
            },
        ["Content_120104_11"] = {
            ["ContentFR"] = "Le jeune Wishen, après s’être suffisamment amusé, consent à rentrer. Ramenez-le à l’autel.",
            ["TextMapId"] = "Content_120104_11",
            },
        ["Content_120104_12"] = {
            ["ContentFR"] = "Grâce aux trois jeunes Wishen, vous atteignez la véritable Source de Yu — un lieu où ce monde et l’autre se frôlent.\
Demandez à l’Aîné Wishen où pousse l’Herbe de l’Oubli.",
            ["TextMapId"] = "Content_120104_12",
            },
        ["Content_120104_13"] = {
            ["ContentFR"] = "Vous apprenez que l’Herbe de l’Oubli pousse près d’une cascade, derrière le massif.\
La Poussière-corrompue a gagné cette région, et certains Wishen y ont disparu. L’Ainé vous demande d’enquêter au passage.",
            ["TextMapId"] = "Content_120104_13",
            },
        ["Content_120104_14"] = {
            ["ContentFR"] = "Vous avez trouvé l’herbe nécessaire pour soigner la jeune fille. Cueillez-la.",
            ["TextMapId"] = "Content_120104_14",
            },
        ["Content_120104_15"] = {
            ["ContentFR"] = "Pendant que vous cueillez l’Herbe de l’Oubli, Snow vous appelle d’un geste. Qu’a-t-elle donc découvert ?",
            ["TextMapId"] = "Content_120104_15",
            },
        ["Content_120104_17"] = {
            ["ContentFR"] = "Avec l’aide de Fushu, vous êtes parvenu à sortir de la Faille de l’Oubli — ce lieu où se mêlent souvenirs et passé jusqu’à tout effacer. Dehors, Snow, qui vous attendait, était à deux doigts de fondre en larmes. Rassurez-la.",
            ["TextMapId"] = "Content_120104_17",
            },
        ["Content_120104_2"] = {
            ["ContentFR"] = "En suivant le sentier de montagne, vous finissez par apercevoir le Pavillon de l’Éphémère, niché au cœur d’un bosquet d’abricotiers.\
L’endroit est silencieux, désert ; vos appels restent sans réponse. Fushu est-elle vraiment ici ? Vous et Snow décidez de pénétrer à l’intérieur pour en avoir le cœur net.",
            ["TextMapId"] = "Content_120104_2",
            },
        ["Content_120104_20"] = {
            ["ContentFR"] = "Attiré par un appel à l’aide venu d’un recoin obscur, vous avez basculé dans la Faille de l’Oubli — un lieu sans lumière où tout finit par se dissoudre dans l’oubli.\
Vous devez absolument en sortir avant que le visage de ceux qui vous sont chers ne s’efface de votre mémoire.",
            ["TextMapId"] = "Content_120104_20",
            },
        ["Content_120104_3"] = {
            ["ContentFR"] = "En suivant le sentier de montagne, vous finissez par apercevoir le Pavillon de l’Éphémère, niché au cœur d’un bosquet d’abricotiers.\
L’endroit est silencieux, désert ; vos appels restent sans réponse. Fushu est-elle vraiment ici ? Cherchez-la.",
            ["TextMapId"] = "Content_120104_3",
            },
        ["Content_120104_4"] = {
            ["ContentFR"] = "La jeune fille ne s’est toujours pas réveillée depuis l’attaque du Bi’an. Fushu a veillé toute la nuit à son chevet, avant de finir par s’assoupir près du lit.\
Après avoir réfléchi avec elle aux solutions possibles, vous décidez de vous rendre en un lieu mystérieux nommé la Source de Yu, pour y cueillir une herbe médicinale appelée Herbe de l’Oubli, capable de soigner ses blessures.",
            ["TextMapId"] = "Content_120104_4",
            },
        ["Content_120104_5"] = {
            ["ContentFR"] = "La Source de Yu souffre elle aussi de la calamité de la Poussière-corrompue. Utilisez la méthode transmise par Maître Gongshang pour purifier la zone.",
            ["TextMapId"] = "Content_120104_5",
            },
        ["Content_120104_6"] = {
            ["ContentFR"] = "Vous avez libéré un jeune Wishen prisonnier de la Poussière-corrompue. Ramenez-le jusqu’à l’autel.",
            ["TextMapId"] = "Content_120104_6",
            },
        ["Content_120104_7"] = {
            ["ContentFR"] = "Sous l’effet de la Poussière-corrompue, les deux autres Wishen qui auraient dû veiller près de l’autel ont eux aussi disparu. Partez à leur recherche.",
            ["TextMapId"] = "Content_120104_7",
            },
        ["Content_120104_8"] = {
            ["ContentFR"] = "Dans une grotte, vous tombez sur un jeune Wishen terrorisé. Des Souillés obstruent le passage. Éliminez-les et ramenez la petite créature saine et sauve jusqu’à l’autel.",
            ["TextMapId"] = "Content_120104_8",
            },
        ["Content_120104_9"] = {
            ["ContentFR"] = "Deux jeunes Wishen ont retrouvé le chemin de l’autel. Il ne vous reste plus qu’à dénicher le dernier.",
            ["TextMapId"] = "Content_120104_9",
            },
        ["Content_120105_1"] = {
            ["ContentFR"] = "Un homme de main de Maître Qiu vous interpelle aux abords d’Éternel Printemps.\
Il vous invite à prendre part à une « grande battue », un acte de « justice », selon lui.\
Ce chef lunatique du marché noir a sûrement une idée derrière la tête... mais la récompense proposée est difficile à refuser.\
Rendez-vous à la Demeure du Dragon Caché pour en apprendre davantage.",
            ["TextMapId"] = "Content_120105_1",
            },
        ["Content_120105_14"] = {
            ["ContentFR"] = "Alarmée par votre présence, la « proie » déclenche la majestueuse Formation des Mille-Serrures, surgissant des entrailles de la terre dans un fracas titanesque. Il vous faut du temps et des efforts pour en sortir et regagner l’intérieur de la Plaine des Corbeaux.\
Puis la vérité éclate : la « proie » n’est autre que Yuming, que vous aviez croisé autrefois. Maître Qiu vous a {性别:trompé|trompée} une fois de plus.\
Comme vous refusez de poursuivre sa mascarade, il invoque les Neuf Chapitres de Dafeng, forçant Yuming à lever la main contre vous.\
Résistez à son assaut : protégez-vous, ne vous laissez pas blesser.",
            ["TextMapId"] = "Content_120105_14",
            },
        ["Content_120105_15"] = {
            ["ContentFR"] = "En plein affrontement, Yuming parvient à retenir son attaque — au prix d’aggraver ses blessures en luttant contre l’ordre imposé par les Neuf Chapitres.\
C’est alors qu’un visiteur inattendu surgit : Kezhou, le vagabond que vous aviez rencontré dans la Formation des Mille-Serrures. Il est venu chercher son frère aîné d’armes... Yuming.\
\
Mais ce dernier, comme fuyant une vérité trop lourde, profite d’une brève ouverture pour s’échapper. Le combat s’achève, mais il reste à demander des comptes à Maître Qiu. Allez leur parler.",
            ["TextMapId"] = "Content_120105_15",
            },
        ["Content_120105_16"] = {
            ["ContentFR"] = "Maître Qiu s’éclipse après vous avoir glissé une recommandation énigmatique.\
Kezhou, lui, semble étrangement abattu.\
Parlez-lui.",
            ["TextMapId"] = "Content_120105_16",
            },
        ["Content_120105_2"] = {
            ["ContentFR"] = "« Chaque instant compte », affirme Maître Qiu en vous pressant de partir.\
Il dévoilera les détails de la mission en chemin vers la Plaine des Corbeaux.",
            ["TextMapId"] = "Content_120105_2",
            },
        ["Content_120105_20"] = {
            ["ContentFR"] = "Alertée par sa proie, la grandiose Formation des Mille-Serrures jaillit du sol dans un fracas assourdissant. Vous voilà pris au piège d’un antique dispositif mécanique. Trouvez au plus vite une issue.",
            ["TextMapId"] = "Content_120105_20",
            },
        ["Content_120105_3"] = {
            ["ContentFR"] = "D’après Maître Qiu, l’objectif serait de capturer un Bi’an afin d’enrichir sa collection.\
La bête a déjà été acculée au cœur de la Plaine des Corbeaux... mais les vestiges d’anciens mécanismes de guerre pourraient bouleverser la traque.\
Restez {性别:vigilant|vigilante} et pénétrez dans la plaine.",
            ["TextMapId"] = "Content_120105_3",
            },
        ["Content_120106_1"] = {
            ["ContentFR"] = "Un moment s’est écoulé depuis que vous avez remis les Écailles de Zhuyin.\
Vous vous demandez où en sont les préparatifs de Zhiliu.\
Retournez à l’Éternel Printemps et voyez si vous pouvez lui prêter main-forte.",
            ["TextMapId"] = "Content_120106_1",
            },
        ["Content_120106_2"] = {
            ["ContentFR"] = "D’étranges grondements résonnent depuis l’Autel de Zhuyin.\
Selon Wangchun, Zhiliu a déjà commencé le rituel de scellement.\
Vous décidez de vous rendre sur place : en ces temps critiques, chaque aide compte.",
            ["TextMapId"] = "Content_120106_2",
            },
        ["Content_120106_3"] = {
            ["ContentFR"] = "Vous arrivez juste au moment où Zhuyin est scellé de justesse. Une portion du sceau demeure instable, et Zhiliu ne peut quitter son poste.\
Vous vous portez volontaire pour aller vérifier et consolider la barrière.",
            ["TextMapId"] = "Content_120106_3",
            },
        ["Content_120106_6"] = {
            ["ContentFR"] = "À mesure que vous approchez, un gémissement diffus semble jaillir du cœur même de Zhuyin. Le sceau cède — et la créature se libère. Dans une fraction de seconde décisive, vous plaquez la pièce de cuivre de Zhiliu sur son front, exploitant les derniers vestiges du pouvoir de scellement pour l’abattre au sol.\
Au moment de la chute, des fragments de mémoire vous traversent — épars, déchirants.\
Vous n’avez pas le loisir d’y réfléchir : le véritable combat commence.",
            ["TextMapId"] = "Content_120106_6",
            },
        ["Content_120106_7"] = {
            ["ContentFR"] = "Zhiliu se retourne soudain contre vous et vous entrave. Le rituel n’était qu’un prétexte : son objectif réel était d’absorber la puissance de Zhuyin — et votre présence imprévue a failli contrecarrer son plan. Fushu et Kezhou arrivent trop tard pour empêcher la tragédie. Zhiliu, qui ne souhaite pas s’encombrer davantage, se retire après avoir atteint son but, vous laissant au milieu des décombres du combat.\
Discutez avec eux de la suite.",
            ["TextMapId"] = "Content_120106_7",
            },
        ["Content_120106_8"] = {
            ["ContentFR"] = "Vous étiez venu à Huaxu par hasard... sans imaginer être {性别:happé|happée} dans une conspiration d’une telle ampleur. Aucune réponse immédiate ne s’offre à vous.\
Quittez l’Autel de Zhuyin pour l’instant.",
            ["TextMapId"] = "Content_120106_8",
            },
        ["Content_120111_0"] = {
            ["ContentFR"] = "Se rendre chez Fina et commencer l’histoire.",
            ["TextMapId"] = "Content_120111_0",
            },
        ["Content_120111_1"] = {
            ["ContentFR"] = "Le Grand Magicien vous a confié son plus puissant sort de protection.\
À présent, soyez courageux — franchissez le seuil et partez à la découverte du vaste monde.",
            ["TextMapId"] = "Content_120111_1",
            },
        ["Content_120111_1_1"] = {
            ["ContentFR"] = "Une nouvelle journée commence. Feuilletez l’histoire restée inachevée hier, et imaginez comment écrire la page suivante.",
            ["TextMapId"] = "Content_120111_1_1",
            },
        ["Content_120111_2"] = {
            ["ContentFR"] = "Dans un coin de Brumelac, quelques enfants jouent. Essayez de leur dire bonjour.",
            ["TextMapId"] = "Content_120111_2",
            },
        ["Content_120111_3"] = {
            ["ContentFR"] = "Le jeu du Glouton commence — partez chercher les « Patates grillées » cachées !",
            ["TextMapId"] = "Content_120111_3",
            },
        ["Content_120111_4"] = {
            ["ContentFR"] = "Le jeu du Glouton commence — partez chercher les « Patates grillées » cachées !",
            ["TextMapId"] = "Content_120111_4",
            },
        ["Content_120111_5"] = {
            ["ContentFR"] = "Une nouvelle manche commence. Cette fois, faites de votre mieux pour trouver toutes les Patates grillées.",
            ["TextMapId"] = "Content_120111_5",
            },
        ["Content_120111_6"] = {
            ["ContentFR"] = "Ouvrez votre grimoire et terminez « Adieu à la caverne d’antan » pour apprendre à invoquer la magie du Grand Magicien.",
            ["TextMapId"] = "Content_120111_6",
            },
        ["Content_120111_7"] = {
            ["ContentFR"] = "Le Grand Magicien semble avoir repéré l’une des Patates grillées — suivez-le pour vérifier.",
            ["TextMapId"] = "Content_120111_7",
            },
        ["Content_120111_8"] = {
            ["ContentFR"] = "Le Grand Magicien semble avoir repéré l’une des Patates grillées — suivez-le pour vérifier.",
            ["TextMapId"] = "Content_120111_8",
            },
        ["Content_120111_9"] = {
            ["ContentFR"] = "Le sort de protection ne dure qu’au grand jour. Rentrez avant la nuit et reposez-vous.",
            ["TextMapId"] = "Content_120111_9",
            },
        ["Content_120112_0"] = {
            ["ContentFR"] = "Se rendre chez Fina et poursuivre l’histoire.",
            ["TextMapId"] = "Content_120112_0",
            },
        ["Content_120112_1"] = {
            ["ContentFR"] = "Une nouvelle journée se lève. Sortez de chez vous et partez pour une nouvelle aventure.",
            ["TextMapId"] = "Content_120112_1",
            },
        ["Content_120112_2"] = {
            ["ContentFR"] = "Hier, vous avez exploré Brumelac — aujourd’hui, un nouveau royaume vous attend.",
            ["TextMapId"] = "Content_120112_2",
            },
        ["Content_120112_3"] = {
            ["ContentFR"] = "Petit Assistant du Détective Taciturne, en route ! La poubelle n° 7 a besoin d’être inspecté à fond !",
            ["TextMapId"] = "Content_120112_3",
            },
        ["Content_120112_3_1"] = {
            ["ContentFR"] = "Même sans indice, un véritable assistant se doit de rapporter fidèlement ses résultats. Retournez voir le Détective Taciturne.",
            ["TextMapId"] = "Content_120112_3_1",
            },
        ["Content_120112_3_2"] = {
            ["ContentFR"] = "Rassuré par ses encouragements, vous retrouvez confiance. Allez fouiller la poubelle ° 9.",
            ["TextMapId"] = "Content_120112_3_2",
            },
        ["Content_120112_4"] = {
            ["ContentFR"] = "Ouvrez votre grimoire et terminez « À travers le labyrinthe des souvenirs » pour apprendre à invoquer {性别:Monsieur|Mademoiselle} Licorne.",
            ["TextMapId"] = "Content_120112_4",
            },
        ["Content_120112_5"] = {
            ["ContentFR"] = "{性别:Monsieur|Mademoiselle} Licorne semble savoir où se cache l’indice — {性别:suivez-le|suivez-la}.",
            ["TextMapId"] = "Content_120112_5",
            },
        ["Content_120112_5_1"] = {
            ["ContentFR"] = "{性别:Guidé|Guidée} par {性别:Monsieur|Mademoiselle} Licorne, vous atteignez l’endroit indiqué. Examinez les environs avec attention.",
            ["TextMapId"] = "Content_120112_5_1",
            },
        ["Content_120112_5_2"] = {
            ["ContentFR"] = "Vous avez trouvé un indice important — confiez-le au Détective Taciturne pour analyse.",
            ["TextMapId"] = "Content_120112_5_2",
            },
        ["Content_120112_6"] = {
            ["ContentFR"] = "Votre aventure du jour touche à sa fin. Profitez qu’il fasse encore jour pour rentrer vous reposer.",
            ["TextMapId"] = "Content_120112_6",
            },
        ["Content_120112_6_2"] = {
            ["ContentFR"] = "{性别:Monsieur|Mademoiselle} Licorne semble avoir fait une découverte — {性别:suivez-le|suivez-la} pour en savoir plus.",
            ["TextMapId"] = "Content_120112_6_2",
            },
        ["Content_120112_7"] = {
            ["ContentFR"] = "Sous la conduite de {性别:Monsieur|Mademoiselle} Licorne, vous rencontrez {性别:le|la} véritable {性别:Monsieur|Mademoiselle} Licorne — quelle journée étonnante ! Rentrez vite consigner ce que vous avez vécu.",
            ["TextMapId"] = "Content_120112_7",
            },
        ["Content_120113_0"] = {
            ["ContentFR"] = "Se rendre chez Fina et poursuivre l’histoire.",
            ["TextMapId"] = "Content_120113_0",
            },
        ["Content_120113_1"] = {
            ["ContentFR"] = "Une nouvelle journée se lève. Sortez de chez vous et partez pour une nouvelle aventure.",
            ["TextMapId"] = "Content_120113_1",
            },
        }
  end },
  { MinKey = "Content_120113_2", MaxKey = "Content_200206_7", Loader = function()
      return {
        ["Content_120113_2"] = {
            ["ContentFR"] = "Vous avez rencontré le Détective Taciturne sur la place hier... Qui croiserez-vous aujourd’hui ? Allez voir.",
            ["TextMapId"] = "Content_120113_2",
            },
        ["Content_120113_3"] = {
            ["ContentFR"] = "Avec {性别:Monsieur|Mademoiselle} Licorne, cherchez sur la place la jeune noble aperçue plus tôt.",
            ["TextMapId"] = "Content_120113_3",
            },
        ["Content_120113_4"] = {
            ["ContentFR"] = "Vous avez fixé un rendez-vous avec Cassandra. Pour honorer sa mission, rentrez vite pratiquer votre magie.",
            ["TextMapId"] = "Content_120113_4",
            },
        ["Content_120113_5"] = {
            ["ContentFR"] = "Ouvrez votre grimoire et terminez « À travers la vallée des ronces » pour apprendre à invoquer Mademoiselle Papillon.",
            ["TextMapId"] = "Content_120113_5",
            },
        ["Content_120113_6"] = {
            ["ContentFR"] = "La nuit tombe — il est temps de se reposer.",
            ["TextMapId"] = "Content_120113_6",
            },
        ["Content_120114_0"] = {
            ["ContentFR"] = "Se rendre chez Fina et poursuivre l’histoire.",
            ["TextMapId"] = "Content_120114_0",
            },
        ["Content_120114_1"] = {
            ["ContentFR"] = "Le jour convenu est arrivé : retrouvez {性别:Monsieur|Mademoiselle} Licorne, puis allez ensemble rejoindre Cassandra.",
            ["TextMapId"] = "Content_120114_1",
            },
        ["Content_120114_10_1"] = {
            ["ContentFR"] = "Le petit Rossignol a enfin trouvé son courage — il déploie ses ailes.",
            ["TextMapId"] = "Content_120114_10_1",
            },
        ["Content_120114_10_2"] = {
            ["ContentFR"] = "L’aventure se termine en beauté. Rentrez à la maison avec vos compagnons.",
            ["TextMapId"] = "Content_120114_10_2",
            },
        ["Content_120114_10_3"] = {
            ["ContentFR"] = "L’aventure se termine en beauté. Rentrez à la maison avec vos compagnons.",
            ["TextMapId"] = "Content_120114_10_3",
            },
        ["Content_120114_10_4"] = {
            ["ContentFR"] = "Cassandra arrive avec les soldats du Bureau de la Sécurité. Le danger est écarté : allez lui parler.",
            ["TextMapId"] = "Content_120114_10_4",
            },
        ["Content_120114_11"] = {
            ["ContentFR"] = "Vous avez promis d’organiser un goûter ce soir — rentrez préparer tout cela.",
            ["TextMapId"] = "Content_120114_11",
            },
        ["Content_120114_12"] = {
            ["ContentFR"] = "On frappe à la porte... allez voir qui c’est.",
            ["TextMapId"] = "Content_120114_12",
            },
        ["Content_120114_13"] = {
            ["ContentFR"] = "Ouvrez votre grimoire et terminez « Vers les prés embaumés » pour apprendre à invoquer le petit Rossignol.",
            ["TextMapId"] = "Content_120114_13",
            },
        ["Content_120114_2"] = {
            ["ContentFR"] = "Le jour convenu est arrivé : retrouvez {性别:Monsieur|Mademoiselle} Licorne, puis allez ensemble rejoindre Cassandra.",
            ["TextMapId"] = "Content_120114_2",
            },
        ["Content_120114_3"] = {
            ["ContentFR"] = "Rejoignez {性别:Monsieur|Mademoiselle} Licorne et rendez-vous au lieu fixé avec Cassandra.",
            ["TextMapId"] = "Content_120114_3",
            },
        ["Content_120114_3_1"] = {
            ["ContentFR"] = "Vous avez répété le \"témoignage\" avec Cassandra. Attendez-la : elle va chercher son ami.",
            ["TextMapId"] = "Content_120114_3_1",
            },
        ["Content_120114_4"] = {
            ["ContentFR"] = "Vous ne vous attendiez pas à ce que son ami soit cette personne... Rentrez vite pour les éviter.",
            ["TextMapId"] = "Content_120114_4",
            },
        ["Content_120114_5"] = {
            ["ContentFR"] = "Selon les enfants, Mark saurait peut-être où se trouve Savio : allez lui demander.",
            ["TextMapId"] = "Content_120114_5",
            },
        ["Content_120114_5_1"] = {
            ["ContentFR"] = "Mark a vu Savio quitter la cité — rattrapez-le !",
            ["TextMapId"] = "Content_120114_5_1",
            },
        ["Content_120114_6"] = {
            ["ContentFR"] = "Mark a vu Savio quitter la cité — rattrapez-le !",
            ["TextMapId"] = "Content_120114_6",
            },
        ["Content_120114_7"] = {
            ["ContentFR"] = "Toutes les pistes mènent au repaire de bandits près du Lac du Deuil. Partez avec {性别:Monsieur|Mademoiselle} Licorne.",
            ["TextMapId"] = "Content_120114_7",
            },
        ["Content_120114_8"] = {
            ["ContentFR"] = "Savio a bel et bien été capturé — trouvez un moyen de le libérer.",
            ["TextMapId"] = "Content_120114_8",
            },
        ["Content_120114_9"] = {
            ["ContentFR"] = "Vainquez les bandits et délivrez Savio.",
            ["TextMapId"] = "Content_120114_9",
            },
        ["Content_120114_9_1"] = {
            ["ContentFR"] = "Le bruit du combat attire des Souillés — éliminez-les aussi.",
            ["TextMapId"] = "Content_120114_9_1",
            },
        ["Content_120201_1"] = {
            ["ContentFR"] = "Au moment où Zhuyin a été scellé, Zhiliu s’est soudain retournée contre vous et vous a emprisonné. Grâce à l’aide de Fushu et de Kezhou, arrivés à temps, vous avez réussi à briser l’emprise de son sort.\
Vous pensiez la crise temporairement écartée... mais à peine un danger dissipé qu’un autre surgit. En quittant la Mer de Poussière, Snow et vous avez été frappés par un talisman dissimulé à un tournant. Votre mémoire s’interrompt brusquement à cet instant.",
            ["TextMapId"] = "Content_120201_1",
            },
        ["Content_120201_10"] = {
            ["ContentFR"] = "Contrairement au Pavillon de l’Encens, bondé de monde, le Pavillon des Artisans est presque désert.\
Cherchez un employé du Pavillon des Artisans.",
            ["TextMapId"] = "Content_120201_10",
            },
        ["Content_120201_11"] = {
            ["ContentFR"] = "Vous trouvez finalement l’artisan. Il a déjà déposé le brûle-encens sur les marches voisines.",
            ["TextMapId"] = "Content_120201_11",
            },
        ["Content_120201_12"] = {
            ["ContentFR"] = "La cloche du Pavillon de l’Arbitrage retentit soudain. D’après l’artisan, c’est un événement rarissime qui ne se produit qu’une fois par siècle. Elle ne sonne que lorsqu’un crime d’une complexité exceptionnelle apparaît.\
Si vous souhaitez en savoir plus, rendez-vous sur la place devant le Pavillon de l’Arbitrage et allez jeter un œil au panneau d’affichage.",
            ["TextMapId"] = "Content_120201_12",
            },
        ["Content_120201_2"] = {
            ["ContentFR"] = "Alors que vous quittiez la Mer de Poussière, Snow et vous avez été pris au piège d’un talisman à un tournant, et votre mémoire s’est arrêtée net à ce moment-là. Il semble que Zhiliu et vous vous soyez violemment affrontés quelque part, pour une raison inconnue. Était-ce réellement arrivé... ou bien une illusion forgée par votre esprit ?",
            ["TextMapId"] = "Content_120201_2",
            },
        ["Content_120201_22"] = {
            ["ContentFR"] = "Après avoir quitté Zhiliu, Snow et vous devez vous rendre au Port des Astres Séparés, au Pavillon de l’Encens et au Pavillon des Artisans afin de récupérer les fournitures nécessaires à la Cérémonie de l’Encens.\
Le responsable du port vous informe que la soie de première qualité est stockée dans un entrepôt voisin. Allez trouver la caisse correspondante.",
            ["TextMapId"] = "Content_120201_22",
            },
        ["Content_120201_23"] = {
            ["ContentFR"] = "Vous avez retrouvé le sachet d’encens emporté par le vent sur un toit. Allez maintenant le rendre à sa propriétaire.",
            ["TextMapId"] = "Content_120201_23",
            },
        ["Content_120201_24"] = {
            ["ContentFR"] = "Ce petit malentendu désormais dissipé, vous obtenez l’encens de Fumée Argentée et laissez derrière vous une belle histoire de bonté et de vertu. Rendez-vous au Pavillon des Artisans, juste en face, afin de poursuivre votre mission.",
            ["TextMapId"] = "Content_120201_24",
            },
        ["Content_120201_25"] = {
            ["ContentFR"] = "À l’approche de la Cérémonie de l’Encens, le Pavillon de l’Encens est noir de monde.\
Une petite mésentente éclate entre vous et une femme persuadée que vous avez tenté de lui passer devant dans la file. Au beau milieu de la dispute, une bourrasque emporte son précieux sachet d’encens, édition limitée du festival. Soyez magnanime et allez l’aider à le retrouver.",
            ["TextMapId"] = "Content_120201_25",
            },
        ["Content_120201_3"] = {
            ["ContentFR"] = "Lorsque vous reprenez vos esprits, Snow, Zhiliu et vous marchez dans les rues animées de Haojing. D’après Snow, après le banquet célébrant la défaite de Zhuyin, vous avez décidé de venir vous promener à Haojing. Mais avant même de commencer la visite, vous sembliez déjà mal en point.\
À la remarque de Snow, quelques souvenirs flous refont surface, sans que vous puissiez les saisir clairement. Voyant votre teint pâle, Zhiliu propose de s’arrêter dans une pharmacie un peu plus loin afin de vous procurer quelques remèdes. Vous pourrez reprendre votre promenade une fois rétabli.",
            ["TextMapId"] = "Content_120201_3",
            },
        ["Content_120201_4"] = {
            ["ContentFR"] = "Le marché de l’Est est noir de monde, envahi par une foule de visiteurs. Sur votre insistance, Snow part d’abord chercher des places tandis que Zhiliu et vous vous rendez à la Pharmacie Zesheng pour acheter des médicaments.",
            ["TextMapId"] = "Content_120201_4",
            },
        ["Content_120201_5"] = {
            ["ContentFR"] = "Zhiliu ne semble montrer aucun signe étrange. Seriez-vous simplement trop méfiant ? La décoction fumante est désormais prête. Il est temps de retourner voir Snow.",
            ["TextMapId"] = "Content_120201_5",
            },
        ["Content_120201_6"] = {
            ["ContentFR"] = "Alors que vous vous reposez, les discussions animées de quelques passants au sujet du Pavillon de l’Arbitrage éveillent votre curiosité et celle de Snow.\
Justement, Zhiliu a une mission à vous confier en lien avec la Cérémonie de l’Encens, qui vous permettra d’admirer le Pavillon de l’Arbitrage de plus près.\
Accompagnez Zhiliu jusqu’au Pavillon des Sources, dans le quartier ouest, afin de récupérer un gage.",
            ["TextMapId"] = "Content_120201_6",
            },
        ["Content_120201_7"] = {
            ["ContentFR"] = "Alors que vous vous reposez, les discussions animées de quelques passants au sujet du Pavillon de l’Arbitrage éveillent votre curiosité et celle de Snow.\
Justement, Zhiliu a une mission à vous confier en lien avec la Cérémonie de l’Encens, qui vous permettra d’admirer le Pavillon de l’Arbitrage de plus près.\
Accompagnez Zhiliu jusqu’au Pavillon des Sources, dans le quartier ouest, afin de récupérer un gage.",
            ["TextMapId"] = "Content_120201_7",
            },
        ["Content_120201_8"] = {
            ["ContentFR"] = "Après avoir quitté Zhiliu, Snow et vous décidez de vous rendre au Port des Astres Séparés, au Pavillon de l’Encens et au Pavillon des Artisans afin de récupérer les fournitures nécessaires à la Cérémonie de l’Encens.\
Commencez par vous rendre au Port des Astres Séparés et cherchez le responsable du port.",
            ["TextMapId"] = "Content_120201_8",
            },
        ["Content_120201_9"] = {
            ["ContentFR"] = "Après quelques péripéties, vous parvenez à récupérer la soie de première qualité des mains d’un Wishen espiègle nommé Xiaoyao.\
Rendez-vous maintenant au Pavillon de l’Encens, dans la cité intérieure, afin de poursuivre votre mission.",
            ["TextMapId"] = "Content_120201_9",
            },
        ["Content_120202_1"] = {
            ["ContentFR"] = "Quelque temps plus tôt, par une nuit de pluie... Kezhou affrontait seul des Bi’an.",
            ["TextMapId"] = "Content_120202_1",
            },
        ["Content_120202_10"] = {
            ["ContentFR"] = "Dans ce moment critique, vous n’avez d’autre choix que d’intervenir pour bloquer l’attaque du dragon.\
Au moment décisif de l’affrontement, votre pouvoir se libère soudainement hors de votre contrôle. Blessé, le Seigneur Dragon d’Argent pousse un cri et s’envole.\
Vous n’avez même pas le temps de comprendre ce qui vient de se produire qu’un blocus tombe du ciel. Brisez l’encerclement avant d’être complètement pris au piège.",
            ["TextMapId"] = "Content_120202_10",
            },
        ["Content_120202_11"] = {
            ["ContentFR"] = "Vous et Kezhou sautez à temps et quittez le sommet du Pavillon de l’Arbitrage avant que le blocus ne se referme.\
À cause de vos actions, la ville entière est désormais en état d’alerte. Des Bi’an et des Magistrats de Yingtian patrouillent partout.\
Trouvez un moyen de quitter les lieux avant que votre trace ne soit découverte.",
            ["TextMapId"] = "Content_120202_11",
            },
        ["Content_120202_12"] = {
            ["ContentFR"] = "À cause de vos actions, la ville entière est désormais en état d’alerte. Des Bi’an et des Magistrats de Yingtian patrouillent partout.\
Alors que toute issue semble vous être fermée, Xiaoyao apparaît soudain devant vous et promet de vous aider à fuir.",
            ["TextMapId"] = "Content_120202_12",
            },
        ["Content_120202_13"] = {
            ["ContentFR"] = "Les escaliers menant au sommet du Pavillon de l’Arbitrage sont étroitement surveillés par les gardes.\
À proximité, une méchapoupée émet des bruits étranges, comme si elle était endommagée. Cette agitation inhabituelle vous donne une idée.",
            ["TextMapId"] = "Content_120202_13",
            },
        ["Content_120202_2"] = {
            ["ContentFR"] = "La cloche du Pavillon de l’Arbitrage se met soudain à sonner. D’après un artisan, c’est un phénomène rarissime qui ne se produit qu’une fois par siècle : elle ne résonne que lorsque l’affaire jugée est d’une complexité telle que nul ne peut en démêler aisément le bien du mal.\
En vous frayant un chemin dans la foule, vous apercevez l’avis placardé sur le panneau. Le visage du criminel représenté est pourtant celui d’une connaissance inattendue — Kezhou.",
            ["TextMapId"] = "Content_120202_2",
            },
        ["Content_120202_3"] = {
            ["ContentFR"] = "En vous frayant un chemin dans la foule, vous apercevez l’avis placardé sur le panneau. Le visage du criminel représenté est pourtant celui d’une connaissance inattendue — Kezhou.\
Vous avez quelque chose d’important à discuter avec Snow. Cet endroit est trop fréquenté : trouvez un lieu plus discret.",
            ["TextMapId"] = "Content_120202_3",
            },
        ["Content_120202_4"] = {
            ["ContentFR"] = "Depuis ce matin, une étrange sensation d’inquiétude vous tenaille. Vous avez le pressentiment que retrouver Kezhou pourrait être la clé de cette énigme.\
L’avis annonce que le « Rite de Délibération » aura lieu demain à midi. D’ici là, préparez-vous soigneusement.",
            ["TextMapId"] = "Content_120202_4",
            },
        ["Content_120202_5"] = {
            ["ContentFR"] = "Le « Rite de Délibération » approche, et la personne que vous venez sauver est actuellement détenue au sommet du Pavillon de l’Arbitrage.\
N’oubliez pas la tâche que Zhiliu vous a confiée : commencez par remettre les fournitures destinées à la Cérémonie de l’Encens à l’intendant du pavillon.",
            ["TextMapId"] = "Content_120202_5",
            },
        ["Content_120202_6"] = {
            ["ContentFR"] = "Le « Rite de Délibération » approche, et la personne que vous venez sauver est actuellement détenue au sommet du Pavillon de l’Arbitrage.\
Grâce à la mission confiée par Zhiliu, vous avez réussi à vous infiltrer dans le pavillon. Trouvez maintenant un moyen d’atteindre l’étage supérieur.",
            ["TextMapId"] = "Content_120202_6",
            },
        ["Content_120202_7"] = {
            ["ContentFR"] = "Les escaliers menant au sommet du Pavillon de l’Arbitrage sont étroitement surveillés par les gardes.\
Impossible de trouver une ouverture : vous décidez de discuter d’un plan avec Snow.",
            ["TextMapId"] = "Content_120202_7",
            },
        ["Content_120202_8"] = {
            ["ContentFR"] = "Vous manipulez légèrement la méchapoupée, attirant ainsi l’attention des gardes. Profitez de leur distraction pour vous faufiler jusqu’au sommet du Pavillon de l’Arbitrage.",
            ["TextMapId"] = "Content_120202_8",
            },
        ["Content_120202_9"] = {
            ["ContentFR"] = "Après bien des difficultés, vous atteignez enfin le sommet du Pavillon de l’Arbitrage — au moment même où apparaît Taihao, le Seigneur Dragon d’Argent.\
Après un échange d’arguments avec lui, Kezhou tente d’assassiner le Seigneur Dragon. Mais la force d’un mortel ne saurait rivaliser avec celle d’un dieu. Projeté violemment en arrière, Kezhou révèle involontairement votre présence et celle de Snow.\
Dans ce moment critique, vous n’avez d’autre choix que d’intervenir pour bloquer l’attaque du dragon.",
            ["TextMapId"] = "Content_120202_9",
            },
        ["Content_120203_1"] = {
            ["ContentFR"] = "Avec l’aide de Xiaoyao, vous vous réfugiez dans la Ruelle Youlai, un endroit où peu de gens s’aventurent. Vous pouvez enfin reprendre votre souffle.",
            ["TextMapId"] = "Content_120203_1",
            },
        ["Content_120203_10"] = {
            ["ContentFR"] = "Après bien des échanges, vous parvenez enfin à entrer en contact avec celle que Kezhou surnomme « Grande-tante » : une jeune fille vive nommée Su Yi.\
Sous sa conduite, vous atteignez la base secrète des Vagabonds — les Pics Extérieurs.",
            ["TextMapId"] = "Content_120203_10",
            },
        ["Content_120203_11"] = {
            ["ContentFR"] = "D’après Oncle Tang, Kezhou est déjà rentré aux Pics Extérieurs avant vous. Allez le rejoindre.",
            ["TextMapId"] = "Content_120203_11",
            },
        ["Content_120203_12"] = {
            ["ContentFR"] = "Le chaos que Kezhou a provoqué à l’extérieur met Su Yi hors d’elle. Vous assistez à une scène où elle le réprimande sévèrement.\
Avec son habituel sourire insolent, Kezhou vous demande de plaider sa cause auprès d’elle. Vous décidez alors...",
            ["TextMapId"] = "Content_120203_12",
            },
        ["Content_120203_13"] = {
            ["ContentFR"] = "Après avoir discuté d’un plan, Fushu part en premier et retourne à Haojing afin de chercher des traces de la Secte de l’Insondable Trésor.\
Pendant votre séjour aux Pics Extérieurs, vous décidez de prêter main-forte aux diverses tâches quotidiennes. C’est aussi une bonne occasion de mieux découvrir cet endroit.",
            ["TextMapId"] = "Content_120203_13",
            },
        ["Content_120203_14"] = {
            ["ContentFR"] = "La jambe d’Oncle Tang est récemment blessée. Vous accompagnez Su Yi pour aller cueillir des herbes médicinales afin de l’aider à se rétablir plus rapidement.\
Près du champ d’herbes, vous rencontrez Pei Chen et Lu Ye, qui se disputent encore sur la façon de corriger la mouette nuageuse qui sème le trouble. Montrez-leur ce dont vous êtes capable.",
            ["TextMapId"] = "Content_120203_14",
            },
        ["Content_120203_15"] = {
            ["ContentFR"] = "Ce petit incident avec la mouette nuageuse est désormais réglé. Le mauvais oiseau qui ravageait sans cesse les champs d’herbes a enfin été maîtrisé. Allez maintenant cueillir quelques herbes médicinales.",
            ["TextMapId"] = "Content_120203_15",
            },
        ["Content_120203_16"] = {
            ["ContentFR"] = "La jambe d’Oncle Tang est récemment blessée. Vous accompagnez Su Yi pour aller cueillir des herbes médicinales afin de l’aider à se rétablir plus rapidement.\
Les herbes ont été récoltées. Apportez-les à Oncle Tang.",
            ["TextMapId"] = "Content_120203_16",
            },
        ["Content_120203_17"] = {
            ["ContentFR"] = "En apportant les herbes à Oncle Tang, vous récupérez également les outils nécessaires à l’ajustement du Voile de Tianluo.\
Il s’agit d’un dispositif développé par la Secte Jishu pour couper la capacité de détection des Neuf Chapitres de Dafeng.\
Suivez maintenant Su Yi afin d’ajuster le Voile de Tianluo.",
            ["TextMapId"] = "Content_120203_17",
            },
        ["Content_120203_18"] = {
            ["ContentFR"] = "En apportant les herbes à Oncle Tang, vous récupérez également les outils nécessaires à l’ajustement du Voile de Tianluo.\
Il s’agit d’un dispositif développé par la Secte Jishu pour couper la capacité de détection des Neuf Chapitres de Dafeng.\
Suivez maintenant Su Yi afin d’ajuster le Voile de Tianluo.",
            ["TextMapId"] = "Content_120203_18",
            },
        ["Content_120203_19"] = {
            ["ContentFR"] = "Shen Han vous arrête pour vous confier son inquiétude au sujet d’un jeune nommé Zhu Pu.\
Ces derniers temps, il s’entraîne aux arts martiaux avec une obsession inquiétante. Vous acceptez d’aller vérifier ce qu’il en est.",
            ["TextMapId"] = "Content_120203_19",
            },
        ["Content_120203_2"] = {
            ["ContentFR"] = "Vous voilà enfin hors de danger. Discutez avec Kezhou pour comprendre ce qui se passe réellement.",
            ["TextMapId"] = "Content_120203_2",
            },
        ["Content_120203_20"] = {
            ["ContentFR"] = "Vous trouvez Zhu Pu dans une grotte, en train de s’entraîner jusqu’à l’épuisement. Il n’écoute plus les conseils de personne.\
Su Yi lui offre alors une « occasion de faire ses preuves ». Donnez quelques conseils à ce jeune obstiné.",
            ["TextMapId"] = "Content_120203_20",
            },
        ["Content_120203_21"] = {
            ["ContentFR"] = "Sous vos coups, Zhu Pu ne tient même pas dix coups avant d’être vaincu. Parlez-lui de nouveau.",
            ["TextMapId"] = "Content_120203_21",
            },
        ["Content_120203_22"] = {
            ["ContentFR"] = "Vous trouvez le contact des Pics Extérieurs, mais son attitude reste froide et distante.\
D’après les indications laissées par Kezhou, vous devez d’abord trouver le signal du jour pour qu’elle accepte de vous reconnaître.",
            ["TextMapId"] = "Content_120203_22",
            },
        ["Content_120203_23"] = {
            ["ContentFR"] = "Vous trouvez le contact des Pics Extérieurs, mais son attitude reste froide et distante.\
D’après les indications laissées par Kezhou, vous devez d’abord trouver le signal du jour pour qu’elle accepte de vous reconnaître.",
            ["TextMapId"] = "Content_120203_23",
            },
        ["Content_120203_3"] = {
            ["ContentFR"] = "Alors que vous parlez avec Kezhou, des pas résonnent soudain au loin. Vous ignorez qui approche. Trouvez vite un endroit où vous cacher et observez la situation.",
            ["TextMapId"] = "Content_120203_3",
            },
        ["Content_120203_4"] = {
            ["ContentFR"] = "La personne qui arrive n’est autre que Fushu. Le danger semble écarté pour le moment : discutez de la situation avec Fushu et Kezhou.",
            ["TextMapId"] = "Content_120203_4",
            },
        ["Content_120203_5"] = {
            ["ContentFR"] = "Sous les paroles de Fushu, vos souvenirs commencent peu à peu à revenir...",
            ["TextMapId"] = "Content_120203_5",
            },
        ["Content_120203_6"] = {
            ["ContentFR"] = "Sous les paroles de Fushu, vos souvenirs commencent peu à peu à revenir...\
Après la bataille contre Zhuyin, Zhiliu vous a plongé dans l’inconscience et vous a emmené dans un lieu inconnu. Là, elle vous a révélé l’avenir prédit par trois présages divinatoires.\
L’affrontement contre le Seigneur Dragon d’Argent au sommet du Pavillon de l’Arbitrage en était le premier.",
            ["TextMapId"] = "Content_120203_6",
            },
        ["Content_120203_7"] = {
            ["ContentFR"] = "Vous devez arrêter Zhiliu avant que les deux autres « prophéties » ne se réalisent. Après avoir discuté avec Fushu et Kezhou, vous décidez de vous rendre aux Pics Extérieurs, afin d’échapper à la traque lancée dans toute la ville et de chercher un moyen de lever le sortilège de Zhiliu.\
Kezhou se porte volontaire pour attirer les poursuivants et part en éclaireur. Suivez les indications qu’il a laissées et trouvez le contact des Pics Extérieurs.",
            ["TextMapId"] = "Content_120203_7",
            },
        ["Content_120203_8"] = {
            ["ContentFR"] = "Vous trouvez le contact des Pics Extérieurs, mais son attitude reste froide et distante.\
D’après les indications laissées par Kezhou, vous devez d’abord trouver le signal du jour pour qu’elle accepte de vous reconnaître.",
            ["TextMapId"] = "Content_120203_8",
            },
        ["Content_120203_9"] = {
            ["ContentFR"] = "Vous avez obtenu le signal. Retournez parler au contact.",
            ["TextMapId"] = "Content_120203_9",
            },
        ["Content_120204_1"] = {
            ["ContentFR"] = "Soudain, un tumulte inquiétant se fait entendre à l’extérieur. Allez vérifier ce qui se passe.",
            ["TextMapId"] = "Content_120204_1",
            },
        ["Content_120204_10"] = {
            ["ContentFR"] = "Au cœur du Labyrinthe de Yanyin, vous découvrez par hasard un ancien secret... et découvrez la clé de la victoire : la méthode d’activation du Canon Céleste.\
Avec ce nouvel atout en main, retournez sur le champ de bataille pour renverser la situation.",
            ["TextMapId"] = "Content_120204_10",
            },
        ["Content_120204_11"] = {
            ["ContentFR"] = "Avec votre retour dans la bataille, la situation s’inverse immédiatement. En un instant, les Sentinelles de Fer de Juntian montrent des signes de défaite.",
            ["TextMapId"] = "Content_120204_11",
            },
        ["Content_120204_12"] = {
            ["ContentFR"] = "Avec votre retour dans la bataille, la situation s’inverse immédiatement. En un instant, les Sentinelles de Fer de Juntian montrent des signes de défaite.\
Soudain, une violente secousse secoue la cité, et les Magistrats de Yingtian battent tous en retraite d’un même mouvement.\
La crise est terminée. Allez parler aux autres.",
            ["TextMapId"] = "Content_120204_12",
            },
        ["Content_120204_13"] = {
            ["ContentFR"] = "Avec la retraite des Sentinelles de Fer de Juntian, le sceau qui retenait vos souvenirs commence à se fissurer...",
            ["TextMapId"] = "Content_120204_13",
            },
        ["Content_120204_14"] = {
            ["ContentFR"] = "Se servir de vous pour blesser Taihao et détourner les Sentinelles de Fer de Juntian faisait partie du plan de Zhiliu.\
Le dispositif se met peu à peu en place, attendant simplement que chaque pièce entre en jeu.\
Pendant ce temps, au sommet du Pavillon de l’Arbitrage, Zhiliu conspire déjà avec Zhuyin...",
            ["TextMapId"] = "Content_120204_14",
            },
        ["Content_120204_2"] = {
            ["ContentFR"] = "La position des Pics Extérieurs a été soudainement révélée. Les Magistrats de Yingtian ont lancé l’assaut et tous sont en danger.\
La situation est critique : aidez les Vagabonds à repousser la première vague.",
            ["TextMapId"] = "Content_120204_2",
            },
        ["Content_120204_3"] = {
            ["ContentFR"] = "La position des Pics Extérieurs a été soudainement révélée. Les Magistrats de Yingtian ont lancé l’assaut et tous sont en danger.\
La situation est critique : allez vérifier la situation avec les Vagabonds.",
            ["TextMapId"] = "Content_120204_3",
            },
        ["Content_120204_4"] = {
            ["ContentFR"] = "La position des Pics Extérieurs a été révélée et les Magistrats de Yingtian ont lancé l’assaut. Leur chef n’est autre que Yuming, autrefois proche des Pics Extérieurs.\
Il semble hésiter à lever les armes contre ses anciens compagnons. Mais les paroles de Kezhou produisent l’effet inverse. Les armes sont déjà dégainées. Il ne reste plus qu’à combattre.",
            ["TextMapId"] = "Content_120204_4",
            },
        ["Content_120204_5"] = {
            ["ContentFR"] = "La position des Pics Extérieurs a été révélée et les Magistrats de Yingtian ont lancé l’assaut. Leur chef n’est autre que Yuming, autrefois proche des Pics Extérieurs.\
Il semble hésiter à lever les armes contre ses anciens compagnons. Mais les paroles de Kezhou produisent l’effet inverse. Les armes sont déjà dégainées. Il ne reste plus qu’à combattre.",
            ["TextMapId"] = "Content_120204_5",
            },
        ["Content_120204_6"] = {
            ["ContentFR"] = "Dans son affrontement contre Yuming, Kezhou commence à perdre l’avantage. Impuissante face à la situation, Su Yi est profondément inquiète. Après avoir pris sa décision, elle vous entraîne dans un ancien souterrain de la Secte Jishu situé à proximité et vous demande de chercher avec elle une autre solution.",
            ["TextMapId"] = "Content_120204_6",
            },
        ["Content_120204_9"] = {
            ["ContentFR"] = "Au cœur du Labyrinthe de Yanyin, vous découvrez par hasard un ancien secret... et découvrez la clé de la victoire : la méthode d’activation du Canon Céleste.\
Avec ce nouvel atout en main, retournez sur le champ de bataille pour renverser la situation.",
            ["TextMapId"] = "Content_120204_9",
            },
        ["Content_120205_1"] = {
            ["ContentFR"] = "Après la grande bataille, vous prenez quelque temps pour vous reposer aux Pics Extérieurs.\
Fushu est revenue en toute hâte, inquiète de votre état. Allez discuter avec elle.",
            ["TextMapId"] = "Content_120205_1",
            },
        ["Content_120205_10"] = {
            ["ContentFR"] = "Le chef du village vous indique enfin la bonne direction : la personne que vous cherchez, Maître Jingyuan, vit en ermite sur la falaise, de l’autre côté du pont brisé.",
            ["TextMapId"] = "Content_120205_10",
            },
        ["Content_120205_11"] = {
            ["ContentFR"] = "Maître Jingyuan vous attendait déjà. Elle refuse de juger les actes de son élève, mais vous raconte un épisode du passé de Zhiliu lorsqu’elle était enfant.\
Lorsque vous serez prêt à lever le sortilège et à briser le sceau qui entrave vos souvenirs, adressez-vous à Maître Jingyuan.",
            ["TextMapId"] = "Content_120205_11",
            },
        ["Content_120205_12"] = {
            ["ContentFR"] = "Grâce à l’aide de Maître Jingyuan, vous parvenez enfin à reconstituer la dernière pièce manquante de vos souvenirs...",
            ["TextMapId"] = "Content_120205_12",
            },
        ["Content_120205_13"] = {
            ["ContentFR"] = "Tout est désormais en place. Pendant ce temps, au cœur du Mausolée de Taixu, un Haut Chancelier de Longyuan s’avance vers la fin de son existence...",
            ["TextMapId"] = "Content_120205_13",
            },
        ["Content_120205_14"] = {
            ["ContentFR"] = "Tout est désormais en place. Pendant ce temps, au cœur du Mausolée de Taixu, un Haut Chancelier de Longyuan s’avance vers la fin de son existence...",
            ["TextMapId"] = "Content_120205_14",
            },
        ["Content_120205_15"] = {
            ["ContentFR"] = "Tout est désormais en place. Pendant ce temps, au cœur du Mausolée de Taixu, un Haut Chancelier de Longyuan s’avance vers la fin de son existence...",
            ["TextMapId"] = "Content_120205_15",
            },
        ["Content_120205_16"] = {
            ["ContentFR"] = "Tout est désormais en place. Pendant ce temps, au cœur du Mausolée de Taixu, un Haut Chancelier de Longyuan s’avance vers la fin de son existence...",
            ["TextMapId"] = "Content_120205_16",
            },
        ["Content_120205_17"] = {
            ["ContentFR"] = "Le plan de Zhiliu pour tuer un dieu est désormais en marche. Les ondes de choc de l’affrontement entre Taihao et Zhuyin plongent toute la ville de Haojing dans le chaos.",
            ["TextMapId"] = "Content_120205_17",
            },
        ["Content_120205_2"] = {
            ["ContentFR"] = "La nuit est tombée, et les Pics Extérieurs paraissent étrangement silencieux après la bataille. Allez chercher Su Yi.",
            ["TextMapId"] = "Content_120205_2",
            },
        ["Content_120205_3"] = {
            ["ContentFR"] = "Vous surprenez une scène où un Vagabond critique votre présence, tandis que Su Yi prend votre défense avec vigueur. Allez lui parler.",
            ["TextMapId"] = "Content_120205_3",
            },
        ["Content_120205_4"] = {
            ["ContentFR"] = "Bien qu’elle regrette votre départ, Su Yi finit par accepter que vous quittiez les Pics Extérieurs.\
Elle vous conseille d’emmener Kezhou avec vous comme allié. Après sa violente dispute avec Yuming, Kezhou a disparu toute la nuit.\
Fait inhabituel, Snow est restée sur place : elle dit vouloir interroger Su Yi au sujet d’un ancien secret. Allez écouter ce qu’elle souhaite lui demander.",
            ["TextMapId"] = "Content_120205_4",
            },
        ["Content_120205_5"] = {
            ["ContentFR"] = "Bien qu’elle regrette votre départ, Su Yi finit par accepter que vous quittiez les Pics Extérieurs.\
Elle vous conseille d’emmener Kezhou avec vous comme allié. Après sa violente dispute avec Yuming, Kezhou a disparu toute la nuit. Allez le chercher.",
            ["TextMapId"] = "Content_120205_5",
            },
        ["Content_120205_6"] = {
            ["ContentFR"] = "Kezhou vous confie le passé tragique qui le lie à son frère d’armes et à Buxia. Vous parvenez à lui redonner courage. Retournez maintenant avec lui afin de discuter d’un plan avec les autres.",
            ["TextMapId"] = "Content_120205_6",
            },
        ["Content_120205_7"] = {
            ["ContentFR"] = "D’après les informations rapportées par Fushu, la Secte de l’Insondable Trésor vivrait recluse au Village de Jiaolan, dans la Banlieue Ouest de Haojing. Cela pourrait être la clé pour lever le sortilège de Zhiliu.\
Ne perdons pas de temps : rendez-vous immédiatement au Village de Jiaolan.",
            ["TextMapId"] = "Content_120205_7",
            },
        ["Content_120205_8"] = {
            ["ContentFR"] = "D’après les informations rapportées par Fushu, la Secte de l’Insondable Trésor vivrait recluse au Village de Jiaolan, dans la Banlieue Ouest de Haojing. Cela pourrait être la clé pour lever le sortilège de Zhiliu.\
Renseignez-vous auprès des villageois afin d’en apprendre davantage.",
            ["TextMapId"] = "Content_120205_8",
            },
        ["Content_120205_9"] = {
            ["ContentFR"] = "Malgré vos recherches, vous n’obtenez aucune information — certains habitants vont même jusqu’à vous fermer leur porte. Kezhou propose alors d’aller directement interroger le chef du village.",
            ["TextMapId"] = "Content_120205_9",
            },
        ["Content_120206_1"] = {
            ["ContentFR"] = "Le plan de Zhiliu pour tuer un dieu est désormais en marche. Les ondes de choc de l’affrontement entre Taihao et Zhuyin plongent toute la ville de Haojing dans le chaos.",
            ["TextMapId"] = "Content_120206_1",
            },
        ["Content_120206_10"] = {
            ["ContentFR"] = "Avec l’aide de Maître Jingyuan, vous découvrez enfin l’intégralité du plan de Zhiliu — ainsi que le moyen de le contrecarrer. Il est encore temps de l’arrêter. Avant que tout ne soit scellé, rendez-vous au Pavillon de l’Arbitrage.",
            ["TextMapId"] = "Content_120206_10",
            },
        ["Content_120206_11"] = {
            ["ContentFR"] = "Avec l’aide de Maître Jingyuan, vous découvrez enfin l’intégralité du plan de Zhiliu — ainsi que le moyen de le contrecarrer.\
En chemin, vous retrouvez Su Yi. Elle s’occupe de vos arrières afin que vous puissiez poursuivre sans entrave. Avant que tout ne soit scellé, rendez-vous au Pavillon de l’Arbitrage.",
            ["TextMapId"] = "Content_120206_11",
            },
        ["Content_120206_12"] = {
            ["ContentFR"] = "Avec l’aide de Maître Jingyuan, vous découvrez enfin l’intégralité du plan de Zhiliu — ainsi que le moyen de le contrecarrer.\
Il est encore temps. Hâtez-vous vers les profondeurs du Mausolée de Taixu.",
            ["TextMapId"] = "Content_120206_12",
            },
        ["Content_120206_13"] = {
            ["ContentFR"] = "Avec l’aide de Maître Jingyuan, vous découvrez enfin l’intégralité du plan de Zhiliu — ainsi que le moyen de le contrecarrer.\
Il est encore temps. Hâtez-vous vers les profondeurs du Mausolée de Taixu.",
            ["TextMapId"] = "Content_120206_13",
            },
        ["Content_120206_14"] = {
            ["ContentFR"] = "L’affrontement entre Taihao et Zhuyin atteint son paroxysme. Au plus profond du Mausolée de Taixu, vous découvrez Zhiliu au bord de l’effondrement.\
Déterminée à mourir, elle vous supplie de transpercer sa poitrine avec votre épée afin d’achever le sacrifice final.",
            ["TextMapId"] = "Content_120206_14",
            },
        ["Content_120206_15"] = {
            ["ContentFR"] = "Vous refusez d’accéder à la demande de Zhiliu — vous êtes venu lui prouver qu’il existe toujours une autre voie.\
Grâce à la Résonance, vous transférez sur vous-même le pouvoir du Pacte d’âme qui la liait.\
Déjà proches de la démence, Taihao et Zhuyin sentent cette intervention et tournent leur regard vers vous. Vainquez-les, et prouvez la force de votre volonté.",
            ["TextMapId"] = "Content_120206_15",
            },
        ["Content_120206_16"] = {
            ["ContentFR"] = "Vous refusez d’accéder à la demande de Zhiliu — vous êtes venu lui prouver qu’il existe toujours une autre voie.\
Grâce à la Résonance, vous transférez brièvement sur vous-même le pouvoir du Pacte d’âme qui la liait.\
Déjà proches de la démence, Taihao et Zhuyin sentent cette intervention et tournent leur regard vers vous. Vainquez-les, et prouvez la force de votre volonté.",
            ["TextMapId"] = "Content_120206_16",
            },
        ["Content_120206_17"] = {
            ["ContentFR"] = "Vous refusez d’accéder à la demande de Zhiliu — vous êtes venu lui prouver qu’il existe toujours une autre voie.\
Grâce à la Résonance, vous transférez brièvement sur vous-même le pouvoir du Pacte d’âme qui la liait.\
Déjà proches de la démence, Taihao et Zhuyin sentent cette intervention et tournent leur regard vers vous. Vainquez-les, et prouvez la force de votre volonté.",
            ["TextMapId"] = "Content_120206_17",
            },
        ["Content_120206_18"] = {
            ["ContentFR"] = "Vous refusez d’accéder à la demande de Zhiliu — vous êtes venu lui prouver qu’il existe toujours une autre voie.\
Grâce à la Résonance, vous transférez brièvement sur vous-même le pouvoir du Pacte d’âme qui la liait.\
Déjà proches de la démence, Taihao et Zhuyin sentent cette intervention et tournent leur regard vers vous. Vainquez-les, et prouvez la force de votre volonté.",
            ["TextMapId"] = "Content_120206_18",
            },
        ["Content_120206_19"] = {
            ["ContentFR"] = "Vous refusez d’accéder à la demande de Zhiliu — vous êtes venu lui prouver qu’il existe toujours une autre voie.\
Grâce à la Résonance, vous transférez brièvement sur vous-même le pouvoir du Pacte d’âme qui la liait.\
Déjà proches de la démence, Taihao et Zhuyin sentent cette intervention et tournent leur regard vers vous. Vainquez-les, et prouvez la force de votre volonté.",
            ["TextMapId"] = "Content_120206_19",
            },
        ["Content_120206_2"] = {
            ["ContentFR"] = "Le plan de Zhiliu pour tuer un dieu est désormais en marche. Les ondes de choc de l’affrontement entre Taihao et Zhuyin plongent toute la ville de Haojing dans le chaos.",
            ["TextMapId"] = "Content_120206_2",
            },
        ["Content_120206_20"] = {
            ["ContentFR"] = "Après avoir vaincu les deux dragons, le Jade de l’Équilibre émet une lumière éclatante qui engloutit tout autour de vous et vous transporte dans un espace irréel et vaporeux...",
            ["TextMapId"] = "Content_120206_20",
            },
        ["Content_120206_21"] = {
            ["ContentFR"] = "Après avoir vaincu les deux dragons, le Jade de l’Équilibre émet une lumière éclatante qui engloutit tout autour de vous et vous transporte dans un espace irréel et vaporeux...",
            ["TextMapId"] = "Content_120206_21",
            },
        ["Content_120206_22"] = {
            ["ContentFR"] = "Après avoir vaincu les deux dragons, le Jade de l’Équilibre émet une lumière éclatante qui engloutit tout autour de vous et vous transporte dans un espace irréel et vaporeux...",
            ["TextMapId"] = "Content_120206_22",
            },
        ["Content_120206_23"] = {
            ["ContentFR"] = "Après avoir vaincu les deux dragons, le Jade de l’Équilibre émet une lumière éclatante qui engloutit tout autour de vous et vous transporte dans un espace irréel et vaporeux...",
            ["TextMapId"] = "Content_120206_23",
            },
        ["Content_120206_24"] = {
            ["ContentFR"] = "Vous atteignez le cœur du Mausolée de Taixu et vous entretenez avec les anciens Ju et Yang. Les Neuf Chapitres de Dafeng, arrachés à leur ordre originel, s’apprêtent enfin à retrouver leur état d’origine.",
            ["TextMapId"] = "Content_120206_24",
            },
        ["Content_120206_25"] = {
            ["ContentFR"] = "Les Neuf Chapitres de Dafeng, arrachés à leur ordre originel, s’apprêtent enfin à retrouver leur état d’origine. Et vous êtes {性别:celui|celle} qui a rendu cela possible. Taihao vous adresse sa gratitude et vous fait une promesse. Allez maintenant discuter avec les autres.",
            ["TextMapId"] = "Content_120206_25",
            },
        ["Content_120206_26"] = {
            ["ContentFR"] = "Zhiliu semble avoir quelque chose à vous dire...",
            ["TextMapId"] = "Content_120206_26",
            },
        ["Content_120206_27"] = {
            ["ContentFR"] = "Zhiliu vous demande de l’accompagner pour une promenade...",
            ["TextMapId"] = "Content_120206_27",
            },
        ["Content_120206_28"] = {
            ["ContentFR"] = "Zhiliu vous demande de l’accompagner pour une promenade...",
            ["TextMapId"] = "Content_120206_28",
            },
        ["Content_120206_3"] = {
            ["ContentFR"] = "Haojing est plongée dans le chaos. Des Bi’an et des Bi’an obscurs, pris de frénésie, se mettent à attaquer les habitants sans distinction. Une petite fille manque d’être blessée lorsqu’un Bi’an surgit — mais Su Yi intervient à temps.",
            ["TextMapId"] = "Content_120206_3",
            },
        ["Content_120206_5"] = {
            ["ContentFR"] = "Haojing est plongée dans le chaos. Des Bi’an et des Bi’an obscurs, pris de frénésie, se mettent à attaquer les habitants sans distinction. Repoussez les Bi’an dans la ville afin de protéger la population.",
            ["TextMapId"] = "Content_120206_5",
            },
        ["Content_120206_6"] = {
            ["ContentFR"] = "Haojing est plongée dans le chaos. Des Bi’an et des Bi’an obscurs sèment toujours la destruction dans les rues. Continuer ainsi ne résoudra rien. Discutez d’un plan.",
            ["TextMapId"] = "Content_120206_6",
            },
        ["Content_120206_7"] = {
            ["ContentFR"] = "Su Yi reçoit un message de {nickname} et s’apprête à lui porter secours. Mais avant de partir, elle insiste pour distribuer les armes de réserve qu’elle a apportées afin que les habitants puissent aussi se défendre.",
            ["TextMapId"] = "Content_120206_7",
            },
        ["Content_120206_8"] = {
            ["ContentFR"] = "Les Vagabonds tentent de distribuer des armes, mais se heurtent à la méfiance des habitants. Pourtant, Su Yi ne semble pas prête à abandonner...",
            ["TextMapId"] = "Content_120206_8",
            },
        ["Content_120206_9"] = {
            ["ContentFR"] = "Avec l’aide de Maître Jingyuan, vous découvrez enfin l’intégralité du plan de Zhiliu — ainsi que le moyen de le contrecarrer. Il est encore temps de l’arrêter. Avant que tout ne soit scellé, rendez-vous au Pavillon de l’Arbitrage.",
            ["TextMapId"] = "Content_120206_9",
            },
        ["Content_200101_1"] = {
            ["ContentFR"] = "Une silhouette familière vous attend devant le Sanctuaire, elle ressemble étrangement à Snow.",
            ["TextMapId"] = "Content_200101_1",
            },
        ["Content_200101_2"] = {
            ["ContentFR"] = "Vous entendez quelqu’un vous appeler. Allez voir de qui il s’agit.",
            ["TextMapId"] = "Content_200101_2",
            },
        ["Content_200101_3"] = {
            ["ContentFR"] = "Celle qui vous a interpellé se présente comme une forgeronne de la race des Luno.\
Selon Snow, il s’agirait d’une ancienne, bien que tous les Luno aient la même apparence juvénile, quel que soit leur âge.\
En échange de ses talents, Luno, la forgeronne souhaite vous accompagner dans votre voyage.\
Ramenez-la au Sanctuaire.",
            ["TextMapId"] = "Content_200101_3",
            },
        ["Content_200101_4"] = {
            ["ContentFR"] = "Luno, la forgeronne ne cache pas sa fierté quant à ses talents.\
Voyez donc de quoi elle est capable.",
            ["TextMapId"] = "Content_200101_4",
            },
        ["Content_200102_1"] = {
            ["ContentFR"] = "Se rendre à la Maison d’Hypnos pour prendre des nouvelles de Psyche, comme convenu.",
            ["TextMapId"] = "Content_200102_1",
            },
        ["Content_200102_2"] = {
            ["ContentFR"] = "Les fleurs que Psyche a si tendrement cultivées se fanent peu à peu, comme privées de nutriments. Pour leur rendre vie, il faut rapporter une terre spéciale que l’on trouve dans une grotte, à l’extérieur de Givrelac.\
Pour un Chasseur de Phoxène, une telle tâche n’est qu’une formalité.",
            ["TextMapId"] = "Content_200102_2",
            },
        ["Content_200102_3"] = {
            ["ContentFR"] = "Selon Psyche, cette terre si particulière pousse dans une grotte, non loin du Lac du Deuil.\
Partez en quête de ce sol fertile pour elle.",
            ["TextMapId"] = "Content_200102_3",
            },
        ["Content_200102_4"] = {
            ["ContentFR"] = "La terre à l’entrée de la grotte est trop sèche pour nourrir les fleurs.\
Explorez plus en profondeur afin de trouver une terre plus adaptée.",
            ["TextMapId"] = "Content_200102_4",
            },
        ["Content_200102_5"] = {
            ["ContentFR"] = "Après bien des efforts, vous découvrez enfin, au cœur de la grotte, une terre souple et fertile.\
Rapportez cette précieuse terre à la Maison d’Hypnos — Psyche en sera sûrement ravie.",
            ["TextMapId"] = "Content_200102_5",
            },
        ["Content_200103_1"] = {
            ["ContentFR"] = "Snow s’agite au Sanctuaire, en criant qu’il est arrivé quelque chose de grave. Vous doutez que ce soit vraiment le cas, mais, pour la calmer, autant aller lui parler.",
            ["TextMapId"] = "Content_200103_1",
            },
        ["Content_200103_2"] = {
            ["ContentFR"] = "On raconte qu’un cochon géant rôde aux abords de Givrelac. Difficile d’y croire... mais s’il est vraiment \"géant\", jusqu’à quel point ? Rien ne vaut vos propres yeux : allez vérifier par vous-même.",
            ["TextMapId"] = "Content_200103_2",
            },
        ["Content_200103_3"] = {
            ["ContentFR"] = "Vous les preniez pour de simples amis des bêtes... mais ce n’étaient que de misérables chasseurs. Heureusement que le cochon géant est intervenu.\
Combattez à ses côtés et balayez ces malfrats !",
            ["TextMapId"] = "Content_200103_3",
            },
        ["Content_200103_4"] = {
            ["ContentFR"] = "Les chasseurs de Géniemon vaincus, vous pouvez enfin observer le cochon géant de plus près. Un instant... Il a vraiment parlé, ou bien cette voix venait-elle de quelqu’un d’autre ?",
            ["TextMapId"] = "Content_200103_4",
            },
        ["Content_200103_5"] = {
            ["ContentFR"] = "Le système des Géniemons est désormais accessible. Offrez-leur de la nourriture et gagnez leur amitié — ils seront de précieux alliés pour la suite de votre voyage.",
            ["TextMapId"] = "Content_200103_5",
            },
        ["Content_200104_1"] = {
            ["ContentFR"] = "Ces derniers temps, aux Asphodèles, on murmure à nouveau au sujet d’un cochon géant. Cela voudrait-il dire que Truffle n’est jamais partie ?\
Allez demander à Camilla ce qu’elle en pense.",
            ["TextMapId"] = "Content_200104_1",
            },
        ["Content_200104_3"] = {
            ["ContentFR"] = "Truffle rôde bel et bien encore aux abords de Givrelac... Serait-ce que ces chasseurs de Géniemon sont revenus ? Trouvez Truffle à l’extérieur de la cité : elle aura sûrement besoin de votre aide.",
            ["TextMapId"] = "Content_200104_3",
            },
        ["Content_200104_4"] = {
            ["ContentFR"] = "C’étaient bien eux — ces odieux chasseurs de Géniemon, prêts à s’en prendre à d’innocentes créatures. Pour une telle cruauté, ils méritent châtiment... Mais avant cela, il faut d’abord les retrouver.",
            ["TextMapId"] = "Content_200104_4",
            },
        ["Content_200104_5"] = {
            ["ContentFR"] = "Encore les Égouts de Givrelac... On dirait que les âmes les plus viles aiment toujours s’y terrer. Avancez, et retrouvez les Géniemon avant qu’ils ne s’imprègnent trop de l’air fétide des tunnels.",
            ["TextMapId"] = "Content_200104_5",
            },
        ["Content_200104_6"] = {
            ["ContentFR"] = "L’odeur du conduit perturbe l’odorat de Filbert, mais il semble qu’un Géniemon plus malin que les autres vous précède et vous guide. Suivez sa trace et poursuivez votre route.",
            ["TextMapId"] = "Content_200104_6",
            },
        ["Content_200104_7"] = {
            ["ContentFR"] = "Vous retrouvez enfin les chasseurs de Géniemon, tout au fond des égouts — en plein discours sur leur passé comme sur leur avenir. Quelle que soit leur histoire... commencez par leur donner la correction qu’ils méritent.",
            ["TextMapId"] = "Content_200104_7",
            },
        ["Content_200104_8"] = {
            ["ContentFR"] = "Vous voilà entouré d’une joyeuse troupe de Géniemon, ce qui est formidable... mais cela finit aussi par faire beaucoup de monde. Mieux vaut demander conseil à Camilla : si quelqu’un peut trouver une solution, c’est bien elle... n’est-ce pas ?",
            ["TextMapId"] = "Content_200104_8",
            },
        ["Content_200104_9"] = {
            ["ContentFR"] = "Emmenez les Géniemon avec vous et rendez-leur la liberté. Avec bienveillance, aidez-les à retrouver leur chemin.\
Quittez ces égouts obscurs et remontez vers la lumière du jour.",
            ["TextMapId"] = "Content_200104_9",
            },
        ["Content_200201_1"] = {
            ["ContentFR"] = "Près de l’entrée secondaire de Givrelac vit Sally, une vieille dame au cœur généreux.\
Chaque passage à proximité s’accompagne du parfum onctueux de sa crème de champignons.\
Mais depuis quelque temps, son regard semble plus lourd — allez donc lui parler.",
            ["TextMapId"] = "Content_200201_1",
            },
        ["Content_200201_2"] = {
            ["ContentFR"] = "Sally paraît tourmentée à propos d’une certaine dame dont elle s’inquiète.\
Si vous croisez cette femme, peut-être pourrez-vous lui venir en aide.",
            ["TextMapId"] = "Content_200201_2",
            },
        ["Content_200201_3"] = {
            ["ContentFR"] = "Dame Hilin attend, depuis de longues années, un Charon nommé Hamel Dickinson.\
La solitude et l’inquiétude pèsent sur elle. Aidez-la à retrouver la trace de cet homme disparu.",
            ["TextMapId"] = "Content_200201_3",
            },
        ["Content_200201_4"] = {
            ["ContentFR"] = "Pénétrez dans les profondeurs de la Fosse pour retrouver des traces de Hamel Dickinson.",
            ["TextMapId"] = "Content_200201_4",
            },
        ["Content_200201_5"] = {
            ["ContentFR"] = "Dans les profondeurs de la fosse, vous découvrez un vieux journal sans titre.\
Sur la page de garde est inscrit un nom : Hamel Dickinson.\
Le journal semble retracer certains événements liés à cet homme.\
Il est temps de retourner à Givrelac et de remettre ce carnet à Dame Hilin.",
            ["TextMapId"] = "Content_200201_5",
            },
        ["Content_200201_6"] = {
            ["ContentFR"] = "Après avoir lu le journal, Dame Hilin souhaite rester seule un moment.\
Allez voir sa domestique, Sally, pour recevoir votre récompense et en apprendre davantage sur cette vieille histoire.",
            ["TextMapId"] = "Content_200201_6",
            },
        ["Content_200201_7"] = {
            ["ContentFR"] = "Vous avez choisi de garder le journal secret — et c’est peut-être le mieux. Trouvez Sally, la servante de Dame Hilin, pour recevoir votre récompense... et apprendre l’histoire de Dame Hilin et de Hamel Dickinson.",
            ["TextMapId"] = "Content_200201_7",
            },
        ["Content_200202_1"] = {
            ["ContentFR"] = "Près des portes de la cité, un homme interpelle les passants — il semble vendre quelque chose.",
            ["TextMapId"] = "Content_200202_1",
            },
        ["Content_200202_2"] = {
            ["ContentFR"] = "Martin, qui se présente comme le \"Roi des Récupérateurs\" de Givrelac, vous a confié quelques objets perdus. Il vous demande d’en retrouver les propriétaires.",
            ["TextMapId"] = "Content_200202_2",
            },
        ["Content_200202_3"] = {
            ["ContentFR"] = "Des étoiles en papier pliées à partir de billets périmés... Peut-être s’agit-il des effets personnels de cette vendeuse de billets.\
Elle paraît toutefois étrangement... courtoise.",
            ["TextMapId"] = "Content_200202_3",
            },
        ["Content_200203_1"] = {
            ["ContentFR"] = "La voix de la femme était rauque et brisée, sa tenue pourtant soignée couverte de poussière.\
Encore et encore, elle arrêtait les passants, cherchant désespérément quelque chose...",
            ["TextMapId"] = "Content_200203_1",
            },
        ["Content_200203_12"] = {
            ["ContentFR"] = "Depuis que vous avez quitté cette femme éplorée, vous sentez un regard peser sur vous. Il semblerait qu’elle ait encore quelque chose à dire.",
            ["TextMapId"] = "Content_200203_12",
            },
        ["Content_200203_13"] = {
            ["ContentFR"] = "Continuez de demander autour de vous — quelqu’un possède peut-être un indice.",
            ["TextMapId"] = "Content_200203_13",
            },
        ["Content_200203_14"] = {
            ["ContentFR"] = "Il semble que d’autres habitants soient au courant. Interrogez-les au sujet du médecin disparu.",
            ["TextMapId"] = "Content_200203_14",
            },
        ["Content_200203_2"] = {
            ["ContentFR"] = "La fille unique de Madame Elsa, Annie, a disparu.\
En parcourant Givrelac, gardez l’œil ouvert : quelqu’un pourrait bien ressembler à Annie.",
            ["TextMapId"] = "Content_200203_2",
            },
        ["Content_200203_3"] = {
            ["ContentFR"] = "Essayez de fouiller à l’extérieur de la ville, le docteur n’a sans doute pas encore quitté les environs. Avec un peu de chance, vous la retrouverez.",
            ["TextMapId"] = "Content_200203_3",
            },
        ["Content_200203_3_2"] = {
            ["ContentFR"] = "Les Souillés gisent à vos pieds. La femme que vous venez de sauver semble vouloir vous parler. Adressez-vous à elle.",
            ["TextMapId"] = "Content_200203_3_2",
            },
        ["Content_200203_3_3"] = {
            ["ContentFR"] = "Hors des murs, un groupe de Souillés a piégé une femme.\
Vainquez-les et mettez-la à l’abri.",
            ["TextMapId"] = "Content_200203_3_3",
            },
        ["Content_200203_4"] = {
            ["ContentFR"] = "Annie a tragiquement perdu la vie, tandis qu’Alice, la jeune fille qui avait revêtu ses vêtements, a survécu.\
Bien qu’elle ait échappé à la mort dans les montagnes enneigées, la fièvre prolongée a effacé sa mémoire.\
À présent que la vérité est révélée, il ne reste plus qu’à la transmettre à celle qui doit l’entendre.",
            ["TextMapId"] = "Content_200203_4",
            },
        ["Content_200203_5"] = {
            ["ContentFR"] = "Alice a retrouvé la mémoire.\
Il est temps d’annoncer à Madame Elsa la mort d’Annie...",
            ["TextMapId"] = "Content_200203_5",
            },
        ["Content_200203_6"] = {
            ["ContentFR"] = "Nous avons choisi de cacher la mort d’Annie. Maintenant... conduisez \"Annie\" auprès de Madame Elsa pour les réunir.",
            ["TextMapId"] = "Content_200203_6",
            },
        ["Content_200204_1"] = {
            ["ContentFR"] = "Vous avez reçu une invitation de Wells, un Chasseur de Phoxène.\
Il souhaite vous rencontrer aux Asphodèles.",
            ["TextMapId"] = "Content_200204_1",
            },
        ["Content_200204_2"] = {
            ["ContentFR"] = "Wells, le Chasseur de Phoxène, a remarqué votre talent et souhaite accomplir une mission à vos côtés.",
            ["TextMapId"] = "Content_200204_2",
            },
        ["Content_200204_3"] = {
            ["ContentFR"] = "Vous avez accepté l’invitation de Wells.\
Préparez-vous et partez avec lui pour cette mission.",
            ["TextMapId"] = "Content_200204_3",
            },
        ["Content_200204_4"] = {
            ["ContentFR"] = "Wells semble en difficulté...\
Trouvez un moyen de le protéger de la colère de son beau-père.",
            ["TextMapId"] = "Content_200204_4",
            },
        ["Content_200204_5"] = {
            ["ContentFR"] = "La résignation est depuis longtemps la toile de fond silencieuse de la vie de Wells.\
Aujourd’hui, il ne souhaite qu’une chose : boire un verre avec vous. Vous reconnaissez ce sourire — trop forcé pour être sincère. Mais que faire d’autre ? Ouvrez quelques tonneaux, trinquez avec lui, et laissez les tracas s’effacer, ne serait-ce qu’un moment.",
            ["TextMapId"] = "Content_200204_5",
            },
        ["Content_200205_1"] = {
            ["ContentFR"] = "Vous avez retrouvé le livre laissé par Brunetto et pêché un poisson de l’Île du Purgatoire. De quoi apaiser sa nostalgie un moment.\
Lorsque vous retournerez à Givrelac, pensez à tout lui remettre.",
            ["TextMapId"] = "Content_200205_1",
            },
        ["Content_200205_10"] = {
            ["ContentFR"] = "Vous avez retrouvé le livre laissé par Brunetto et pêché un poisson de l’Île du Purgatoire. De quoi apaiser sa nostalgie un moment.\
Lorsque vous retournerez à Givrelac, pensez à tout lui remettre.",
            ["TextMapId"] = "Content_200205_10",
            },
        ["Content_200205_2"] = {
            ["ContentFR"] = "De fil en aiguille, vous apprenez que Brunetto est — comme vous — originaire de l’Île du Purgatoire. Dans sa jeunesse, il rêvait d’horizons lointains, et un simple trajet sur un bateau de pêche le mena jusqu’à l’Empire... pour ne plus jamais revoir son foyer. Depuis, il survit en vendant des histoires et des illusions.\
Lorsque vous lui racontez ce qu’est devenue l’île, sa nostalgie remonte à la surface. Si l’occasion se présente, retournez là-bas pour lui : retrouvez sa demeure abandonnée et rapportez-lui un fragment de son passé.",
            ["TextMapId"] = "Content_200205_2",
            },
        ["Content_200205_3"] = {
            ["ContentFR"] = "Vous voilà de retour sur l’îÎle du Purgatoire. Le temps semble s’y être figé : le village repose encore dans l’état où les Souillés l’ont laissé. La maison de Brunetto se trouvait tout à l’est. Rendez-vous sur place — peut-être y reste-t-il quelque chose.",
            ["TextMapId"] = "Content_200205_3",
            },
        ["Content_200205_4"] = {
            ["ContentFR"] = "Dans l’ancienne maison de Brunetto, vous découvrez un coffre encore intact. Son contenu doit être précieux. Malheureusement, la clé n’est pas là. Cherchez dans les environs : si la chance vous sourit, elle n’aura pas été perdue.",
            ["TextMapId"] = "Content_200205_4",
            },
        ["Content_200205_5"] = {
            ["ContentFR"] = "Après avoir fouillé les décombres, vous trouvez une petite clé coincée dans l’angle d’un mur écroulé — parfaitement adaptée à la serrure du coffre.\
Utilisez-la et récupérez ce que Brunetto y a laissé.",
            ["TextMapId"] = "Content_200205_5",
            },
        ["Content_200205_6"] = {
            ["ContentFR"] = "Vous êtes de retour à Givrelac, les bras chargés des trésors de l’Île du Purgatoire.\
Brunetto, lui, distribue des prospectus au nom de l’Association des pêcheurs de Givrelac. Il semble enfin avoir trouvé un moyen honnête de vivre.\
Remettez-lui ce que vous avez rapporté.",
            ["TextMapId"] = "Content_200205_6",
            },
        ["Content_200205_7"] = {
            ["ContentFR"] = "Vous parvenez à ouvrir le coffre de Brunetto, mais il ne contient qu’un livre.\
À peine l’avez-vous soulevé que le bruit de la serrure attire des Souillés. Préparez-vous à vous battre.",
            ["TextMapId"] = "Content_200205_7",
            },
        ["Content_200205_8"] = {
            ["ContentFR"] = "Le lieu... la rixe... tout vous semble étrangement familier. Il y a des années, vous vous étiez disputé ici avec le petit-fils de Brunetto, une querelle qui avait tourné à la bagarre. Vous vous étiez réconciliés, mais les détails restent flous.\
Retrouvez le toit où vous aviez l’habitude de vous asseoir — peut-être que la mémoire vous reviendra.",
            ["TextMapId"] = "Content_200205_8",
            },
        ["Content_200205_9"] = {
            ["ContentFR"] = "Assis sur le toit, un autre fragment de votre vie sur l’Île du Purgatoire refait surface :\
trois miches de pain, un garçon qui hoquetait, et une poignée de main réconciliatrice. Vous étiez lié à Brunetto bien avant de le savoir.\
Pour honorer cette étrange connexion, rapportez-lui un poisson de l’île.",
            ["TextMapId"] = "Content_200205_9",
            },
        ["Content_20020605_3"] = {
            ["ContentFR"] = "Près de la maison de Buck, vous tombez sur une bouteille de lait mêlée d’alcool,\
du pop-corn enseveli sous la neige, et une petite piste d’empreintes d’enfant.\
Comme Buck ne boit jamais, ces indices devraient vous aider à réduire la liste des suspects.",
            ["TextMapId"] = "Content_20020605_3",
            },
        ["Content_20020606_5"] = {
            ["ContentFR"] = "Près du Théâtre Galea, vous repérez trois silhouettes suspectes : un ivrogne, une jeune fille curieuse et un garçon vendeur de friandises. Tous ont un lien — même ténu — avec l’alcool ou le pop-corn.\
À vous de réfléchir : qui est le plus susceptible d’avoir enivré Buck ?",
            ["TextMapId"] = "Content_20020606_5",
            },
        ["Content_200206_1"] = {
            ["ContentFR"] = "Comme à votre habitude, vous vous rendez aux Asphodèles pour consulter les nouvelles missions. Mais aujourd’hui, l’endroit semble plus animé qu’à l’ordinaire — une agitation inhabituelle flotte dans l’air.",
            ["TextMapId"] = "Content_200206_1",
            },
        ["Content_200206_2"] = {
            ["ContentFR"] = "Un client surexcité s’est hissé sur une table, débitant un flot de paroles incompréhensibles — sans pour autant sentir l’alcool.\
Discutez avec Camilla pour en savoir plus sur cet étrange personnage.",
            ["TextMapId"] = "Content_200206_2",
            },
        ["Content_200206_3"] = {
            ["ContentFR"] = "Le dramaturge Buck manie les figures de style avec une éloquence certaine, comme pour rappeler à chacun son talent littéraire.\
Pourtant, à cet instant, ce dont il a le plus besoin, c’est d’un traducteur plutôt que d’un public.\
Tendez l’oreille, et essayez de comprendre ce qu’il tente d’exprimer.",
            ["TextMapId"] = "Content_200206_3",
            },
        ["Content_200206_4"] = {
            ["ContentFR"] = "Il semble que Monsieur Buck souffre d’un visiteur nocturne indésirable. Une nouvelle mission de Chasseur de Phoxène vient donc de vous tomber dessus.\
Enquêtez autour de sa demeure.",
            ["TextMapId"] = "Content_200206_4",
            },
        ["Content_200206_5"] = {
            ["ContentFR"] = "Si quelqu’un est réellement entré chez Monsieur Buck, il aura forcément laissé des traces. Examinez les environs : vous y trouverez peut-être un indice.",
            ["TextMapId"] = "Content_200206_5",
            },
        ["Content_200206_6"] = {
            ["ContentFR"] = "D’après son voisin, aucun enfant ne s’approche de la maison de Buck — et les Asphodèles n’acceptent pas les mineurs. Il ne reste qu’un endroit où l’intrus a pu le croiser : le Théâtre Galea. Rendez-vous là-bas et cherchez un enfant correspondant au profil du Voleur d’inspiration.",
            ["TextMapId"] = "Content_200206_6",
            },
        ["Content_200206_7"] = {
            ["ContentFR"] = "Après réflexion, vous écartez l’ivrogne et la fillette. Ne reste qu’Arnaud, le garçon qui vendait bière et pop-corn devant le théâtre. Parlez-lui. Quelques questions bien placées suffiront pour révéler la vérité.",
            ["TextMapId"] = "Content_200206_7",
            },
        }
  end },
  { MinKey = "Content_200206_8", MaxKey = "Content_200315_1", Loader = function()
      return {
        ["Content_200206_8"] = {
            ["ContentFR"] = "Vous découvrez enfin pourquoi Arnaud s’est introduit en secret, au cœur de la nuit, dans la demeure de Buck.\
Mais seul le dramaturge peut décider de la suite à donner à cette affaire.\
Ramenez Arnaud et vos conclusions aux Asphodèles.",
            ["TextMapId"] = "Content_200206_8",
            },
        ["Content_200206_9"] = {
            ["ContentFR"] = "Votre déduction indique qu’un enfant s’est introduit chez Buck et a réussi à l’enivrer. Mais son identité reste inconnue.\
Parlez d’abord avec le voisin de Buck pour élargir vos recherches.",
            ["TextMapId"] = "Content_200206_9",
            },
        ["Content_200207_1"] = {
            ["ContentFR"] = "Près du monument de la Place de la Paix d’Argent, une cérémonie scolaire a lieu.\
L’élève récompensée pour ses bons résultats offrira des fleurs une fois les discours terminés. Approchez pour écouter.",
            ["TextMapId"] = "Content_200207_1",
            },
        ["Content_200207_2"] = {
            ["ContentFR"] = "Emma, une étudiante venue déposer des fleurs au monument, semble ailleurs, perdue dans ses pensées.\
Tandis qu’elle se tient seule, saisissez ce moment pour lui demander ce qui la préoccupe.",
            ["TextMapId"] = "Content_200207_2",
            },
        ["Content_200207_3"] = {
            ["ContentFR"] = "Emma s’est liée d’amitié avec une vieille Charon vivant dans les taudis.\
Mais, retenue par la cérémonie, elle ne peut la rejoindre aujourd’hui et vous confie une poupée faite de ses mains pour la lui remettre.",
            ["TextMapId"] = "Content_200207_3",
            },
        ["Content_200207_4"] = {
            ["ContentFR"] = "Dans Brumelac, vous retrouvez la vieille femme dont parlait Emma — Belinda, une médium qui apaise les âmes des Charons grâce à ses mots. Remettez-lui la poupée.",
            ["TextMapId"] = "Content_200207_4",
            },
        ["Content_200207_5"] = {
            ["ContentFR"] = "Belinda remarque que vous avez perdu quelqu’un de cher et murmure que vos chemins se recroiseront un jour.\
Elle souhaite vous offrir un présent, mais il lui faut un fil de fer imprégné de votre essence. Cherchez-en un dans la Fosse de Glevum.",
            ["TextMapId"] = "Content_200207_5",
            },
        ["Content_200207_6"] = {
            ["ContentFR"] = "Vous avez repris le fil de fer volé par Lulu, pilleuse de loot.\
Retournez à Givrelac et remettez-le à Belinda — voyons quel présent elle compte vous offrir.",
            ["TextMapId"] = "Content_200207_6",
            },
        ["Content_200207_7"] = {
            ["ContentFR"] = "Alors que vous récupériez le fil demandé par Belinda, Lulu, pilleuse de loot a surgi de nulle part pour vous le dérober. Peu importe les raisons d’une médium pour convoiter un objet marqué de votre essence : vous n’allez pas laisser passer ça. Rattrapez-la et donnez-lui une bonne leçon.",
            ["TextMapId"] = "Content_200207_7",
            },
        ["Content_200208_1"] = {
            ["ContentFR"] = "Vous avez reçu de Margie une clé dont le motif réveille de vieux souvenirs. Si votre mémoire est bonne, vous avez déjà vu une serrure similaire chez Henrik. Quelle histoire pourrait bien se cacher derrière ce verrou ?\
Rendez-vous à la Maison d’Hypnos pour en avoir le cœur net.",
            ["TextMapId"] = "Content_200208_1",
            },
        ["Content_200208_2"] = {
            ["ContentFR"] = "Une inconnue s’affaire avec aisance à nettoyer la Maison d’Hypnos. Vous le savez : à cette heure, seules des personnes liées à Henrik ou aux enfants qu’il a recueillis peuvent encore hanter ces lieux.\
Parlez-lui, et voyez si votre intuition se confirme.",
            ["TextMapId"] = "Content_200208_2",
            },
        ["Content_200208_3"] = {
            ["ContentFR"] = "Vous apprenez que Lina fut autrefois la domestique de la Maison d’Hypnos. La clé obtenue auprès de Margie semble pouvoir ouvrir le coffre où Henrik conservait ses documents les plus importants.\
Trouvez ce coffre... et soyez le témoin du dénouement de la Maison d’Hypnos.",
            ["TextMapId"] = "Content_200208_3",
            },
        ["Content_200208_4"] = {
            ["ContentFR"] = "Près du coffre laissé par Henrik, vous remarquez un petit coffret de bois finement travaillé — un objet qui n’était clairement pas là auparavant. Il détonne tellement, comme si quelqu’un avait tenu à ce qu’il soit vu, et cela ne ressemble en rien aux habitudes de Henrik. Si ce n’est pas lui qui l’a posé ici... alors qui ?\
Une seule façon de le savoir : ouvrez-le, et découvrez ce qu’il renferme.",
            ["TextMapId"] = "Content_200208_4",
            },
        ["Content_200209_1"] = {
            ["ContentFR"] = "Sur la Place de la Paix d’Argent, Docteur Luna semble tourmentée, immobile au bord de la rue. Allez voir si elle a besoin d’aide.",
            ["TextMapId"] = "Content_200209_1",
            },
        ["Content_200209_2"] = {
            ["ContentFR"] = "Vous remarquez le Docteur Luna, une liasse d’ordonnances serrée entre ses mains. Elle semble liée à l’un des indices que vous a confiés Margie. Allez lui parler.",
            ["TextMapId"] = "Content_200209_2",
            },
        ["Content_200209_3"] = {
            ["ContentFR"] = "Quelque chose vous traverse l’esprit. Si vous pouviez aider cette médecin tourmentée — qui cherche désespérément à se faire entendre — cela pourrait tout changer.",
            ["TextMapId"] = "Content_200209_3",
            },
        ["Content_200209_4"] = {
            ["ContentFR"] = "Quelque chose vous traverse l’esprit. Si vous pouviez aider cette médecin tourmentée — qui cherche désespérément à se faire entendre — cela pourrait tout changer.",
            ["TextMapId"] = "Content_200209_4",
            },
        ["Content_200209_5"] = {
            ["ContentFR"] = "La Maison d’Hypnos pourrait receler des indices, des informations utiles... voire même le remède exact qu’elle cherche.",
            ["TextMapId"] = "Content_200209_5",
            },
        ["Content_200209_6"] = {
            ["ContentFR"] = "Le remède en main, il est temps de retrouver Luna et de lui faire part de vos découvertes... quel qu’en soit le résultat.",
            ["TextMapId"] = "Content_200209_6",
            },
        ["Content_200209_7"] = {
            ["ContentFR"] = "Chasser les voyous qui la harcèlent.",
            ["TextMapId"] = "Content_200209_7",
            },
        ["Content_200210_1"] = {
            ["ContentFR"] = "Vous avez réussi à pénétrer dans le marché noir. Un marchand au regard mauvais attire votre attention. Allez lui parler pour en savoir plus.",
            ["TextMapId"] = "Content_200210_1",
            },
        ["Content_200210_2"] = {
            ["ContentFR"] = "Suivez les instructions du contrebandier Harlowe jusqu’au lieu convenu, près du Lac du Deuil, afin d’accomplir la mission.",
            ["TextMapId"] = "Content_200210_2",
            },
        ["Content_200210_3"] = {
            ["ContentFR"] = "La zone est envahie par des Souillés. Éliminez-les.",
            ["TextMapId"] = "Content_200210_3",
            },
        ["Content_200210_4"] = {
            ["ContentFR"] = "Vous avez enfin purgé la zone de toute présence des Souillés.\
Il est temps d’aller réclamer votre juste récompense auprès de Harlowe.",
            ["TextMapId"] = "Content_200210_4",
            },
        ["Content_200210_7"] = {
            ["ContentFR"] = "Des rumeurs évoquent l’existence d’un marché noir secret dans les Égouts de Givrelac, où se dérouleraient d’obscures transactions.\
En tant que Chasseur de Phoxène vigilant et aguerri, il est de votre devoir d’aller y voir de plus près.",
            ["TextMapId"] = "Content_200210_7",
            },
        ["Content_200211_1"] = {
            ["ContentFR"] = "Une jeune Sola semble persuadée d’être une Charon. Allez voir de quoi il retourne à Givrelac.",
            ["TextMapId"] = "Content_200211_1",
            },
        ["Content_200211_2"] = {
            ["ContentFR"] = "Faye, humiliée par ses camarades, s’est enfuie en pleurant, les mains sur les oreilles. Retrouvez la fillette et tentez de la réconforter.",
            ["TextMapId"] = "Content_200211_2",
            },
        ["Content_200211_3"] = {
            ["ContentFR"] = "Après avoir échangé quelques mots avec Faye, vous découvrez comment ses camarades la maltraitent. Il est temps de lui apprendre à se défendre : allez donner une leçon à ces élèves cruels.",
            ["TextMapId"] = "Content_200211_3",
            },
        ["Content_200211_4"] = {
            ["ContentFR"] = "Après avoir échangé quelques mots avec Faye, vous découvrez comment ses camarades la maltraitent. Il est temps de lui apprendre à se défendre : allez donner une leçon à ces élèves cruels.",
            ["TextMapId"] = "Content_200211_4",
            },
        ["Content_200211_5"] = {
            ["ContentFR"] = "Grâce à votre aide, Faye a enfin trouvé le courage de répondre à ses harceleurs.\
Furieux, ils ont rameuté des complices pour en découdre — en vain.\
Après avoir dispersé cette bande de lâches, retournez voir Faye pour prendre de ses nouvelles.",
            ["TextMapId"] = "Content_200211_5",
            },
        ["Content_200212_2"] = {
            ["ContentFR"] = "À Givrelac, un mineur nerveux attire votre attention : un sac de minerai, couvert de traces suspectes, gît à ses pieds. Quelque chose cloche.\
Mieux vaut en informer Kevin, des Veilleurs, posté près de la porte de la cité.",
            ["TextMapId"] = "Content_200212_2",
            },
        ["Content_200212_3"] = {
            ["ContentFR"] = "Comme prévu, Kevin a lui aussi reçu un rapport au sujet de cette affaire.\
En {性别:citoyen dévoué|citoyenne dévouée} de Givrelac, vous acceptez de l’accompagner jusqu’à l’endroit où se trouvait Larry afin d’enquêter.",
            ["TextMapId"] = "Content_200212_3",
            },
        ["Content_200212_4"] = {
            ["ContentFR"] = "À la vue de Kevin et de vous, Larry, membre des Veilleurs, perd ses moyens et attaque sous le coup de la panique. Vainquez-le pour calmer la situation.",
            ["TextMapId"] = "Content_200212_4",
            },
        ["Content_200212_5"] = {
            ["ContentFR"] = "Vous parvenez à maîtriser Larry, qui retrouve enfin son calme.\
Discutez avec lui, aux côtés de Kevin, pour découvrir le fin mot de l’histoire.",
            ["TextMapId"] = "Content_200212_5",
            },
        ["Content_200212_6"] = {
            ["ContentFR"] = "Ce fragment de Phoxène est taché de sang... Et Larry, avec sa voix tremblante et son regard fuyant, n’est guère rassurant. Il prétend n’être qu’un simple mineur, mais affirme pourtant posséder tout un sac de Phoxène.\
Quelque chose cloche. Mieux vaut enquêter vous-même sur l’origine réelle de cette pierre.",
            ["TextMapId"] = "Content_200212_6",
            },
        ["Content_200212_7"] = {
            ["ContentFR"] = "Ce sac de Phoxène a clairement une provenance douteuse. Peu importe dans quelle poche il finit, il ne deviendra jamais un bien \"propre\"... alors pourquoi ne serait-il pas dans la vôtre ? Retournez voir Larry.",
            ["TextMapId"] = "Content_200212_7",
            },
        ["Content_200212_8"] = {
            ["ContentFR"] = "L’esprit de Larry vacille. Son ego fragile et la culpabilité qui le ronge depuis son crime l’ont déchiré intérieurement. Face à l’effondrement de ses illusions, il se jette sur vous, désespéré.\
Défendez-vous — et forcez-le à affronter la vérité qu’il refuse de voir.",
            ["TextMapId"] = "Content_200212_8",
            },
        ["Content_200213_1"] = {
            ["ContentFR"] = "Vous séjournez à Givrelac depuis un certain temps. Malgré le froid mordant, Margie continue d’y apporter chaleur et espoir, distribuant vivres et vêtements aux plus démunis.\
Depuis la chasse au voleur menée à ses côtés dans les égouts, vous n’avez guère eu l’occasion de lui reparler.\
Allez donc lui donner de vos nouvelles.",
            ["TextMapId"] = "Content_200213_1",
            },
        ["Content_200213_2"] = {
            ["ContentFR"] = "Comme l’a dit Margie, les choses les plus dérisoires cachent parfois la plus grande valeur. Même les poubelles de la ville semblent abriter des récits oubliés.\
Les trois objets confiés par Margie — une ordonnance, une boîte d’étoiles en papier et une clé — sont autant de balises pointant chacune vers sa propre histoire.\
Suivez ces indices et découvrez les secrets qu’ils renferment !",
            ["TextMapId"] = "Content_200213_2",
            },
        ["Content_200213_3"] = {
            ["ContentFR"] = "Après avoir levé le voile sur les mystères de ces trois objets, votre regard sur Givrelac a changé.\
Retournez voir Margie dans le quartier des taudis.",
            ["TextMapId"] = "Content_200213_3",
            },
        ["Content_200213_4"] = {
            ["ContentFR"] = "Vous avez percé le secret des trois objets. Allez raconter vos découvertes à Margie.",
            ["TextMapId"] = "Content_200213_4",
            },
        ["Content_200215_1"] = {
            ["ContentFR"] = "À force de discuter, vous découvrez que Marcus est un cuisinier avide d’expérimenter de nouvelles recettes. Vous connaissez un bon coin de pêche près du Lac du Deuil.\
Allez y jeter votre ligne et tentez de ramener un poisson de choix.",
            ["TextMapId"] = "Content_200215_1",
            },
        ["Content_200215_2"] = {
            ["ContentFR"] = "Pêchez une Phoxénotruite pour Marcus.\
Cette fois, il recherche une saveur bien précise — espérons que sa recette soit enfin un succès !",
            ["TextMapId"] = "Content_200215_2",
            },
        ["Content_200215_3"] = {
            ["ContentFR"] = "Vous avez enfin réuni les ingrédients nécessaires à la marinade. Apportez-les à Marcus.",
            ["TextMapId"] = "Content_200215_3",
            },
        ["Content_200215_4"] = {
            ["ContentFR"] = "Bien que sa cuisine soit toujours difficile à avaler, vous avez accepté de devenir son partenaire culinaire.\
Voyons quelle nouvelle création il mijote cette fois.",
            ["TextMapId"] = "Content_200215_4",
            },
        ["Content_200215_41"] = {
            ["ContentFR"] = "Vous avez des doutes... mais après tout, vous avez pêché ces poissons vous-même. Autant goûter — à contrecœur — la cuisine de Marcus.",
            ["TextMapId"] = "Content_200215_41",
            },
        ["Content_200215_5"] = {
            ["ContentFR"] = "Excellent travail ! Personne ne manie la canne à pêche mieux que vous.\
Apportez donc la Phoxénotruite fraîchement pêchée à Marcus.",
            ["TextMapId"] = "Content_200215_5",
            },
        ["Content_200215_6"] = {
            ["ContentFR"] = "Excellent travail ! Personne ne manie la canne à pêche mieux que vous.\
Apportez donc la Phoxénotruite fraîchement pêchée à Marcus.",
            ["TextMapId"] = "Content_200215_6",
            },
        ["Content_200215_7"] = {
            ["ContentFR"] = "Cela fait un moment que vous n’avez pas revu Marcus.\
Vous vous demandez comment se porte ce cuisinier aussi courageux qu’obstiné. On dit qu’il traîne souvent près des portes de Givrelac — allez donc prendre de ses nouvelles.",
            ["TextMapId"] = "Content_200215_7",
            },
        ["Content_200215_8"] = {
            ["ContentFR"] = "Marcus est assis sur un banc près des portes de Givrelac. Allez lui parler.",
            ["TextMapId"] = "Content_200215_8",
            },
        ["Content_200216_1"] = {
            ["ContentFR"] = "On raconte qu’un coffre suspect se trouve à l’extérieur de Givrelac.\
Allez voir de quoi il retourne.",
            ["TextMapId"] = "Content_200216_1",
            },
        ["Content_200216_2"] = {
            ["ContentFR"] = "Vous trouvez bien un coffre au bord de la route — à première vue, rien de particulier. Autant l’ouvrir pour en avoir le cœur net.",
            ["TextMapId"] = "Content_200216_2",
            },
        ["Content_200216_3"] = {
            ["ContentFR"] = "Alors que vous vous apprêtez à l’ouvrir, trois hommes surgissent du coffre, se proclamant « le trio de l’Empire » et revendiquant le butin.\
Impossible de discuter : il va falloir régler ça autrement.",
            ["TextMapId"] = "Content_200216_3",
            },
        ["Content_200216_4"] = {
            ["ContentFR"] = "Après avoir calmé le trio de l’Empire, il semble qu’ils aient quelque chose à vous dire.",
            ["TextMapId"] = "Content_200216_4",
            },
        ["Content_200217_1"] = {
            ["ContentFR"] = "Dean, le marchand de spiritueux posté à l’extérieur des Asphodèles, semble avoir quelques griefs contre Camilla. Allez découvrir de quoi il retourne.",
            ["TextMapId"] = "Content_200217_1",
            },
        ["Content_200218_1"] = {
            ["ContentFR"] = "Vous voilà de retour en ce lieu silencieux.\
Même aujourd’hui, vous croyez encore entendre les dernières paroles tremblantes de Psyche flotter dans l’air glacé.\
Une femme mystérieuse murmure une prière — une psalmodie douce et funèbre, pareille à la compassion d’une mère divine.\
Et dans ce murmure, l’âme endeuillée qui hante ces falaises semble enfin trouver la paix...",
            ["TextMapId"] = "Content_200218_1",
            },
        ["Content_200219_1"] = {
            ["ContentFR"] = "Aux abords de Givrelac, les trains vont et viennent sans fin, leurs sifflets saluant les voyageurs qui arrivent et ceux qui partent.\
Mais aujourd’hui, quelque chose semble se tramer près du guichet — allez y jeter un œil.",
            ["TextMapId"] = "Content_200219_1",
            },
        ["Content_200219_2"] = {
            ["ContentFR"] = "Un marchand venu d’ailleurs semble en difficulté. Allez lui parler.",
            ["TextMapId"] = "Content_200219_2",
            },
        ["Content_200219_3"] = {
            ["ContentFR"] = "En bon Chasseur de Phoxène, vous ne sauriez ignorer un voyageur en détresse.\
Confrontez la vendeuse désagréable et réglez ce différend.",
            ["TextMapId"] = "Content_200219_3",
            },
        ["Content_200219_4"] = {
            ["ContentFR"] = "Le vieux récupérateur ne cesse de vous observer, comme s’il cherchait le courage de vous adresser la parole.\
Approchez-vous — il pourrait avoir quelque chose à dire.",
            ["TextMapId"] = "Content_200219_4",
            },
        ["Content_200219_5"] = {
            ["ContentFR"] = "Aidez la marchande étrangère à terminer son pliage — un souhait silencieux, né de mains attentives.",
            ["TextMapId"] = "Content_200219_5",
            },
        ["Content_200220_1"] = {
            ["ContentFR"] = "En bon Chasseur de Phoxène, vous partez une nouvelle fois vers les Asphodèles afin d’y accepter de nouvelles missions. Peut-être y trouverez-vous quelque requête intrigante.",
            ["TextMapId"] = "Content_200220_1",
            },
        ["Content_200220_2"] = {
            ["ContentFR"] = "Près du tableau des missions, un domestique inconnu marmonne pour lui-même. Approchez-vous et engagez la conversation.",
            ["TextMapId"] = "Content_200220_2",
            },
        ["Content_200220_3"] = {
            ["ContentFR"] = "Après avoir formé une équipe de Chasseurs de Phoxène avec l’Étranger, Snow propose de décider du nom du groupe à travers une petite épreuve.",
            ["TextMapId"] = "Content_200220_3",
            },
        ["Content_200220_4"] = {
            ["ContentFR"] = "Après la création de votre équipe, Snow suggère une épreuve pour déterminer qui en choisira le nom.\
D’après elle, Luno, l’exploratrice postée près du Sanctuaire, connaît bien ce genre de concours. Allez lui parler.",
            ["TextMapId"] = "Content_200220_4",
            },
        ["Content_200220_5"] = {
            ["ContentFR"] = "Sous l’œil attentif de Luno, l’exploratrice, la première manche est sur le point de commencer !\
Rendez-vous à l’endroit qu’elle a marqué pour débuter le défi.",
            ["TextMapId"] = "Content_200220_5",
            },
        ["Content_200220_6"] = {
            ["ContentFR"] = "Le défi commence ! Suivez la piste de cercles lumineux indiquée par Luno, l’exploratrice jusqu’à la ligne d’arrivée.",
            ["TextMapId"] = "Content_200220_6",
            },
        ["Content_200220_7"] = {
            ["ContentFR"] = "Sous la supervision de Luno, l’exploratrice, la seconde manche du défi est prête à débuter. Rendez-vous à l’endroit indiqué pour commencer.",
            ["TextMapId"] = "Content_200220_7",
            },
        ["Content_200220_8"] = {
            ["ContentFR"] = "Le défi commence ! Ajustez votre visée et faites éclater les ballons fabriqués par Luno, la forgeronne.",
            ["TextMapId"] = "Content_200220_8",
            },
        ["Content_200220_9"] = {
            ["ContentFR"] = "Le défi est terminé ! Vous avez triomphé de l’Étranger et remporté la victoire.\
Il ne vous reste plus qu’à trouver un nom digne de votre nouvelle équipe de Chasseurs de Phoxène.",
            ["TextMapId"] = "Content_200220_9",
            },
        ["Content_200221_1"] = {
            ["ContentFR"] = "Près du panneau des missions aux Asphodèles, une jeune érudite marmonne pour elle-même, visiblement troublée. Peut-être aurait-elle besoin d’un coup de main.",
            ["TextMapId"] = "Content_200221_1",
            },
        ["Content_200221_2"] = {
            ["ContentFR"] = "Après avoir accepté d’aider Shirley à trouver un sujet intéressant, vous décidez d’explorer des lieux souvent négligés.",
            ["TextMapId"] = "Content_200221_2",
            },
        ["Content_200221_3"] = {
            ["ContentFR"] = "Contre toute attente, vous faites de petites découvertes dans les égouts. Il semble que l’inspiration se cache vraiment dans les recoins oubliés. Les remparts valent peut-être le détour.",
            ["TextMapId"] = "Content_200221_3",
            },
        ["Content_200221_4"] = {
            ["ContentFR"] = "Un simple détour s’est révélé plus fructueux que prévu. Shirley vous attend aux portes de Givrelac, une récompense à la main.",
            ["TextMapId"] = "Content_200221_4",
            },
        ["Content_200221_5"] = {
            ["ContentFR"] = "Il ne manque jamais de personnes dans le besoin, et ceux qui tendent la main reçoivent souvent bien plus qu’ils ne l’espéraient.\
Rendez-vous aux Asphodèles et voyez qui pourrait avoir besoin d’aide. La jeune Shirley, là-bas dans l’ombre, semble particulièrement anxieuse.",
            ["TextMapId"] = "Content_200221_5",
            },
        ["Content_200222_1"] = {
            ["ContentFR"] = "Un projet \"récréatif\" installé dans les Égouts de Givrelac... voilà qui inspire peu confiance. Mais l’homme nommé Dutton semble étonnamment sûr de lui.\
Puisque c’est gratuit, autant aller voir quelle folie il a imaginée.",
            ["TextMapId"] = "Content_200222_1",
            },
        ["Content_200222_2"] = {
            ["ContentFR"] = "Contre toute attente, Dutton a recréé dans les égouts une version du toboggan aquatique de Luca. À la vue du conduit dégoulinant d’humidité, vous décidez sagement de ne pas servir de cobaye : laissez donc Dutton vous en faire la démonstration.",
            ["TextMapId"] = "Content_200222_2",
            },
        ["Content_200222_3"] = {
            ["ContentFR"] = "Dutton n’est pas apparu à la sortie prévue. À en juger par les chocs résonnant dans les tuyaux, son état doit être préoccupant. Mieux vaut le retrouver rapidement.",
            ["TextMapId"] = "Content_200222_3",
            },
        ["Content_200222_4"] = {
            ["ContentFR"] = "Vous finissez par retrouver Dutton. Au vu du trajet, qu’il soit encore en vie tient presque du miracle. Espérons que cette mésaventure ne lui ôtera pas son enthousiasme pour développer d’autres attractions dans Brumelac.",
            ["TextMapId"] = "Content_200222_4",
            },
        ["Content_200223_1"] = {
            ["ContentFR"] = "Theo — un jeune chercheur autoproclamé — brûle de comprendre le moindre détail de la vie des Charons. Et vous voilà désigné... comme son tout premier sujet d’étude.",
            ["TextMapId"] = "Content_200223_1",
            },
        ["Content_200224_1"] = {
            ["ContentFR"] = "Vous recroisez Theo près de l’entrée des Égouts de Givrelac. Allez discuter avec lui : il semble avoir trouvé un nouveau sujet d’observation.",
            ["TextMapId"] = "Content_200224_1",
            },
        ["Content_200224_2"] = {
            ["ContentFR"] = "Pour une raison qui lui appartient, Theo s’est découvert une passion soudaine pour les rats des égouts. À sa demande insistante, vous acceptez de l’accompagner pour localiser leur nid.",
            ["TextMapId"] = "Content_200224_2",
            },
        ["Content_200224_3"] = {
            ["ContentFR"] = "Au détour d’un couloir, vous repérez l’un des rats qu’il souhaite étudier. En le suivant, vous finirez sûrement par trouver le nid.",
            ["TextMapId"] = "Content_200224_3",
            },
        ["Content_200224_4"] = {
            ["ContentFR"] = "Theo parvient enfin à observer les rats de près... Hélas, ils ne ressemblent en rien aux petites créatures courageuses et solidaires qu’il imaginait. Agressifs, ils vous prennent pour cible.\
Vous ordonnez à Theo de fuir et vous préparez à les affronter {性别:seul|seule}.",
            ["TextMapId"] = "Content_200224_4",
            },
        ["Content_200224_5"] = {
            ["ContentFR"] = "Les rats dispersés, Theo peut compléter son étude... et il a eu un aperçu du quotidien des Chasseurs de Phoxène. Allez le retrouver : il aura sans doute beaucoup à dire.",
            ["TextMapId"] = "Content_200224_5",
            },
        ["Content_200225_1"] = {
            ["ContentFR"] = "Vous retrouvez Theo près de la Maison d’Hypnos. Allez lui parler : une nouvelle curiosité semble l’habiter.",
            ["TextMapId"] = "Content_200225_1",
            },
        ["Content_200225_2"] = {
            ["ContentFR"] = "Cette fois, Theo veut mieux comprendre la vie des Charons. Plutôt que de longues explications, mieux vaut lui montrer la réalité : emmenez-le parcourir la cité et photographiez le quotidien des Charons.",
            ["TextMapId"] = "Content_200225_2",
            },
        ["Content_200225_3"] = {
            ["ContentFR"] = "En observant les Charons vivre simplement, Theo réalise qu’ils ne sont guère différents des Solariens — des gens ordinaires, loin des monstres dépeints par les adultes. Plein d’enthousiasme, il court vers la Maison d’Hypnos pour discuter avec ses habitants. Mais vous connaissez la vérité : la maison est vide désormais.\
Il est peut-être temps de lui dévoiler la seconde raison pour laquelle les Charons sont rejetés... la Dégradation.",
            ["TextMapId"] = "Content_200225_3",
            },
        ["Content_200227_1"] = {
            ["ContentFR"] = "Le théâtre immersif, une nouvelle forme scénique venue de Luca, fait son entrée à Givrelac. Le Théâtre Galea recrute des volontaires pour cette expérience artistique.\
Si vous avez un moment, allez donc discuter avec un membre de la troupe.",
            ["TextMapId"] = "Content_200227_1",
            },
        ["Content_200228_1"] = {
            ["ContentFR"] = "Luno, la forgeronne, vous interpelle soudain. Elle semble avoir quelque chose d’important à vous dire. Passez la voir dès que vous en avez l’occasion.",
            ["TextMapId"] = "Content_200228_1",
            },
        ["Content_200228_2"] = {
            ["ContentFR"] = "Avant toute aventure, mieux vaut se préparer — un principe que tout novice devrait suivre. Retournez au Sanctuaire et posez les bases de votre première expédition.",
            ["TextMapId"] = "Content_200228_2",
            },
        ["Content_200228_3"] = {
            ["ContentFR"] = "Une arme est la compagne la plus fidèle de tout voyageur.\
Sous la direction de Luno, voyez si vous pouvez en forger une qui vous convienne.",
            ["TextMapId"] = "Content_200228_3",
            },
        ["Content_200229_1"] = {
            ["ContentFR"] = "Près du Sanctuaire, quelqu’un semble vous appeler. Si vous avez un instant, suivez la voix et voyez ce qu’on attend de vous.",
            ["TextMapId"] = "Content_200229_1",
            },
        ["Content_200229_2"] = {
            ["ContentFR"] = "Luno, la forgeronne a obtenu une nouvelle recette de teinture et souhaite que vous la testiez. Connaissant la réputation... fluctuante d’Amiette, il est normal que vous soyez un peu {性别:inquiet|inquiète} du résultat.",
            ["TextMapId"] = "Content_200229_2",
            },
        ["Content_200229_3"] = {
            ["ContentFR"] = "Suivez les instructions de la recette et menez l’opération jusqu’au bout — pour la noble cause de l’esthétique, bien sûr.",
            ["TextMapId"] = "Content_200229_3",
            },
        ["Content_200230_1"] = {
            ["ContentFR"] = "Un homme aux gestes théâtraux vous barre la route : il affirme que son « professeur » vous attend. Suivez-le et voyez ce qu’il en est.",
            ["TextMapId"] = "Content_200230_1",
            },
        ["Content_200230_2"] = {
            ["ContentFR"] = "Violetta vous a donné l’adresse approximative de l’expéditeur. Mieux vaut interroger les habitants du quartier.",
            ["TextMapId"] = "Content_200230_2",
            },
        ["Content_200230_3"] = {
            ["ContentFR"] = "Un soldat de garde s’acharne sur un vieux phonographe. Donnez-lui un coup de main : il pourrait, en retour, vous livrer quelques renseignements.",
            ["TextMapId"] = "Content_200230_3",
            },
        ["Content_200230_4"] = {
            ["ContentFR"] = "Le phonographe fonctionne à nouveau. Il est temps que le soldat tienne parole.",
            ["TextMapId"] = "Content_200230_4",
            },
        ["Content_200230_5"] = {
            ["ContentFR"] = "Ce fan de Violetta a complètement mal interprété votre venue. Il va falloir le calmer — même si cela passe par des moyens un peu musclés.",
            ["TextMapId"] = "Content_200230_5",
            },
        ["Content_200230_6"] = {
            ["ContentFR"] = "Ce fan exalté ne réalise pas qu’il importune son idole. Aidez-le à regarder la réalité en face.",
            ["TextMapId"] = "Content_200230_6",
            },
        ["Content_200230_7"] = {
            ["ContentFR"] = "L’affaire semble, pour l’instant, réglée. Retournez voir Violetta et racontez-lui toute l’histoire.",
            ["TextMapId"] = "Content_200230_7",
            },
        ["Content_200231_1"] = {
            ["ContentFR"] = "Un garçon prénommé Lars vous demande de l’aide. Écoutez ce qu’il a à vous dire.",
            ["TextMapId"] = "Content_200231_1",
            },
        ["Content_200231_2"] = {
            ["ContentFR"] = "Suivez Lars jusqu’à Brumelac pour trouver la maison de Donat.",
            ["TextMapId"] = "Content_200231_2",
            },
        ["Content_200231_3"] = {
            ["ContentFR"] = "Donat n’est pas chez lui. Lars se souvient qu’il parlait de retourner à la Fosse de Glevum — allez l’y chercher.",
            ["TextMapId"] = "Content_200231_3",
            },
        ["Content_200231_4"] = {
            ["ContentFR"] = "Donat tient à s’enfoncer plus loin dans la mine. Vous avez promis à Lars de veiller sur lui : escortez-le tout en assurant sa sécurité.",
            ["TextMapId"] = "Content_200231_4",
            },
        ["Content_200231_5"] = {
            ["ContentFR"] = "Donat finit par vous confier son \"crime\" — qui semble lié à une affaire remontant à seize ans.",
            ["TextMapId"] = "Content_200231_5",
            },
        ["Content_200231_6"] = {
            ["ContentFR"] = "Des Souillés rôdent encore dans les parages. Nettoyez la zone avant de poursuivre.",
            ["TextMapId"] = "Content_200231_6",
            },
        ["Content_200232_1"] = {
            ["ContentFR"] = "Un chant inquiétant vous parvient d’un coin de rue. Vous prenez votre courage à deux mains et décidez d’en remonter la source.",
            ["TextMapId"] = "Content_200232_1",
            },
        ["Content_200232_2"] = {
            ["ContentFR"] = "Vous découvrez l’origine du chant : une curieuse caisse en bois. Peut-être pourriez-vous lui demander pourquoi elle entonne ses mélodies la nuit.",
            ["TextMapId"] = "Content_200232_2",
            },
        ["Content_200232_3"] = {
            ["ContentFR"] = "Une Chasseuse de Phoxène prénommée Giselle se montre très intriguée par votre histoire. Elle accepte de se renseigner pour vous, à condition que vous lui cueilliez quelques herbes.",
            ["TextMapId"] = "Content_200232_3",
            },
        ["Content_200232_4"] = {
            ["ContentFR"] = "Vous avez recueilli les herbes demandées. Apportez-les aux Asphodèles et profitez-en pour interroger Camilla à propos de Giselle.",
            ["TextMapId"] = "Content_200232_4",
            },
        ["Content_200232_5"] = {
            ["ContentFR"] = "Ce que vous avez vécu défie l’entendement. Retournez chez Giselle et demandez-lui franchement des explications.",
            ["TextMapId"] = "Content_200232_5",
            },
        ["Content_200232_6"] = {
            ["ContentFR"] = "Des Souillés se sont attroupés autour des herbes. Vous n’avez d’autre choix que de les éliminer d’abord.",
            ["TextMapId"] = "Content_200232_6",
            },
        ["Content_200233_1"] = {
            ["ContentFR"] = "Les événements récents convergent vers une affaire d’enlèvement et d’incendie survenue il y a seize ans. Votre instinct vous souffle que tout cela est intimement lié — faites le point sur vos indices et tentez d’y voir plus clair.",
            ["TextMapId"] = "Content_200233_1",
            },
        ["Content_200233_2"] = {
            ["ContentFR"] = "Si votre intuition est juste, Giselle est l’instigatrice de toute cette mise en scène — y compris de \"l’enlèvement\" de l’élève de Violetta. Rendez-vous au lieu convenu et découvrez ce qu’elle prépare.",
            ["TextMapId"] = "Content_200233_2",
            },
        ["Content_200233_3"] = {
            ["ContentFR"] = "Les paroles de Violetta ont poussé Giselle au bord du gouffre. Arrêtez-la avant qu’elle ne commette l’irréparable.",
            ["TextMapId"] = "Content_200233_3",
            },
        ["Content_200233_4"] = {
            ["ContentFR"] = "Violetta reconnaît tacitement la justesse de vos déductions, même si certains détails restent flous. Avant d’aller plus loin, elle souhaite que vous l’accompagniez en un lieu qui lui tient à cœur.",
            ["TextMapId"] = "Content_200233_4",
            },
        ["Content_200233_5"] = {
            ["ContentFR"] = "La fin que vous avez choisie n’est pas celle qu’auraient souhaitée les morts, et vous décidez d’aider Violetta à taire la vérité. L’histoire n’est pas achevée : <I>Putini</> continue d’être joué, soir après soir, au théâtre de Givrelac.",
            ["TextMapId"] = "Content_200233_5",
            },
        ["Content_200233_6"] = {
            ["ContentFR"] = "Quoi qu’il en soit, la vérité mérite de voir le jour, et les morts n’ont pas à porter des fautes qui ne sont pas les leurs. Violetta accepte votre choix et décide de mettre un point final à tout cela avec une représentation d’adieu.",
            ["TextMapId"] = "Content_200233_6",
            },
        ["Content_200234_1"] = {
            ["ContentFR"] = "Vous croisez de nouveau le chat errant qui rôde près de la place. Il semble vous avoir reconnu : de loin, il miaule dans votre direction.",
            ["TextMapId"] = "Content_200234_1",
            },
        ["Content_200234_2"] = {
            ["ContentFR"] = "Le chat s’élance vers le Sanctuaire, puis se retourne pour vous regarder, comme s’il vous invitait à le suivre. Puisqu’il insiste... allez voir où il vous mène.",
            ["TextMapId"] = "Content_200234_2",
            },
        ["Content_200235_1"] = {
            ["ContentFR"] = "Accomplir une mission : [Précaution].",
            ["TextMapId"] = "Content_200235_1",
            },
        ["Content_200235_2"] = {
            ["ContentFR"] = "Accomplir une mission du Manuel des Vagabonds de la Nuit.",
            ["TextMapId"] = "Content_200235_2",
            },
        ["Content_200236_1"] = {
            ["ContentFR"] = "Terminer le Mandat scellé de Truffle et Filbert pour obtenir leurs Fragments de pensée.",
            ["TextMapId"] = "Content_200236_1",
            },
        ["Content_200236_2"] = {
            ["ContentFR"] = "Dans l’onglet Arsenal, utiliser les Fragments de pensée de Truffle et Filbert pour compléter la Réminiscence et débloquer le personnage.",
            ["TextMapId"] = "Content_200236_2",
            },
        ["Content_200301_1"] = {
            ["ContentFR"] = "Un vieil homme aux airs de prophète vous arrête en chemin. Entre deux phrases sibyllines, il vous confie une mission.",
            ["TextMapId"] = "Content_200301_1",
            },
        ["Content_200301_2"] = {
            ["ContentFR"] = "À la lisière de la Mer de Poussière, les ennuis ne tardent pas à vous trouver.",
            ["TextMapId"] = "Content_200301_2",
            },
        ["Content_200301_3"] = {
            ["ContentFR"] = "Une personne que vous n’auriez jamais pensé voir ici se présente à vous. Avec le recul... ce n’est peut-être pas si surprenant.",
            ["TextMapId"] = "Content_200301_3",
            },
        ["Content_200301_4"] = {
            ["ContentFR"] = "Après votre échange, vous décidez d’escorter le vieil homme jusqu’à la Mer de Poussière. Le lieu est d’une dangerosité extrême — préparez-vous.",
            ["TextMapId"] = "Content_200301_4",
            },
        ["Content_200301_5"] = {
            ["ContentFR"] = "Peu après votre entrée dans la Mer de Poussière, vous êtes pris pour cible. Une fois les ennemis repoussés, la destination se dessine à l’horizon. Accordez-vous un bref répit, puis poursuivez votre route.",
            ["TextMapId"] = "Content_200301_5",
            },
        ["Content_200301_6"] = {
            ["ContentFR"] = "Après bien des péripéties, vous parvenez enfin à conduire le vieil homme à destination. Il semble avoir encore quelque chose à vous dire — allez lui parler.",
            ["TextMapId"] = "Content_200301_6",
            },
        ["Content_200301_7"] = {
            ["ContentFR"] = "Pour une raison inconnue, un groupe de Bi’an vous attaque soudainement. Repoussez-les.",
            ["TextMapId"] = "Content_200301_7",
            },
        ["Content_200302_1"] = {
            ["ContentFR"] = "En passant devant Éternel Printemps, vous surprenez au loin une discussion animée. Il s’agit des affaires d’un Tisse-Étoiles à Huaxu, rendues précaires par le Fléau de Zhuyin. Si vous avez un peu de temps devant vous, prêtez main-forte à Zhao Qian.",
            ["TextMapId"] = "Content_200302_1",
            },
        ["Content_200302_2"] = {
            ["ContentFR"] = "Après votre échange, vous acceptez d’accompagner ce Tisse-Étoiles quelque temps. Commencez par l’aider à récupérer la première cargaison.",
            ["TextMapId"] = "Content_200302_2",
            },
        ["Content_200302_3"] = {
            ["ContentFR"] = "En chemin, plusieurs Bi’an obscurs barrent votre route. Éliminez-les.",
            ["TextMapId"] = "Content_200302_3",
            },
        ["Content_200302_4"] = {
            ["ContentFR"] = "Une fois les fruits confits destinés aux Monts Vidofnir récupérés, Zhao Qian vous demande de l’accompagner chercher la seconde cargaison. Après une courte pause, vous reprenez la route.",
            ["TextMapId"] = "Content_200302_4",
            },
        ["Content_200302_5"] = {
            ["ContentFR"] = "Les marchandises sont prêtes. Il ne reste plus qu’à les transporter jusqu’au Quai-aux-Étoiles.",
            ["TextMapId"] = "Content_200302_5",
            },
        ["Content_200302_6"] = {
            ["ContentFR"] = "Le point de chargement du Quai-aux-Étoiles est envahi par de petits animaux. Chassez-les, terminez le déchargement, puis attendez l’arrivée du navire de fret avec Zhao Qian.",
            ["TextMapId"] = "Content_200302_6",
            },
        ["Content_200303_1"] = {
            ["ContentFR"] = "Un homme étrange vous arrête au marché noir. Il semble connaître l’origine de cette voix qui résonne dans votre esprit. Autant écouter ce qu’il a à dire.",
            ["TextMapId"] = "Content_200303_1",
            },
        ["Content_200303_2"] = {
            ["ContentFR"] = "Son histoire vous paraît suspecte... mais une chasse au trésor ne coûte rien. Suivez ses indications — pour voir où elles mènent.",
            ["TextMapId"] = "Content_200303_2",
            },
        ["Content_200303_3"] = {
            ["ContentFR"] = "otre première exploration a porté ses fruits. Que réserve la suivante ? Rendez-vous au lieu désigné par l’Oracle.",
            ["TextMapId"] = "Content_200303_3",
            },
        ["Content_200303_4"] = {
            ["ContentFR"] = "Vous envoyer dans un endroit aussi dangereux ne peut être un hasard. Il est temps de comprendre ce que cherche vraiment Ren Wu.",
            ["TextMapId"] = "Content_200303_4",
            },
        ["Content_200303_5"] = {
            ["ContentFR"] = "Ren Wu surgit soudain et s’empare de votre \"prise\". Quelque chose ne tourne pas rond... Il doit exister un moyen de récupérer ce qui vous revient.",
            ["TextMapId"] = "Content_200303_5",
            },
        ["Content_200304_1"] = {
            ["ContentFR"] = "Snow a entendu parler d’une échoppe de gâteaux à l’osmanthus réputée pour leur saveur authentique, située sur les quais du Port-des-Brumes. Accompagnez-la pour aller y jeter un œil.",
            ["TextMapId"] = "Content_200304_1",
            },
        ["Content_200304_10"] = {
            ["ContentFR"] = "Après avoir raconté le passé de Yuming et Kezhou, l’ancien prend congé. Profitez-en pour transmettre à Yuming le message que Kezhou vous avait confié.",
            ["TextMapId"] = "Content_200304_10",
            },
        ["Content_200304_2"] = {
            ["ContentFR"] = "Vous apercevez l’échoppe de gâteaux à l’osmanthe dont Snow vous a parlé. Allez faire la queue.",
            ["TextMapId"] = "Content_200304_2",
            },
        ["Content_200304_3"] = {
            ["ContentFR"] = "Deux enfants terminent l’énigme, reçoivent leurs gâteaux à l’osmanthe et repartent ravis. En les observant, vous décidez de tenter vous aussi l’épreuve.",
            ["TextMapId"] = "Content_200304_3",
            },
        ["Content_200304_4"] = {
            ["ContentFR"] = "À peine avez-vous reçu votre gâteau qu’une rumeur vous parvient : Li aux gâteaux d’osmanthe serait en danger. Accompagnez Li Huan pour partir à sa recherche.",
            ["TextMapId"] = "Content_200304_4",
            },
        ["Content_200304_5"] = {
            ["ContentFR"] = "En suivant Li Huan, vous retrouvez Li aux gâteaux d’osmanthe, mais découvrez qu’il est encerclé avec les deux enfants par des Bi’an obscurs. Vite, portez-leur secours.",
            ["TextMapId"] = "Content_200304_5",
            },
        ["Content_200304_6"] = {
            ["ContentFR"] = "Alors que vous combattez les Bi’an obscurs, un allié inattendu apparaît : Yuming. Grâce à son aide, les ennemis sont rapidement repoussés. Allez parler à Li aux gâteaux d’osmanthe pour comprendre la situation.",
            ["TextMapId"] = "Content_200304_6",
            },
        ["Content_200304_7"] = {
            ["ContentFR"] = "Après cet échange, vous décidez d’accompagner l’ancien pour une courte promenade et de le raccompagner en sécurité.",
            ["TextMapId"] = "Content_200304_7",
            },
        ["Content_200304_8"] = {
            ["ContentFR"] = "Les Bi’an obscurs surgissent de nouveau et interrompent la discussion. Repoussez-les.",
            ["TextMapId"] = "Content_200304_8",
            },
        ["Content_200304_9"] = {
            ["ContentFR"] = "Une fois les Bi’an obscurs vaincus, Li s’arrête et laisse échapper un long soupir. Approchez-vous et écoutez ce qu’il souhaite dire.",
            ["TextMapId"] = "Content_200304_9",
            },
        ["Content_200305_1"] = {
            ["ContentFR"] = "Une petite fille, transie de peur, prie le Seigneur Dragon d’Argent de lui venir en aide. Allez voir ce qui l’a tant effrayée.",
            ["TextMapId"] = "Content_200305_1",
            },
        ["Content_200305_2"] = {
            ["ContentFR"] = "Au fil de la conversation, vous apprenez que d’étranges événements se produisent récemment chez Lingling. Il est évident qu’il serait dangereux de la laisser seule dans un endroit pareil. Allez enquêter chez elle afin de découvrir la vérité.",
            ["TextMapId"] = "Content_200305_2",
            },
        ["Content_200305_3"] = {
            ["ContentFR"] = "Après avoir fouillé la maison de Lingling, vous avez mis au jour plusieurs indices dignes d’attention. Examinez-les attentivement et cherchez le lien qui les unit.",
            ["TextMapId"] = "Content_200305_3",
            },
        ["Content_200305_4"] = {
            ["ContentFR"] = "Votre enquête révèle que ces phénomènes étranges sont causés par un Wishen. Au Port-des-Brumes, nul ne connaît mieux les Wishen que Fushu. Rendez-vous au Pavillon de l’Éphémère pour solliciter son aide.",
            ["TextMapId"] = "Content_200305_4",
            },
        ["Content_200305_5"] = {
            ["ContentFR"] = "Fushu vous explique que des Lys célestes permettront à Lingling de voir le Wishen qui hante sa maison. Partez en collecter sans tarder.",
            ["TextMapId"] = "Content_200305_5",
            },
        ["Content_200305_6"] = {
            ["ContentFR"] = "Ces Lys célestes devraient suffire. Retournez au Pavillon de l’Éphémère pour les remettre à Fushu.",
            ["TextMapId"] = "Content_200305_6",
            },
        ["Content_200305_7"] = {
            ["ContentFR"] = "Munis des Lys célestes imprégnés du sort de Fushu, vous retournez chez Lingling. Il est temps qu’elle voie enfin le véritable responsable des phénomènes qui tourmentent sa maison.",
            ["TextMapId"] = "Content_200305_7",
            },
        ["Content_200305_8"] = {
            ["ContentFR"] = "Le Wishen qui erre dans la demeure de Lingling n’est pas sa grand-mère, mais son arrière-arrière-grand-père. Il a pris Lingling pour sa petite-fille, Pingping. Aidez Lingling à collecter quelques Grillons du métier afin d’exaucer le dernier souhait de cet homme.",
            ["TextMapId"] = "Content_200305_8",
            },
        ["Content_200305_9"] = {
            ["ContentFR"] = "Avec ces Grillons du métier, l’arrière-arrière-grand-père de Lingling pourra enfin apaiser son cœur. Retournez chez elle.",
            ["TextMapId"] = "Content_200305_9",
            },
        ["Content_200306_1"] = {
            ["ContentFR"] = "Le Nexus mécanique que vous portez contre vous émet une étrange vibration, comme s’il tentait de vous indiquer une direction. Puisqu’il en est ainsi, allez voir de quoi il retourne.",
            ["TextMapId"] = "Content_200306_1",
            },
        ["Content_200306_2"] = {
            ["ContentFR"] = "Maître Gongshang tient absolument à vous faire découvrir les plaisirs des mécanismes. Après un bref échange, vous décidez de l’accompagner pour essayer plusieurs dispositifs à proximité.",
            ["TextMapId"] = "Content_200306_2",
            },
        ["Content_200306_3"] = {
            ["ContentFR"] = "Vous avez enfin expérimenté l’ensemble des mécanismes. Allez faire part de vos impressions à Maître Gongshang.",
            ["TextMapId"] = "Content_200306_3",
            },
        ["Content_200307_1"] = {
            ["ContentFR"] = "L’absence de l’acteur principal tourmente le réalisateur depuis bien trop longtemps. Sous l’insistance répétée de ce dernier, accepterez-vous de lui prêter main-forte en tournant quelques scènes à Port-des-Brumes ?",
            ["TextMapId"] = "Content_200307_1",
            },
        ["Content_200308_1"] = {
            ["ContentFR"] = "Dans un recoin oublié de d’Éternel Printemps, un entrepôt délaissé fait l’objet de rumeurs de hantise. Lorsque la nuit tombe et que les rues se vident, allez enquêter avec Snow.",
            ["TextMapId"] = "Content_200308_1",
            },
        ["Content_200308_1_1"] = {
            ["ContentFR"] = "Les ouvriers du port du Quai-aux-Étoiles murmurent qu’un entrepôt d’Éternel Printemps serait hanté. Provoquée par l’un d’eux, Snow accepte de s’y rendre à minuit pour vérifier.",
            ["TextMapId"] = "Content_200308_1_1",
            },
        ["Content_200308_2"] = {
            ["ContentFR"] = "De l’extérieur, l’entrepôt semble tout à fait ordinaire. Pourtant, quelque chose s’y cache peut-être... Entrez et découvrez-le.",
            ["TextMapId"] = "Content_200308_2",
            },
        ["Content_200308_3"] = {
            ["ContentFR"] = "Des Wishen errent dans tout l’entrepôt, comme s’ils montaient la garde. Avancez prudemment et évitez de vous faire repérer.",
            ["TextMapId"] = "Content_200308_3",
            },
        ["Content_200308_4"] = {
            ["ContentFR"] = "Ce soi-disant entrepôt « hanté » n’était qu’un malentendu : un Géniemon entré clandestinement à Huaxu, attiré par l’encens, a tenté de s’approprier les lieux, entraînant avec lui des Wishen solitaires. La vérité révélée, emmenez le Géniemon et mettez fin à cette farce.",
            ["TextMapId"] = "Content_200308_4",
            },
        ["Content_200309_1"] = {
            ["ContentFR"] = "Ces derniers temps, plusieurs habitants de Huaxu affirment ressentir de soudaines rafales glacées en traversant le Ravin du Clair-Obscur. Il s’agit sans doute de l’œuvre d’un Wishen. Profitez-en pour vous y rendre avec Snow et éclaircir la situation.",
            ["TextMapId"] = "Content_200309_1",
            },
        ["Content_200309_2"] = {
            ["ContentFR"] = "Bien que le Wishen nommé Weisheng soit mort depuis longtemps, il demeure hanté par le sort de son épouse gravement malade, Xianshu. Il pense que les médecins du Pavillon de l’Éphémère pourraient en savoir davantage. Allez interroger Fushu.",
            ["TextMapId"] = "Content_200309_2",
            },
        ["Content_200309_3"] = {
            ["ContentFR"] = "Fushu explique que la mort de Weisheng remonte à de nombreuses années. La médecin qui s’était occupée de son épouse était sa sœur aînée, Fufeng. Cette dernière a laissé plusieurs dossiers médicaux au Pavillon de l’Éphémère — l’un d’eux contient peut-être des informations sur Xianshu.",
            ["TextMapId"] = "Content_200309_3",
            },
        ["Content_200309_4"] = {
            ["ContentFR"] = "Avec Snow, vous avez consulté plusieurs dossiers médicaux au Pavillon de l’Éphémère, sans toutefois retrouver celui de Xianshu. Néanmoins, certains indices commencent à émerger. Il serait sans doute judicieux d’en reparler avec Fushu.",
            ["TextMapId"] = "Content_200309_4",
            },
        ["Content_200309_5"] = {
            ["ContentFR"] = "La vérité est désormais établie. Fushu vous fait part de son avis sur la manière d’annoncer les faits à Weisheng. Il est temps de retourner auprès de ce pauvre être, qui attend depuis près d’un siècle, et de lui révéler le sort de Xianshu.",
            ["TextMapId"] = "Content_200309_5",
            },
        ["Content_200309_6"] = {
            ["ContentFR"] = "Bien que vous ayez consulté trois dossiers médicaux de dates proches, aucun ne correspond parfaitement aux informations concernant l’épouse de Weisheng — à l’exception d’un seul... Se pourrait-il que l’identité du patient soit en réalité... ? Prenez le temps d’y réfléchir avant de trancher.",
            ["TextMapId"] = "Content_200309_6",
            },
        ["Content_200310_1"] = {
            ["ContentFR"] = "Un sanglot étouffé résonne non loin de vous. Allez voir ce qu’il se passe.",
            ["TextMapId"] = "Content_200310_1",
            },
        ["Content_200310_2"] = {
            ["ContentFR"] = "Snow et vous entendez des appels au loin. Quelqu’un semble en difficulté… allez lui porter secours.",
            ["TextMapId"] = "Content_200310_2",
            },
        ["Content_200310_3"] = {
            ["ContentFR"] = "En suivant le bruit, vous finissez par apercevoir un homme encerclé par des Souillés. Repoussez-les et tirez-le de là.",
            ["TextMapId"] = "Content_200310_3",
            },
        ["Content_200310_4"] = {
            ["ContentFR"] = "Les Souillés vaincus, un instant de répit s’installe. Examinez ses blessures et interrogez-le sur ce qui s’est passé.",
            ["TextMapId"] = "Content_200310_4",
            },
        ["Content_200310_5"] = {
            ["ContentFR"] = "Vous reconnaissez cet homme : c’est celui qui avait été chassé lors de l’attaque d’Éternel Printemps. Grièvement blessé, il doit y être reconduit au plus vite.",
            ["TextMapId"] = "Content_200310_5",
            },
        ["Content_200310_5_1"] = {
            ["ContentFR"] = "Le chemin vers Éternel Printemps n’est pas sûr. Éliminez les Souillés qui bloquent la route.",
            ["TextMapId"] = "Content_200310_5_1",
            },
        ["Content_200310_5_2"] = {
            ["ContentFR"] = "Le retour reste périlleux. Repoussez les Souillés qui tentent de vous barrer le passage.",
            ["TextMapId"] = "Content_200310_5_2",
            },
        ["Content_200310_6"] = {
            ["ContentFR"] = "Vous êtes parvenus à le raccompagner à Éternel Printemps, mais l’homme hésite encore. Allez lui parler.",
            ["TextMapId"] = "Content_200310_6",
            },
        ["Content_200311_1"] = {
            ["ContentFR"] = "Un père accompagné de son enfant semble avoir besoin d’aide. Allez lui parler.",
            ["TextMapId"] = "Content_200311_1",
            },
        ["Content_200311_2"] = {
            ["ContentFR"] = "Vous avez acheté les poires demandées, mais une autre paire père-fils s’est approchée. Allez comprendre ce qu’il se passe.",
            ["TextMapId"] = "Content_200311_2",
            },
        ["Content_200312_1"] = {
            ["ContentFR"] = "La petite fille, à l’abri sous l’auvent, semble prête à s’endormir debout. Allez voir comment elle va.",
            ["TextMapId"] = "Content_200312_1",
            },
        ["Content_200312_2"] = {
            ["ContentFR"] = "Après le départ de Qingqing, le porteur du cadeau apparaît comme prévu. Rattrapez-le et demandez-lui des explications.",
            ["TextMapId"] = "Content_200312_2",
            },
        ["Content_200312_3"] = {
            ["ContentFR"] = "Vous acceptez la requête de l’ami de Zhaoyu et décidez de préserver ce mensonge bienveillant. Retournez voir Qingqing et trouvez les mots pour la rassurer.",
            ["TextMapId"] = "Content_200312_3",
            },
        ["Content_200313_1"] = {
            ["ContentFR"] = "Près du Quai-aux-Étoiles, des voix s’élèvent du côté d’une maison de thé. On dirait une dispute... Voilà une scène qui mérite un détour. Allons voir.",
            ["TextMapId"] = "Content_200313_1",
            },
        ["Content_200313_2"] = {
            ["ContentFR"] = "Devant la maison de thé, Chen Baisha se dispute sans fin avec le marchand au sujet du goût du thé servi en grand bol. Qui a raison... ou s’agit-il d’un simple malentendu ?",
            ["TextMapId"] = "Content_200313_2",
            },
        ["Content_200313_3"] = {
            ["ContentFR"] = "Chen Baisha propose de se rendre à Éternel Printemps pour y retrouver un ami négociant en thé. Et sans trop savoir pourquoi, vous acceptez cette mission... La route ne sera pas paisible : repoussez les Souillés et le Bi’an obscur.",
            ["TextMapId"] = "Content_200313_3",
            },
        ["Content_200313_4"] = {
            ["ContentFR"] = "Les temps changent. Les bouleversements de la Baie des Roseaux-Pâles semblent plonger Chen Baisha dans une étrange mélancolie.",
            ["TextMapId"] = "Content_200313_4",
            },
        ["Content_200313_5"] = {
            ["ContentFR"] = "À Éternel Printemps, vous rencontrez le chaleureux Patron Hu... peut-être même un peu trop. Chen Baisha peine à placer un mot pour expliquer la raison de votre venue.",
            ["TextMapId"] = "Content_200313_5",
            },
        ["Content_200313_6"] = {
            ["ContentFR"] = "Chen Baisha vous interpelle et vous invite à faire la course sur la berge. Vous ignorez pourquoi un adulte se découvre soudain ce genre de passion... mais plus étrange encore : vous acceptez.",
            ["TextMapId"] = "Content_200313_6",
            },
        ["Content_200313_7"] = {
            ["ContentFR"] = "Courir pieds nus sur la berge, le corps bientôt maculé de boue, est assurément une expérience à part. Dans cette course menée à cœur perdu, même si rien de concret n’en naît, vous parvenez pourtant à toucher quelque chose de rare : un souvenir authentique.",
            ["TextMapId"] = "Content_200313_7",
            },
        ["Content_200314_1"] = {
            ["ContentFR"] = "Maître Qiu vous observe partir avec un sourire énigmatique. On dirait qu’il a encore quelque chose en tête... Allez donc voir ce qu’il mijote.",
            ["TextMapId"] = "Content_200314_1",
            },
        ["Content_200315_1"] = {
            ["ContentFR"] = "Qui aurait cru que le Marché Voilé vendrait en plein jour quelque chose d’aussi dangereux que des « Coups de Grâce » ? Il faut les arrêter avant que la situation ne s’aggrave.",
            ["TextMapId"] = "Content_200315_1",
            },
        }
  end },
  { MinKey = "Content_200315_2", MaxKey = "DUNGEON_DEFENCE_109", Loader = function()
      return {
        ["Content_200315_2"] = {
            ["ContentFR"] = "Après avoir fait le point avec Snow, vous décidez qu’il faut avant tout gagner du temps. Quelles que soient les intentions malveillantes du marchand du marché noir en vendant le « Coup de Grâce », il est impératif de le calmer, afin d’éviter qu’il ne déclenche immédiatement cet objet extrêmement dangereux.",
            ["TextMapId"] = "Content_200315_2",
            },
        ["Content_200315_3"] = {
            ["ContentFR"] = "La discussion avec le marchand du marché noir est sur le point de tourner court. Consultez Snow et décidez de la marche à suivre.",
            ["TextMapId"] = "Content_200315_3",
            },
        ["Content_200315_4"] = {
            ["ContentFR"] = "Snow parvient à détourner l’attention du marchand du marché noir. Profitez-en pour le neutraliser avec le fourreau de votre épée et l’empêcher de déclencher le « Coup de Grâce ».",
            ["TextMapId"] = "Content_200315_4",
            },
        ["Content_200315_5"] = {
            ["ContentFR"] = "Vous retenez votre force et repoussez aisément le marchand du marché noir. Approchez-vous sans tarder pour le maîtriser.",
            ["TextMapId"] = "Content_200315_5",
            },
        ["Content_400111_1"] = {
            ["ContentFR"] = "Autrefois animées par les rires, les Asphodèles semblent désormais envahies par les soupirs. Il vaudrait mieux aller voir ce qui se trame.",
            ["TextMapId"] = "Content_400111_1",
            },
        ["Content_400111_2"] = {
            ["ContentFR"] = "Pour rendre le sourire à Givrelac, il faudra consulter l’avis de plusieurs anciennes Luno !",
            ["TextMapId"] = "Content_400111_2",
            },
        ["Content_400111_3"] = {
            ["ContentFR"] = "Les méthodes de Luno, la forgeronne ne semblent pas très efficaces... Il est temps de laisser Luno, la servante, entrer en scène.",
            ["TextMapId"] = "Content_400111_3",
            },
        ["Content_400111_4"] = {
            ["ContentFR"] = "Essayons maintenant la méthode de Luno, l’exploratrice. Ça ira... probablement !",
            ["TextMapId"] = "Content_400111_4",
            },
        ["Content_400111_5"] = {
            ["ContentFR"] = "À peine arrivée en pleine nature, un danger inattendu surgit. Aidez les enfants à se mettre hors de danger.",
            ["TextMapId"] = "Content_400111_5",
            },
        ["Content_400111_6"] = {
            ["ContentFR"] = "Toutes les idées ont été tentées... N’existe-t-il vraiment aucun autre moyen de redonner le sourire ? Réfléchissez encore... encore..",
            ["TextMapId"] = "Content_400111_6",
            },
        ["Content_400111_7"] = {
            ["ContentFR"] = "Les efforts finissent toujours par payer... enfin, quand Snow s’en mêle ! Même si tout cela relevait du hasard, l’enthousiasme s’est propagé. On peut appeler ça une fin heureuse !",
            ["TextMapId"] = "Content_400111_7",
            },
        ["Content_Batt01_01_01"] = {
            ["ContentFR"] = "Alertée par sa proie, la grandiose Formation des Mille-Serrures jaillit du sol dans un fracas assourdissant. Vous voilà pris au piège d’un antique dispositif mécanique. Trouvez au plus vite une issue.",
            ["TextMapId"] = "Content_Batt01_01_01",
            },
        ["Content_Batt01_01_02"] = {
            ["ContentFR"] = "Alertée par sa proie, la grandiose Formation des Mille-Serrures jaillit du sol dans un fracas assourdissant. Vous voilà pris au piège d’un antique dispositif mécanique. Trouvez au plus vite une issue.",
            ["TextMapId"] = "Content_Batt01_01_02",
            },
        ["Content_Batt01_01_03"] = {
            ["ContentFR"] = "Alertée par sa proie, la grandiose Formation des Mille-Serrures jaillit du sol dans un fracas assourdissant. Vous voilà pris au piège d’un antique dispositif mécanique. Trouvez au plus vite une issue.",
            ["TextMapId"] = "Content_Batt01_01_03",
            },
        ["Content_Batt01_01_04"] = {
            ["ContentFR"] = "Alertée par sa proie, la grandiose Formation des Mille-Serrures jaillit du sol dans un fracas assourdissant. Vous voilà pris au piège d’un antique dispositif mécanique. Trouvez au plus vite une issue.",
            ["TextMapId"] = "Content_Batt01_01_04",
            },
        ["Content_Batt01_02_01"] = {
            ["ContentFR"] = "Alertée par sa proie, la grandiose Formation des Mille-Serrures jaillit du sol dans un fracas assourdissant. Vous voilà pris au piège d’un antique dispositif mécanique. Trouvez au plus vite une issue.",
            ["TextMapId"] = "Content_Batt01_02_01",
            },
        ["Content_Batt01_02_02"] = {
            ["ContentFR"] = "Alertée par sa proie, la grandiose Formation des Mille-Serrures jaillit du sol dans un fracas assourdissant. Vous voilà pris au piège d’un antique dispositif mécanique. Trouvez au plus vite une issue.",
            ["TextMapId"] = "Content_Batt01_02_02",
