        ["DUNGEON_RESCUE_101"] = {
            ["ContentFR"] = "Repérez la <H>Cellule secrète</> où le prisonnier est détenu, déverrouillez le mécanisme et retrouvez la cible.",
            ["TextMapId"] = "DUNGEON_RESCUE_101",
            },
        ["DUNGEON_RESCUE_102"] = {
            ["ContentFR"] = "Lors de vos déplacements dans la <H>zone des Cellules secrètes</>, évitez d’être repéré par les <H>patrouilles ennemies</>.\
 Si vous êtes découvert, éliminez rapidement vos assaillants pour les empêcher de donner l’alerte.",
            ["TextMapId"] = "DUNGEON_RESCUE_102",
            },
        ["DUNGEON_RESCUE_103"] = {
            ["ContentFR"] = "Si les patrouilles parviennent à donner l’alerte, la cible sera en danger. Trouvez-la avant la fin du <H>décompte</>, sans quoi la mission échouera.",
            ["TextMapId"] = "DUNGEON_RESCUE_103",
            },
        ["DUNGEON_RESCUE_104"] = {
            ["ContentFR"] = "Une fois la cible libérée, escortez-la jusqu’au Point d’évacuation tout en veillant constamment à sa sécurité.",
            ["TextMapId"] = "DUNGEON_RESCUE_104",
            },
        ["DUNGEON_RESCUE_105"] = {
            ["ContentFR"] = "La mission sera accomplie une fois la cible arrivée saine et sauve au Point d’évacuation.",
            ["TextMapId"] = "DUNGEON_RESCUE_105",
            },
        ["DUNGEON_SABOTAGEPRO_100"] = {
            ["ContentFR"] = "Démanteler",
            ["TextMapId"] = "DUNGEON_SABOTAGEPRO_100",
            },
        ["DUNGEON_SABOTAGEPRO_101"] = {
            ["ContentFR"] = "Démanteler trois dispositifs",
            ["TextMapId"] = "DUNGEON_SABOTAGEPRO_101",
            },
        ["DUNGEON_SABOTAGEPRO_102"] = {
            ["ContentFR"] = "Déverrouiller le mécanisme pour exposer le noyau du dispositif",
            ["TextMapId"] = "DUNGEON_SABOTAGEPRO_102",
            },
        ["DUNGEON_SABOTAGEPRO_103"] = {
            ["ContentFR"] = "Démanteler les trois dispositifs dans le temps imparti",
            ["TextMapId"] = "DUNGEON_SABOTAGEPRO_103",
            },
        ["DUNGEON_SABOTAGE_100"] = {
            ["ContentFR"] = "Piratez le mécanisme pour exposer le détonateur du « Coup de Grâce »",
            ["TextMapId"] = "DUNGEON_SABOTAGE_100",
            },
        ["DUNGEON_SABOTAGE_101"] = {
            ["ContentFR"] = "Mission secondaire",
            ["TextMapId"] = "DUNGEON_SABOTAGE_101",
            },
        ["DUNGEON_SABOTAGE_102"] = {
            ["ContentFR"] = "Trouvez et éliminez les membres des Déchus (facultatif)",
            ["TextMapId"] = "DUNGEON_SABOTAGE_102",
            },
        ["DUNGEON_SABOTAGE_103"] = {
            ["ContentFR"] = "Détruisez le détonateur du « Coup de Grâce » pour empêcher l’explosion",
            ["TextMapId"] = "DUNGEON_SABOTAGE_103",
            },
        ["DUNGEON_SABOTAGE_104"] = {
            ["ContentFR"] = "Le Détoniste a été vaincu. Le détonateur du « Coup de Grâce » est désormais plus vulnérable.",
            ["TextMapId"] = "DUNGEON_SABOTAGE_104",
            },
        ["DUNGEON_SABOTAGE_105"] = {
            ["ContentFR"] = "Le Machinateur a été vaincu. Des plaques de propulsion sont désormais disponibles sur la route d’évacuation.",
            ["TextMapId"] = "DUNGEON_SABOTAGE_105",
            },
        ["DUNGEON_SABOTAGE_106"] = {
            ["ContentFR"] = "Le Dévoyeur a été vaincu. Les ennemis d’élite n’apparaîtront plus dans cette mission.",
            ["TextMapId"] = "DUNGEON_SABOTAGE_106",
            },
        ["DUNGEON_SABOTAGE_107"] = {
            ["ContentFR"] = "Décompte avant la soumission de la mission",
            ["TextMapId"] = "DUNGEON_SABOTAGE_107",
            },
        ["DUNGEON_SABOTAGE_108"] = {
            ["ContentFR"] = "« Coup de Grâce »",
