            ["TextMapId"] = "MESSAGE_LOADING_2_Phone",
            },
        ["MESSAGE_LOADING_31_PC"] = {
            ["ContentFR"] = "Équiper des Sceaux démoniaques renforce considérablement vos personnages et leurs armes. Certains Sceaux rares peuvent même modifier les effets des compétences.",
            ["TextMapId"] = "MESSAGE_LOADING_31_PC",
            },
        ["MESSAGE_LOADING_32_PC"] = {
            ["ContentFR"] = "Les Sceaux démoniaques imposent une charge physique à leur porteur, dont la limite est appelée Tolérance. L’amélioration du niveau des personnages et des armes augmente cette Tolérance, permettant d’équiper plus de Sceaux pour un avantage accru au combat.",
            ["TextMapId"] = "MESSAGE_LOADING_32_PC",
            },
        ["MESSAGE_LOADING_33_PC"] = {
            ["ContentFR"] = "Chaque Sceau démoniaque possède un attribut propre, appelé Affinité, qui résonne différemment selon les porteurs. Si l’affinité du Sceau correspond à celle du personnage ou de l’arme, il consomme moins de Tolérance — sinon, il en consomme davantage.",
            ["TextMapId"] = "MESSAGE_LOADING_33_PC",
