        ["Message_Guide_ModLevelUp_1"] = {
            ["ContentFR"] = "Améliorer le <H>niveau d’un Sceau démoniaque</> renforce encore la puissance des Daimons et de vos armes.",
            ["TextMapId"] = "Message_Guide_ModLevelUp_1",
            },
        ["Message_Guide_ModLevelUp_4"] = {
            ["ContentFR"] = "Sélectionnez un Sceau démoniaque",
            ["TextMapId"] = "Message_Guide_ModLevelUp_4",
            },
        ["Message_Guide_ModLevelUp_4_Pad"] = {
            ["ContentFR"] = "Appuyer pour sélectionner un Sceau démoniaque",
            ["TextMapId"] = "Message_Guide_ModLevelUp_4_Pad",
            },
        ["Message_Guide_ModLevelUp_5"] = {
            ["ContentFR"] = "Sélectionnez « Améliorer Sceau démoniaque »",
            ["TextMapId"] = "Message_Guide_ModLevelUp_5",
            },
        ["Message_Guide_ModLevelUp_5_Pad"] = {
            ["ContentFR"] = "Appuyer pour sélectionner « Améliorer Sceau démoniaque »",
            ["TextMapId"] = "Message_Guide_ModLevelUp_5_Pad",
            },
        ["Message_Guide_ModLevelUp_6"] = {
            ["ContentFR"] = "Sélectionnez un Sceau démoniaque",
            ["TextMapId"] = "Message_Guide_ModLevelUp_6",
            },
        ["Message_Guide_ModLevelUp_7"] = {
            ["ContentFR"] = "L’amélioration d’un Sceau démoniaque <H>augmente la Tolérance requise</>.\
Veillez à ce que la Tolérance totale équipée <H>ne dépasse pas</> la <H>limite de Tolérance</> du personnage ou de l’arme après l’amélioration.",
            ["TextMapId"] = "Message_Guide_ModLevelUp_7",
            },
        ["Message_Guide_ModTendency_1"] = {
            ["ContentFR"] = "Les <H>Modules de transfert d’affinité</> permettent de modifier l’Affinité de base des emplacements d’un personnage",
            ["TextMapId"] = "Message_Guide_ModTendency_1",
            },
        ["Message_Guide_ModTendency_10"] = {
            ["ContentFR"] = "Vous avez obtenu un puissant Sceau démoniaque, mais son <H>Affinité ne correspond pas</> ? Essayez de <H>modifier l’Affinité</> de son emplacement !",
            ["TextMapId"] = "Message_Guide_ModTendency_10",
            },
        ["Message_Guide_ModTendency_11"] = {
            ["ContentFR"] = "Lorsque l’Affinité d’un emplacement <H>correspond</> à celle d’un Sceau démoniaque, la <H>Tolérance</> requise pour l’équiper est <H>réduite</>.",
            ["TextMapId"] = "Message_Guide_ModTendency_11",
            },
        ["Message_Guide_ModTendency_4"] = {
            ["ContentFR"] = "Appuyez sur un emplacement de Sceau démoniaque",
            ["TextMapId"] = "Message_Guide_ModTendency_4",
            },
        ["Message_Guide_ModTendency_4_Pad"] = {
            ["ContentFR"] = "Appuyer pour sélectionner un emplacement de Sceau démoniaque",
            ["TextMapId"] = "Message_Guide_ModTendency_4_Pad",
            },
        ["Message_Guide_ModTendency_5"] = {
            ["ContentFR"] = "Appuyez sur « Modifier l’affinité »",
            ["TextMapId"] = "Message_Guide_ModTendency_5",
            },
        ["Message_Guide_ModTendency_5_Pad"] = {
            ["ContentFR"] = "Appuyer pour sélectionner « Modifier l’affinité »",
            ["TextMapId"] = "Message_Guide_ModTendency_5_Pad",
            },
        ["Message_Guide_ModTendency_6"] = {
            ["ContentFR"] = "Utilisez un <H>Module de transfert d’affinité</> afin d’ajouter, modifier ou supprimer l’<H>Affinité</> de base d’un emplacement de Sceau démoniaque",
            ["TextMapId"] = "Message_Guide_ModTendency_6",
            },
        ["Message_Guide_ModTendency_7"] = {
            ["ContentFR"] = "Marre de ne pas pouvoir équiper plus de Sceaux démoniaques ? Surveillez votre <H>Affinité</> !",
            ["TextMapId"] = "Message_Guide_ModTendency_7",
            },
        ["Message_Guide_ModTendency_8"] = {
            ["ContentFR"] = "Chaque personnage et chaque arme possèdent des traits uniques, influençant la configuration de leurs <H>emplacements de Sceaux démoniaques</> selon leur <H>Affinité</>.",
            ["TextMapId"] = "Message_Guide_ModTendency_8",
            },
        ["Message_Guide_ModTendency_9"] = {
            ["ContentFR"] = "Certains <H>Sceaux démoniaques</> ont été créés avec une <H>Affinité</> spécifique, afin de mieux s’adapter à certains individus.",
            ["TextMapId"] = "Message_Guide_ModTendency_9",
            },
        ["Message_Guide_Mod_1"] = {
            ["ContentFR"] = "Les <H>Sceaux démoniaques</>, conçus par les Spathatoi d’Hyperborea, sont des composants portables qui renforcent considérablement la puissance des Daimons et des armes lorsqu’ils sont équipés.",
            ["TextMapId"] = "Message_Guide_Mod_1",
            },
        ["Message_Guide_Mod_10"] = {
            ["ContentFR"] = "Touchez un Sceau démoniaque pour consulter ses effets",
            ["TextMapId"] = "Message_Guide_Mod_10",
            },
        ["Message_Guide_Mod_11"] = {
            ["ContentFR"] = "Dépensez des <H>Pièces</> et des <H>Globules cramoisis</> pour <H>améliorer</> vos Sceaux démoniaques et renforcer considérablement leur puissance. Cependant, leur amélioration augmente également la charge sur le porteur et peut dépasser la limite de Tolérance.",
            ["TextMapId"] = "Message_Guide_Mod_11",
            },
        ["Message_Guide_Mod_12"] = {
            ["ContentFR"] = "Ici, vous pouvez basculer rapidement entre vos personnages et vos armes pour ajuster leurs Sceaux démoniaques",
            ["TextMapId"] = "Message_Guide_Mod_12",
            },
        ["Message_Guide_Mod_13"] = {
            ["ContentFR"] = "Un même Sceau démoniaque de personnage peut être équipé par plusieurs personnages.\
De même, un Sceau démoniaque d’arme peut être partagé entre plusieurs armes.",
            ["TextMapId"] = "Message_Guide_Mod_13",
            },
        ["Message_Guide_Mod_14"] = {
            ["ContentFR"] = "<H>Améliorer</> vos personnages et vos armes augmente leur Tolérance maximale.",
            ["TextMapId"] = "Message_Guide_Mod_14",
            },
        ["Message_Guide_Mod_15"] = {
            ["ContentFR"] = "Appuyer ici pour équiper automatiquement un Sceau démoniaque",
            ["TextMapId"] = "Message_Guide_Mod_15",
            },
        ["Message_Guide_Mod_16"] = {
            ["ContentFR"] = "Cliquer sur « Confirmer » pour équiper automatiquement un Sceau démoniaque",
            ["TextMapId"] = "Message_Guide_Mod_16",
            },
        ["Message_Guide_Mod_16_Pad"] = {
            ["ContentFR"] = "Appuyer sur « Confirmer » pour équiper automatiquement un Sceau démoniaque",
            ["TextMapId"] = "Message_Guide_Mod_16_Pad",
            },
        ["Message_Guide_Mod_2"] = {
            ["ContentFR"] = "Appuyez sur « Sceaux démoniaques » pour les configurer",
            ["TextMapId"] = "Message_Guide_Mod_2",
            },
        ["Message_Guide_Mod_2_Pad"] = {
            ["ContentFR"] = "Appuyer pour sélectionner un <H>Sceau démoniaque</> à équiper",
            ["TextMapId"] = "Message_Guide_Mod_2_Pad",
            },
        ["Message_Guide_Mod_3"] = {
            ["ContentFR"] = "Il existe deux types de Sceaux : les <H>Sceaux démoniaques de personnage</> et les <H>Sceaux démoniaques d’arme</>, qui ne sont pas interchangeables",
            ["TextMapId"] = "Message_Guide_Mod_3",
            },
        ["Message_Guide_Mod_4"] = {
            ["ContentFR"] = "Chaque Sceau démoniaque offre des effets d’amélioration différents, il doit être <H>équipé dans un emplacement</> pour être activé",
            ["TextMapId"] = "Message_Guide_Mod_4",
            },
        ["Message_Guide_Mod_5"] = {
            ["ContentFR"] = "Cet emplacement n’est pas encore débloqué. Réalisez des <H>Ascensions</> à votre personnage pour débloquer davantage d’emplacements",
            ["TextMapId"] = "Message_Guide_Mod_5",
            },
        ["Message_Guide_Mod_6"] = {
            ["ContentFR"] = "Les Sceaux démoniaques renferment une grande puissance, ce qui impose une certaine charge à leur porteur",
            ["TextMapId"] = "Message_Guide_Mod_6",
            },
        ["Message_Guide_Mod_7"] = {
            ["ContentFR"] = "<H>L’angle supérieur gauche</> indique la <H>Tolérance requise</> pour ce Sceau démoniaque",
            ["TextMapId"] = "Message_Guide_Mod_7",
            },
        ["Message_Guide_Mod_8"] = {
            ["ContentFR"] = "Tant que la Tolérance n’a pas atteint sa limite, vous pouvez faire glisser un Sceau démoniaque dans un emplacement vide pour l’équiper",
            ["TextMapId"] = "Message_Guide_Mod_8",
            },
        ["Message_Guide_Mod_9"] = {
            ["ContentFR"] = "La <H>Tolérance</> désigne la capacité d’un personnage ou d’une arme à supporter les Sceaux démoniaques. Le nombre affiché ci-dessous indique leur limite de Tolérance",
            ["TextMapId"] = "Message_Guide_Mod_9",
            },
        ["Message_Guide_OnlineAreaPre_1"] = {
            ["ContentFR"] = "Terminez le chapitre 1 du Vagabond de la Nuit, « Fer noir, fleur blanche », pour débloquer la coopération. Dans les zones dédiées, vous pourrez croiser d’autres joueurs venus d’autres lignes temporelles.",
            ["TextMapId"] = "Message_Guide_OnlineAreaPre_1",
            },
        ["Message_Guide_OnlineAreaPre_2"] = {
            ["ContentFR"] = "Une fois la coopération débloquée, certaines zones deviennent des zones coop. Y entrer active automatiquement la coopération ; en sortir la désactive.",
            ["TextMapId"] = "Message_Guide_OnlineAreaPre_2",
            },
        ["Message_Guide_OnlineAreaPre_3"] = {
            ["ContentFR"] = "Vous pouvez régler l’option d’entrée automatique en mode coop dans le menu Paramètres.",
            ["TextMapId"] = "Message_Guide_OnlineAreaPre_3",
            },
        ["Message_Guide_OnlineArea_1"] = {
            ["ContentFR"] = "Certaines zones permettent la coopération : vous pourrez y croiser des Chasseurs de Phoxène venus d’autres lignes temporelles.",
            ["TextMapId"] = "Message_Guide_OnlineArea_1",
            },
        ["Message_Guide_OnlineArea_2"] = {
            ["ContentFR"] = "Entrer dans ces zones active automatiquement la coop. En sortir la désactive.",
            ["TextMapId"] = "Message_Guide_OnlineArea_2",
            },
        ["Message_Guide_OnlineArea_3"] = {
            ["ContentFR"] = "Vous pouvez régler l’option d’entrée automatique dans le menu Paramètres.",
            ["TextMapId"] = "Message_Guide_OnlineArea_3",
            },
        ["Message_Guide_OpenArmory_PC"] = {
