  { MinKey = "Mod_Sell_Tip", MaxKey = "Mon_Name_6001024", Loader = function()
      return {
        ["Mod_Sell_Tip"] = {
            ["ContentFR"] = "Le Sceau démoniaque est actuellement équipé. Voulez-vous vraiment le vendre ?",
            ["TextMapId"] = "Mod_Sell_Tip",
            },
        ["Mod_SuitName_1"] = {
            ["ContentFR"] = "Ensemble I",
            ["TextMapId"] = "Mod_SuitName_1",
            },
        ["Mod_SuitName_2"] = {
