        ["MonsterRushEvent_Wuyou_DungeonDes01"] = {
            ["ContentFR"] = "Un Wishen mystérieux, épée en main, surgit de nulle part et bloque votre route.\
  Peut-être a-t-il senti votre talent exceptionnel, car il semble prêt à vous enseigner une technique ou deux.\
  « Regarde bien... je ne montre ça qu’une seule fois. »",
            ["TextMapId"] = "MonsterRushEvent_Wuyou_DungeonDes01",
            },
        ["MonsterRushEvent_Wuyou_DungeonDes02"] = {
            ["ContentFR"] = "À travers le feuillage, la lumière filtre doucement ; une brise légère effleure vos cheveux. Comme rappelé par quelque après-midi perdu dans une mémoire lointaine, le petit Wishen pousse un long bâillement.\
  « ... Les Wishen bâillent aussi ? »",
            ["TextMapId"] = "MonsterRushEvent_Wuyou_DungeonDes02",
            },
        ["MonsterRushEvent_Wuyou_DungeonDes03"] = {
            ["ContentFR"] = "Le disciple studieux et le jeune berger paresseux : leurs disputes incessantes vous tournent autour sans relâche. Espérons qu’ils ne décident pas de retourner leur mauvaise humeur contre vous... pauvre {性别:voyageur embarqué|voyageuse embarquée} malgré vous dans leur querelle joyeusement assourdissante.",
            ["TextMapId"] = "MonsterRushEvent_Wuyou_DungeonDes03",
            },
        ["MonsterRushEvent_Wuyou_DungeonDes04"] = {
            ["ContentFR"] = "Une feuille... puis deux... puis trois... Vous voyez le Wishen sortir talisman après talisman de derrière son dos, comme un magicien de scène faisant jaillir à l’infini des cartes de ses manches.\
  « Pas celui-ci... ni celui-là... Où est passé mon talisman de foudre !? »",
            ["TextMapId"] = "MonsterRushEvent_Wuyou_DungeonDes04",
            },
        ["MonsterRushEvent_Wuyou_DungeonDes05"] = {
            ["ContentFR"] = "Sans se presser, un Wishen dépose son chapeau de paille entre vos mains et vous le confie pour un moment. L’instant d’après, vous croyez apercevoir une silhouette en costume surgir de son ombre, brandissant une hache et hurlant :\
  « Qui d’autre veut s’y frotter !? »",
            ["TextMapId"] = "MonsterRushEvent_Wuyou_DungeonDes05",
            },
        ["MonsterRushEvent_Wuyou_DungeonDes06"] = {
            ["ContentFR"] = "On raconte que les Wishen naissent des désirs non accomplis. Vous tournez le regard vers le compagnon flottant tranquillement à vos côtés. Quelle volonté persistante, vous demandez-vous, peut bien les retenir encore dans ce monde ?",
            ["TextMapId"] = "MonsterRushEvent_Wuyou_DungeonDes06",
            },
        ["MonsterRushEvent_Wuyou_DungeonDes07"] = {
            ["ContentFR"] = "Si se dissiper signifie enfin trouver la paix, alors les adieux douloureux n’existent pas dans le monde des Wishen. Teintes des couleurs de l’âme, ces esprits fantasques se rassemblent ici — et demain, comme toujours, sera un jour vibrant de vie et de joyeux vacarme.",
            ["TextMapId"] = "MonsterRushEvent_Wuyou_DungeonDes07",
            },
        ["MonsterRushEvent_Wuyou_DungeonName01"] = {
            ["ContentFR"] = "La Leçon de l’épéiste sans nom",
            ["TextMapId"] = "MonsterRushEvent_Wuyou_DungeonName01",
            },
        ["MonsterRushEvent_Wuyou_DungeonName02"] = {
            ["ContentFR"] = "Le bâillement du jeune berger",
            ["TextMapId"] = "MonsterRushEvent_Wuyou_DungeonName02",
            },
        ["MonsterRushEvent_Wuyou_DungeonName03"] = {
            ["ContentFR"] = "La farce des deux querelleurs",
            ["TextMapId"] = "MonsterRushEvent_Wuyou_DungeonName03",
            },
        ["MonsterRushEvent_Wuyou_DungeonName04"] = {
            ["ContentFR"] = "Le magicien aux talismans sans fin",
            ["TextMapId"] = "MonsterRushEvent_Wuyou_DungeonName04",
            },
        ["MonsterRushEvent_Wuyou_DungeonName05"] = {
            ["ContentFR"] = "Le fou placide",
            ["TextMapId"] = "MonsterRushEvent_Wuyou_DungeonName05",
            },
        ["MonsterRushEvent_Wuyou_DungeonName06"] = {
            ["ContentFR"] = "L’épreuve des vœux persistants",
            ["TextMapId"] = "MonsterRushEvent_Wuyou_DungeonName06",
            },
        ["MonsterRushEvent_Wuyou_DungeonName07"] = {
            ["ContentFR"] = "Un lendemain sans souci",
            ["TextMapId"] = "MonsterRushEvent_Wuyou_DungeonName07",
            },
        ["MonsterRushEvent_Wuyou_PetDesc_1"] = {
            ["ContentFR"] = "Un Wishen maniant des talismans destructeurs avec une aisance déconcertante — mais ce qui vous intrigue le plus, c’est de savoir où il puise cette réserve presque inépuisable de talismans.",
            ["TextMapId"] = "MonsterRushEvent_Wuyou_PetDesc_1",
            },
        ["MonsterRushEvent_Wuyou_PetDesc_2"] = {
            ["ContentFR"] = "Un Wishen à l’allure calme et maîtrisée — mais éveiller sa colère pourrait entraîner des conséquences que nul n’ose imaginer.",
            ["TextMapId"] = "MonsterRushEvent_Wuyou_PetDesc_2",
            },
        ["MonsterRushEvent_Wuyou_PetDesc_3"] = {
            ["ContentFR"] = "Un Wishen passé maître dans l’art de faire virevolter les épées : les lames qui gravitent autour de lui feraient un décor parfait pour une photographie... à condition qu’il accepte de vous rendre ce service.",
            ["TextMapId"] = "MonsterRushEvent_Wuyou_PetDesc_3",
            },
        ["MonsterRushEvent_Wuyou_PetDesc_4"] = {
            ["ContentFR"] = "Un Wishen qui se déplace toujours avec une légèreté nonchalante. Et les jours de cafard, il suffit de lui caresser doucement le sommet de la tête pour sentir votre cœur s’alléger.",
            ["TextMapId"] = "MonsterRushEvent_Wuyou_PetDesc_4",
            },
        ["MonsterRushEvent_Wuyou_PetName_1"] = {
