        ["PartyTopic_Description_110101"] = {
            ["ContentFR"] = "Elle versa d’étranges ingrédients au fond du chaudron, y mêlant la maladroite tendresse qu’elle portait au fond du cœur.",
            ["TextMapId"] = "PartyTopic_Description_110101",
            },
        ["PartyTopic_Description_110102"] = {
            ["ContentFR"] = "Tu es la raison pour laquelle je ne peux fuir.",
            ["TextMapId"] = "PartyTopic_Description_110102",
            },
        ["PartyTopic_Description_110103"] = {
            ["ContentFR"] = "Cette rive est tout mon monde — et le monde entier est ma cage.",
            ["TextMapId"] = "PartyTopic_Description_110103",
            },
        ["PartyTopic_Description_110104"] = {
            ["ContentFR"] = "Tout est fini, et tout recommence.",
            ["TextMapId"] = "PartyTopic_Description_110104",
            },
        ["PartyTopic_Description_110301"] = {
            ["ContentFR"] = "Un dramaturge m’a un jour confié qu’avant de pousser un héros à agir,\
il faut d’abord lui arracher tout espoir.\
Puissé-je seulement croire que la réalité ne fonctionne pas ainsi.",
            ["TextMapId"] = "PartyTopic_Description_110301",
            },
        ["PartyTopic_Description_110302"] = {
            ["ContentFR"] = "Lorsque l’espoir s’effondre et que toute échappatoire disparaît, le protagoniste ne peut plus jamais revenir à la vie qu’il connaissait.\
J’ai tenté, autant que possible, de retarder ce moment.",
            ["TextMapId"] = "PartyTopic_Description_110302",
            },
        ["PartyTopic_Description_110303"] = {
            ["ContentFR"] = "Les spectateurs raffolent des rebondissements ; les dramaturges n’ont donc de cesse de faire ondoyer leurs récits. Mais mon histoire, elle, ne connaît qu’une seule direction : vers le bas — encore, toujours, inexorable, dans une chute sans fin.",
            ["TextMapId"] = "PartyTopic_Description_110303",
            },
        ["PartyTopic_Description_110304"] = {
            ["ContentFR"] = "Peut-être n’étais-je pas destiné à une belle histoire. Mais j’ai tout de même le droit d’en choisir la fin.",
            ["TextMapId"] = "PartyTopic_Description_110304",
            },
        ["PartyTopic_Description_150201"] = {
            ["ContentFR"] = "Parfois, un espoir déformé se révèle plus cruel que le désespoir lui-même : il prolonge les souffrances d’hier dans un futur où elles auraient déjà dû s’éteindre.",
            ["TextMapId"] = "PartyTopic_Description_150201",
            },
        ["PartyTopic_Description_150202"] = {
            ["ContentFR"] = "Même si le vent de demain emportera toute trace de notre passage, les instants où nous avons brillé resteront à jamais gravés dans la mémoire de ceux qui demeurent.",
            ["TextMapId"] = "PartyTopic_Description_150202",
            },
        }
  end },
  { MinKey = "PartyTopic_Description_150203", MaxKey = "Pet_Break_LevelReset_Over", Loader = function()
      return {
        ["PartyTopic_Description_150203"] = {
            ["ContentFR"] = "Nous avons choisi d’emprunter cette route qui mène au bord du précipice... parce qu’elle était bordée de fleurs.",
            ["TextMapId"] = "PartyTopic_Description_150203",
            },
        ["PartyTopic_Description_150204"] = {
            ["ContentFR"] = "Une histoire après l’autre — ainsi se tisse le long récit de sa vie.",
            ["TextMapId"] = "PartyTopic_Description_150204",
            },
        ["PartyTopic_Description_150301"] = {
            ["ContentFR"] = "Là où les forêts sont épaisses et les roseaux entremêlés, circulent toujours des récits de vagabonds retirés du monde. La plupart parlent de haines et de serments. Mais ceux qui se sont réellement détachés ne laissent derrière eux aucune trace.",
            ["TextMapId"] = "PartyTopic_Description_150301",
            },
        ["PartyTopic_Description_150302"] = {
            ["ContentFR"] = "Derrière chaque montagne naît un espoir, avant de s’éteindre à son tour. Pourtant, en se retournant, le plus beau paysage reste toujours celui du départ.",
            ["TextMapId"] = "PartyTopic_Description_150302",
            },
        ["PartyTopic_Description_150303"] = {
            ["ContentFR"] = "Les odeurs réveillent la mémoire. Peut-être est-ce pour cela que chacun a ses mets de prédilection : nos chemins d’origine ne se ressemblent jamais.",
            ["TextMapId"] = "PartyTopic_Description_150303",
            },
        ["PartyTopic_Description_150304"] = {
            ["ContentFR"] = "Dans la jeunesse, on apprend l’épée en visant toujours plus haut. On marche, on marche encore — les compagnons se font rares. Parvenu au sommet, il ne reste plus personne. Seule la neige demeure, s’accumulant sur la tête.",
            ["TextMapId"] = "PartyTopic_Description_150304",
            },
        ["PartyTopic_Description_150401"] = {
            ["ContentFR"] = "Les feuilles portées par le vent finissent par retomber sur la terre. Ceux qui ont longtemps erré trouvent, eux aussi, le chemin du retour.",
            ["TextMapId"] = "PartyTopic_Description_150401",
            },
        ["PartyTopic_Description_150402"] = {
            ["ContentFR"] = "La route qui s’éloigne de la maison est longue et tortueuse. Et tu n’oses pas te retourner pour regarder derrière toi.",
            ["TextMapId"] = "PartyTopic_Description_150402",
            },
        ["PartyTopic_Description_150403"] = {
            ["ContentFR"] = "Les liens du sang sont de ces choses qu’on ne peut jamais vraiment couper. Comme lorsqu’on tente de fendre l’eau avec une lame : la coupure ne tient pas, et le courant poursuit sa course.",
            ["TextMapId"] = "PartyTopic_Description_150403",
            },
        ["PartyTopic_Description_180101"] = {
            ["ContentFR"] = "Elle confia ses souhaits magiques à ses amis.",
            ["TextMapId"] = "PartyTopic_Description_180101",
            },
        ["PartyTopic_Description_180102"] = {
            ["ContentFR"] = "Elle offrit ses rêves oubliés aux étoiles.",
            ["TextMapId"] = "PartyTopic_Description_180102",
            },
        ["PartyTopic_Description_180103"] = {
            ["ContentFR"] = "Elle enterra ses souvenirs dans des terres lointaines.",
            ["TextMapId"] = "PartyTopic_Description_180103",
            },
        ["PartyTopic_Description_180104"] = {
            ["ContentFR"] = "Elle confia ses lendemains à venir aux pages blanches.",
            ["TextMapId"] = "PartyTopic_Description_180104",
            },
        ["PartyTopic_Description_210101"] = {
            ["ContentFR"] = "Boum, boum... tu l’entends ? C’est le son de l’amour qui s’écoule.",
            ["TextMapId"] = "PartyTopic_Description_210101",
            },
        ["PartyTopic_Description_210102"] = {
            ["ContentFR"] = "L’amour se mesure à l’épreuve. Face aux doux serments, une seule goutte de venin dit bien mieux la vérité. Soit la mort, soit l’éternité — pourquoi ne pas tenter votre chance ?",
            ["TextMapId"] = "PartyTopic_Description_210102",
            },
        ["PartyTopic_Description_210103"] = {
            ["ContentFR"] = "Même les monstres ont leurs failles. Ce ne sont pas des démons sans âme, seulement des êtres à part, perdus parmi les hommes.",
            ["TextMapId"] = "PartyTopic_Description_210103",
            },
        ["PartyTopic_Description_210104"] = {
            ["ContentFR"] = "L’amour est une lame qui tranche toutes les entraves — montagnes, océans ou poison.",
            ["TextMapId"] = "PartyTopic_Description_210104",
            },
        ["PartyTopic_Description_230101"] = {
            ["ContentFR"] = "La dissimulation protège, l’imitation punit.",
            ["TextMapId"] = "PartyTopic_Description_230101",
            },
        ["PartyTopic_Description_230102"] = {
            ["ContentFR"] = "Le bien et le mal se jugent par autrui, mais seul soi-même décide du juste et du faux.",
            ["TextMapId"] = "PartyTopic_Description_230102",
            },
        ["PartyTopic_Description_230103"] = {
            ["ContentFR"] = "Ôtez la feuille qui vous cache les yeux, et le monde s’ouvre — plus vaste que vous ne l’imaginiez.",
            ["TextMapId"] = "PartyTopic_Description_230103",
            },
        ["PartyTopic_Description_230104"] = {
            ["ContentFR"] = "Même dans le chaos, on peut encore trouver une chaleur.",
            ["TextMapId"] = "PartyTopic_Description_230104",
            },
        ["PartyTopic_Description_240101"] = {
            ["ContentFR"] = "Après un siècle de sommeil, l’ancienne guérisseuse vous propose d’apaiser vos nuits tourmentées.",
            ["TextMapId"] = "PartyTopic_Description_240101",
            },
        ["PartyTopic_Description_240102"] = {
            ["ContentFR"] = "Une herbe suffit parfois à voiler le regard, et ce que l’on voit n’est plus que le songe éveillé d’un passé révolu.",
            ["TextMapId"] = "PartyTopic_Description_240102",
            },
        ["PartyTopic_Description_240103"] = {
            ["ContentFR"] = "Vous l’avez vue de vos propres yeux — une guérisseuse, une dissidente, une sœur.",
            ["TextMapId"] = "PartyTopic_Description_240103",
            },
        ["PartyTopic_Description_240104"] = {
            ["ContentFR"] = "Le Pavillon de l’Éphémère est désormais désert. Mais tant que subsistent les souvenirs d’autrefois, il demeure encore le lieu qu’elle appelle son foyer.",
            ["TextMapId"] = "PartyTopic_Description_240104",
            },
        ["PartyTopic_Description_310101"] = {
            ["ContentFR"] = "Vivre, c’est manger. Tant que vous savez manger pour vivre — et pas vivre seulement pour manger — ça ira.",
            ["TextMapId"] = "PartyTopic_Description_310101",
            },
        ["PartyTopic_Description_310102"] = {
            ["ContentFR"] = "Il y a dans la haute tension une sorte de magie : elle vous attire, vous frôle, vous défie de toucher le danger pour en percer le secret.",
            ["TextMapId"] = "PartyTopic_Description_310102",
            },
        ["PartyTopic_Description_310103"] = {
            ["ContentFR"] = "Plus cruel que perdre sa maison : la voir encore là, intacte... et savoir qu’on ne pourra jamais y revenir.",
            ["TextMapId"] = "PartyTopic_Description_310103",
            },
        ["PartyTopic_Description_310201"] = {
            ["ContentFR"] = "Le rôle d’une servante couvre chaque aspect du quotidien — y compris, à l’occasion, des tâches qui laissent des taches de sang.",
            ["TextMapId"] = "PartyTopic_Description_310201",
            },
        ["PartyTopic_Description_310202"] = {
            ["ContentFR"] = "On dit que la première impression décide de tout. Et la première impression, le plus souvent, c’est ce que vous portez. S’habiller, c’est une discipline qui ne vieillit jamais.",
            ["TextMapId"] = "PartyTopic_Description_310202",
            },
        ["PartyTopic_Description_310203"] = {
            ["ContentFR"] = "Clic. Clic. Les ciseaux tranchent les fleurs fanées — et un peu des soucis du cœur.",
            ["TextMapId"] = "PartyTopic_Description_310203",
            },
        ["PartyTopic_Description_310204"] = {
            ["ContentFR"] = "On a beau se cacher dans le moindre recoin... « grandir » finit toujours par nous retrouver.",
            ["TextMapId"] = "PartyTopic_Description_310204",
            },
        ["PartyTopic_Description_310301"] = {
            ["ContentFR"] = "Il ne parle que d’explosifs et d’étincelles. C’est une façon... percutante de se présenter.",
            ["TextMapId"] = "PartyTopic_Description_310301",
            },
        ["PartyTopic_Description_310302"] = {
            ["ContentFR"] = "Une visite qui tombe sans prévenir. Une conversation qui ne tombe pas juste.",
            ["TextMapId"] = "PartyTopic_Description_310302",
            },
        ["PartyTopic_Description_310303"] = {
            ["ContentFR"] = "Parfois, « l’ennemi juré » n’est qu’une autre moitié de soi.",
            ["TextMapId"] = "PartyTopic_Description_310303",
            },
        ["PartyTopic_Description_310304"] = {
            ["ContentFR"] = "Prisonniers d’une même nuit, ils n’avaient qu’une seule chandelle : la chaleur de l’autre.",
            ["TextMapId"] = "PartyTopic_Description_310304",
            },
        ["PartyTopic_Description_320101"] = {
            ["ContentFR"] = "Une maison hantée, une cliente aux identités multiples... et {性别:un barman|une barmaid} un peu novice.",
            ["TextMapId"] = "PartyTopic_Description_320101",
            },
        ["PartyTopic_Description_320102"] = {
            ["ContentFR"] = "Un alcool fort infusé d’essences végétales. Malgré son nom, son goût n’a rien d’une amertume simple ou uniforme : il est complexe, changeant, presque insaisissable.",
            ["TextMapId"] = "PartyTopic_Description_320102",
            },
        ["PartyTopic_Description_320103"] = {
            ["ContentFR"] = "La passion du sucre est instinctive : l’être humain cherche sans même s’en rendre compte à retrouver la douceur de ses souvenirs heureux... même si l’excès lui coûte cher.",
            ["TextMapId"] = "PartyTopic_Description_320103",
            },
        ["PartyTopic_Description_320104"] = {
            ["ContentFR"] = "Il brûle la gorge comme une lame — et seuls ceux qui le boivent savent ce qu’il vient ouvrir au fond d’eux.",
            ["TextMapId"] = "PartyTopic_Description_320104",
            },
        ["PartyTopic_Description_320201"] = {
            ["ContentFR"] = "Aujourd’hui aux Asphodèles : promotion spéciale — toutes les boissons à –20 % ! Même les Charon peuvent en profiter !",
            ["TextMapId"] = "PartyTopic_Description_320201",
            },
        ["PartyTopic_Description_320202"] = {
            ["ContentFR"] = "Au moment où elle décida de mourir, Camilla fit elle aussi son choix.",
            ["TextMapId"] = "PartyTopic_Description_320202",
            },
        ["PartyTopic_Description_320203"] = {
            ["ContentFR"] = "Des années ont passé : les Asphodèles n’ont pas changé, et sa propriétaire non plus. Seule une ancienne habituée est devenue presque méconnaissable.",
            ["TextMapId"] = "PartyTopic_Description_320203",
            },
        ["PartyTopic_Description_330101"] = {
            ["ContentFR"] = "Un bon moral décuple l’efficacité.\
Et garder le moral, c’est aussi savoir quand prendre soin de soi.",
            ["TextMapId"] = "PartyTopic_Description_330101",
            },
        ["PartyTopic_Description_330102"] = {
            ["ContentFR"] = "Même ce que les autres jettent — ce qu’ils fuient, ce qu’ils dédaignent — peut renaître autrement.",
            ["TextMapId"] = "PartyTopic_Description_330102",
            },
        ["PartyTopic_Description_330103"] = {
            ["ContentFR"] = "Ce qui se transmet entre un père et sa fille, ce n’est pas seulement les habitudes, le métier, le sang, la manière de regarder le monde.\
Parfois, c’est aussi le même surnom idiot.",
            ["TextMapId"] = "PartyTopic_Description_330103",
            },
        ["PartyTopic_Description_330104"] = {
            ["ContentFR"] = "Le chemin d’un humain et celui d’un chat finissent toujours par diverger.\
On se sépare en souriant, et l’on espère une prochaine rencontre.",
            ["TextMapId"] = "PartyTopic_Description_330104",
            },
        ["PartyTopic_Description_410101"] = {
            ["ContentFR"] = "Détourner le regard est, à ses yeux, la plus grande des cruautés. Alors elle se répète : « Je dois faire quelque chose, même si ce n’est presque rien. »",
            ["TextMapId"] = "PartyTopic_Description_410101",
            },
        ["PartyTopic_Description_410102"] = {
            ["ContentFR"] = "Il faut parfois s’arrêter, ne serait-ce qu’un instant, pour discerner la route à venir... et marcher plus loin.",
            ["TextMapId"] = "PartyTopic_Description_410102",
            },
        ["PartyTopic_Description_410103"] = {
            ["ContentFR"] = "Ne plus courir entre les notes que d’autres ont tracées — mais ouvrir une page blanche, et y écrire son propre mouvement.",
            ["TextMapId"] = "PartyTopic_Description_410103",
            },
        ["PartyTopic_Description_410201"] = {
            ["ContentFR"] = "Une Voie que l’on peut nommer n’est jamais la Voie véritable. Ce qui soutient l’ordre de toute chose relève d’un principe qui dépasse les mots.",
            ["TextMapId"] = "PartyTopic_Description_410201",
            },
        ["PartyTopic_Description_410202"] = {
            ["ContentFR"] = "Gouverner n’est, au fond, qu’une affaire de décision. Depuis l’aube des temps, ceux qui ont accompli de grandes œuvres se sont-ils jamais laissés entraver par des détails insignifiants ?",
            ["TextMapId"] = "PartyTopic_Description_410202",
            },
        ["PartyTopic_Description_410203"] = {
            ["ContentFR"] = "Cultiver la vertu au sein du royaume, et elle s’épanouit. La cultiver en soi-même, et elle révèle sa véritable nature.",
            ["TextMapId"] = "PartyTopic_Description_410203",
            },
        ["PartyTopic_Description_410204"] = {
            ["ContentFR"] = "Mon cœur n’est point de pierre, il ne saurait être détourné. Mon cœur n’est point de tissu, il ne saurait être plié.",
            ["TextMapId"] = "PartyTopic_Description_410204",
            },
        ["PartyTopic_Description_420101"] = {
            ["ContentFR"] = "Une mélodie de flûte s’élève, portée par le vent. Avec elle se dissipent des souvenirs où l’amertume et la joie s’entrelacent.",
            ["TextMapId"] = "PartyTopic_Description_420101",
            },
        ["PartyTopic_Description_420102"] = {
            ["ContentFR"] = "Le foyer d’autrefois s’est effondré sous le vent et la pluie. Où donc se trouve encore le véritable havre ?",
            ["TextMapId"] = "PartyTopic_Description_420102",
            },
        ["PartyTopic_Description_420103"] = {
            ["ContentFR"] = "Lorsque la lame se teinte de sang, en se retournant, il devient déjà impossible de retrouver le chemin parcouru.",
            ["TextMapId"] = "PartyTopic_Description_420103",
            },
        ["PartyTopic_Description_420104"] = {
            ["ContentFR"] = "Lorsque la poussière retombe et que les nuages se dissipent, où donc s’avance celui qui s’était égaré ?",
            ["TextMapId"] = "PartyTopic_Description_420104",
            },
        ["PartyTopic_Description_420201"] = {
            ["ContentFR"] = "Chez les gens intelligents, chaque phrase sert un but. On pourrait appeler cela de la manipulation. Ou, si l’on est indulgent, une forme de franchise.",
            ["TextMapId"] = "PartyTopic_Description_420201",
            },
        ["PartyTopic_Description_420202"] = {
            ["ContentFR"] = "Un « gentleman », ça ne tombe pas du ciel.\
On le façonne : éducation, milieu... et la pression discrète de la famille.",
            ["TextMapId"] = "PartyTopic_Description_420202",
            },
        ["PartyTopic_Description_420203"] = {
            ["ContentFR"] = "Ah, père...",
            ["TextMapId"] = "PartyTopic_Description_420203",
            },
        ["PartyTopic_Description_420204"] = {
            ["ContentFR"] = "Une danse, avant que la cloche ne sonne.",
            ["TextMapId"] = "PartyTopic_Description_420204",
            },
        ["PartyTopic_Description_430101"] = {
            ["ContentFR"] = "La vraie loyauté se mesure sous une lame suspendue, dont on ignore l’instant où elle tombera.",
            ["TextMapId"] = "PartyTopic_Description_430101",
            },
        ["PartyTopic_Description_430102"] = {
            ["ContentFR"] = "La guerre n’est jamais partie. Elle a seulement changé de forme.",
            ["TextMapId"] = "PartyTopic_Description_430102",
            },
        ["PartyTopic_Description_430103"] = {
            ["ContentFR"] = "Depuis que l’humanité errait entre forêt et steppe, l’outil n’a eu qu’un rôle : nous permettre de survivre.\
Rien n’a changé — qu’il serve à créer ou à détruire.",
            ["TextMapId"] = "PartyTopic_Description_430103",
            },
        ["PartyTopic_Description_510101"] = {
            ["ContentFR"] = "Manger est le besoin le plus simple des vivants. Mais bien manger, ça, c’est tout un art.",
            ["TextMapId"] = "PartyTopic_Description_510101",
            },
        ["PartyTopic_Description_510102"] = {
            ["ContentFR"] = "« Le gaspillage, c’est la honte » — on nous le répète dès l’enfance.\
Et pourtant, plus on grandit, plus il devient difficile d’honorer cette règle.",
            ["TextMapId"] = "PartyTopic_Description_510102",
            },
        ["PartyTopic_Description_510103"] = {
            ["ContentFR"] = "Aux yeux du monde, un cochon n’a rien d’exceptionnel. Mais Filbert, pour Truffle, est irremplaçable.",
            ["TextMapId"] = "PartyTopic_Description_510103",
            },
        ["PartyTopic_Description_510104"] = {
            ["ContentFR"] = "Chacun a sa propre idée du bonheur. Mais quoi qu’il arrive, il faut un ventre plein pour avoir la force de le poursuivre.",
            ["TextMapId"] = "PartyTopic_Description_510104",
            },
        ["PartyTopic_Description_510201"] = {
            ["ContentFR"] = "Les vrais amis ne demandent rien : un repas simple, un salut sincère — cela suffit.",
            ["TextMapId"] = "PartyTopic_Description_510201",
            },
        ["PartyTopic_Description_510202"] = {
            ["ContentFR"] = "Même les règles les plus contraignantes finissent par s’apprivoiser.\
Mais les gens compliqués ? S’y habituer ne mène qu’au chaos, et votre vie devient un nœud impossible à défaire.",
            ["TextMapId"] = "PartyTopic_Description_510202",
            },
        ["PartyTopic_Description_510203"] = {
            ["ContentFR"] = "Certains secrets rapprochent, allègent le cœur. \
Mais d’autres doivent être ensevelis — profonds, sombres, intouchés. Mieux vaut qu’ils ne revoient jamais la lumière du jour.",
            ["TextMapId"] = "PartyTopic_Description_510203",
            },
        ["PartyTopic_Description_510204"] = {
            ["ContentFR"] = "Ce n’est pas mon vrai nom. Mais « L’Étranger »... me va mieux.",
            ["TextMapId"] = "PartyTopic_Description_510204",
            },
        ["PartyTopic_Description_530101"] = {
            ["ContentFR"] = "La valeur d’une vie ne se compte pas en jours, mais en la manière dont ces jours sont vécus.",
            ["TextMapId"] = "PartyTopic_Description_530101",
            },
        ["PartyTopic_Description_530102"] = {
            ["ContentFR"] = "La mort n’est pas ce qu’il y a de plus effrayant.\
Ce qui glace vraiment, c’est l’oubli.",
            ["TextMapId"] = "PartyTopic_Description_530102",
            },
        ["PartyTopic_Description_530103"] = {
            ["ContentFR"] = "On ne sait jamais si demain viendra avant l’accident...\
Mais pour demain, nous affrontons chaque imprévu.",
            ["TextMapId"] = "PartyTopic_Description_530103",
            },
        ["PartyTopic_Description_540101"] = {
            ["ContentFR"] = "Une douleur qui s’éternise... ou une mort instantanée. Je ne sais pas laquelle est la plus cruelle. Mais peut-être... avons-nous encore une chance de vaincre la première.",
            ["TextMapId"] = "PartyTopic_Description_540101",
            },
        ["PartyTopic_Description_540102"] = {
            ["ContentFR"] = "Retournez en arrière — vite ! Ce n’est pas la tour dont je rêvais.\
Dans mes rêves, il n’y avait ni sang... ni cris.",
            ["TextMapId"] = "PartyTopic_Description_540102",
            },
        ["PartyTopic_Description_540103"] = {
            ["ContentFR"] = "À l’approche de la fin de cette longue nuit, moi aussi je prendrai la route. Je ne crois pas qu’une mort vaine m’attende... mais quelque chose au-delà.\
Quelque chose que je dois découvrir.",
            ["TextMapId"] = "PartyTopic_Description_540103",
            },
        ["PartyTopic_Name_110101"] = {
            ["ContentFR"] = "Saveur",
            ["TextMapId"] = "PartyTopic_Name_110101",
            },
        ["PartyTopic_Name_110102"] = {
            ["ContentFR"] = "Blessures",
            ["TextMapId"] = "PartyTopic_Name_110102",
            },
        ["PartyTopic_Name_110103"] = {
            ["ContentFR"] = "Au-delà",
            ["TextMapId"] = "PartyTopic_Name_110103",
            },
        ["PartyTopic_Name_110104"] = {
            ["ContentFR"] = "Demain",
            ["TextMapId"] = "PartyTopic_Name_110104",
            },
        ["PartyTopic_Name_110301"] = {
            ["ContentFR"] = "Départ funeste",
            ["TextMapId"] = "PartyTopic_Name_110301",
            },
        ["PartyTopic_Name_110302"] = {
            ["ContentFR"] = "Article de journal pompeux",
            ["TextMapId"] = "PartyTopic_Name_110302",
            },
        ["PartyTopic_Name_110303"] = {
            ["ContentFR"] = "Brisure moqueuse",
            ["TextMapId"] = "PartyTopic_Name_110303",
            },
        ["PartyTopic_Name_110304"] = {
            ["ContentFR"] = "Faux épilogue",
            ["TextMapId"] = "PartyTopic_Name_110304",
            },
        ["PartyTopic_Name_150201"] = {
            ["ContentFR"] = "La mort est douce",
            ["TextMapId"] = "PartyTopic_Name_150201",
            },
        ["PartyTopic_Name_150202"] = {
            ["ContentFR"] = "Une éclaircie fugitive",
            ["TextMapId"] = "PartyTopic_Name_150202",
            },
        ["PartyTopic_Name_150203"] = {
            ["ContentFR"] = "Le paysage du mauvais chemin",
            ["TextMapId"] = "PartyTopic_Name_150203",
            },
        ["PartyTopic_Name_150204"] = {
            ["ContentFR"] = "Son histoire",
            ["TextMapId"] = "PartyTopic_Name_150204",
            },
        ["PartyTopic_Name_150301"] = {
            ["ContentFR"] = "L’enfant et l’épée, au cœur des bois",
            ["TextMapId"] = "PartyTopic_Name_150301",
            },
        ["PartyTopic_Name_150302"] = {
            ["ContentFR"] = "Le vagabond aux regrets, par-delà monts et rivières",
            ["TextMapId"] = "PartyTopic_Name_150302",
            },
        ["PartyTopic_Name_150303"] = {
            ["ContentFR"] = "La flûte de jade et le breuvage trouble",
            ["TextMapId"] = "PartyTopic_Name_150303",
            },
        ["PartyTopic_Name_150304"] = {
