  { MinKey = "Pet_Break_ReConfirm", MaxKey = "PlayerLevel_PetBreak", Loader = function()
      return {
        ["Pet_Break_ReConfirm"] = {
            ["ContentFR"] = "Consommer un Géniemon ayant subi une ascension ne restitue pas les matériaux utilisés. Continuer ?",
            ["TextMapId"] = "Pet_Break_ReConfirm",
            },
        ["Pet_Filter"] = {
            ["ContentFR"] = "Filtrer les Géniemon",
            ["TextMapId"] = "Pet_Filter",
            },
        ["Pet_Filter_Title1"] = {
            ["ContentFR"] = "Nombre de traits",
            ["TextMapId"] = "Pet_Filter_Title1",
            },
        ["Pet_Filter_Title2"] = {
            ["ContentFR"] = "Altéré ou non",
            ["TextMapId"] = "Pet_Filter_Title2",
            },
        ["Pet_Filter_Title3"] = {
            ["ContentFR"] = "Rareté",
            ["TextMapId"] = "Pet_Filter_Title3",
            },
        ["Pet_Filter_Title4"] = {
            ["ContentFR"] = "Traits inclus",
            ["TextMapId"] = "Pet_Filter_Title4",
            },
        ["Pet_IpDes_401"] = {
            ["ContentFR"] = "Souvent aperçu près des ruines, des champs de bataille ou des cimetières, ce Géniemon se nourrit des restes des défunts. Ses deux cornes, autant que ses habitudes funèbres, lui ont valu d’être tenu pour un funeste présage.",
            ["TextMapId"] = "Pet_IpDes_401",
            },
        ["Pet_IpDes_402"] = {
            ["ContentFR"] = "Géniemon aquatique flottant dans les airs. Son corps translucide, recroquevillé sur lui-même, se fond si bien dans la lumière qu’on le distingue à peine.\
Ce n’est qu’à la pluie qu’il s’éveille et s’étire, s’épanouissant dans le ciel tel une fleur de cristal.",
            ["TextMapId"] = "Pet_IpDes_402",
            },
        ["Pet_IpDes_403"] = {
            ["ContentFR"] = "Géniemon dont plus de la moitié du corps est composée de glandes thermiques. Il suffit qu’il entrouvre la bouche pour qu’en jaillisse une vague brûlante, capable d’embraser l’air lui-même.",
            ["TextMapId"] = "Pet_IpDes_403",
            },
        ["Pet_IpDes_404"] = {
            ["ContentFR"] = "Géniemon des hauts plateaux, célèbre pour son pelage à la conductivité exceptionnelle. Longtemps chassé par les humains, il s’est fait méfiant : à la moindre présence, il se roule en boule et dévale les pentes à la vitesse de l’éclair.",
            ["TextMapId"] = "Pet_IpDes_404",
            },
        ["Pet_IpDes_405"] = {
            ["ContentFR"] = "Géniemon parasite qui s’installe dans les champignons, prenant peu à peu le contrôle de leur organisme.\
Le son « pouf pouf » qu’il émet provient du vent s’engouffrant dans la cavité entre son corps et l’enveloppe de son hôte.",
            ["TextMapId"] = "Pet_IpDes_405",
            },
        ["Pet_IpDes_406"] = {
            ["ContentFR"] = "Géniemon vif, malicieux et cupide, passionné par tout ce qui brille.\
Si vous avez la chance d’en apercevoir un... vérifiez aussitôt si vos bijoux sont toujours à leur place.",
            ["TextMapId"] = "Pet_IpDes_406",
            },
        ["Pet_IpDes_407"] = {
            ["ContentFR"] = "Géniemon charognard à tendance casanière.\
Il collectionne compulsivement tout ce qu’il peut entasser : une partie sert de nourriture, le reste de matériaux pour tapisser son nid intérieur.",
            ["TextMapId"] = "Pet_IpDes_407",
            },
        ["Pet_IpDes_408"] = {
            ["ContentFR"] = "Géniemon d’une agilité remarquable. Ses longues oreilles, loin d’entraver ses mouvements, lui donnent une silhouette fuselée et parfaitement aérodynamique.",
            ["TextMapId"] = "Pet_IpDes_408",
            },
        ["Pet_IpDes_409"] = {
            ["ContentFR"] = "Géniemon paresseux mais à la longévité légendaire.\
On estime qu’il passe plus de 98 % de sa vie à dormir — un repos qui, semble-t-il, lui assure une éternelle jeunesse.",
            ["TextMapId"] = "Pet_IpDes_409",
            },
        ["Pet_IpDes_411"] = {
            ["ContentFR"] = "Ce Géniemon hante les vieux châteaux, les ruines et toutes les bâtisses désertées.\
De loin, il n’est qu’une lueur flottant dans l’ombre — une petite flamme spectrale suspendue dans les airs.",
            ["TextMapId"] = "Pet_IpDes_411",
            },
        ["Pet_IpDes_412"] = {
            ["ContentFR"] = "Aussi souple qu’un pudding et adorable à souhait, ce Géniemon — surnommé le Lapiniva — fit un temps fureur sur tout le continent.\
Jusqu’au jour où un érudit d’Aethyrie révéla que ses deux petits \"yeux\" noirs... n’étaient pas des yeux, mais une partie de son système interne. Depuis, disons simplement que sa popularité n’est jamais remontée.",
            ["TextMapId"] = "Pet_IpDes_412",
            },
        ["Pet_IpDes_413"] = {
            ["ContentFR"] = "Entièrement drapé de flammes, ce Géniemon né des terres brûlantes dégage en permanence un délicat parfum de viande grillée... Un fumet qui annonce sa présence bien avant que vous ne l’aperceviez.",
            ["TextMapId"] = "Pet_IpDes_413",
            },
        ["Pet_IpDes_414"] = {
            ["ContentFR"] = "Constamment parcouru d’électricité statique, ce pauvre Géniemon se voit souvent rejeté par les siens. Nul ne connaît réellement son apparence ; tout ce que l’on aperçoit, ce sont deux yeux tristes qui dépassent timidement d’une minuscule voiture-jouet.",
            ["TextMapId"] = "Pet_IpDes_414",
            },
        ["Pet_IpDes_415"] = {
            ["ContentFR"] = "Vif et minuscule, ce Géniemon est incapable de demeurer en place. Il se laisse porter aux quatre vents, agrippé à une graine de coton, poursuivant l’illusion obstinée d’un voyage dont l’ultime destination... n’existe pas.",
            ["TextMapId"] = "Pet_IpDes_415",
            },
        ["Pet_IpDes_416"] = {
            ["ContentFR"] = "Aussi éclatant qu’une étoile embrasée, ce Géniemon sert parfois de guide ou de flambeau aux voyageurs épuisés. Mais prenez garde : ses éclairs lumineux, réguliers et aveuglants, ne doivent jamais être fixés trop longtemps.",
            ["TextMapId"] = "Pet_IpDes_416",
            },
        ["Pet_IpDes_421"] = {
            ["ContentFR"] = "D’une rareté presque mythique, ce Géniemon arbore l’éclat sombre et profond de l’obsidienne. Longtemps, l’on crut qu’il n’existait que dans les ballades des bardes et les rêves des ménestrels.",
            ["TextMapId"] = "Pet_IpDes_421",
            },
        ["Pet_IpDes_422"] = {
            ["ContentFR"] = "D’une rareté presque mythique, ce Géniemon arbore l’éclat limpide et bleuté de l’iolite. Longtemps, l’on crut qu’il n’existait que dans les ballades des bardes et les rêves des ménestrels.",
            ["TextMapId"] = "Pet_IpDes_422",
            },
        ["Pet_IpDes_423"] = {
            ["ContentFR"] = "D’une rareté presque mythique, ce Géniemon arbore l’éclat chaleureux de la cornaline. Longtemps, l’on crut qu’il n’existait que dans les ballades des bardes et les rêves des ménestrels.",
            ["TextMapId"] = "Pet_IpDes_423",
            },
        ["Pet_IpDes_424"] = {
            ["ContentFR"] = "D’une rareté presque mythique, ce Géniemon arbore l’éclat cristallin de l’améthyste.\
Longtemps, l’on crut qu’il n’existait que dans les ballades des bardes et les rêves des ménestrels.",
            ["TextMapId"] = "Pet_IpDes_424",
            },
        ["Pet_IpDes_425"] = {
            ["ContentFR"] = "D’une rareté presque mythique, ce Géniemon arbore l’éclat profond de l’émeraude. Longtemps, l’on crut qu’il n’existait que dans les ballades des bardes et les rêves des ménestrels.",
            ["TextMapId"] = "Pet_IpDes_425",
            },
        ["Pet_IpDes_426"] = {
            ["ContentFR"] = "D’une rareté presque mythique, ce Géniemon arbore les reflets changeants de l’opale. Longtemps, l’on crut qu’il n’existait que dans les ballades des bardes et les rêves des ménestrels.",
            ["TextMapId"] = "Pet_IpDes_426",
            },
        ["Pet_IpDes_491"] = {
            ["ContentFR"] = "Ce Géniemon a choisi de prendre l’apparence d’un Drone guérisseur. Les principes du mimétisme des Géniemon demeurent inconnus, mais celui-ci s’est parfaitement adapté aux conditions des Éolipyliens, développant les caractéristiques les plus propices à sa survie.",
            ["TextMapId"] = "Pet_IpDes_491",
            },
        ["Pet_IpDes_492"] = {
            ["ContentFR"] = "Ce Géniemon a choisi de prendre l’apparence d’un Drone magnétique. Les principes du mimétisme des Géniemon demeurent inconnus, mais celui-ci s’est parfaitement adapté aux conditions des Éolipyliens, développant les caractéristiques les plus propices à sa survie.",
            ["TextMapId"] = "Pet_IpDes_492",
            },
        ["Pet_IpDes_493"] = {
            ["ContentFR"] = "Ce Géniemon fouisseur se glisse entre les failles du sol. Il se nourrit de décomposition et, ce faisant, enrichit la terre — rendant à la nature ce qu’elle lui a accordé.",
            ["TextMapId"] = "Pet_IpDes_493",
            },
