        ["QuestDesc_10020101"] = {
            ["ContentFR"] = "Ce jour-là, sur l’Île du Purgatoire, vous avez survécu par miracle.\
À votre réveil, Berenica avait disparu, et la plaine enneigée devant vous vous était totalement étrangère.\
Une femme en rouge nommée Camilla, accompagnée d’une jeune fille appelée Snow, vous a proposé de les suivre jusqu’à Givrelac.\
Après mûre réflexion, vous avez accepté de les accompagner...",
            ["TextMapId"] = "QuestDesc_10020101",
            },
        ["QuestDesc_10020102"] = {
            ["ContentFR"] = "Ce jour-là, sur l’Île du Purgatoire, vous avez survécu par miracle.\
À votre réveil, Berenica avait disparu, et la plaine enneigée devant vous vous était totalement étrangère.\
Une femme en rouge nommée Camilla, accompagnée d’une jeune fille appelée Snow, vous a proposé de les suivre jusqu’à Givrelac.\
Après mûre réflexion, vous avez accepté de les accompagner...",
            ["TextMapId"] = "QuestDesc_10020102",
            },
        ["QuestDesc_10020103"] = {
            ["ContentFR"] = "Des véhicules renversés et des cargaisons éparpillées sur le pont ont attiré les Souillés.\
Repoussez ces intrus indésirables.",
            ["TextMapId"] = "QuestDesc_10020103",
            },
        ["QuestDesc_10020104"] = {
            ["ContentFR"] = "Après avoir repoussé les créatures, vous et Snow reprenez la route en direction de Givrelac.",
            ["TextMapId"] = "QuestDesc_10020104",
            },
        ["QuestDesc_10020105"] = {
            ["ContentFR"] = "Malgré un contrôle inopiné des gardes concernant les permis de circulation, vous avez pu entrer à Givrelac grâce à l’intervention habile de Camilla.",
            ["TextMapId"] = "QuestDesc_10020105",
            },
        ["QuestDesc_10020106"] = {
            ["ContentFR"] = "Camilla vous conseille d’aller loger à la Maison d’Hypnos.\
Bien que le lieu soit entouré de rumeurs inquiétantes, vous décidez de vous y rendre pour en savoir plus...",
            ["TextMapId"] = "QuestDesc_10020106",
            },
        ["QuestDesc_10020107"] = {
            ["ContentFR"] = "Camilla vous conseille d’aller loger à la Maison d’Hypnos.\
Bien que le lieu soit entouré de rumeurs inquiétantes, vous décidez de vous y rendre pour en savoir plus...",
            ["TextMapId"] = "QuestDesc_10020107",
            },
        ["QuestDesc_10020108"] = {
            ["ContentFR"] = "Le propriétaire de la Maison d’Hypnos, Henrik, est un homme froid et taciturne.\
Malgré son ton brusque, il finit par vous accorder une nuit d’hébergement, à la demande d’une jeune fille enjouée.\
Rendez-vous maintenant à la demeure qu’elle vous a indiquée.",
            ["TextMapId"] = "QuestDesc_10020108",
            },
        ["QuestDesc_10020109"] = {
            ["ContentFR"] = "Le propriétaire de la Maison d’Hypnos, Henrik, est un homme froid et taciturne.\
Malgré son ton brusque, il finit par vous accorder une nuit d’hébergement, à la demande d’une jeune fille enjouée.\
Rendez-vous maintenant à la demeure qu’elle vous a indiquée.",
            ["TextMapId"] = "QuestDesc_10020109",
            },
        ["QuestDesc_10020110"] = {
            ["ContentFR"] = "Un rare moment de répit.\
Vous en profitez pour reprendre votre souffle et faire le point sur la situation.",
            ["TextMapId"] = "QuestDesc_10020110",
            },
        ["QuestDesc_10020111"] = {
            ["ContentFR"] = "Vous avez quelques questions à poser à Psyche.",
            ["TextMapId"] = "QuestDesc_10020111",
            },
        ["QuestDesc_10020112"] = {
            ["ContentFR"] = "Avant de vous lancer à la recherche de Berenica, il vous faut réunir de l’argent et obtenir un permis de circulation.\
D’après Psyche, la taverne des Asphodèles, tenue par Camilla, permet d’accepter des missions rémunérées sans avoir besoin de permis.",
            ["TextMapId"] = "QuestDesc_10020112",
            },
        ["QuestDesc_10020201"] = {
            ["ContentFR"] = "Avant de vous lancer à la recherche de Berenica, il vous faut réunir de l’argent et obtenir un permis de circulation.\
D’après Psyche, la taverne des Asphodèles, tenue par Camilla, permet d’accepter des missions rémunérées sans avoir besoin de permis.",
            ["TextMapId"] = "QuestDesc_10020201",
            },
        ["QuestDesc_10020202"] = {
            ["ContentFR"] = "Avant de vous lancer à la recherche de Berenica, il vous faut réunir de l’argent et obtenir un permis de circulation.\
D’après Psyche, la taverne des Asphodèles, tenue par Camilla, permet d’accepter des missions rémunérées sans avoir besoin de permis.",
            ["TextMapId"] = "QuestDesc_10020202",
            },
        ["QuestDesc_10020203"] = {
            ["ContentFR"] = "Sur la place, vous êtes témoin d’une scène de violence — chose malheureusement banale pour les Charons, reconnaissables à leurs cornes et à leur épine dorsale.\
Pour éviter d’attirer des ennuis à Camilla, qui s’est portée garante de vous, vous préférez rester discret.\
Continuez votre chemin vers les Asphodèles.",
            ["TextMapId"] = "QuestDesc_10020203",
            },
        ["QuestDesc_10020204"] = {
            ["ContentFR"] = "Une jeune fille nommée Margie, une récupératrice de déchets, semble en difficulté.\
Allez lui parler pour en apprendre davantage.",
            ["TextMapId"] = "QuestDesc_10020204",
            },
        ["QuestDesc_10020205"] = {
            ["ContentFR"] = "Une jeune fille nommée Margie, une récupératrice de déchets, semble en difficulté.\
Allez lui parler pour en apprendre davantage.",
            ["TextMapId"] = "QuestDesc_10020205",
            },
        ["QuestDesc_10020206"] = {
            ["ContentFR"] = "Margie s’est fait dérober sa bourse par un voleur.\
Aidez-la à la récupérer — non seulement pour lui rendre service, mais aussi pour prouver votre valeur à Camilla.",
            ["TextMapId"] = "QuestDesc_10020206",
            },
        ["QuestDesc_10020207"] = {
            ["ContentFR"] = "Une jeune récupératrice nommée Margie s’est fait dérober sa bourse.\
Après avoir quitté les Asphodèles, interrogez les habitants de la place pour savoir si quelqu’un a aperçu le voleur.",
            ["TextMapId"] = "QuestDesc_10020207",
            },
        ["QuestDesc_10020208"] = {
            ["ContentFR"] = "Un vieil homme nommé Badi, posté près de la place, affirme avoir vu le voleur.\
Selon ses dires, la piste mène du côté de la troisième poubelle.",
            ["TextMapId"] = "QuestDesc_10020208",
            },
        ["QuestDesc_10020209"] = {
            ["ContentFR"] = "Près de la poubelle, vous découvrez effectivement des traces du voleur — elles mènent jusqu’aux toits.\
Montez sur le toit et poursuivez votre enquête.",
            ["TextMapId"] = "QuestDesc_10020209",
            },
        ["QuestDesc_10020210"] = {
            ["ContentFR"] = "Vous êtes sur le toit. Fouillez les environs à la recherche du voleur.",
            ["TextMapId"] = "QuestDesc_10020210",
            },
        ["QuestDesc_10020211"] = {
            ["ContentFR"] = "Vous retrouvez enfin le voleur qui a dérobé la bourse de Margie.\
Après une brève confrontation, il s’enfuit soudainement.\
Pas une minute à perdre : poursuivez-le !\
Attendez... quelque chose semble étrange près de la bouche d’égout.",
            ["TextMapId"] = "QuestDesc_10020211",
            },
        ["QuestDesc_10020212"] = {
            ["ContentFR"] = "Vous poursuivez le voleur jusque dans les égouts de Givrelac.\
Il a laissé derrière lui plusieurs dispositifs destinés à entraver votre progression.\
Trouvez un moyen de désactiver les vannes pour continuer la chasse.",
            ["TextMapId"] = "QuestDesc_10020212",
            },
        ["QuestDesc_10020213"] = {
            ["ContentFR"] = "Les mécanismes sont désamorcés, le niveau d’eau a baissé.\
Pas de temps à perdre : reprenez la poursuite.",
            ["TextMapId"] = "QuestDesc_10020213",
            },
        ["QuestDesc_10020213_1"] = {
            ["ContentFR"] = "Le voleur vous a tendu une embuscade à l’aide d’un petit piège qu’il avait préparé. Margie et Snow ont été prises au dépourvu et ont subi quelques coups.\
Continuez de fouiller les environs : il ne peut pas être bien loin.",
            ["TextMapId"] = "QuestDesc_10020213_1",
            },
        ["QuestDesc_10020214"] = {
            ["ContentFR"] = "Le voleur a utilisé un petit dispositif pour répandre un épais nuage de fumée et disparaître dans la brume. Pour poursuivre la traque, vous devrez trouver une clé de rechange.",
            ["TextMapId"] = "QuestDesc_10020214",
            },
        ["QuestDesc_10020215"] = {
            ["ContentFR"] = "Vous avez enfin repéré le voleur ! Cette fois, il ne vous échappera pas.\
Affrontez-le et capturez-le.",
            ["TextMapId"] = "QuestDesc_10020215",
            },
        ["QuestDesc_10020221"] = {
            ["ContentFR"] = "Vous avez accompli la mission confiée par Margie.\
Retournez aux Asphodèles pour en recevoir la récompense.",
            ["TextMapId"] = "QuestDesc_10020221",
            },
        ["QuestDesc_10020222"] = {
            ["ContentFR"] = "Toutes les missions destinées aux Chasseurs de Phoxène sont affichées sur le tableau des Asphodèles. Allez y jeter un œil.",
            ["TextMapId"] = "QuestDesc_10020222",
            },
        ["QuestDesc_10020223"] = {
            ["ContentFR"] = "Un malentendu embarrassant s’est produit avec Wells, un Chasseur de Phoxène.\
Pour s’excuser, il vous invite à boire quelque chose de chaud.",
            ["TextMapId"] = "QuestDesc_10020223",
            },
        ["QuestDesc_10020224"] = {
            ["ContentFR"] = "Les Géniemon sont désormais disponibles.\
Capturez-en un pour qu’il vous accompagne dans vos futures aventures.",
            ["TextMapId"] = "QuestDesc_10020224",
            },
        ["QuestDesc_10020301"] = {
            ["ContentFR"] = "Henrik, le propriétaire de la Maison d’Hypnos, a offert une forte récompense aux Chasseurs de Phoxène pour retrouver un artéfact appelé l’Éclat stellaire, enfoui dans la Fosse de Glevum.\
Cette somme suffirait à payer votre passage vers le Sud, vous décidez donc de tenter l’aventure...",
            ["TextMapId"] = "QuestDesc_10020301",
            },
        ["QuestDesc_10020302"] = {
            ["ContentFR"] = "Psyche a décidé de vous accompagner et de vous guider jusqu’à la Fosse de Glevum.\
Partez avec elle vers la mine.",
            ["TextMapId"] = "QuestDesc_10020302",
            },
        ["QuestDesc_10020303"] = {
            ["ContentFR"] = "Psyche semble avoir pris sa décision : elle se joint à vous pour cette petite \"aventure\". Partez avec elle vers la Fosse de Glevum.",
            ["TextMapId"] = "QuestDesc_10020303",
            },
        ["QuestDesc_10020304"] = {
            ["ContentFR"] = "Les portes de la Fosse de Glevum sont condamnées depuis des années.\
Cherchez un autre moyen d’y pénétrer.",
            ["TextMapId"] = "QuestDesc_10020304",
            },
        ["QuestDesc_10020305"] = {
            ["ContentFR"] = "En suivant un ancien conduit, vous atteignez les entrailles de la Fosse de Glevum.\
Autrefois, un immense Arbre Céleste perçait la montagne, mais il a été entièrement extrait, ne laissant que de fines racines — les vestiges d’un âge d’abondance.\
Explorez les profondeurs de cette mine délaissée pour y trouver l’Éclat stellaire demandé par Henrik.",
            ["TextMapId"] = "QuestDesc_10020305",
            },
        ["QuestDesc_10020306"] = {
            ["ContentFR"] = "En suivant un ancien conduit, vous atteignez les entrailles de la Fosse de Glevum.\
Autrefois, un immense Arbre Céleste perçait la montagne, mais il a été entièrement extrait, ne laissant que de fines racines — les vestiges d’un âge d’abondance.\
Explorez les profondeurs de cette mine délaissée pour y trouver l’Éclat stellaire demandé par Henrik.",
            ["TextMapId"] = "QuestDesc_10020306",
            },
        ["QuestDesc_10020307"] = {
            ["ContentFR"] = "Vous êtes {性别:parvenus|parvenues} à pénétrer dans la Fosse de Glevum, mais une porte scellée bloque votre avancée. Explorez les alentours : vous trouverez peut-être un moyen de l’ouvrir.\
...\
Un Chasseur de Phoxène mentionnait autrefois, dans son journal, des lampes de guidage et des panneaux indicateurs. Si vous en avez la force, songez à les remettre en état : ils pourraient illuminer la route de ceux qui viendront après.",
            ["TextMapId"] = "QuestDesc_10020307",
            },
        ["QuestDesc_10020308"] = {
            ["ContentFR"] = "En suivant un ancien conduit, vous atteignez les entrailles de la Fosse de Glevum.\
Autrefois, un immense Arbre Céleste perçait la montagne, mais il a été entièrement extrait, ne laissant que de fines racines — les vestiges d’un âge d’abondance.\
De nombreux Souillés rôdent encore dans la fosse abandonnée. Vainquez ceux qui barrent la route, et poursuivez votre avancée.",
            ["TextMapId"] = "QuestDesc_10020308",
            },
        ["QuestDesc_10020309"] = {
            ["ContentFR"] = "En suivant un ancien conduit, vous atteignez les entrailles de la Fosse de Glevum.\
Autrefois, un immense Arbre Céleste perçait la montagne, mais il a été entièrement extrait, ne laissant que de fines racines — les vestiges d’un âge d’abondance.\
Actionnez le mécanisme pour ouvrir la porte, puis continuez à explorer la mine délaissée afin d’y trouver l’Éclat stellaire demandé par Henrik.",
            ["TextMapId"] = "QuestDesc_10020309",
            },
        ["QuestDesc_10020310"] = {
            ["ContentFR"] = "En suivant un ancien conduit, vous atteignez les entrailles de la Fosse de Glevum.\
Autrefois, un immense Arbre Céleste perçait la montagne, mais il a été entièrement extrait, ne laissant que de fines racines — les vestiges d’un âge d’abondance.\
Explorez les profondeurs de cette mine délaissée pour y trouver l’Éclat stellaire demandé par Henrik.",
            ["TextMapId"] = "QuestDesc_10020310",
            },
        ["QuestDesc_10020311"] = {
            ["ContentFR"] = "En longeant les tunnels abandonnés, vous atteignez les profondeurs de la Fosse de Glevum. Là où s’élevait jadis un majestueux Arbre Céleste, il ne subsiste plus que de frêles racines — vestiges d’une splendeur arrachée par des années d’exploitation. Les éboulis et les pointes cristallines qui parsèment le sol laissent présager un danger latent. Pénétrez dans la mine délaissée et cherchez l’Éclat stellaire qu’Henrik vous a chargé de retrouver.",
            ["TextMapId"] = "QuestDesc_10020311",
            },
        ["QuestDesc_10020312"] = {
            ["ContentFR"] = "En longeant les tunnels abandonnés, vous atteignez les profondeurs de la Fosse de Glevum. Là où s’élevait jadis un majestueux Arbre Céleste, il ne subsiste plus que de frêles racines — vestiges d’une splendeur arrachée par des années d’exploitation. Les éboulis et les pointes cristallines qui parsèment le sol laissent présager un danger latent. Pénétrez dans la mine délaissée et cherchez l’Éclat stellaire qu’Henrik vous a chargé de retrouver.",
            ["TextMapId"] = "QuestDesc_10020312",
            },
        ["QuestDesc_10020313"] = {
            ["ContentFR"] = "Votre arrivée a réveillé le gigantesque Souillé tapi dans les profondeurs de la Fosse de Glevum. Il est trop tard pour reculer, trouvez un moyen de l’abattre avant qu’il ne déchaîne toute sa fureur.",
            ["TextMapId"] = "QuestDesc_10020313",
            },
        ["QuestDesc_10020314"] = {
            ["ContentFR"] = "Sous la carcasse terrifiante du gigantesque Souillé repose un joyau irradiant d’une lueur astrale.\
Ramassez-le et emportez-le avec vous.",
            ["TextMapId"] = "QuestDesc_10020314",
            },
        ["QuestDesc_10020315"] = {
            ["ContentFR"] = "Votre première expédition à la Fosse de Glevum s’est achevée sans encombre — à l’exception de cette désagréable rencontre avec l’Étranger.\
L’Étranger est reparti avec l’Éclat stellaire.\
Il semble vouloir vous parler, et vous avez convenu de vous retrouver chez lui.",
            ["TextMapId"] = "QuestDesc_10020315",
            },
        ["QuestDesc_10020316"] = {
            ["ContentFR"] = "Votre première expédition dans la Fosse de Glevum s’achève — malgré la fâcheuse apparition de l’Étranger. L’Étranger est parti avec l’Éclat stellaire. Il semble vouloir vous parler, et vous avez convenu de le retrouver chez lui.\
Pendant ce temps, quelqu’un vous attend aux portes de Givrelac... et il n’a pas l’air ravi.",
            ["TextMapId"] = "QuestDesc_10020316",
            },
        ["QuestDesc_10020401"] = {
            ["ContentFR"] = "L’Étranger a insisté pour vous rencontrer {性别:seul|seule}, et Snow est repartie en avance.\
Il habite dans les taudis — selon ses dires, sa porte est ornée d’un petit oiseau.",
            ["TextMapId"] = "QuestDesc_10020401",
            },
        ["QuestDesc_10020402"] = {
            ["ContentFR"] = "Vous avez partagé un goûter modeste mais chaleureux avec l’Étranger et sa sœur Fina.\
Après le repas, il semble vouloir s’entretenir en privé avec vous.",
            ["TextMapId"] = "QuestDesc_10020402",
            },
        ["QuestDesc_10020403"] = {
            ["ContentFR"] = "Vous avez partagé un goûter modeste mais chaleureux avec l’Étranger et sa sœur Fina.\
Après le repas, il semble vouloir s’entretenir en privé avec vous.",
            ["TextMapId"] = "QuestDesc_10020403",
            },
        ["QuestDesc_10020404"] = {
            ["ContentFR"] = "En échange d’un permis de circulation, l’Étranger vous demande d’enquêter sur la Maison d’Hypnos, sous prétexte d’y remettre l’Éclat stellaire.\
Mais avant cela, prenez un peu de repos.",
            ["TextMapId"] = "QuestDesc_10020404",
            },
        ["QuestDesc_10020405"] = {
            ["ContentFR"] = "D’après les révélations de l’Étranger la nuit dernière, la Maison d’Hypnos, dirigée par Henrik, dissimulerait un lourd secret — un Chasseur de Phoxène nommé Hunt y aurait disparu.\
Vous décidez de mener l’enquête.",
            ["TextMapId"] = "QuestDesc_10020405",
            },
        ["QuestDesc_10020406"] = {
            ["ContentFR"] = "En échange de la remise de l’Éclat stellaire, Henrik accepte à contrecœur de vous ouvrir la porte.\
Entrez et poursuivez votre investigation.",
            ["TextMapId"] = "QuestDesc_10020406",
            },
        ["QuestDesc_10020407"] = {
            ["ContentFR"] = "Henrik s’est retiré pour vérifier l’authenticité de l’Éclat stellaire. C’est l’occasion d’explorer un peu les lieux.\
Psyche vous a salué — allez lui parler d’abord.",
            ["TextMapId"] = "QuestDesc_10020407",
            },
        ["QuestDesc_10020408"] = {
            ["ContentFR"] = "Vous avez reçu un présent de Psyche, selon elle, les fleurs portent chance.\
Vous apprenez également que tous les pensionnaires de la Maison d’Hypnos souffrent d’un mal étrange, et qu’Henrik semble mener d’étranges recherches en secret.\
Examinez les autres pièces de l’auberge.",
            ["TextMapId"] = "QuestDesc_10020408",
            },
        ["QuestDesc_10020409"] = {
            ["ContentFR"] = "Les pensionnaires de la Maison d’Hypnos semblent pour le moins singuliers.\
Interrogez-les pour recueillir des indices concernant Henrik.",
            ["TextMapId"] = "QuestDesc_10020409",
            },
        ["QuestDesc_10020410"] = {
            ["ContentFR"] = "Vous avez appris que le bureau d’Henrik, verrouillé à double tour, est un lieu interdit dans cet établissement. Vous savez désormais qu’il quitte toujours la Maison d’Hypnos à dix-sept heures précises, le vingtième jour de chaque mois.\
Enfin, il est confirmé que Hunt, le Chasseur de Phoxène disparu, a bien séjourné ici autrefois — Henrik devrait rentrer d’un instant à l’autre.",
            ["TextMapId"] = "QuestDesc_10020410",
            },
        ["QuestDesc_10020411"] = {
            ["ContentFR"] = "Bien que vous n’ayez pas pu pénétrer dans le bureau verrouillé, vous avez tout de même obtenu plusieurs informations utiles.\
Retournez faire votre rapport à l’Étranger.",
            ["TextMapId"] = "QuestDesc_10020411",
            },
        ["QuestDesc_10020412"] = {
            ["ContentFR"] = "Bien que vous n’ayez pas pu pénétrer dans le bureau verrouillé, vous avez tout de même obtenu plusieurs informations utiles.\
Retournez faire votre rapport à l’Étranger.",
            ["TextMapId"] = "QuestDesc_10020412",
            },
        ["QuestDesc_10020501"] = {
            ["ContentFR"] = "Il reste encore du temps avant le vingtième jour du mois. Rendez-vous au panneau d’affichage des Asphodèles et accomplissez une mission [Médiation] afin d’acquérir de l’expérience.",
            ["TextMapId"] = "QuestDesc_10020501",
            },
        ["QuestDesc_10020502"] = {
            ["ContentFR"] = "Alors que vous apprenez peu à peu à vous adapter à la vie de Givrelac et à devenir un véritable Chasseur de Phoxène, à la Capitale Impériale de Dismania, la Légion semble préparer quelque chose...",
            ["TextMapId"] = "QuestDesc_10020502",
            },
        ["QuestDesc_10020503"] = {
            ["ContentFR"] = "À l’extérieur de Givrelac, l’Étranger dispose des pièges sur une clairière en périphérie, attendant votre arrivée.\
Allez donc voir ce qu’il prépare.",
            ["TextMapId"] = "QuestDesc_10020503",
            },
        ["QuestDesc_10020504"] = {
            ["ContentFR"] = "Selon les indications de l’Étranger, éliminez les Souillés qui approchent pour achever votre entraînement au combat.",
            ["TextMapId"] = "QuestDesc_10020504",
            },
        ["QuestDesc_10020504_1"] = {
            ["ContentFR"] = "Vous avez éliminé tous les Souillés. Allez parler à l’Étranger.",
            ["TextMapId"] = "QuestDesc_10020504_1",
            },
        ["QuestDesc_10020505"] = {
            ["ContentFR"] = "On ignore ce que l’Étranger a manigancé, mais il a réussi à attirer une véritable horde de Souillés. Pas le temps de discuter — aidez-le à se débarrasser de ces créatures.",
            ["TextMapId"] = "QuestDesc_10020505",
            },
        ["QuestDesc_10020505_1"] = {
            ["ContentFR"] = "Vous aviez convenu d’un entraînement spécial de Chasseur de Phoxène avec l’Étranger à l’extérieur de Givrelac, mais, pour une raison inconnue, il a attiré un grand nombre de Souillés. Après l’avoir aidé à régler ce fâcheux incident, allez voir ce qu’il manigance encore.",
            ["TextMapId"] = "QuestDesc_10020505_1",
            },
        ["QuestDesc_10020506"] = {
            ["ContentFR"] = "Selon les instructions de l’Étranger, la nouvelle phase d’entraînement consiste à protéger cet étrange appareil hurlant.\
Votre tâche est simple : éliminez les Souillés et empêchez-les de l’endommager.",
            ["TextMapId"] = "QuestDesc_10020506",
            },
        ["QuestDesc_10020507"] = {
            ["ContentFR"] = "Henrik ne devrait plus tarder à sortir.\
Rejoignez Snow, postée près de la Maison d’Hypnos, chargée de surveiller discrètement ses allées et venues.",
            ["TextMapId"] = "QuestDesc_10020507",
            },
        ["QuestDesc_10020601"] = {
            ["ContentFR"] = "Henrik ne devrait plus tarder à sortir.\
Rejoignez Snow, postée près de la Maison d’Hypnos, chargée de surveiller discrètement ses allées et venues.",
            ["TextMapId"] = "QuestDesc_10020601",
            },
        ["QuestDesc_10020602"] = {
            ["ContentFR"] = "Henrik semble se diriger vers les abords de la cité.\
Suivez-le discrètement pour découvrir ce qu’il manigance.",
            ["TextMapId"] = "QuestDesc_10020602",
            },
        ["QuestDesc_10020603"] = {
            ["ContentFR"] = "Henrik s’arrête chez un fleuriste, achète un bouquet, puis reprend sa route. Suivez-le.",
            ["TextMapId"] = "QuestDesc_10020603",
            },
        ["QuestDesc_10020604"] = {
            ["ContentFR"] = "L’Étranger s’est faufilé par la cheminée pour pénétrer dans la pièce verrouillée.\
Examinez les lieux et découvrez ce qu’ils recèlent.",
            ["TextMapId"] = "QuestDesc_10020604",
            },
        ["QuestDesc_10020605"] = {
            ["ContentFR"] = "Vous et Snow avez découvert, au fond de l’eau, la boîte qu’Henrik avait dissimulée. Son contenu semble s’être dissous.\
Retournez voir ce que l’Étranger a pu apprendre de son côté.",
            ["TextMapId"] = "QuestDesc_10020605",
            },
        ["QuestDesc_10020606"] = {
            ["ContentFR"] = "L’Étranger a infiltré le bureau d’Henrik et y a trouvé un dossier intitulé « Projet Léthé ».\
Ce document répertorie plusieurs personnes portées disparues — dont le nom de Psyche figure sur la liste.\
Craignant pour sa sécurité, vous décidez d’intervenir et de vous rendre à la Maison d’Hypnos pour enquêter.",
            ["TextMapId"] = "QuestDesc_10020606",
            },
        ["QuestDesc_10020607"] = {
            ["ContentFR"] = "Vous entendez des sanglots étouffés provenant de la chambre de Psyche. Allez vérifier comment elle se porte.",
            ["TextMapId"] = "QuestDesc_10020607",
            },
        ["QuestDesc_10020608"] = {
            ["ContentFR"] = "Pour une raison inconnue, Psyche semble de mauvaise humeur, bien que Henrik affirme qu’elle n’a qu’un léger malaise.\
Certaines choses méritent d’être dites en privé — vous l’invitez donc à aller prendre l’air au bord du Lac du Deuil.\
Le lac se trouve tout près de Givrelac : accompagnez Psyche et marchez un moment avec elle pour lui changer les idées.",
            ["TextMapId"] = "QuestDesc_10020608",
            },
        ["QuestDesc_10020609"] = {
            ["ContentFR"] = "Vous remarquez que la vue de Psyche semble gravement altérée, mais elle refuse d’en parler.\
Elle vous demande de l’accompagner près des racines d’un vieil arbre au bord du Lac du Deuil, un lieu qui semble lié à ses souvenirs d’enfance.",
            ["TextMapId"] = "QuestDesc_10020609",
            },
        ["QuestDesc_10020610"] = {
            ["ContentFR"] = "Selon Psyche, un secret serait enfoui sous ces racines. Dégagez la terre et découvrez ce qu’elles dissimulent.",
            ["TextMapId"] = "QuestDesc_10020610",
            },
        ["QuestDesc_10020611"] = {
            ["ContentFR"] = "Psyche vous confie l’appareil photo qu’elle avait enterré durant son enfance.\
Ses yeux ne voient plus, mais elle espère que vous utiliserez cet objet pour contempler et immortaliser le monde à sa place.\
Elle semble encore avoir bien des choses à dire... Marchez avec elle le long de la rive du Lac du Deuil et écoutez ce qu’elle souhaite vous confier.",
            ["TextMapId"] = "QuestDesc_10020611",
            },
        ["QuestDesc_10020612"] = {
            ["ContentFR"] = "L’arrivée soudaine d’Henrik interrompt votre conversation avec Psyche.\
Avant de vous séparer, vous lui dites que vous l’attendrez près du guichet du théâtre à deux heures du matin, en espérant qu’elle viendra.\
Il est temps maintenant de retourner à Givrelac pour préparer votre plan de fuite.",
            ["TextMapId"] = "QuestDesc_10020612",
            },
        ["QuestDesc_10020613"] = {
            ["ContentFR"] = "Sur le chemin du retour vers Givrelac, vous croisez un soldat au comportement suspect. À votre approche, il se montre nerveux... puis vous attaque sans prévenir.",
            ["TextMapId"] = "QuestDesc_10020613",
            },
        ["QuestDesc_10020614"] = {
            ["ContentFR"] = "Après un échange de coups que l’on pourrait qualifier de \"cordial\", le soldat — prénommé Kevin — finit par retrouver son calme.\
Il semble vouloir vous parler. Approchez-vous et écoutez ce qu’il a à dire.",
            ["TextMapId"] = "QuestDesc_10020614",
            },
        ["QuestDesc_10020615"] = {
            ["ContentFR"] = "Kevin avoue avoir tenté d’enterrer en secret le corps d’un Dégradé — un ancien voisin. Il vous supplie de garder le silence.\
C’est lui qui vous explique ce qu’est la Dégradation, et vous révèle aussi certains faits sur le passé d’Henrik. Grâce à ces informations, vous en apprenez bien davantage.\
Retournez sans tarder à Givrelac pour tout rapporter à l’Étranger et à Snow.",
            ["TextMapId"] = "QuestDesc_10020615",
            },
        ["QuestDesc_10020701"] = {
            ["ContentFR"] = "La nuit est tombée.\
Comme convenu, vous devez retrouver Psyche à deux heures du matin, près du guichet du théâtre, au sud de la Maison d’Hypnos.\
L’Étranger semble fin prêt.\
Il n’y a pas de temps à perdre — rendez-vous sans tarder au lieu convenu.",
            ["TextMapId"] = "QuestDesc_10020701",
            },
        ["QuestDesc_10020702"] = {
            ["ContentFR"] = "Alors que vous attendez l’arrivée de Psyche, un cri strident retentit — c’est la voix de Snow, venue de la direction de la Maison d’Hypnos.\
Un mauvais pressentiment vous serre le cœur. Vous devez aller voir ce qui s’y passe.",
            ["TextMapId"] = "QuestDesc_10020702",
            },
        ["QuestDesc_10020703"] = {
            ["ContentFR"] = "D’après Snow, le corps de Psyche montre déjà des signes de Dégradation.\
Au même moment, un jeune garçon vivant à la Maison d’Hypnos vous supplie d’aider Henrik.\
Suivez le garçon à l’intérieur et découvrez ce qu’il s’y passe réellement.",
            ["TextMapId"] = "QuestDesc_10020703",
            },
        ["QuestDesc_10020704"] = {
            ["ContentFR"] = "Le bureau du rez-de-chaussée de la Maison d’Hypnos, d’ordinaire fermé à clé, est grand ouvert.\
Tout porte à croire que le bureau d’Henrik est l’épicentre de l’incident.",
            ["TextMapId"] = "QuestDesc_10020704",
            },
        ["QuestDesc_10020705"] = {
            ["ContentFR"] = "Henrik, grièvement blessé, vous confie la vérité dans un dernier souffle.\
Avant de mourir, il vous supplie de sauver Psyche, qui a perdu la raison — un vœu partagé par tous les habitants de la Maison d’Hypnos.\
Selon Snow, Psyche s’est enfuie vers le Lac du Deuil. Partez à sa recherche.",
            ["TextMapId"] = "QuestDesc_10020705",
            },
        ["QuestDesc_10020706"] = {
            ["ContentFR"] = "Sur le chemin qu’a emprunté Psyche, d’innombrables papillons apparaissent, semblant vous montrer la voie. Suivez-les pour retrouver sa trace.",
            ["TextMapId"] = "QuestDesc_10020706",
            },
        ["QuestDesc_10020707"] = {
            ["ContentFR"] = "Guidés par les papillons, vous arrivez près du Lac du Deuil. Une tempête y fait rage, comme si les vents eux-mêmes voulaient vous barrer la route.\
Heureusement, les rafales suivent un certain rythme — restez attentif et traversez prudemment la surface gelée.",
            ["TextMapId"] = "QuestDesc_10020707",
            },
        ["QuestDesc_10020708"] = {
            ["ContentFR"] = "L’état de Psyche s’aggrave peu à peu.\
Lorsque vous la retrouvez enfin, elle s’est changée en Souillé : « l’Éclose ».\
Vainquez l’Éclose et réveillez la véritable Psyche.",
            ["TextMapId"] = "QuestDesc_10020708",
            },
        ["QuestDesc_10020709"] = {
            ["ContentFR"] = "Psyche repose encore au cœur de la tempête.\
Dans le hurlement du vent, vous ressentez toute la cruauté du destin, mais vos mains refusent de renoncer. Au bout de la lutte, il ne vous reste qu’une seule offrande : une fleur pour la jeune fille endormie.",
            ["TextMapId"] = "QuestDesc_10020709",
            },
        ["QuestDesc_10020801"] = {
            ["ContentFR"] = "La tempête s’est soudainement dissipée. Psyche se retrouve dans un lieu étrangement familier...",
            ["TextMapId"] = "QuestDesc_10020801",
            },
        ["QuestDesc_10020802"] = {
            ["ContentFR"] = "Un long couloir tissé de souvenirs s’étend devant elle. Et au bout, une silhouette ancienne — à la fois connue et étrangère.",
            ["TextMapId"] = "QuestDesc_10020802",
            },
        ["QuestDesc_10020803"] = {
            ["ContentFR"] = "L’ombre dévore peu à peu l’esprit de Psyche, mais votre voix la ramène à la raison. Quand ses ailes renaissent, une détermination nouvelle s’ancre dans son cœur.",
            ["TextMapId"] = "QuestDesc_10020803",
            },
        ["QuestDesc_10020804"] = {
            ["ContentFR"] = "L’histoire de Psyche s’achève sur une seule balle tirée par un membre des Veilleurs. Rhythm, l’officière, vous prend pour des otages attaqués par un Souillé, et son regard trahit l’inquiétude.",
            ["TextMapId"] = "QuestDesc_10020804",
            },
        ["QuestDesc_10020805"] = {
            ["ContentFR"] = "Selon la tradition des Charons, vous confiez Psyche aux eaux, afin que son âme rejoigne la Mer du Silence.",
            ["TextMapId"] = "QuestDesc_10020805",
            },
        ["QuestDesc_10020806"] = {
            ["ContentFR"] = "Avec l’Étranger, vous trouvez un endroit isolé près du Lac du Deuil pour offrir vos adieux à Psyche. Vous savez qu’elle aurait aimé ce lieu — paisible, baigné de lumière, sans plainte ni fracas, où seule la brise inconnue murmure sa prière.",
            ["TextMapId"] = "QuestDesc_10020806",
            },
        ["QuestDesc_10020807"] = {
            ["ContentFR"] = "Cette nuit sera sans sommeil. Incapable de trouver le repos, vous vous rendez à la Grotte du Dégel.\
C’est là que vous aviez autrefois creusé la terre pour elle — l’un des rares refuges hors des murs, épargné par le vent et le blizzard.",
            ["TextMapId"] = "QuestDesc_10020807",
            },
        ["QuestDesc_10020808"] = {
            ["ContentFR"] = "Une femme inconnue se tient dans la <H>Grotte du Dégel</>.\
En croisant votre regard, elle semble vouloir vous adresser la parole.",
            ["TextMapId"] = "QuestDesc_10020808",
            },
        ["QuestDesc_10020809"] = {
            ["ContentFR"] = "Ici, dans la fine faille entre rêve et réalité, les passants du songe s’éveillent.\
Et dans cet instant suspendu, le tumulte du monde se change en écho de sable.",
            ["TextMapId"] = "QuestDesc_10020809",
            },
        ["QuestDesc_10029701"] = {
            ["ContentFR"] = "Augmentez votre Niveau d’Aventure pour poursuivre la quête principale.\
\
Vous pouvez gagner de l’EXP d’aventure :\
1) En accomplissant des <H>missions</> (hors celles du <H>Manuel des Vagabonds de la Nuit</>)\
2) En parlant avec les habitants et en terminant des <H>quêtes secondaires</>",
            ["TextMapId"] = "QuestDesc_10029701",
            },
        ["QuestDesc_10029801"] = {
            ["ContentFR"] = "Augmentez votre Niveau d’Aventure pour poursuivre la quête principale.\
\
Vous pouvez gagner de l’EXP d’aventure :\
1) En accomplissant des <H>missions</> (hors celles du <H>Manuel des Vagabonds de la Nuit</>)\
2) En parlant avec les habitants et en terminant des <H>quêtes secondaires</>",
            ["TextMapId"] = "QuestDesc_10029801",
            },
        ["QuestDesc_10029901"] = {
            ["ContentFR"] = "Augmentez votre Niveau d’Aventure pour poursuivre la quête principale.\
\
Vous pouvez gagner de l’EXP d’aventure :\
1) En terminant les tutoriels du <H>Lunotelier du Sceau démoniaque</> de Luno, la forgeronne.\
2) En accomplissant des <H>missions</> (hors celles du <H>Manuel des Vagabonds de la Nuit</>)\
3) En parlant avec les habitants et en terminant des <H>quêtes secondaires</>",
            ["TextMapId"] = "QuestDesc_10029901",
            },
        ["QuestDesc_10030101"] = {
            ["ContentFR"] = "Après plusieurs jours à dériver dans une nuit sans fin, votre conscience se remet enfin à flot...",
            ["TextMapId"] = "QuestDesc_10030101",
            },
        ["QuestDesc_10030102"] = {
            ["ContentFR"] = "Après cinq jours de coma, vous vous réveillez au Sanctuaire. La première silhouette qui se découpe devant vous est celle de Camilla. Parlez-lui donc : elle saura vous dire ce qui s’est passé durant votre absence.",
            ["TextMapId"] = "QuestDesc_10030102",
            },
        ["QuestDesc_10030103"] = {
            ["ContentFR"] = "Camilla vous apprend que, lors de l’attaque survenue cinq jours plus tôt, vous êtes {性别:le seul|la seule} à avoir survécu. Pour le reste, elle demeure évasive et vous conseille plutôt de rejoindre les Asphodèles : vos amis, qui se sont inquiétés pour vous, vous raconteront le reste.",
            ["TextMapId"] = "QuestDesc_10030103",
            },
        ["QuestDesc_10030104"] = {
            ["ContentFR"] = "À peine sorti du Sanctuaire, vous découvrez Givrelac couverte de décorations festives. Pourtant, les rues sont étrangement désertes, traversées seulement par quelques passants pressés, le regard fuyant. Ce contraste ne présage rien de bon. Pour comprendre ce qui est arrivé à la cité, mieux vaut vous rendre sans tarder aux Asphodèles et parler à vos compagnons.",
            ["TextMapId"] = "QuestDesc_10030104",
            },
        ["QuestDesc_10030105"] = {
            ["ContentFR"] = "Rhythm est, elle aussi, venue pour la Traque aux Charons. Après avoir pesé le pour et le contre, vous choisissez de la suivre et d’engager la conversation. C’est autant pour préserver votre place à Givrelac que pour saisir une occasion de soutirer à la Légion des informations sur Berenica.",
            ["TextMapId"] = "QuestDesc_10030105",
            },
        ["QuestDesc_10030106"] = {
            ["ContentFR"] = "Au terme de cet échange, vous décidez de mener l’enquête sur la Traque aux Charons aux côtés de Rhythm. La première étape est claire : retourner sur les lieux du crime et y chercher tout indice capable de vous mettre sur la piste de l’agresseur.",
            ["TextMapId"] = "QuestDesc_10030106",
            },
        ["QuestDesc_10030107"] = {
            ["ContentFR"] = "Les indices relevés sur la scène du crime laissent penser que l’agresseur est lié soit au théâtre, soit à l’usine. Vous vous répartissez les tâches : à la tête des Vagabonds de la Nuit, vous partez inspecter le Théâtre Galea, tandis que Rhythm se rend seule à l’usine.",
            ["TextMapId"] = "QuestDesc_10030107",
            },
        ["QuestDesc_10030108"] = {
            ["ContentFR"] = "Au loin, une vieille dame vous interpelle. Tout indique qu’il s’agit de la directrice du théâtre. Allez lui parler : peut-être détient-elle des informations utiles sur la Traque aux Charons.",
            ["TextMapId"] = "QuestDesc_10030108",
            },
        ["QuestDesc_10030109"] = {
            ["ContentFR"] = "Putsch, la directrice de la troupe, semble bien plus préoccupée par la représentation préparée pour la Fête de la Chandelle d’Argent que par la Traque aux Charons. Après quelques mots échangés, elle retourne déjà surveiller les répétitions. Au moins ne vous empêche-t-elle pas de poursuivre vos recherches dans le théâtre.\
Un peu plus loin, le Chef accessoiriste supervise l’ensemble des entrées et sorties de matériel. Allez lui parler : il aura peut-être des informations plus concrètes à vous offrir.",
            ["TextMapId"] = "QuestDesc_10030109",
            },
        ["QuestDesc_10030110"] = {
            ["ContentFR"] = "D’après les registres du Chef accessoiriste, la troupe entière s’est consacrée aux répétitions intensives tout au long du dernier mois. Rien de vraiment compromettant. Votre regard se tourne alors vers la scène : une chanteuse à l’élégance impeccable, aux côtés d’un jeune homme nerveux, le regard perdu. Son attitude trouble a de quoi éveiller les soupçons... Serait-il lié à la Traque aux Charons ?",
            ["TextMapId"] = "QuestDesc_10030110",
            },
        ["QuestDesc_10030111"] = {
            ["ContentFR"] = "Entre leurs horaires de répétition et l’absence de mobile évident, les membres de la troupe semblent n’avoir ni le temps, ni la raison de commettre un tel crime. Le théâtre ne recèle visiblement plus aucun indice utile. Il est temps de partir et de voir si Rhythm a découvert quelque chose du côté de l’usine.",
            ["TextMapId"] = "QuestDesc_10030111",
            },
        ["QuestDesc_10030112"] = {
            ["ContentFR"] = "Rhythm vous apprend qu’un vol de Phoxichor a récemment eu lieu à l’usine : les réserves ont été siphonnées puis remplacées par de l’huile de poisson. Cela pourrait expliquer l’odeur saturée de Phoxichor qui imprégnait l’agresseur. Vos soupçons se tournent alors vers l’Association des pêcheurs. Rendez-vous à Brumelac pour les retrouver.",
            ["TextMapId"] = "QuestDesc_10030112",
            },
        ["QuestDesc_10030113"] = {
            ["ContentFR"] = "Vous prenez l’huile de poisson des mains de Rhythm, et le chat, comme prévu, s’en montre immédiatement ravi : il se frotte contre vos jambes, remue la queue et miaule en vous invitant à le suivre. Puisqu’il insiste autant, mieux vaut voir où il souhaite vous mener.",
            ["TextMapId"] = "QuestDesc_10030113",
            },
        ["QuestDesc_10030114"] = {
            ["ContentFR"] = "Sur les traces du chat, vous tombez sur un pêcheur au regard fuyant. Avant même que vous ne lui adressiez la parole, il s’effondre à genoux en larmes, promettant de « tout avouer ». Voilà qui ne laisse guère de doute. Il est temps de l’interroger sérieusement.",
            ["TextMapId"] = "QuestDesc_10030114",
            },
        ["QuestDesc_10030201"] = {
            ["ContentFR"] = "Vous arrivez dans les égouts proches de l’usine. Quel chemin emprunter ? Mieux vaut demander son avis à Rhythm — elle saura sans doute quoi faire.",
            ["TextMapId"] = "QuestDesc_10030201",
            },
        ["QuestDesc_10030202"] = {
            ["ContentFR"] = "À peine entrés dans les égouts, l’Étranger perçoit d’étranges bruits plus loin. Avancez prudemment pour en découvrir l’origine.",
            ["TextMapId"] = "QuestDesc_10030202",
            },
        ["QuestDesc_10030203"] = {
            ["ContentFR"] = "Des appels à l’aide résonnent dans le tunnel. Avant même que vous ne puissiez réagir, Rhythm fonce vers la source du bruit. Rattrapez-la vite.",
            ["TextMapId"] = "QuestDesc_10030203",
            },
        ["QuestDesc_10030204"] = {
            ["ContentFR"] = "Vous libérez le premier citoyen piégé et ouvrez la porte verrouillée. Continuez d’avancer : une seconde personne attend encore d’être secourue.",
            ["TextMapId"] = "QuestDesc_10030204",
            },
        ["QuestDesc_10030205"] = {
            ["ContentFR"] = "D’après le citoyen, son compagnon est coincé juste devant. Dépêchez-vous.",
            ["TextMapId"] = "QuestDesc_10030205",
            },
        ["QuestDesc_10030206"] = {
            ["ContentFR"] = "La voix du second citoyen se fait entendre non loin. Allez voir dans quel état il se trouve.",
            ["TextMapId"] = "QuestDesc_10030206",
            },
        ["QuestDesc_10030207"] = {
            ["ContentFR"] = "Les deux civils sont enfin en sécurité. Parlez à Rhythm et voyez comment elle se remet de cette intervention.",
            ["TextMapId"] = "QuestDesc_10030207",
            },
        ["QuestDesc_10030208"] = {
            ["ContentFR"] = "Une fois les eaux usées évacuées, les grognements de l’agresseur deviennent plus distincts. Restez sur vos gardes et avancez.",
            ["TextMapId"] = "QuestDesc_10030208",
            },
        ["QuestDesc_10030210"] = {
            ["ContentFR"] = "Personne n’aurait imaginé que la Traque aux Charons impliquait deux agresseurs. Rhythm a été grièvement blessée en vous protégeant du second.\
À présent que les renforts de la Légion prennent le relais, les Vagabonds de la Nuit se concertent et décident d’aller rendre visite à Rhythm à l’hôpital — pour la récompense peut-être, mais surtout pour lui témoigner votre gratitude.",
            ["TextMapId"] = "QuestDesc_10030210",
            },
        ["QuestDesc_10030211"] = {
            ["ContentFR"] = "Personne n’aurait imaginé que la Traque aux Charons impliquait deux agresseurs. Rhythm a été grièvement blessée en vous protégeant du second.\
À présent que les renforts de la Légion prennent le relais, les Vagabonds de la Nuit se concertent et décident d’aller rendre visite à Rhythm à l’hôpital — pour la récompense peut-être, mais surtout pour lui témoigner votre gratitude.",
            ["TextMapId"] = "QuestDesc_10030211",
            },
        ["QuestDesc_10030212"] = {
            ["ContentFR"] = "La Légion affirmait qu’un détachement viendrait vous escorter... mais en arrivant, vous ne trouvez personne. À la place, les murs sont criblés d’impacts. Manifestement, les soldats ont croisé la route de l’agresseur. Puisque vous quittez les égouts, suivez la piste laissée derrière lui.",
            ["TextMapId"] = "QuestDesc_10030212",
            },
        ["QuestDesc_10030213"] = {
            ["ContentFR"] = "Vous découvrez un conduit que l’agresseur a probablement utilisé pour s’enfuir. Il mène jusqu’à la sortie extérieure des égouts. Avancez avec prudence.",
            ["TextMapId"] = "QuestDesc_10030213",
            },
        ["QuestDesc_10030214"] = {
            ["ContentFR"] = "Plus vous approchez de la sortie, plus le silence devient anormal. Quelque chose s’est passé ici. Restez vigilants.",
            ["TextMapId"] = "QuestDesc_10030214",
            },
        ["QuestDesc_10030215"] = {
            ["ContentFR"] = "La sortie des égouts est un véritable carnage. Les traces de poison — qui n’ont rien à faire sur des soldats impériaux — jettent une nouvelle ombre sur la Traque aux Charons. Après discussion, l’Étranger reste pour informer la Légion, tandis que Snow et vous maintenez votre plan initial : aller voir comment se porte Rhythm à l’hôpital.",
            ["TextMapId"] = "QuestDesc_10030215",
            },
        ["QuestDesc_10030216"] = {
            ["ContentFR"] = "Quelques jours plus tard, Rhythm sort enfin du coma. Vous lui racontez la suite des événements dans les égouts. Pour vous remercier, elle vous demande de récupérer dans sa base secrète un sceau en argent portant son nom. Depuis son lit d’hôpital, elle souhaite écrire des lettres personnelles à des amis de confiance afin de recueillir des nouvelles de Berenica pour vous.",
            ["TextMapId"] = "QuestDesc_10030216",
            },
        ["QuestDesc_10030217"] = {
            ["ContentFR"] = "Quelques jours plus tard, Rhythm sort enfin du coma. Vous lui racontez la suite des événements dans les égouts. Pour vous remercier, elle vous demande de récupérer dans sa base secrète un sceau en argent portant son nom. Depuis son lit d’hôpital, elle souhaite écrire des lettres personnelles à des amis de confiance afin de recueillir des nouvelles de Berenica pour vous.",
            ["TextMapId"] = "QuestDesc_10030217",
            },
        ["QuestDesc_10030218"] = {
            ["ContentFR"] = "Vous atteignez la base secrète de Rhythm. Fouillez les lieux et retrouvez le sceau en argent gravé à son nom.",
            ["TextMapId"] = "QuestDesc_10030218",
            },
        ["QuestDesc_10030219"] = {
            ["ContentFR"] = "Vous atteignez la base secrète de Rhythm. Fouillez les lieux et retrouvez le sceau en argent gravé à son nom.",
            ["TextMapId"] = "QuestDesc_10030219",
            },
        ["QuestDesc_100302sp101"] = {
            ["ContentFR"] = "Un citoyen et son compagnon sont coincés dans les égouts, pris au piège par un monstre — probablement l’agresseur de la Traque aux Charons. Preuve que vous êtes sur la bonne piste.\
La créature s’est enfuie on ne sait où ; commencez par déverrouiller la porte et mettez ces deux civils en sécurité.",
            ["TextMapId"] = "QuestDesc_100302sp101",
            },
        ["QuestDesc_100302sp102"] = {
            ["ContentFR"] = "Pour réactiver la console de commande, vous devez d’abord dégager les canalisations de cette zone. Mais dès que le système de drainage s’enclenche, une nuée de Souillés jaillit des tuyaux. Repoussez-les et protégez le citoyen !",
            ["TextMapId"] = "QuestDesc_100302sp102",
            },
        ["QuestDesc_100302sp103"] = {
            ["ContentFR"] = "Toutes les canalisations obstruées sont maintenant dégagées. Essayez de déverrouiller la porte à nouveau.",
            ["TextMapId"] = "QuestDesc_100302sp103",
            },
        ["QuestDesc_100302sp104"] = {
            ["ContentFR"] = "Pour réactiver la console de commande, vous devez d’abord dégager les canalisations de cette zone. Mais dès que le système de drainage s’enclenche, une nuée de Souillés jaillit des tuyaux. Repoussez-les et protégez le citoyen !",
            ["TextMapId"] = "QuestDesc_100302sp104",
            },
        ["QuestDesc_100302sp201"] = {
            ["ContentFR"] = "Le second citoyen est pris au piège derrière les dispositifs défensifs des égouts.\
Désactivez-les depuis la console de commande et libérez-le sain et sauf.",
            ["TextMapId"] = "QuestDesc_100302sp201",
            },
        ["QuestDesc_100302sp202"] = {
            ["ContentFR"] = "Comme auparavant, la console est verrouillée à cause de conduites obstruées.\
Ouvrez les vannes, évacuez les blocages et rétablissez son fonctionnement.",
            ["TextMapId"] = "QuestDesc_100302sp202",
            },
        ["QuestDesc_100302sp203"] = {
            ["ContentFR"] = "Le second citoyen est pris au piège derrière les dispositifs défensifs des égouts.\
Désactivez-les depuis la console de commande et libérez-le sain et sauf.",
            ["TextMapId"] = "QuestDesc_100302sp203",
            },
        ["QuestDesc_100302sp301"] = {
            ["ContentFR"] = "L’agresseur de la Traque aux Charons surgit dans un rugissement sauvage. Affrontez-le — mettez un terme définitif à cette affaire.",
            ["TextMapId"] = "QuestDesc_100302sp301",
            },
        ["QuestDesc_10030301"] = {
            ["ContentFR"] = "Dans la base secrète, vous trouvez non seulement son sceau, mais aussi de petits objets liés au passé de Rhythm. En les observant un par un, vous commencez à mieux la comprendre — peut-être n’avez-vous jamais été aussi opposés que vous le pensiez. Ramenez-lui le sceau et écoutez ce qu’elle souhaite vous dire.",
            ["TextMapId"] = "QuestDesc_10030301",
            },
        ["QuestDesc_10030302"] = {
            ["ContentFR"] = "Pour éviter tout incident inutile, il est préférable — pour l’instant — de coopérer avec les opérations de la XIIIᵉ Légion à Givrelac.",
            ["TextMapId"] = "QuestDesc_10030302",
            },
        ["QuestDesc_10030303"] = {
            ["ContentFR"] = "La Traque aux Charons entre dans une nouvelle phase. Sur ordre de Clive, vous vous rendez dans les égouts sous la Place de la Paix d’Argent. Une fois sur place, tentez de rétablir le contact avec lui.",
            ["TextMapId"] = "QuestDesc_10030303",
            },
        ["QuestDesc_10030304"] = {
            ["ContentFR"] = "Après que vous avez confié à Rhythm des pistes concernant Berenica, l’Officier Lynn de la XIIIᵉ Légion surgit dans la chambre. Elle annonce sans détour que son unité reprend l’enquête sur la Traque aux Charons.\
Heureusement, elle ignore votre passé avec Sibylle — et vous propose même de collaborer. Ce n’est pas le moment d’attirer l’attention de la XIIIᵉ Légion : discutez avec elle et préservez l’illusion d’une collaboration sans accroc.",
            ["TextMapId"] = "QuestDesc_10030304",
            },
        ["QuestDesc_100303sp101"] = {
            ["ContentFR"] = "Vous acceptez d’aider dans l’enquête de la Traque aux Charons. Lynn ne perd pas de temps et vous confie votre première mission : rendez-vous avec Clive de la XIIIᵉ Légion, hors de Givrelac, pour réceptionner divers approvisionnements destinés à son unité.",
            ["TextMapId"] = "QuestDesc_100303sp101",
            },
        ["QuestDesc_100303sp102"] = {
            ["ContentFR"] = "Quelques jours plus tard, vous terminez enfin toutes les tâches assignées par la XIIIᵉ Légion. Mais aujourd’hui, aucun signe de Rhythm au point de rassemblement.\
Quelque chose lui serait-il arrivé ? Examinez les environs.",
            ["TextMapId"] = "QuestDesc_100303sp102",
            },
        ["QuestDesc_100303sp103"] = {
            ["ContentFR"] = "Pour aider les citoyens dont la vie a été perturbée par la XIIIᵉ Légion, Rhythm s’est portée volontaire pour constituer des vivres essentiels. En tant que compagnon, vous décidez de lui prêter main-forte.",
            ["TextMapId"] = "QuestDesc_100303sp103",
            },
        }
  end },
  { MinKey = "QuestDesc_100303sp104", MaxKey = "QuestName_10030112", Loader = function()
      return {
        ["QuestDesc_100303sp104"] = {
            ["ContentFR"] = "Une fois la pêche terminée, vous avez réuni tout ce dont les habitants ont besoin. Apportez-leur les provisions.",
            ["TextMapId"] = "QuestDesc_100303sp104",
            },
        ["QuestDesc_100303sp105"] = {
            ["ContentFR"] = "À peine avez-vous remis les fournitures à Margie qu’un nouvel ordre de Clive tombe.\
La XIIIᵉ Légion prépare visiblement une opération. Rendez-vous immédiatement auprès de lui.",
            ["TextMapId"] = "QuestDesc_100303sp105",
            },
        ["QuestDesc_100303sp201"] = {
            ["ContentFR"] = "Des soldats de la XIIIᵉ Légion sont déployés dans chaque section des égouts.\
L’atmosphère est lourde et étouffante dans ces tunnels exigus. Rejoignez la zone que Clive a assignée aux Vagabonds de la Nuit.",
            ["TextMapId"] = "QuestDesc_100303sp201",
            },
        ["QuestDesc_100303sp202"] = {
            ["ContentFR"] = "Des soldats de la XIIIᵉ Légion sont déployés dans chaque section des égouts.\
L’atmosphère est lourde et étouffante dans ces tunnels exigus. Rejoignez la zone que Clive a assignée aux Vagabonds de la Nuit.",
            ["TextMapId"] = "QuestDesc_100303sp202",
            },
        ["QuestDesc_100303sp203"] = {
            ["ContentFR"] = "La zone que Clive vous a assignée est temporairement inaccessible — encore une console bloquée par les eaux usées. Purgeons-les, levons le verrouillage, puis avançons vers la zone déterminée.",
            ["TextMapId"] = "QuestDesc_100303sp203",
            },
        ["QuestDesc_100303sp204"] = {
            ["ContentFR"] = "Après quelques contretemps, vous pouvez enfin accéder à la zone confiée par Clive. Dépêchez-vous.",
            ["TextMapId"] = "QuestDesc_100303sp204",
            },
        ["QuestDesc_100303sp205"] = {
            ["ContentFR"] = "Après avoir inspecté les alentours, vous tentez de faire un rapport à Clive — mais le communicateur de Rhythm tombe en panne, rendant ses paroles inaudibles.\
Essayez de le réparer.",
            ["TextMapId"] = "QuestDesc_100303sp205",
            },
        ["QuestDesc_100303sp206"] = {
            ["ContentFR"] = "Dès que le communicateur revient en ligne, vous apprenez que l’agresseur a franchi le blocus de la XIIIᵉ Légion et fonce vers votre secteur. Heureusement, Lynn arrive juste à temps avec du renfort. À présent — éliminez-le.",
            ["TextMapId"] = "QuestDesc_100303sp206",
            },
        ["QuestDesc_10030401"] = {
            ["ContentFR"] = "Bien que la XIIIᵉ Légion ait proclamé la Traque aux Charons \"résolue\" et soit repartie vers la capitale couverte d’honneurs, vous le savez — tout comme Rhythm : cette affaire est loin d’être terminée.",
            ["TextMapId"] = "QuestDesc_10030401",
            },
        ["QuestDesc_10030402"] = {
            ["ContentFR"] = "En recoupant les indices, vous en venez à soupçonner un lien entre le meurtrier et l’opéra. La mélodie qu’il fredonnait pourrait être tirée d’un véritable air lyrique — l’identifier permettrait peut-être de réduire le champ de recherche.\
Le petit frère de Rhythm, Blues, était passionné d’opéra : il a laissé de nombreuses cassettes dans leur base secrète. Peut-être y retrouverez-vous la même mélodie.",
            ["TextMapId"] = "QuestDesc_10030402",
            },
        ["QuestDesc_10030403"] = {
            ["ContentFR"] = "Il est temps de mettre votre mémoire et votre oreille à l’épreuve... Écouter toutes les cassettes laissées par Blues, une par une.",
            ["TextMapId"] = "QuestDesc_10030403",
            },
        ["QuestDesc_10030404"] = {
            ["ContentFR"] = "Le temps file sans que vous vous en rendiez compte tandis que vous écoutez les enregistrements. Rhythm est sortie prendre l’air. La recherche est longue et éreintante — faites une pause, et allez voir comment elle se porte.",
            ["TextMapId"] = "QuestDesc_10030404",
            },
        ["QuestDesc_10030501"] = {
            ["ContentFR"] = "La prétendue gloire des Charons Couronnés n’était qu’un mensonge. Dans la cité intérieure, ne vous attendaient que les tables glaciales de l’Académie d’Alchimie. Désormais réduit à l’état de monstre, il ne vous reste qu’une chose à faire : obéir.",
            ["TextMapId"] = "QuestDesc_10030501",
            },
        ["QuestDesc_10030502"] = {
            ["ContentFR"] = "En tant que monstre, votre volonté n’a plus d’importance. Accomplissez l’ordre : éliminez la cible.",
            ["TextMapId"] = "QuestDesc_10030502",
            },
        ["QuestDesc_10030503"] = {
            ["ContentFR"] = "Vous n’êtes plus humain. Plus de pensée. Plus de choix. Rejoignez le terrain d’essai — et éliminez la cible.",
            ["TextMapId"] = "QuestDesc_10030503",
            },
        ["QuestDesc_10030504"] = {
            ["ContentFR"] = "Vous n’êtes plus humain. Plus de pensée. Plus de choix. Rejoignez le terrain d’essai — et éliminez la cible.",
            ["TextMapId"] = "QuestDesc_10030504",
            },
        ["QuestDesc_10030505"] = {
            ["ContentFR"] = "Vous n’êtes plus humain. Plus de pensée. Plus de choix. Rejoignez le terrain d’essai — et éliminez la cible.",
            ["TextMapId"] = "QuestDesc_10030505",
            },
        ["QuestDesc_10030506"] = {
            ["ContentFR"] = "Ce naïf... il a vraiment réussi. Vous ne pouvez plus revenir en arrière. Fuyez — en tant qu’humain.",
            ["TextMapId"] = "QuestDesc_10030506",
            },
        ["QuestDesc_10030507"] = {
            ["ContentFR"] = "Ce naïf... il a vraiment réussi. Vous ne pouvez plus revenir en arrière. Fuyez — en tant qu’humain.",
            ["TextMapId"] = "QuestDesc_10030507",
            },
        ["QuestDesc_10030508"] = {
            ["ContentFR"] = "Ce naïf... il a vraiment réussi. Vous ne pouvez plus revenir en arrière. Fuyez — en tant qu’humain.",
            ["TextMapId"] = "QuestDesc_10030508",
            },
        ["QuestDesc_10030601"] = {
            ["ContentFR"] = "Le titre de Charon Couronné n’était qu’une supercherie. Vous ne pouvez laisser Rhythm poursuivre un rêve fondé sur un mensonge. Racontez-lui ce qu’il s’est réellement passé à l’Académie d’Alchimie... puis accomplissez ce qui doit l’être.",
            ["TextMapId"] = "QuestDesc_10030601",
            },
        ["QuestDesc_10030602"] = {
            ["ContentFR"] = "Au Théâtre Galea, la Fête de la Chandelle d’Argent bat son plein.\
Masques et costumes extravagants forment un camouflage parfait pour un monstre comme vous. Faufilez-vous parmi la foule et retrouvez votre contact.",
            ["TextMapId"] = "QuestDesc_10030602",
            },
        ["QuestDesc_10030603"] = {
            ["ContentFR"] = "La XIIIᵉ Légion est partie depuis plusieurs jours. Rhythm semble peu à peu se relever — du moins en partie — de la perte de Blues. Elle paraît avoir encore quelque chose à vous dire. Allez l’écouter.",
            ["TextMapId"] = "QuestDesc_10030603",
            },
        ["QuestDesc_10030604"] = {
            ["ContentFR"] = "La Traque aux Charons est close. Les Déchus ont été repoussés hors de la région de Cocytus. Mais ce n’est pas une conclusion — seulement un répit avant la tempête.",
            ["TextMapId"] = "QuestDesc_10030604",
            },
        ["QuestDesc_1003plus01"] = {
            ["ContentFR"] = "La journée, lourde de douleur et de séparations, touche enfin à sa fin. Cette nuit sera sans sommeil — une promenade solitaire dans Givrelac vous aidera peut-être à apaiser votre esprit.",
            ["TextMapId"] = "QuestDesc_1003plus01",
            },
        ["QuestDesc_1003plus02"] = {
            ["ContentFR"] = "Vous apprenez de l’Étranger et de Snow que vous avez été mêlé à la Traque aux Charons il y a cinq jours. Mais avant d’obtenir des réponses, Rhythm surgit et interrompt la conversation. Vous ne pouvez plus l’éviter — autant entendre ce qu’elle a à dire.",
            ["TextMapId"] = "QuestDesc_1003plus02",
            },
        ["QuestDesc_1003plus03"] = {
            ["ContentFR"] = "Vous avez découvert plusieurs indices liés, de près ou de loin, à la Traque aux Charons. Lorsque la piste refroidit, tenter des recoupements peut révéler de nouvelles voies à explorer.",
            ["TextMapId"] = "QuestDesc_1003plus03",
            },
        ["QuestDesc_1003plus04"] = {
            ["ContentFR"] = "Au terme de cet échange, vous décidez de mener l’enquête sur la Traque aux Charons aux côtés de Rhythm. La première étape est claire : retourner sur les lieux du crime et y chercher tout indice capable de vous mettre sur la piste de l’agresseur.",
            ["TextMapId"] = "QuestDesc_1003plus04",
            },
        ["QuestDesc_1003plus05"] = {
            ["ContentFR"] = "Une rangée d’affiches immenses vous accueille dès votre arrivée au Théâtre Galea.\
En les examinant de plus près, vous pourriez y déceler des indices sur les activités récentes de la troupe. Allez jeter un œil.",
            ["TextMapId"] = "QuestDesc_1003plus05",
            },
        ["QuestDesc_1003plus06"] = {
            ["ContentFR"] = "Le Chef accessoiriste affirme que la tenture trouvée sur les lieux du crime ne provient pas du Théâtre Galea. Le registre détaillé semble soutenir sa version.\
Autant le vérifier vous-même.",
            ["TextMapId"] = "QuestDesc_1003plus06",
            },
        ["QuestDesc_1003plus07"] = {
            ["ContentFR"] = "Un comédien épuisé vous explique que toute la troupe se consacre jour et nuit aux répétitions de la Fête de la Chandelle d’Argent.\
Le registre de présence, posé à côté, consigne précisément les allées et venues de chacun.",
            ["TextMapId"] = "QuestDesc_1003plus07",
            },
        ["QuestDesc_1003plus08"] = {
            ["ContentFR"] = "En refermant le registre, un bruit venant de la passerelle attire votre attention.\
Allez voir ce qui se passe.",
            ["TextMapId"] = "QuestDesc_1003plus08",
            },
        ["QuestDesc_1003plus09"] = {
            ["ContentFR"] = "Vous arrivez dans le quartier où vivent les pêcheurs. Il est temps de frapper à chaque porte et de procéder à une vérification maison par maison.",
            ["TextMapId"] = "QuestDesc_1003plus09",
            },
        ["QuestDesc_1003plus10"] = {
            ["ContentFR"] = "Vous frappez aux portes des pêcheurs, mais personne ne répond. C’est alors qu’un chat surgit derrière vous, miaulant comme s’il avait flairé quelque chose sur vous. Allez voir de quoi il s’agit.",
            ["TextMapId"] = "QuestDesc_1003plus10",
            },
        ["QuestDesc_1003plus11"] = {
            ["ContentFR"] = "Vous mettez la main sur le pêcheur qui avait volé la Phoxichor. Hélas, ce n’est pas l’agresseur — mais heureusement, il vous révèle que le coupable se cache sans doute dans les égouts. Remettez-le au Bureau de la Sécurité, puis discutez avec Rhythm de la suite des opérations.",
            ["TextMapId"] = "QuestDesc_1003plus11",
            },
        ["QuestDesc_1003plus12"] = {
            ["ContentFR"] = "Après avoir escorté le pêcheur, vous accompagnez Rhythm dans les égouts pour localiser précisément la cache de l’agresseur.\
Ce n’est qu’en confirmant sa position qu’elle pourra obtenir le soutien de la VIᵉ Légion — et que vous pourrez mettre un terme à la Traque aux Charons.",
            ["TextMapId"] = "QuestDesc_1003plus12",
            },
        ["QuestDesc_1003plus13"] = {
            ["ContentFR"] = "À peine les civils sont-ils en sécurité qu’un hurlement monstrueux retentit au fond du réseau d’égouts — la créature dont ils vous avaient parlé.\
Purgeons les eaux usées qui bloquent le passage et reprenons la poursuite.",
            ["TextMapId"] = "QuestDesc_1003plus13",
            },
        ["QuestDesc_1003plus14"] = {
            ["ContentFR"] = "Quelques jours plus tard, Rhythm se réveille enfin. Allez lui raconter ce qui s’est passé pendant son coma.",
            ["TextMapId"] = "QuestDesc_1003plus14",
            },
        ["QuestDesc_1003plus15"] = {
            ["ContentFR"] = "Vous atteignez la base secrète de Rhythm. Fouillez les lieux et retrouvez le sceau en argent gravé à son nom.",
            ["TextMapId"] = "QuestDesc_1003plus15",
            },
        ["QuestDesc_1003plus16"] = {
            ["ContentFR"] = "Vous atteignez la base secrète de Rhythm. Fouillez les lieux et retrouvez le sceau en argent gravé à son nom.",
            ["TextMapId"] = "QuestDesc_1003plus16",
            },
        ["QuestDesc_1003plus17"] = {
            ["ContentFR"] = "Des soldats de la XIIIᵉ Légion sont déployés dans chaque section des égouts.\
L’atmosphère est lourde et étouffante dans ces tunnels exigus. Rejoignez la zone que Clive a assignée aux Vagabonds de la Nuit.",
            ["TextMapId"] = "QuestDesc_1003plus17",
            },
        ["QuestDesc_1003plus18"] = {
            ["ContentFR"] = "Vous atteignez la section confiée à votre groupe. Examinez les environs et évaluez la situation.",
            ["TextMapId"] = "QuestDesc_1003plus18",
            },
        ["QuestDesc_1003plus19"] = {
            ["ContentFR"] = "Vous vous souvenez avoir découvert plusieurs nouveaux indices concernant l’agresseur. Reprenez-les méthodiquement : l’un d’eux pourrait éclairer son identité et vous indiquer la suite de l’enquête.",
            ["TextMapId"] = "QuestDesc_1003plus19",
            },
        ["QuestDesc_1003plus20"] = {
            ["ContentFR"] = "Rhythm fredonne une mélodie — étrangement proche de celle entonnée par l’agresseur la nuit de l’attaque. Elle provient de l’opéra <I>Né du blizzard</>. Vous élaboriez à peine un plan pour attirer le coupable grâce à ce nouvel indice... quand celui-ci se présente de lui-même.",
            ["TextMapId"] = "QuestDesc_1003plus20",
            },
        ["QuestDesc_1003plus20_1"] = {
            ["ContentFR"] = "Rhythm fredonne une mélodie — étrangement proche de celle entonnée par l’agresseur la nuit de l’attaque. Elle provient de l’opéra <I>Né du blizzard</>. Vous élaboriez à peine un plan pour attirer le coupable grâce à ce nouvel indice... quand celui-ci se présente de lui-même.",
            ["TextMapId"] = "QuestDesc_1003plus20_1",
            },
        ["QuestDesc_1003plus21"] = {
            ["ContentFR"] = "Au Théâtre Galea, la Fête de la Chandelle d’Argent bat son plein.\
Masques et costumes extravagants forment un camouflage parfait pour un monstre comme vous. Faufilez-vous parmi la foule et retrouvez votre contact.",
            ["TextMapId"] = "QuestDesc_1003plus21",
            },
        ["QuestDesc_1003plus22"] = {
            ["ContentFR"] = "Votre contact des Déchus doit déjà être arrivé. Rejoignez-le.",
            ["TextMapId"] = "QuestDesc_1003plus22",
            },
        ["QuestDesc_1003plus23"] = {
            ["ContentFR"] = "Les Déchus constituent, eux aussi, une menace pour la ville. Éliminez-les.",
            ["TextMapId"] = "QuestDesc_1003plus23",
            },
        ["QuestDesc_1003plus24"] = {
            ["ContentFR"] = "À peine le combat s’achève-t-il que des soldats de la XIIIᵉ Légion déboulent. S’ils veulent se battre... alors aucun d’eux ne quittera cet endroit vivant.",
            ["TextMapId"] = "QuestDesc_1003plus24",
            },
        ["QuestDesc_1003plus25"] = {
            ["ContentFR"] = "Vous ignorez comment Rhythm et les Chasseurs de Phoxène ont retrouvé votre trace, mais ce n’est pas le moment de s’y attarder.\
La Légion est toujours là — et le combat n’est pas terminé.",
            ["TextMapId"] = "QuestDesc_1003plus25",
            },
        ["QuestDesc_1003plus26"] = {
            ["ContentFR"] = "Vous avez offert une performance parfaite en tant que Blues. Rhythm n’apprendra jamais qu’elle a tué son propre frère. La XIIIᵉ Légion comme les Déchus n’auront aucune raison de soupçonner Rhythm ou les Chasseurs de Phoxène pour les événements d’aujourd’hui.\
Désormais, il est temps de monter sur scène une dernière fois — cette fois en tant que Parsifal.",
            ["TextMapId"] = "QuestDesc_1003plus26",
            },
        ["QuestDesc_1003plus27"] = {
            ["ContentFR"] = "Que le rideau se lève — et avec lui, que tout prenne fin.",
            ["TextMapId"] = "QuestDesc_1003plus27",
            },
        ["QuestDesc_1003plus28"] = {
            ["ContentFR"] = "Le vacarme causé par la purge des eaux usées attire une nuée de Souillés. Repoussez-les.",
            ["TextMapId"] = "QuestDesc_1003plus28",
            },
        ["QuestDesc_1003plus29"] = {
            ["ContentFR"] = "Le vacarme causé par la purge des eaux usées attire une nuée de Souillés. Repoussez-les.",
            ["TextMapId"] = "QuestDesc_1003plus29",
            },
        ["QuestDesc_1003plus30"] = {
            ["ContentFR"] = "La zone que Clive vous a assignée est temporairement inaccessible — encore une console bloquée par les eaux usées. Purgeons-les, levons le verrouillage, puis avançons vers la zone déterminée.",
            ["TextMapId"] = "QuestDesc_1003plus30",
            },
        ["QuestDesc_1003plus31"] = {
            ["ContentFR"] = "Rhythm souhaite clarifier certains points concernant le Phoxichor trouvé dans la neige. Échangez vos informations — vous pourriez en tirer une piste nouvelle.",
            ["TextMapId"] = "QuestDesc_1003plus31",
            },
        ["QuestDesc_1003plus32"] = {
            ["ContentFR"] = "Après un premier examen, il apparaît que le couloir d’entrée ne recèle aucun indice digne d’intérêt. Avancez plus loin dans le Théâtre Galea et échangez avec les membres de son personnel.",
            ["TextMapId"] = "QuestDesc_1003plus32",
            },
        ["QuestDesc_1003plus33"] = {
            ["ContentFR"] = "{性别:Guidé|Guidée} par les appels désespérés, vous découvrez le second citoyen pris au piège. Cherchez comment le tirer de cette situation.",
            ["TextMapId"] = "QuestDesc_1003plus33",
            },
        ["QuestDesc_1003plus34"] = {
            ["ContentFR"] = "Après une courte discussion, vous convenez de collaborer temporairement avec la XIIIᵉ Légion. Allez écouter les instructions de l’Officier Lynn.",
            ["TextMapId"] = "QuestDesc_1003plus34",
            },
        ["QuestDesc_1003plus35"] = {
            ["ContentFR"] = "Lorsque vous retrouvez Clive, il est déjà en train de repousser les loups des neiges qui rôdent autour du point de livraison. Aidez-le à sécuriser les lieux en attendant l’arrivée de l’équipe de transport.",
            ["TextMapId"] = "QuestDesc_1003plus35",
            },
