        ["RLBlessingGroup_Desc_1"] = {
            ["ContentFR"] = "Renforcements des armes de mêlée",
            ["TextMapId"] = "RLBlessingGroup_Desc_1",
            },
        ["RLBlessingGroup_Desc_101"] = {
            ["ContentFR"] = "Chaque [Lucimèche] de cet ensemble confère +<Highlight>15 %</> de Taux CRIT et +<Highlight>15 %</> de DGT CRIT pour les armes de mêlée.\
Les attaques de mêlée ont <Highlight>10 %</> de chance d’appliquer 1 cumul de [Flammes ardentes].",
            ["TextMapId"] = "RLBlessingGroup_Desc_101",
            },
        ["RLBlessingGroup_Desc_102"] = {
            ["ContentFR"] = "[Flammes ardentes] inflige des Dégâts sur la durée équivalents à <Highlight>35 %</> de l’ATQ du personnage chaque <Highlight>1</> s.",
            ["TextMapId"] = "RLBlessingGroup_Desc_102",
            },
        ["RLBlessingGroup_Desc_103"] = {
            ["ContentFR"] = "Prolonge la durée de [Flammes ardentes] à <Highlight>10</> s et augmente le cumul maximum à <Highlight>20</>.",
            ["TextMapId"] = "RLBlessingGroup_Desc_103",
            },
        ["RLBlessingGroup_Desc_104"] = {
            ["ContentFR"] = "Les cibles affectées par [Flammes ardentes] subissent un effet de [Lame ardente] toutes les <Highlight>5</> s. Les armes de mêlée ont <Highlight>10 %</> de chance de déclencher une [Lame ardente] supplémentaire.",
            ["TextMapId"] = "RLBlessingGroup_Desc_104",
            },
        ["RLBlessingGroup_Desc_2"] = {
            ["ContentFR"] = "Renforcements des armes à distance",
            ["TextMapId"] = "RLBlessingGroup_Desc_2",
            },
        ["RLBlessingGroup_Desc_201"] = {
            ["ContentFR"] = "Chaque [Lucimèche] de cet ensemble confère +<Highlight>15 %</> de Taux CRIT et +<Highlight>15 %</> de DGT CRIT pour les armes à distance.\
Augmente la Portée ramassage auto et confère l’immunité à l’interruption pendant <Highlight>3</> s après avoir ramassé un objet.",
            ["TextMapId"] = "RLBlessingGroup_Desc_201",
            },
        ["RLBlessingGroup_Desc_202"] = {
            ["ContentFR"] = "Les armes à distance déclenchent [Lune marine] et génèrent <Highlight>3</> [Mini Lunes marines]. Cet effet ne peut se déclencher qu’une fois toutes les <Highlight>10</> secondes.",
            ["TextMapId"] = "RLBlessingGroup_Desc_202",
            },
        ["RLBlessingGroup_Desc_203"] = {
            ["ContentFR"] = "Ramasser une [Mini Lune marine] octroie 1 [Lune voilée].",
            ["TextMapId"] = "RLBlessingGroup_Desc_203",
            },
        ["RLBlessingGroup_Desc_204"] = {
            ["ContentFR"] = "Consommer une [Lune voilée] libère <Highlight>3</> [Aiguillons] en éventail. Ramasser un objet accorde 1 cumul de [Dérive fantôme].",
            ["TextMapId"] = "RLBlessingGroup_Desc_204",
            },
        ["RLBlessingGroup_Desc_3"] = {
            ["ContentFR"] = "Renforcements des compétences",
            ["TextMapId"] = "RLBlessingGroup_Desc_3",
            },
        ["RLBlessingGroup_Desc_301"] = {
            ["ContentFR"] = "Chaque [Lucimèche] de cet ensemble confère +<Highlight>15 %</> de Bouclier max. Dégâts de compétence +<Highlight>25 %</>.",
            ["TextMapId"] = "RLBlessingGroup_Desc_301",
            },
        ["RLBlessingGroup_Desc_302"] = {
            ["ContentFR"] = "Gagne 1 cumul de [Lueur] par seconde (max 60). À 60 cumuls, l’utilisation d’une compétence consomme toutes les [Lueurs] et confère [Éclat] pendant <Highlight>10</> s, augmentant les dégâts de compétence de <Highlight>50 %</>.",
            ["TextMapId"] = "RLBlessingGroup_Desc_302",
            },
        ["RLBlessingGroup_Desc_303"] = {
            ["ContentFR"] = "Sous [Éclat], déclenche une [Émission] toutes les 2 s, infligeant des Dégâts de compétence équivalents à <Highlight>810 %</> de l’ATQ du personnage dans un rayon de <Highlight>6</> m.",
            ["TextMapId"] = "RLBlessingGroup_Desc_303",
            },
        ["RLBlessingGroup_Desc_304"] = {
            ["ContentFR"] = "Prolonge la durée d’[Éclat] à <Highlight>20</> s.",
            ["TextMapId"] = "RLBlessingGroup_Desc_304",
            },
        ["RLBlessingGroup_Desc_4"] = {
            ["ContentFR"] = "Spécialisation des invocations",
            ["TextMapId"] = "RLBlessingGroup_Desc_4",
            },
        ["RLBlessingGroup_Desc_401"] = {
            ["ContentFR"] = "Chaque [Lucimèche] de cet ensemble confère +<Highlight>15 %</> de Dégâts d’invocation.\
Invoquer un familier autre que la lignée [Rameau lumineux] invoque aussi 1 [Graine de Lumen].\
[Graine de Lumen] : explose lorsqu’un ennemi entre dans un rayon de <Highlight>3</> m, infligeant des dégâts équivalents à <Highlight>600 %</> de l’ATQ. Dure <Highlight>10</> s, jusqu’à 10 simultanément.",
            ["TextMapId"] = "RLBlessingGroup_Desc_401",
            },
        ["RLBlessingGroup_Desc_402"] = {
            ["ContentFR"] = "Chaque [Graine de Lumen] a <Highlight>40 %</> de chance d’évoluer en [Feuille de Lumen].\
[Feuille de Lumen] : explose lorsqu’un ennemi approche à <Highlight>3</> m, infligeant <Highlight>1000 %</> de l’ATQ. Dure <Highlight>10</> s, jusqu’à 10 simultanément.",
            ["TextMapId"] = "RLBlessingGroup_Desc_402",
            },
        ["RLBlessingGroup_Desc_403"] = {
            ["ContentFR"] = "Lorsqu’une [Feuille de Lumen] explose, elle invoque un [Arbre de Lumen].\
Lorsqu’elle est soignée, inflige des dégâts équivalents à <Highlight>4000 %</> des PV restaurés aux ennemis dans un rayon de 6 m.\
[Arbre de Lumen] : soigne les alliés dans un rayon de <Highlight>10</> m à hauteur de <Highlight>5 %</> de leurs PV max par seconde. Dure <Highlight>10</> s, un seul actif à la fois.",
            ["TextMapId"] = "RLBlessingGroup_Desc_403",
            },
        ["RLBlessingGroup_Desc_404"] = {
            ["ContentFR"] = "Double les chances de toutes les sources pouvant invoquer une [Graine de Lumen]. [Arbre de Lumen] inflige <Highlight>650 %</> de l’ATQ en dégâts par seconde aux ennemis à portée.",
            ["TextMapId"] = "RLBlessingGroup_Desc_404",
            },
        ["RLBlessingGroup_Desc_5"] = {
            ["ContentFR"] = "Renforcements de la mobilité",
            ["TextMapId"] = "RLBlessingGroup_Desc_5",
            },
        ["RLBlessingGroup_Desc_501"] = {
            ["ContentFR"] = "Chaque [Lucimèche] de cet ensemble confère +<Highlight>10 %</> de Lucidité max. Chaque cumul de [Dévoreur d’ombre] augmente l’ATQ du personnage de <Highlight>1 %</>.",
            ["TextMapId"] = "RLBlessingGroup_Desc_501",
            },
        ["RLBlessingGroup_Desc_502"] = {
            ["ContentFR"] = "Infliger des dégâts octroie <Highlight>5</> cumuls de [Dévoreur d’ombre]. Cet effet ne peut se déclencher qu’une fois toutes les <Highlight>5</> s.",
            ["TextMapId"] = "RLBlessingGroup_Desc_502",
            },
        ["RLBlessingGroup_Desc_503"] = {
            ["ContentFR"] = "Restaure <Highlight>2</> de Lucidité par seconde pour chaque tranche de 10 cumuls de [Dévoreur d’ombre].",
            ["TextMapId"] = "RLBlessingGroup_Desc_503",
            },
        ["RLBlessingGroup_Desc_504"] = {
            ["ContentFR"] = "[Poudre d’écailles], [Ailes de vent] et [Ailes-lames] infligent une attaque supplémentaire basée sur l’ATQ et la Lucidité max du personnage (<Highlight>1 % × ATQ × Lucidité max</>).",
            ["TextMapId"] = "RLBlessingGroup_Desc_504",
            },
        ["RLBlessingGroup_Desc_6"] = {
            ["ContentFR"] = "Missiles à tête chercheuse",
            ["TextMapId"] = "RLBlessingGroup_Desc_6",
            },
        ["RLBlessingGroup_Desc_601"] = {
            ["ContentFR"] = "Chaque [Lucimèche] de cet ensemble confère +<Highlight>10 %</> de Portée de compétence. Augmente la limite de [Luciole brillante] de <Highlight>+1</>, et leurs attaques infligent désormais des DGT de zone dans un rayon de <Highlight>2</> m.",
            ["TextMapId"] = "RLBlessingGroup_Desc_601",
            },
        ["RLBlessingGroup_Desc_602"] = {
            ["ContentFR"] = "Obtenir une [Luciole brillante] a <Highlight>30 %</> de chance de faire apparaître une [Luciole brillante] plus grande.",
            ["TextMapId"] = "RLBlessingGroup_Desc_602",
            },
        ["RLBlessingGroup_Desc_603"] = {
            ["ContentFR"] = "Limite de [Luciole brillante] +<Highlight>1</>. Les versions de grande taille se scindent en <Highlight>3</> [Luciole brillante] standard lorsqu’elles touchent un ennemi.",
            ["TextMapId"] = "RLBlessingGroup_Desc_603",
            },
        ["RLBlessingGroup_Desc_604"] = {
            ["ContentFR"] = "Lorsque [Luciole brillante] inflige des dégâts, elle applique <Highlight>1</> cumul augmentant les dégâts subis par la cible de <Highlight>12 %</>, de façon permanente. Cet effet peut se cumuler jusqu’à <Highlight>5</> fois.",
            ["TextMapId"] = "RLBlessingGroup_Desc_604",
            },
        ["RLBlessingGroup_Desc_7"] = {
            ["ContentFR"] = "Améliore la survie et confère des capacités de rage",
            ["TextMapId"] = "RLBlessingGroup_Desc_7",
            },
        ["RLBlessingGroup_Desc_701"] = {
            ["ContentFR"] = "Chaque [Lucimèche] de cet ensemble confère +<Highlight>10 %</> de Durée de compétence. Vaincre un ennemi augmente les PV max de <Highlight>0,5 %</>, jusqu’à un maximum de <Highlight>50 %</>.",
            ["TextMapId"] = "RLBlessingGroup_Desc_701",
            },
        ["RLBlessingGroup_Desc_702"] = {
            ["ContentFR"] = "Restaure <Highlight>1 %</> des PV max par seconde. L’effet est amplifié de <Highlight>0,33 %</> pour chaque tranche de <Highlight>25 %</> de PV perdus.",
            ["TextMapId"] = "RLBlessingGroup_Desc_702",
            },
        ["RLBlessingGroup_Desc_703"] = {
            ["ContentFR"] = "Toutes les <Highlight>3</> secondes, inflige aux ennemis à proximité des dégâts équivalents à <Highlight>50 %</> des PV max du personnage.\
Chaque diminution de <Highlight>25 %</> des PV augmente l’efficacité de cet effet de <Highlight>16,7 %</>.",
            ["TextMapId"] = "RLBlessingGroup_Desc_703",
            },
        ["RLBlessingGroup_Desc_704"] = {
            ["ContentFR"] = "Lorsque les PV sont supérieurs à <Highlight>40 %</>, tous les effets [Fleur vampirique] basés sur le pourcentage de PV sont calculés comme si les PV étaient fixés à <Highlight>40 %</>.\
Les effets liés à la Vigueur et à la Ténacité utilisent également cette valeur.",
            ["TextMapId"] = "RLBlessingGroup_Desc_704",
            },
        ["RLBlessingGroup_Desc_unknown"] = {
            ["ContentFR"] = "Cette bénédiction demeure encore voilée par la brume.",
            ["TextMapId"] = "RLBlessingGroup_Desc_unknown",
            },
