            },
        ["RLBlessing_Desc_104"] = {
            ["ContentFR"] = "Vaincre un ennemi dans un rayon de <Highlight>$2</> m restaure <Highlight>$1</> PV.",
            ["TextMapId"] = "RLBlessing_Desc_104",
            },
        ["RLBlessing_Desc_105"] = {
