            ["TextMapId"] = "RLBlessing_Desc_105",
            },
        ["RLBlessing_Desc_106"] = {
            ["ContentFR"] = "Subir des dégâts applique <Highlight>1</> cumul de [Flammes ardentes] aux ennemis dans un rayon de <Highlight>8</> m. Cet effet ne peut se déclencher qu’une fois toutes les <Highlight>$1</> s.",
