            ["TextMapId"] = "RLBlessing_Desc_108",
            },
        ["RLBlessing_Desc_109"] = {
            ["ContentFR"] = "Augmentation des dégâts des attaques plongeantes, chargées et en glissade des armes de mêlée de <Highlight>$1</>.",
            ["TextMapId"] = "RLBlessing_Desc_109",
            },
        ["RLBlessing_Desc_110"] = {
            ["ContentFR"] = "Applique <Highlight>1</> cumul de [Flammes ardentes] aux ennemis dans un rayon de <Highlight>8</> m toutes les <Highlight>$1</> s.",
            ["TextMapId"] = "RLBlessing_Desc_110",
            },
        ["RLBlessing_Desc_111"] = {
            ["ContentFR"] = "Infliger des dégâts à un ennemi possédant plus de <Highlight>$3</> cumuls de [Flammes ardentes] restaure <Highlight>$1</> PV. Cet effet ne peut se déclencher qu’une fois toutes les <Highlight>$2</> s.",
            ["TextMapId"] = "RLBlessing_Desc_111",
            },
        ["RLBlessing_Desc_112"] = {
            ["ContentFR"] = "Augmentation de la <Highlight>Vitesse d’attaque</> des armes de mêlée de <Highlight>#1</> et de leur <Highlight>Portée d’attaque</> de <Highlight>#2</>.",
            ["TextMapId"] = "RLBlessing_Desc_112",
            },
        ["RLBlessing_Desc_113"] = {
            ["ContentFR"] = "Si les dégâts réduisent les PV d’une cible en dessous de <Highlight>$3</>, inflige des dégâts supplémentaires équivalents à <Highlight>$1</> de l’ATQ du personnage.\
Ne peut se produire qu’une fois toutes les <Highlight>$2</> s sur la même cible.",
            ["TextMapId"] = "RLBlessing_Desc_113",
            },
        ["RLBlessing_Desc_114"] = {
            ["ContentFR"] = "Les armes de mêlée infligent des dégâts supplémentaires équivalents à <Highlight>$1</> de l’ATQ du personnage aux ennemis ayant plus de <Highlight>$2</> cumuls de [Flammes ardentes].",
            ["TextMapId"] = "RLBlessing_Desc_114",
