        ["TempleSolo_Total_Time"] = {
            ["ContentFR"] = "Résultats",
            ["TextMapId"] = "TempleSolo_Total_Time",
            },
        ["TextMap_AnswerDetail_100003"] = {
            ["ContentFR"] = "Le morceau de rideau pointe vers le Théâtre Galea, et le fredonnement opératique de l’agresseur renforce ce lien. Le théâtre mérite une inspection approfondie.",
            ["TextMapId"] = "TextMap_AnswerDetail_100003",
            },
        ["TextMap_AnswerDetail_100004"] = {
            ["ContentFR"] = "L’agresseur a fui vers le sud-ouest — et la seule installation de cette zone manipulant de grandes quantités de Phoxichor est l’usine locale. Quoi qu’il en soit, elle mérite d’être inspectée.",
            ["TextMapId"] = "TextMap_AnswerDetail_100004",
            },
        ["TextMap_AnswerDetail_100005"] = {
            ["ContentFR"] = "Décorant sa cachette d’accessoires scéniques et fredonnant un air d’opéra en pleine agression... tout laisse penser que l’agresseur apprécie l’opéra. Partir de la mélodie pourrait aider à l’identifier.",
            ["TextMapId"] = "TextMap_AnswerDetail_100005",
            },
        ["TextMap_AnswerDetail_100101"] = {
            ["ContentFR"] = "En vous remémorant la position de la lune lors de l’agression, vous estimez que l’attaque a eu lieu entre quatre et cinq heures du matin.",
            ["TextMapId"] = "TextMap_AnswerDetail_100101",
            },
        ["TextMap_AnswerDetail_100201"] = {
            ["ContentFR"] = "Cette girouette récemment brisée a sans doute été arrachée lorsque l’agresseur a bondi sur le toit. Combinée à d’autres indices, elle pourrait révéler davantage.",
            ["TextMapId"] = "TextMap_AnswerDetail_100201",
            },
        ["TextMap_AnswerDetail_100202"] = {
            ["ContentFR"] = "Le socle de la girouette est tordu en direction du sud-ouest. Avec d’autres indices, cela pourrait éclairer la fuite de l’agresseur.",
            ["TextMapId"] = "TextMap_AnswerDetail_100202",
            },
        ["TextMap_AnswerDetail_100203"] = {
            ["ContentFR"] = "Les marques de rupture du socle et de la girouette coïncident parfaitement : l’agresseur l’a heurtée en s’échappant par les toits.\
Réassemblé, l’ensemble pointe vers le sud-ouest — confirmant la direction de la fuite.",
            ["TextMapId"] = "TextMap_AnswerDetail_100203",
            },
        ["TextMap_AnswerDetail_100301"] = {
            ["ContentFR"] = "Cette nuit-là, l’agresseur fredonnait une mélodie au timbre rauque, presque chantée... Est-il chanteur ? Ou simple amateur de musique ?",
            ["TextMapId"] = "TextMap_AnswerDetail_100301",
            },
        ["TextMap_AnswerDetail_100302"] = {
            ["ContentFR"] = "Un morceau de velours identique à celui utilisé au Théâtre Galea a été retrouvé sur place. L’opéra est-il lié à l’affaire ? D’autres indices doivent confirmer ce soupçon.",
            ["TextMapId"] = "TextMap_AnswerDetail_100302",
            },
        ["TextMap_AnswerDetail_100303"] = {
            ["ContentFR"] = "Le morceau de rideau oriente les soupçons vers le Théâtre Galea, et le fredonnement de l’agresseur vient confirmer cette piste sous un autre angle. Quoi qu’il en soit, le théâtre mérite d’être examiné de près.",
            ["TextMapId"] = "TextMap_AnswerDetail_100303",
            },
        ["TextMap_AnswerDetail_100401"] = {
            ["ContentFR"] = "La fuite vers le sud-ouest mène à une zone dense : habitations, école, usine. Un périmètre trop vaste pour que Rhythm progresse. Il faudra d’autres indices pour resserrer la recherche.",
            ["TextMapId"] = "TextMap_AnswerDetail_100401",
            },
        ["TextMap_AnswerDetail_100402"] = {
            ["ContentFR"] = "Quelques gouttes de Phoxichor ont été trouvées dans la neige, loin de toute source connue. Interroger Rhythm sur les détails de la nuit pourrait révéler leur origine.",
            ["TextMapId"] = "TextMap_AnswerDetail_100402",
            },
        ["TextMap_AnswerDetail_100403"] = {
            ["ContentFR"] = "Vous vous souvenez de l’odeur âcre qui enveloppait l’agresseur : un signe clair d’exposition massive au Phoxichor. Peu d’endroits à Givrelac en contiennent autant. Croiser les indices permettra de réduire les possibilités.",
            ["TextMapId"] = "TextMap_AnswerDetail_100403",
            },
        ["TextMap_AnswerDetail_100404"] = {
            ["ContentFR"] = "L’agresseur s’est enfui vers le sud-ouest — et, dans cette direction, seul l’usine permet d’accéder à autant de Phoxichor. Serait-ce là sa cachette ? Dans tous les cas, l’usine reste un lieu à examiner de près.",
            ["TextMapId"] = "TextMap_AnswerDetail_100404",
            },
        ["TextMap_AnswerDetail_100501"] = {
            ["ContentFR"] = "Dans les égouts, vous avez trouvé un rideau de scène et des mannequins disposés comme des acteurs. L’agresseur se mettrait-il en scène ? En combinant ces indices, vous pourriez approcher son identité.",
            ["TextMapId"] = "TextMap_AnswerDetail_100501",
            },
        ["TextMap_AnswerDetail_100502"] = {
            ["ContentFR"] = "Cette nuit-là, l’agresseur fredonnait une mélodie au timbre rauque, presque chantée... Est-il chanteur ? Ou simple amateur de musique ?",
            ["TextMapId"] = "TextMap_AnswerDetail_100502",
            },
        ["TextMap_AnswerDetail_100503"] = {
            ["ContentFR"] = "Décorant sa cachette d’accessoires scéniques et fredonnant un air d’opéra en pleine agression... tout laisse penser que l’agresseur apprécie l’opéra. Partir de la mélodie pourrait aider à l’identifier.",
            ["TextMapId"] = "TextMap_AnswerDetail_100503",
            },
        ["TextMap_AnswerDetail_200101"] = {
            ["ContentFR"] = "Monsieur Buck ne boit que du jus et du lait aux Asphodèles. Il ne supporte absolument pas l’alcool : une seule gorgée suffit à l’assommer.",
            ["TextMapId"] = "TextMap_AnswerDetail_200101",
            },
        ["TextMap_AnswerDetail_200102"] = {
            ["ContentFR"] = "Quelqu’un a versé de l’alcool dans sa bouteille de lait à son insu. Une petite empreinte de main poisseuse est encore visible sur le récipient.",
            ["TextMapId"] = "TextMap_AnswerDetail_200102",
            },
        ["TextMap_AnswerDetail_200103"] = {
            ["ContentFR"] = "Une série de petites empreintes mène de la rue jusqu’à sa fenêtre : un enfant s’est clairement introduit chez lui.",
            ["TextMapId"] = "TextMap_AnswerDetail_200103",
            },
        ["TextMap_AnswerDetail_200104"] = {
            ["ContentFR"] = "Quelques grains de pop-corn jonchent la neige : probablement collés à l’intrus, puis tombés lorsqu’il a enjambé la fenêtre.",
            ["TextMapId"] = "TextMap_AnswerDetail_200104",
            },
        ["TextMap_AnswerDetail_200105"] = {
            ["ContentFR"] = "Un jeune Charon tremblant de froid vend bière, pop-corn, billets d’opéra et affiches\
près du guichet du Théâtre Galea.",
            ["TextMapId"] = "TextMap_AnswerDetail_200105",
            },
        ["TextMap_AnswerDetail_200106"] = {
            ["ContentFR"] = "Un enfant sachant que Monsieur Buck ne tolère pas l’alcool s’est glissé chez lui et a versé assez d’alcool dans son lait pour l’assommer. Voilà pourquoi Monsieur Buck s’endormait si tôt, chaque soir.",
            ["TextMapId"] = "TextMap_AnswerDetail_200106",
            },
        ["TextMap_AnswerDetail_200107"] = {
            ["ContentFR"] = "Un ivrogne avachi près d’une poubelle. Impossible qu’il soit l’intrus — ce n’est ni un enfant, ni quelqu’un qui partagerait volontiers sa boisson.",
            ["TextMapId"] = "TextMap_AnswerDetail_200107",
            },
        ["TextMap_AnswerDetail_200108"] = {
            ["ContentFR"] = "Une fillette supplie son père de lui acheter du pop-corn. Mais avec un père aussi strict, impossible que les pop-corns sous la fenêtre proviennent d’elle.",
            ["TextMapId"] = "TextMap_AnswerDetail_200108",
            },
        ["TextMap_AnswerDetail_200201"] = {
            ["ContentFR"] = "Il y a seize ans, Sig, l’ami de Donat, a monté un enlèvement. La victime, Enola, est morte dans des circonstances dites accidentelles, et Sig a été condamné à mort.",
            ["TextMapId"] = "TextMap_AnswerDetail_200201",
            },
        ["TextMap_AnswerDetail_200202"] = {
            ["ContentFR"] = "Giselle, aujourd’hui Chasseuse de Phoxène, travaillait autrefois pour les Veilleurs. Elle a quitté le service il y a seize ans, après s’être opposée à un verdict dans une affaire.",
            ["TextMapId"] = "TextMap_AnswerDetail_200202",
            },
        ["TextMap_AnswerDetail_200203"] = {
            ["ContentFR"] = "La sœur de Sig, Violette, qui avait quitté Givrelac seize ans plus tôt, semble être revenue. Un ruban violet a été retrouvé sur la tombe de son frère.",
            ["TextMapId"] = "TextMap_AnswerDetail_200203",
            },
        ["TextMap_AnswerDetail_200204"] = {
            ["ContentFR"] = "Violetta porte toujours un ruban violet sur scène. Elle affirme que c’est un souvenir offert par une amie chère.",
            ["TextMapId"] = "TextMap_AnswerDetail_200204",
            },
        ["TextMap_AnswerDetail_200205"] = {
            ["ContentFR"] = "Rosalind, la fille du Comte Magnus, a disparu — tout indique un enlèvement. Avant cela, le couple Magnus lui avait engagé un professeur de chant.",
            ["TextMapId"] = "TextMap_AnswerDetail_200205",
            },
        ["TextMap_AnswerDetail_200206"] = {
            ["ContentFR"] = "L’une des élèves de Violetta a été enlevée. La lettre de rançon fait allusion, sans les nommer, aux événements survenus seize ans plus tôt.",
            ["TextMapId"] = "TextMap_AnswerDetail_200206",
            },
        ["TextMap_AnswerDetail_200207"] = {
            ["ContentFR"] = "Il y a seize ans, Giselle faisait partie de l’équipe chargée d’enquêter sur l’enlèvement.\
Le verdict rendu dans cette affaire l’a tant marquée qu’elle a quitté les Veilleurs.",
            ["TextMapId"] = "TextMap_AnswerDetail_200207",
            },
        ["TextMap_AnswerDetail_200208"] = {
            ["ContentFR"] = "La couleur et la forme des deux rubans sont identiques. Tout porte à croire que Violetta et Violette partagent un lien étroit — et leurs prénoms étonnamment proches semblent confirmer cette connexion.",
            ["TextMapId"] = "TextMap_AnswerDetail_200208",
            },
        ["TextMap_AnswerDetail_200209"] = {
            ["ContentFR"] = "L’élève disparue de Violetta est très probablement Rosalind, la fille du Comte Magnus.\
La lettre de rançon mentionnait explicitement les événements d’il y a seize ans, ce qui laisse penser que Violetta pourrait être impliquée plus profondément dans cette affaire qu’il n’y paraît.",
            ["TextMapId"] = "TextMap_AnswerDetail_200209",
            },
        ["TextMap_AnswerDetail_200210"] = {
            ["ContentFR"] = "Le mobile derrière \"l’enlèvement\" de Rosalind semble étroitement lié à celui de l’affaire survenue seize ans plus tôt. Tout indique que Violetta connaît la vérité sur ce drame passé — peut-être même qu’elle en détient la clé.",
            ["TextMapId"] = "TextMap_AnswerDetail_200210",
            },
        ["TextMap_AnswerDetail_200211"] = {
            ["ContentFR"] = "L’affaire d’autrefois cachait une vérité que Violetta porte depuis longtemps.\
Pour la contraindre à se dévoiler, Giselle a mis en scène \"l’enlèvement\" de son élève et exigé une rencontre en tête-à-tête.",
            ["TextMapId"] = "TextMap_AnswerDetail_200211",
            },
        ["TextMap_AnswerDetail_200301"] = {
            ["ContentFR"] = "Sur le rebord de la fenêtre repose un bouquet de Lys célestes, encore perlé de la rosée du matin — quelqu’un vient de le déposer là.",
            ["TextMapId"] = "TextMap_AnswerDetail_200301",
            },
        ["TextMap_AnswerDetail_200302"] = {
            ["ContentFR"] = "Ce recoin d’Éternel Printemps est parfaitement calme : hormis les traces de pas de Lingling, on ne distingue aucune autre empreinte, ni la moindre anomalie.",
            ["TextMapId"] = "TextMap_AnswerDetail_200302",
            },
        ["TextMap_AnswerDetail_200303"] = {
            ["ContentFR"] = "Trouvé près de la porte, l’album rassemble de nombreuses photos de famille.\
Sur l’une d’elles, une Lingling plus jeune tient un bouquet de Lys célestes, aux côtés de sa grand-mère, devant cette même maison.",
            ["TextMapId"] = "TextMap_AnswerDetail_200303",
            },
        ["TextMap_AnswerDetail_200304"] = {
            ["ContentFR"] = "Une lettre raconte que la famille de Lingling a dû, pour des raisons professionnelles, quitter Haojing et revenir à Port-des-Brumes, s’installant provisoirement dans l’ancien dortoir des ouvriers où ils vivaient autrefois.",
            ["TextMapId"] = "TextMap_AnswerDetail_200304",
            },
        ["TextMap_AnswerDetail_200305"] = {
            ["ContentFR"] = "Quelqu’un a déposé ce bouquet sans laisser la moindre trace de son passage.",
            ["TextMapId"] = "TextMap_AnswerDetail_200305",
            },
        ["TextMap_AnswerDetail_200306"] = {
            ["ContentFR"] = "Le \"fantôme\" connaît intimement cette demeure sans éclat et semble très attaché à l’album de famille. Peut-être a-t-il lui aussi fait partie de ce foyer.",
            ["TextMapId"] = "TextMap_AnswerDetail_200306",
            },
        ["TextMap_AnswerDetail_200307"] = {
            ["ContentFR"] = "Le bouquet de Lys célestes, l’album de famille, la familiarité avec l’ancienne maison... Tout converge vers la même conclusion : un être cher est revenu sous une autre forme.",
            ["TextMapId"] = "TextMap_AnswerDetail_200307",
            },
        ["TextMap_AnswerDetail_200401"] = {
            ["ContentFR"] = "Un enfant de douze ans ayant attrapé un rhume après avoir joué dans la neige... Ce dossier pourrait-il concerner l’épouse de Weisheng ?",
            ["TextMapId"] = "TextMap_AnswerDetail_200401",
            },
        ["TextMap_AnswerDetail_200402"] = {
            ["ContentFR"] = "Une femme de trente et un ans dont la vue s’est détériorée après de longues nuits d’étude... Ce dossier pourrait-il concerner l’épouse de Weisheng ?",
            ["TextMapId"] = "TextMap_AnswerDetail_200402",
            },
        ["TextMap_AnswerDetail_200403"] = {
            ["ContentFR"] = "Un homme de quarante ans souffrant d’hallucinations dues au deuil de son épouse défunte... Ce dossier pourrait-il concerner l’épouse de Weisheng ?",
            ["TextMapId"] = "TextMap_AnswerDetail_200403",
            },
        ["TextMap_AnswerName_100003"] = {
            ["ContentFR"] = "Théâtre Galea — Cachette potentielle",
            ["TextMapId"] = "TextMap_AnswerName_100003",
            },
        ["TextMap_AnswerName_100004"] = {
            ["ContentFR"] = "Usine — Cachette potentielle",
            ["TextMapId"] = "TextMap_AnswerName_100004",
            },
        ["TextMap_AnswerName_100005"] = {
            ["ContentFR"] = "Mélodie d’opéra entendue lors de l’attaque",
            ["TextMapId"] = "TextMap_AnswerName_100005",
            },
        ["TextMap_AnswerName_100101"] = {
            ["ContentFR"] = "Heure estimée de l’attaque — entre 4 h et 5 h",
            ["TextMapId"] = "TextMap_AnswerName_100101",
            },
        ["TextMap_AnswerName_100201"] = {
            ["ContentFR"] = "Girouette récemment endommagée",
            ["TextMapId"] = "TextMap_AnswerName_100201",
            },
        ["TextMap_AnswerName_100202"] = {
            ["ContentFR"] = "Socle de la girouette plié vers le sud-ouest",
            ["TextMapId"] = "TextMap_AnswerName_100202",
            },
        ["TextMap_AnswerName_100203"] = {
            ["ContentFR"] = "Girouette réassemblée : fuite confirmée vers le sud-ouest",
            ["TextMapId"] = "TextMap_AnswerName_100203",
            },
        ["TextMap_AnswerName_100301"] = {
            ["ContentFR"] = "Chant étrange de l’agresseur",
            ["TextMapId"] = "TextMap_AnswerName_100301",
            },
        ["TextMap_AnswerName_100302"] = {
            ["ContentFR"] = "Morceau de rideau de scène trouvé sur place",
            ["TextMapId"] = "TextMap_AnswerName_100302",
            },
        ["TextMap_AnswerName_100303"] = {
            ["ContentFR"] = "Théâtre Galea — Cachette potentielle",
            ["TextMapId"] = "TextMap_AnswerName_100303",
            },
        ["TextMap_AnswerName_100401"] = {
            ["ContentFR"] = "Zone de recherche étendue au sud-ouest : usine — habitations — écoles",
            ["TextMapId"] = "TextMap_AnswerName_100401",
            },
        ["TextMap_AnswerName_100402"] = {
            ["ContentFR"] = "Traces de Phoxichor dans la neige",
            ["TextMapId"] = "TextMap_AnswerName_100402",
            },
        ["TextMap_AnswerName_100403"] = {
            ["ContentFR"] = "Agresseur fortement imprégné de Phoxichor",
            ["TextMapId"] = "TextMap_AnswerName_100403",
            },
        ["TextMap_AnswerName_100404"] = {
            ["ContentFR"] = "Usine — Cachette potentielle",
            ["TextMapId"] = "TextMap_AnswerName_100404",
            },
        ["TextMap_AnswerName_100501"] = {
            ["ContentFR"] = "L’agresseur serait amateur d’opéra ?",
            ["TextMapId"] = "TextMap_AnswerName_100501",
            },
        ["TextMap_AnswerName_100502"] = {
            ["ContentFR"] = "Chant étrange de l’agresseur",
            ["TextMapId"] = "TextMap_AnswerName_100502",
            },
        ["TextMap_AnswerName_100503"] = {
            ["ContentFR"] = "Mélodie d’opéra entendue lors de l’attaque",
            ["TextMapId"] = "TextMap_AnswerName_100503",
            },
        ["TextMap_AnswerName_200101"] = {
            ["ContentFR"] = "Monsieur Buck sombre après la moindre goutte d’alcool",
            ["TextMapId"] = "TextMap_AnswerName_200101",
            },
        ["TextMap_AnswerName_200102"] = {
            ["ContentFR"] = "La bouteille de lait a été alcoolisée à son insu",
            ["TextMapId"] = "TextMap_AnswerName_200102",
            },
        ["TextMap_AnswerName_200103"] = {
            ["ContentFR"] = "Des empreintes d’enfant sur le rebord de la fenêtre",
            ["TextMapId"] = "TextMap_AnswerName_200103",
            },
        ["TextMap_AnswerName_200104"] = {
            ["ContentFR"] = "Du pop-corn éparpillé près des empreintes",
            ["TextMapId"] = "TextMap_AnswerName_200104",
            },
        ["TextMap_AnswerName_200105"] = {
            ["ContentFR"] = "Un garçon vendait bière et pop-corn près du théâtre",
            ["TextMapId"] = "TextMap_AnswerName_200105",
            },
        ["TextMap_AnswerName_200106"] = {
            ["ContentFR"] = "Un enfant s’est introduit chez Monsieur Buck et l’a enivré",
            ["TextMapId"] = "TextMap_AnswerName_200106",
            },
        ["TextMap_AnswerName_200107"] = {
            ["ContentFR"] = "Un ivrogne avachi près d’une poubelle réclame encore à boire",
            ["TextMapId"] = "TextMap_AnswerName_200107",
            },
        ["TextMap_AnswerName_200108"] = {
            ["ContentFR"] = "Une fillette supplie son père pour du pop-corn",
            ["TextMapId"] = "TextMap_AnswerName_200108",
            },
        ["TextMap_AnswerName_200201"] = {
            ["ContentFR"] = "L’enlèvement survenu il y a seize ans",
            ["TextMapId"] = "TextMap_AnswerName_200201",
            },
        ["TextMap_AnswerName_200202"] = {
            ["ContentFR"] = "La démission de Giselle des Veilleurs, il y a seize ans",
            ["TextMapId"] = "TextMap_AnswerName_200202",
            },
        ["TextMap_AnswerName_200203"] = {
            ["ContentFR"] = "Le ruban violet sur la tombe de Sig",
            ["TextMapId"] = "TextMap_AnswerName_200203",
            },
        ["TextMap_AnswerName_200204"] = {
            ["ContentFR"] = "Le ruban signature de Violetta",
            ["TextMapId"] = "TextMap_AnswerName_200204",
            },
        ["TextMap_AnswerName_200205"] = {
            ["ContentFR"] = "L’héritière enlevée",
            ["TextMapId"] = "TextMap_AnswerName_200205",
            },
        ["TextMap_AnswerName_200206"] = {
            ["ContentFR"] = "L’élève disparue de Violetta",
            ["TextMapId"] = "TextMap_AnswerName_200206",
            },
        ["TextMap_AnswerName_200207"] = {
            ["ContentFR"] = "Giselle a quitté les Veilleurs à cause de l’affaire d’enlèvement",
            ["TextMapId"] = "TextMap_AnswerName_200207",
            },
        ["TextMap_AnswerName_200208"] = {
            ["ContentFR"] = "Violetta et Violette sont liées",
            ["TextMapId"] = "TextMap_AnswerName_200208",
            },
        ["TextMap_AnswerName_200209"] = {
            ["ContentFR"] = "L’héritière enlevée est probablement l’élève disparue de Violetta",
            ["TextMapId"] = "TextMap_AnswerName_200209",
            },
        ["TextMap_AnswerName_200210"] = {
            ["ContentFR"] = "Violetta connaît la vérité sur l’enlèvement d’il y a seize ans",
            ["TextMapId"] = "TextMap_AnswerName_200210",
            },
        ["TextMap_AnswerName_200211"] = {
            ["ContentFR"] = "Giselle est l’instigatrice du dernier enlèvement",
            ["TextMapId"] = "TextMap_AnswerName_200211",
            },
        ["TextMap_AnswerName_200301"] = {
            ["ContentFR"] = "Bouquet de fleurs",
            ["TextMapId"] = "TextMap_AnswerName_200301",
            },
        ["TextMap_AnswerName_200302"] = {
            ["ContentFR"] = "Sol et fenêtres impeccables",
            ["TextMapId"] = "TextMap_AnswerName_200302",
            },
        ["TextMap_AnswerName_200303"] = {
            ["ContentFR"] = "Album de famille",
            ["TextMapId"] = "TextMap_AnswerName_200303",
            },
        ["TextMap_AnswerName_200304"] = {
            ["ContentFR"] = "Lettre parlant du déménagement",
            ["TextMapId"] = "TextMap_AnswerName_200304",
            },
        ["TextMap_AnswerName_200305"] = {
            ["ContentFR"] = "Une visite fantomatique",
            ["TextMapId"] = "TextMap_AnswerName_200305",
            },
        ["TextMap_AnswerName_200306"] = {
            ["ContentFR"] = "Un attachement tenace à la maison",
            ["TextMapId"] = "TextMap_AnswerName_200306",
            },
        ["TextMap_AnswerName_200307"] = {
            ["ContentFR"] = "Le \"fantôme\", un Wishen issu de sa famille",
            ["TextMapId"] = "TextMap_AnswerName_200307",
            },
        ["TextMap_AnswerName_200401"] = {
            ["ContentFR"] = "Dossier médical — Femme de la famille Liu",
            ["TextMapId"] = "TextMap_AnswerName_200401",
            },
        ["TextMap_AnswerName_200402"] = {
            ["ContentFR"] = "Dossier médical — Femme de la famille Chen",
            ["TextMapId"] = "TextMap_AnswerName_200402",
            },
        ["TextMap_AnswerName_200403"] = {
            ["ContentFR"] = "Dossier médical — Homme de la famille Liu",
            ["TextMapId"] = "TextMap_AnswerName_200403",
            },
        ["TextMap_Inference_1000"] = {
            ["ContentFR"] = "Traque aux Charons",
            ["TextMapId"] = "TextMap_Inference_1000",
            },
        ["TextMap_Inference_1001"] = {
            ["ContentFR"] = "À quel moment avez-vous été attaqué ?",
            ["TextMapId"] = "TextMap_Inference_1001",
            },
        ["TextMap_Inference_1002"] = {
            ["ContentFR"] = "Dans quelle direction l’agresseur s’est-il enfui ?",
            ["TextMapId"] = "TextMap_Inference_1002",
            },
        ["TextMap_Inference_1003"] = {
            ["ContentFR"] = "Où l’agresseur pourrait-il se cacher ? (I)",
            ["TextMapId"] = "TextMap_Inference_1003",
            },
        ["TextMap_Inference_1004"] = {
            ["ContentFR"] = "Où l’agresseur pourrait-il se cacher ? (II)",
            ["TextMapId"] = "TextMap_Inference_1004",
            },
        ["TextMap_Inference_1005"] = {
            ["ContentFR"] = "Existe-t-il d’autres indices permettant d’identifier l’agresseur ?",
            ["TextMapId"] = "TextMap_Inference_1005",
            },
        ["TextMap_Inference_2001"] = {
            ["ContentFR"] = "Identifier le Voleur d’inspiration",
            ["TextMapId"] = "TextMap_Inference_2001",
            },
        ["TextMap_Inference_2002"] = {
            ["ContentFR"] = "{$Huozai04Tag$|Reconstituez les liens entre ces événements et dévoilez la vérité cachée : ???}",
            ["TextMapId"] = "TextMap_Inference_2002",
            },
        ["TextMap_Inference_2003"] = {
            ["ContentFR"] = "La vieille demeure hantée",
            ["TextMapId"] = "TextMap_Inference_2003",
            },
        ["TextMap_Inference_2004"] = {
            ["ContentFR"] = "Quel dossier médical est lié à l’épouse de Weisheng ?",
            ["TextMapId"] = "TextMap_Inference_2004",
            },
