            },
        ["TextMap_ResultTips_10030101"] = {
            ["ContentFR"] = "Théâtre Galea — Cachette potentielle",
            ["TextMapId"] = "TextMap_ResultTips_10030101",
            },
        ["TextMap_ResultTips_10040101"] = {
            ["ContentFR"] = "Usine — Cachette potentielle",
