            ["TextMapId"] = "TextMap_ResultTips_10050101",
            },
        ["TextMap_ResultTips_20010101"] = {
            ["ContentFR"] = "Le Voleur d’inspiration n’est autre qu’un jeune Charon nommé Arnaud.",
            ["TextMapId"] = "TextMap_ResultTips_20010101",
            },
        ["TextMap_ResultTips_20020101"] = {
            ["ContentFR"] = "Giselle est l’instigatrice du dernier enlèvement",
            ["TextMapId"] = "TextMap_ResultTips_20020101",
            },
        ["TextMap_ResultTips_20030101"] = {
            ["ContentFR"] = "Le bouquet de Lys célestes, l’album de famille, la familiarité avec l’ancienne maison... Tout converge vers la même conclusion : un être cher est revenu sous une autre forme.",
            ["TextMapId"] = "TextMap_ResultTips_20030101",
            },
        ["TextMap_ResultTips_20040101"] = {
            ["ContentFR"] = "Aussi absurde que puisse paraître l’idée que l’« épouse » de Weisheng soit un homme, une fois les deux réponses erronées écartées, la dernière — si invraisemblable soit-elle — pourrait bien contenir une part de vérité.",
            ["TextMapId"] = "TextMap_ResultTips_20040101",
            },
