        ["UIGuide_Rouge_1"] = {
            ["ContentFR"] = "L’espace de l’Abysse est instable — un chaos en perpétuelle métamorphose.\
À chaque profondeur franchie, de nouvelles issues s’ouvrent, menant vers des zones aux propriétés distinctes.\
Choisir la voie à suivre sera essentiel pour poursuivre votre exploration.",
            ["TextMapId"] = "UIGuide_Rouge_1",
            },
        ["UIGuide_Rouge_2_1"] = {
            ["ContentFR"] = "Secteur Umbré : un secteur entièrement dédié au combat. Affrontez et dissipez les Umbrés pour obtenir des Braises ainsi que d’autres récompenses utiles.",
            ["TextMapId"] = "UIGuide_Rouge_2_1",
            },
        ["UIGuide_Rouge_2_2"] = {
            ["ContentFR"] = "Secteur des Échos : un lieu où surgissent d’étranges fortunes — événements imprévisibles, rencontres singulières, choix aux conséquences inattendues.",
            ["TextMapId"] = "UIGuide_Rouge_2_2",
            },
        ["UIGuide_Rouge_2_3"] = {
            ["ContentFR"] = "Secteur du Repos : une zone sûre. Vous pouvez y échanger des Braises contre des provisions, restaurer vos PV et retrouver de la Lucidité avant de repartir.",
            ["TextMapId"] = "UIGuide_Rouge_2_3",
            },
        ["UIGuide_Run_PC"] = {
            ["ContentFR"] = "Maintenir &Avoid& pour courir",
            ["TextMapId"] = "UIGuide_Run_PC",
            },
        ["UIGuide_Run_Phone"] = {
            ["ContentFR"] = "Maintenir le bouton pour courir",
            ["TextMapId"] = "UIGuide_Run_Phone",
            },
        ["UIGuide_SIDEWAYSJUMP"] = {
            ["ContentFR"] = "Lorsque vous êtes collé à un mur grimpable, maintenez une direction et appuyez sur &Jump& <H>à plusieurs reprises</> pour effectuer des sauts latéraux successifs.",
            ["TextMapId"] = "UIGuide_SIDEWAYSJUMP",
            },
        ["UIGuide_Saiqi_1"] = {
            ["ContentFR"] = "Appuyez sur &Skill1& pour que Psyche se projette vers l’avant et créer un [Mirage] à son point de départ. Cette compétence peut être utilisée à tout moment et n’interrompt aucune action en cours.",
            ["TextMapId"] = "UIGuide_Saiqi_1",
            },
        ["UIGuide_Saiqi_1_Gamepad"] = {
            ["ContentFR"] = "Appuyer sur &GamepadUseSkill& + &Attack& pour que Psyche se projette vers l’avant et créer un [Mirage] à son point de départ. Cette compétence peut être utilisée à tout moment et n’interrompt aucune action en cours.",
            ["TextMapId"] = "UIGuide_Saiqi_1_Gamepad",
            },
        ["UIGuide_Saiqi_1_Phone"] = {
            ["ContentFR"] = "Touchez le bouton pour que Psyche se projette vers l’avant et créer un [Mirage] à son point de départ. Cette compétence peut être utilisée à tout moment et n’interrompt aucune action en cours.",
            ["TextMapId"] = "UIGuide_Saiqi_1_Phone",
            },
        ["UIGuide_Saiqi_2"] = {
            ["ContentFR"] = "Appuyez sur &Skill2& pour faire entrer Psyche en état de [Métamorphose radieuse], lui conférant la capacité de voler. Dans cet état, elle ne peut qu’utiliser des compétences ou tirer. [Rêve de Chrysalide] est remplacé par [Chasse-lumière] : Psyche se projette vers l’avant en libérant une [Poussière éthérée] auto-guidée, infligeant des Dégâts Anémo.",
            ["TextMapId"] = "UIGuide_Saiqi_2",
            },
        ["UIGuide_Saiqi_2_Gamepad"] = {
            ["ContentFR"] = "Appuyez sur &GamepadUseSkill& + &Interactive& pour faire entrer Psyche en état de [Métamorphose radieuse], lui conférant la capacité de voler. Dans cet état, elle ne peut qu’utiliser des compétences ou tirer. [Rêve de Chrysalide] est remplacé par [Chasse-lumière] : Psyche se projette vers l’avant en libérant une [Poussière éthérée] auto-guidée, infligeant des Dégâts Anémo.",
            ["TextMapId"] = "UIGuide_Saiqi_2_Gamepad",
            },
        ["UIGuide_Saiqi_2_Phone"] = {
            ["ContentFR"] = "Touchez le bouton pour faire entrer Psyche en état de [Métamorphose radieuse], lui conférant la capacité de voler. Dans cet état, elle ne peut qu’utiliser des compétences ou tirer. [Rêve de Chrysalide] est remplacé par [Chasse-lumière] : Psyche se projette vers l’avant en libérant une [Poussière éthérée] auto-guidée, infligeant des Dégâts Anémo.",
            ["TextMapId"] = "UIGuide_Saiqi_2_Phone",
            },
        ["UIGuide_Shadow_1"] = {
            ["ContentFR"] = "Utilisez un <H>Emblème de combat</> pour appeler un partenaire en combat. Avant cela, ouvrez l’interface du Sac tactique et glissez-y l’emblème correspondant.",
            ["TextMapId"] = "UIGuide_Shadow_1",
            },
        ["UIGuide_Shadow_2"] = {
            ["ContentFR"] = "Maintenez &OpenBattleWheel& pour invoquer un allié. Il combattra aux côtés de votre personnage actuel.",
            ["TextMapId"] = "UIGuide_Shadow_2",
            },
        ["UIGuide_ShanYe_1"] = {
            ["ContentFR"] = "Utiliser la fonction Attraction du Nexus mécanique pour faire tourner les pales, générer un courant d’air et ouvrir la porte mécanique.",
            ["TextMapId"] = "UIGuide_ShanYe_1",
            },
        ["UIGuide_ShengMing_1"] = {
            ["ContentFR"] = "La <H>réputation</> s’obtient en accomplissant des <H>Épreuves</> et des <H>Offrandes</>. Elle est soumise à un plafond hebdomadaire.",
            ["TextMapId"] = "UIGuide_ShengMing_1",
            },
        ["UIGuide_ShengMing_2"] = {
            ["ContentFR"] = "Les Épreuves comportent trois niveaux de difficulté. Terminer une épreuve permet d’obtenir de la réputation et de déverrouiller le niveau de difficulté suivant. Les épreuves se réinitialisent automatiquement chaque jour.",
            ["TextMapId"] = "UIGuide_ShengMing_2",
            },
        ["UIGuide_ShengMing_3"] = {
            ["ContentFR"] = "La réputation s’obtient en collectant et en soumettant les objets requis pour les Offrandes. Les offrandes se réinitialisent automatiquement chaque semaine, mais peuvent aussi être actualisées instantanément en dépensant des pièces.",
            ["TextMapId"] = "UIGuide_ShengMing_3",
            },
        ["UIGuide_Sojourns_01"] = {
            ["ContentFR"] = "<Highlight>Fragments de mémoire</> débloqués. Accédez-y depuis le Sanctuaire en sélectionnant l’icône dédiée.",
            ["TextMapId"] = "UIGuide_Sojourns_01",
            },
        ["UIGuide_Sojourns_01_Pad"] = {
            ["ContentFR"] = "Les <Highlight>Fragments de mémoire</> sont désormais disponibles. Accédez-y depuis le Sanctuaire pour les consulter",
            ["TextMapId"] = "UIGuide_Sojourns_01_Pad",
            },
        ["UIGuide_Sojourns_02"] = {
            ["ContentFR"] = "Les <Highlight>Fragments de mémoire</> rassemblent des éclats de souvenirs et de temps.",
            ["TextMapId"] = "UIGuide_Sojourns_02",
            },
        ["UIGuide_Sojourns_03"] = {
            ["ContentFR"] = "Dans l’<Highlight>Anthologie du temps</>, vous pouvez découvrir des épisodes de la vie des personnages.",
            ["TextMapId"] = "UIGuide_Sojourns_03",
            },
        ["UIGuide_Sojourns_03_Pad"] = {
            ["ContentFR"] = "Appuyer pour ouvrir l’<Highlight>Anthologie du temps</> et découvrir des fragments de vie de chaque personnage",
            ["TextMapId"] = "UIGuide_Sojourns_03_Pad",
            },
        ["UIGuide_Sojourns_04"] = {
            ["ContentFR"] = "Chaque personnage possède ses propres histoires.",
            ["TextMapId"] = "UIGuide_Sojourns_04",
            },
        ["UIGuide_Sojourns_04_Pad"] = {
            ["ContentFR"] = "Appuyer pour parcourir les histoires propres à chaque personnage",
            ["TextMapId"] = "UIGuide_Sojourns_04_Pad",
            },
        ["UIGuide_Sojourns_05"] = {
            ["ContentFR"] = "Dépensez des <Highlight>Empreintes d’âme</> pour reconstituer ces récits. Certains nécessitent des conditions de déblocage particulières.",
            ["TextMapId"] = "UIGuide_Sojourns_05",
            },
        ["UIGuide_Sojourns_06"] = {
            ["ContentFR"] = "En remplissant les conditions, vous débloquez de nouvelles histoires et obtenez des récompenses.",
            ["TextMapId"] = "UIGuide_Sojourns_06",
            },
        ["UIGuide_Sojourns_06_Pad"] = {
            ["ContentFR"] = "Les histoires se débloquent après avoir rempli les conditions. Appuyer pour récupérer les récompenses",
            ["TextMapId"] = "UIGuide_Sojourns_06_Pad",
            },
        ["UIGuide_Sojourns_07"] = {
            ["ContentFR"] = "Les histoires débloquées peuvent être revues dans <Highlight>Instants figés</>.",
            ["TextMapId"] = "UIGuide_Sojourns_07",
            },
        ["UIGuide_Sp"] = {
            ["ContentFR"] = "La ressource principale nécessaire pour utiliser vos compétences. Elle se <H>régénère naturellement</> avec le temps.",
            ["TextMapId"] = "UIGuide_Sp",
            },
        ["UIGuide_SpecialDestructible_1"] = {
            ["ContentFR"] = "Certains objets ne peuvent être détruits qu’à l’aide d’un <H>Effet supplémentaire spécifique</> ou d’une <H>compétence infligeant des dégâts d’un attribut particulier</>.",
            ["TextMapId"] = "UIGuide_SpecialDestructible_1",
            },
        ["UIGuide_SpecialDestructible_2"] = {
            ["ContentFR"] = "Par exemple, certains coffres recouverts de <H>Cristaux de glace</> peuvent être détruits à l’aide d’un <H>Effet supplémentaire : Contondant</>, d’un <H>Effet supplémentaire : Pyro</> ou d’une <H>compétence infligeant des Dégâts Pyro</>.\
(Les <H>attributs</> des personnages et des armes, ainsi que la <H>probabilité</> d’activer un Effet supplémentaire, peuvent être consultés dans le menu <H>Arsenal</>.)",
            ["TextMapId"] = "UIGuide_SpecialDestructible_2",
            },
        ["UIGuide_SpecialDestructible_3"] = {
            ["ContentFR"] = "Certains objets ne peuvent être détruits qu’à l’aide d’un <H>Effet supplémentaire spécifique</> ou d’une <H>compétence infligeant des dégâts d’un attribut particulier</>.\
Par exemple, certains coffres recouverts de <H>Vignes Umbro</> peuvent être détruits à l’aide d’un <H>Effet supplémentaire : Tranchant</>, d’un <H>Effet supplémentaire : Lumino</> ou d’une <H>compétence infligeant des dégâts Lumino</>.\
(Les <H>attributs</> des personnages et des armes, ainsi que la <H>probabilité</> d’activer un Effet supplémentaire, peuvent être consultés dans le menu <H>Arsenal</>.)",
            ["TextMapId"] = "UIGuide_SpecialDestructible_3",
            },
        ["UIGuide_SpecialDestructible_4"] = {
            ["ContentFR"] = "Certains objets ne peuvent être détruits qu’à l’aide d’un <H>Effet supplémentaire spécifique</> ou d’une <H>compétence infligeant des dégâts d’un attribut particulier</>.\
Par exemple, certains coffres recouverts de <H>Gravier</> peuvent être détruits à l’aide d’un <H>Effet supplémentaire : Contondant</>.\
(Les <H>attributs</> des personnages et des armes, ainsi que la <H>probabilité</> d’activer un Effet supplémentaire, peuvent être consultés dans le menu <H>Arsenal</>.)",
            ["TextMapId"] = "UIGuide_SpecialDestructible_4",
            },
        ["UIGuide_SpecialDestructible_5"] = {
            ["ContentFR"] = "Certains objets ne peuvent être détruits qu’à l’aide d’un <H>Effet supplémentaire spécifique</> ou d’une <H>compétence infligeant des dégâts d’un attribut particulier</>.\
Par exemple, certains coffres recouverts de <H>Bouclier Lumino</> peuvent être détruits à l’aide d’un <H>Effet supplémentaire : Perforant</>, d’un <H>Effet supplémentaire : Umbro</> ou d’une <H>compétence infligeant des dégâts Umbro</>.\
(Les <H>attributs</> des personnages et des armes, ainsi que la <H>probabilité</> d’activer un Effet supplémentaire, peuvent être consultés dans le menu <H>Arsenal</>.)",
            ["TextMapId"] = "UIGuide_SpecialDestructible_5",
            },
        ["UIGuide_SpecialSideStoryUI1"] = {
            ["ContentFR"] = "Vous pouvez rencontrer des quêtes secondaires spéciales, signalées par une icône bleue dans votre journal.",
            ["TextMapId"] = "UIGuide_SpecialSideStoryUI1",
            },
        ["UIGuide_SpecialSideStoryUI2"] = {
            ["ContentFR"] = "Les mêmes icônes apparaissent dans le monde pendant votre exploration. Terminer ces quêtes peut débloquer de nouvelles fonctionnalités.",
            ["TextMapId"] = "UIGuide_SpecialSideStoryUI2",
            },
        ["UIGuide_SwitchMaster_PC"] = {
            ["ContentFR"] = "Dans les zones sûres, <H>maintenez</> &Skill3& pour incarner {性别:le|la} protagoniste et explorer librement.",
            ["TextMapId"] = "UIGuide_SwitchMaster_PC",
            },
        ["UIGuide_SwitchMaster_Phone"] = {
            ["ContentFR"] = "Dans les zones sûres, <H>maintenez</> le bouton correspondant pour incarner {性别:le|la} protagoniste et explorer librement.",
            ["TextMapId"] = "UIGuide_SwitchMaster_Phone",
            },
        ["UIGuide_TaskAcceptance"] = {
            ["ContentFR"] = "En explorant les villes, interagir avec certains habitants peut révéler des quêtes secondaires cachées.",
            ["TextMapId"] = "UIGuide_TaskAcceptance",
            },
        ["UIGuide_Team_1"] = {
            ["ContentFR"] = "Vous pouvez inviter des amis à former une <H>équipe</> afin d’accomplir ensemble une mission.",
            ["TextMapId"] = "UIGuide_Team_1",
            },
        ["UIGuide_Team_2_PC"] = {
            ["ContentFR"] = "Les <H>informations d’équipe</> s’affichent en <H>bas à gauche</> des interfaces <H>Amis</>, <H>Missions</> et <H>Accueil</>.",
            ["TextMapId"] = "UIGuide_Team_2_PC",
            },
        ["UIGuide_Team_2_Phone"] = {
            ["ContentFR"] = "Les <H>informations d’équipe</> s’affichent en <H>haut à droite</> des interfaces <H>Amis</>, <H>Missions</> et <H>Accueil</>.",
            ["TextMapId"] = "UIGuide_Team_2_Phone",
            },
        ["UIGuide_Temple_1"] = {
            ["ContentFR"] = "En méditant à certains lieux enregistrés, vous pouvez accéder aux Épreuves de l’Oiseau onirique, débloquant une série de défis spéciaux.",
            ["TextMapId"] = "UIGuide_Temple_1",
            },
        ["UIGuide_Temple_2"] = {
            ["ContentFR"] = "Votre première réussite à une Épreuve vous octroie une récompense selon son niveau d’étoiles. Vous pouvez la retenter pour viser une meilleure note et des récompenses plus prestigieuses.",
