            },
        ["UIGuide_TongLv_1"] = {
            ["ContentFR"] = "Certains personnages possèdent une Arme de Consonance unique. Celle-ci évolue avec le niveau du personnage et ne peut être remplacée ni améliorée indépendamment, mais elle peut être équipée de Sceaux démoniaques.",
            ["TextMapId"] = "UIGuide_TongLv_1",
            },
        ["UIGuide_TrainingGround_1"] = {
            ["ContentFR"] = "La Méditation du Royaume des Sables vous permet d’affronter librement des ennemis déjà rencontrés, afin d’étudier leurs attaques et perfectionner vos compétences.",
            ["TextMapId"] = "UIGuide_TrainingGround_1",
            },
        ["UIGuide_TrainingGround_2"] = {
            ["ContentFR"] = "Dans le <H>Tourbillon de sable</>, vous trouverez des <H>Caisses de munitions</>, du <H>Sel volatil</>, du <H>Sel volatil concentré</> et d’autres fournitures de combat pour faciliter vos entraînements.",
            ["TextMapId"] = "UIGuide_TrainingGround_2",
            },
        ["UIGuide_TrainingGround_3_PC"] = {
            ["ContentFR"] = "Ouvrez <H>l’Arsenal</> en haut à <H>droite</> pour changer rapidement de personnage.",
            ["TextMapId"] = "UIGuide_TrainingGround_3_PC",
            },
        ["UIGuide_TrainingGround_3_Phone"] = {
            ["ContentFR"] = "Ouvrez <H>l’Arsenal</> en haut à <H>gauche</> pour changer rapidement de personnage.",
            ["TextMapId"] = "UIGuide_TrainingGround_3_Phone",
            },
        ["UIGuide_TrainingGround_4_PC"] = {
            ["ContentFR"] = "Dans la Méditation du Royaume des Sables, appuyer sur &OpenMenu& pour choisir <H>Quitter la Méditation</>.",
            ["TextMapId"] = "UIGuide_TrainingGround_4_PC",
            },
        ["UIGuide_TrainingGround_4_Phone"] = {
            ["ContentFR"] = "Ouvrez le <H>menu</> en haut à <H>gauche</> et sélectionnez <H>Quitter la Méditation</>.",
            ["TextMapId"] = "UIGuide_TrainingGround_4_Phone",
            },
        ["UIGuide_TrialRank_1"] = {
            ["ContentFR"] = "Gagner de l’EXP d’aventure en améliorant vos personnages, armes, Géniemon et Sceaux démoniaques, ou en accomplissant des missions, afin d’augmenter votre Niveau d’Aventure.",
            ["TextMapId"] = "UIGuide_TrialRank_1",
            },
        ["UIGuide_TrialRank_2"] = {
            ["ContentFR"] = "Atteindre un Niveau d’Aventure élevé octroie de précieuses récompenses et de puissants bonus.",
            ["TextMapId"] = "UIGuide_TrialRank_2",
            },
        ["UIGuide_TriggerEffect_1"] = {
            ["ContentFR"] = "Les <H>personnages</> possèdent un <H>attribut élémentaire</>.\
Il existe six éléments : <H>Hydro, Pyro, Anémo, Électro, Lumino et Umbro</>.\
Chaque élément applique un <H>Effet supplémentaire</> sous forme de <H>Dégâts sur la durée</> :\
\
Hydro : inflige des Dégâts Hydro sur la durée.\
Pyro : inflige des Dégâts Pyro sur la durée.\
Électro : inflige des Dégâts Électro sur la durée.\
Anémo : inflige des Dégâts Anémo sur la durée.\
Lumino : inflige des Dégâts Lumino sur la durée et <H>réinitialise</> la durée restante de tous les Effets supplémentaires élémentaires actifs.\
Umbro : inflige des Dégâts Umbro sur la durée et <H>ralentit</> la vitesse de récupération de posture de la cible.",
            ["TextMapId"] = "UIGuide_TriggerEffect_1",
            },
        ["UIGuide_TriggerEffect_2"] = {
            ["ContentFR"] = "Les <H>armes</> possèdent un <H>attribut physique</> : <H>Tranchant, Perforant ou Contondant</>.\
Chaque attribut confère un <H>Effet supplémentaire</> influant sur les dégâts ou la posture :\
\
Tranchant : augmente les dégâts infligés aux <H>Boucliers</>.\
Perforant : augmente les dégâts infligés aux <H>PV</>.\
Contondant : augmente <H>l’affaiblissement de la posture</> de l’ennemi.",
            ["TextMapId"] = "UIGuide_TriggerEffect_2",
            },
        ["UIGuide_TriggerEffect_3"] = {
            ["ContentFR"] = "En infligeant des dégâts avec une arme ou certaines compétences, vous pouvez déclencher un <H>Effet supplémentaire</> correspondant à l’attribut de dégâts.\
La probabilité dépend de la valeur de <H>Chance de déclenchement</> de l’arme.",
            ["TextMapId"] = "UIGuide_TriggerEffect_3",
            },
        ["UIGuide_TurnTable"] = {
            ["ContentFR"] = "Serrure magique standard. Allumez toutes les zones blanches avant la fin du temps imparti pour déverrouiller la porte.",
            ["TextMapId"] = "UIGuide_TurnTable",
            },
        ["UIGuide_ValveMechanism"] = {
            ["ContentFR"] = "Un mécanisme de serrure magique courant. Déplacez le curseur jusqu’à la position finale dans le temps imparti pour dissiper le sceau et déverrouiller la serrure.",
            ["TextMapId"] = "UIGuide_ValveMechanism",
            },
        ["UIGuide_WIKI_01"] = {
            ["ContentFR"] = "Lors des dialogues, si le bouton <H>Consulter l’entrée</> apparaît en bas à droite, appuyez dessus pour afficher les mots-clés et leurs explications.",
            ["TextMapId"] = "UIGuide_WIKI_01",
            },
        ["UIGuide_WIKI_02"] = {
            ["ContentFR"] = "Dans <H>Atlasium</>, vous pouvez consulter toutes les entrées déjà découvertes.",
            ["TextMapId"] = "UIGuide_WIKI_02",
            },
        ["UIGuide_WallJump_PC"] = {
            ["ContentFR"] = "Près d’un mur, appuyez <H>plusieurs fois</> sur &Jump& pour escalader.",
            ["TextMapId"] = "UIGuide_WallJump_PC",
            },
        ["UIGuide_WallJump_Phone"] = {
            ["ContentFR"] = "Près d’un mur, touchez <H>plusieurs fois</> le bouton pour grimper.",
            ["TextMapId"] = "UIGuide_WallJump_Phone",
            },
        ["UIGuide_WangXi_1"] = {
            ["ContentFR"] = "La Faille de l’Oubli érode continuellement tout être vivant qui y tombe. Tant que vous vous trouvez dans cet environnement, vos PV diminuent sans cesse.",
            ["TextMapId"] = "UIGuide_WangXi_1",
            },
        ["UIGuide_WangXi_2"] = {
            ["ContentFR"] = "La Faille de l’Oubli est parcourue par les eaux du Fleuve de l’Oubli. Entrer en contact avec ces eaux accélère considérablement la perte de PV.",
            ["TextMapId"] = "UIGuide_WangXi_2",
            },
        ["UIGuide_WangXi_3"] = {
            ["ContentFR"] = "Exploiter judicieusement les zones de refuge formées par les Fleurs-lanternes est la clé pour quitter la Faille de l’Oubli.",
            ["TextMapId"] = "UIGuide_WangXi_3",
            },
        ["UIGuide_WuYou_1"] = {
            ["ContentFR"] = "Vaincre un nombre déterminé d’ennemis permet d’accéder à des menaces majeures.",
            ["TextMapId"] = "UIGuide_WuYou_1",
            },
        ["UIGuide_WuYou_2"] = {
            ["ContentFR"] = "Vaincre des ennemis au cours du combat permet de renforcer les Wishen.",
            ["TextMapId"] = "UIGuide_WuYou_2",
            },
        ["UIGuide_WuYou_3"] = {
            ["ContentFR"] = "Terminer le niveau dans le temps imparti permet d’atteindre les objectifs de récompense.",
            ["TextMapId"] = "UIGuide_WuYou_3",
            },
        ["UIGuide_XiQiu_1"] = {
            ["ContentFR"] = "Utiliser la fonction Attraction du Nexus mécanique pour attirer les sphères de mécanisme vers leur socle correspondant et déverrouiller le dispositif.",
            ["TextMapId"] = "UIGuide_XiQiu_1",
            },
        ["UIGuide_XiaoChuan_1"] = {
            ["ContentFR"] = "Des <H>petites embarcations</> dérivent sur les eaux du Fleuve de l’Oubli. Lorsqu’elles sont allumées, elles génèrent autour d’elles une zone de refuge mobile, vous aidant à résister à l’érosion de la Faille. Vous pouvez vous déplacer dans cette zone et y récupérer des PV.",
            ["TextMapId"] = "UIGuide_XiaoChuan_1",
            },
        ["UIGuide_XingShi_1"] = {
            ["ContentFR"] = "Frapper la <H>Stèle de l’Éveil</> permet d’activer les mécanismes de la Formation des Mille-Serrures et d’en modifier la structure.",
            ["TextMapId"] = "UIGuide_XingShi_1",
            },
        ["UIGuide_YanShi_1"] = {
            ["ContentFR"] = "L’entrée de certaines cavernes est obstruée par des rochers.",
            ["TextMapId"] = "UIGuide_YanShi_1",
            },
        ["UIGuide_YanShi_2"] = {
            ["ContentFR"] = "Ces rochers peuvent être détruits à l’aide d’armes de mêlée ou à distance — les attaques de mêlée sont plus efficaces.",
            ["TextMapId"] = "UIGuide_YanShi_2",
            },
        ["UIGuide_ZhanFeng_1"] = {
            ["ContentFR"] = "Faire résonner le <H>Carillon des Vents</> : il répondra à votre vœu, éveillant des mécanismes dissimulés ou des souvenirs d’un autre temps.",
            ["TextMapId"] = "UIGuide_ZhanFeng_1",
            },
        ["UIGuide_ZhouYe_1"] = {
            ["ContentFR"] = "À Huaxu, vous pouvez ouvrir l’interface de <H>Gestion du temps</> afin de modifier l’heure actuelle.",
            ["TextMapId"] = "UIGuide_ZhouYe_1",
            },
        ["UIGuide_ZuoQi_1"] = {
            ["ContentFR"] = "Ouvrir l’interface des <H>Montures</> pour prévisualiser toutes les montures disponibles.",
            ["TextMapId"] = "UIGuide_ZuoQi_1",
            },
        ["UIGuide_ZuoQi_2"] = {
            ["ContentFR"] = "Augmenter le <H>Niveau de réputation</> de la région concernée permet d’obtenir des <H>Avantages de réputation</>. Une fois obtenus, ces avantages autorisent l’utilisation des montures volantes dans la région correspondante.",
            ["TextMapId"] = "UIGuide_ZuoQi_2",
            },
        ["UIGuide_ZuoQi_3"] = {
            ["ContentFR"] = "Avant de monter une monture, celle-ci doit être placée dans le Sac tactique.",
            ["TextMapId"] = "UIGuide_ZuoQi_3",
            },
        ["UIGuide_content_203001"] = {
            ["ContentFR"] = "En explorant le monde, vous rencontrerez parfois des <H>Géniemon</>. Offrez-leur des <H>friandises</> pour gagner leur confiance. Les Géniemon peuvent ensuite vous prêter main-forte au combat grâce au Soutien de Géniemon.",
            ["TextMapId"] = "UIGuide_content_203001",
            },
        }
  end },
