            },
        ["UI_COMMONPOP_TEXT_100051"] = {
            ["ContentFR"] = "Votre compte (UID : %d) a été suspendu jusqu’au %s pour comportement inapproprié.\
En cas de question, veuillez contacter le service client officiel.",
            ["TextMapId"] = "UI_COMMONPOP_TEXT_100051",
