            },
        ["UI_COMMONPOP_TEXT_100056"] = {
            ["ContentFR"] = "Impossible de modifier à nouveau après confirmation",
            ["TextMapId"] = "UI_COMMONPOP_TEXT_100056",
            },
        ["UI_COMMONPOP_TEXT_100057"] = {
            ["ContentFR"] = "<H>La date d’anniversaire ne peut être modifiée qu’une seule fois</>. Confirmez-vous le changement pour le <H>%s</> ?",
            ["TextMapId"] = "UI_COMMONPOP_TEXT_100057",
            },
        ["UI_COMMONPOP_TEXT_100058"] = {
            ["ContentFR"] = "Souhaitez-vous mettre fin à l’exploration et procéder au décompte des résultats ?",
