            },
        ["UI_COMMONPOP_TEXT_100058_2"] = {
            ["ContentFR"] = "Les récompenses et points seront calculés selon votre progression actuelle.",
            ["TextMapId"] = "UI_COMMONPOP_TEXT_100058_2",
            },
        ["UI_COMMONPOP_TEXT_100066"] = {
            ["ContentFR"] = "Cette arme est actuellement utilisée par un Emblème de combat. La vendre malgré tout ?",
