            },
        ["UI_COMMONPOP_TEXT_100077"] = {
            ["ContentFR"] = "Souhaitez-vous retirer ce joueur de votre liste d’amis ?",
            ["TextMapId"] = "UI_COMMONPOP_TEXT_100077",
            },
        ["UI_COMMONPOP_TEXT_100078"] = {
