        ["UI_HeadFrame_Des_10001"] = {
            ["ContentFR"] = "Un éclat de lumière saisi avant qu’il ne s’éteigne.",
            ["TextMapId"] = "UI_HeadFrame_Des_10001",
            },
        ["UI_HeadFrame_Des_10002"] = {
            ["ContentFR"] = "Forgée dans l’ardeur. Destinée à durer.",
            ["TextMapId"] = "UI_HeadFrame_Des_10002",
            },
        ["UI_HeadFrame_Des_10003"] = {
            ["ContentFR"] = "Une réponse portée à travers la nuit étoilée et les brumes du matin.",
            ["TextMapId"] = "UI_HeadFrame_Des_10003",
            },
        ["UI_HeadFrame_Des_10004"] = {
            ["ContentFR"] = "Dans ces épines de métal, la gravité rencontre l’élégance.",
            ["TextMapId"] = "UI_HeadFrame_Des_10004",
            },
        ["UI_HeadFrame_Des_10005"] = {
            ["ContentFR"] = "Derrière son voile de fumée... un fragment de divin.",
            ["TextMapId"] = "UI_HeadFrame_Des_10005",
            },
        ["UI_HeadFrame_Des_10006"] = {
            ["ContentFR"] = "Une réponse portée à travers la nuit étoilée et les brumes du matin.",
            ["TextMapId"] = "UI_HeadFrame_Des_10006",
            },
        ["UI_HeadFrame_Des_10007"] = {
            ["ContentFR"] = "Mon esprit — lucide, clairvoyant.",
            ["TextMapId"] = "UI_HeadFrame_Des_10007",
            },
        ["UI_HeadFrame_Des_10008"] = {
            ["ContentFR"] = "Je défends ce qui est juste. Même lorsque cela coûte.",
            ["TextMapId"] = "UI_HeadFrame_Des_10008",
            },
        ["UI_HeadFrame_Des_10009"] = {
            ["ContentFR"] = "Ils parlent de calcul. Je parle de clairvoyance.",
            ["TextMapId"] = "UI_HeadFrame_Des_10009",
            },
        ["UI_HeadFrame_Des_10010"] = {
            ["ContentFR"] = "J’entends leurs souffrances. Je tends la main.",
            ["TextMapId"] = "UI_HeadFrame_Des_10010",
            },
        ["UI_HeadFrame_Des_10011"] = {
            ["ContentFR"] = "Chut... vous pourriez effaroucher leur doux battement.",
            ["TextMapId"] = "UI_HeadFrame_Des_10011",
            },
        ["UI_HeadFrame_Des_10012"] = {
            ["ContentFR"] = "Chut... vous pourriez effaroucher leur doux battement.",
            ["TextMapId"] = "UI_HeadFrame_Des_10012",
            },
        ["UI_HeadFrame_Des_10013"] = {
            ["ContentFR"] = "Moi — libre, imprévisible, sans contour, sans carte.",
            ["TextMapId"] = "UI_HeadFrame_Des_10013",
            },
        ["UI_HeadFrame_Des_10014"] = {
            ["ContentFR"] = "Un ruban où se gravent les instants que nul retour ne ramènera.",
            ["TextMapId"] = "UI_HeadFrame_Des_10014",
            },
        ["UI_HeadFrame_Des_10015"] = {
            ["ContentFR"] = "Avancez doucement... les fleurs rouges nichées dans les ronces guettent.",
            ["TextMapId"] = "UI_HeadFrame_Des_10015",
            },
        ["UI_HeadFrame_Des_10016"] = {
            ["ContentFR"] = "Tracer, à l’encre de plume, les rêves et les espoirs.",
            ["TextMapId"] = "UI_HeadFrame_Des_10016",
            },
        ["UI_HeadFrame_Des_10017"] = {
            ["ContentFR"] = "Le départ s’amorce à l’instant où le crépuscule se fond dans la nuit.",
            ["TextMapId"] = "UI_HeadFrame_Des_10017",
            },
        ["UI_HeadFrame_Des_10018"] = {
            ["ContentFR"] = "La brise du soir effleure, les flots d’azur ondulent.",
            ["TextMapId"] = "UI_HeadFrame_Des_10018",
            },
        ["UI_HeadFrame_Des_10019"] = {
            ["ContentFR"] = "Un homme, une épée, un monde à parcourir.",
            ["TextMapId"] = "UI_HeadFrame_Des_10019",
            },
        ["UI_HeadFrame_Des_10020"] = {
            ["ContentFR"] = "Lire les augures et entrevoir l’avenir.",
            ["TextMapId"] = "UI_HeadFrame_Des_10020",
            },
        ["UI_HeadFrame_Des_10021"] = {
            ["ContentFR"] = "Comment dissiper la pluie sombre qui voile le cœur ?",
            ["TextMapId"] = "UI_HeadFrame_Des_10021",
            },
        ["UI_HeadFrame_Des_10022"] = {
            ["ContentFR"] = "Une brochette de douceurs cristallisées.",
            ["TextMapId"] = "UI_HeadFrame_Des_10022",
            },
        ["UI_HeadFrame_Des_10023"] = {
            ["ContentFR"] = "Du vent sous vos pas, la chance à vos côtés.",
            ["TextMapId"] = "UI_HeadFrame_Des_10023",
            },
