        ["UI_Skin_Des_0010"] = {
            ["ContentFR"] = "À la saison où le jour est le plus court, lorsque les clochettes résonnent, chacun confie ses vœux au ciel nocturne, les laissant s’envoler, portés par l’éclat des étoiles, vers l’avenir.",
            ["TextMapId"] = "UI_Skin_Des_0010",
            },
        ["UI_Skin_Des_0011"] = {
            ["ContentFR"] = "Une allure accomplie, où l’élégance se déploie d’elle-même.",
            ["TextMapId"] = "UI_Skin_Des_0011",
            },
        ["UI_Skin_Des_0121"] = {
            ["ContentFR"] = "Pourquoi, parmi tous ces bonshommes de neige, l’un d’eux paraît-il nettement plus imposant que les autres ?",
            ["TextMapId"] = "UI_Skin_Des_0121",
            },
        ["UI_Skin_Des_0122"] = {
            ["ContentFR"] = "Entre la sonnerie et les pages qui se tournent, les années s’éclipsent en silence.",
            ["TextMapId"] = "UI_Skin_Des_0122",
            },
        ["UI_Skin_Des_1101"] = {
            ["ContentFR"] = "Le noir est la couleur de la nuit : un voile paisible posé sur le monde. Le noir est la couleur de l’ombre : une présence fidèle près de ceux que l’on aime. C’est pour cela que Berenica l’affectionne tant.",
            ["TextMapId"] = "UI_Skin_Des_1101",
            },
        ["UI_Skin_Des_1103"] = {
            ["ContentFR"] = "Une ombre en mouvement. Un comédien maladroit sur scène. Une histoire que seul un fou raconterait.",
            ["TextMapId"] = "UI_Skin_Des_1103",
            },
        ["UI_Skin_Des_1104"] = {
            ["ContentFR"] = "Une tenue de haute couture, ostentatoire, faite sur mesure. Plus qu’un vêtement : une proclamation de statut.",
            ["TextMapId"] = "UI_Skin_Des_1104",
            },
        ["UI_Skin_Des_1501"] = {
            ["ContentFR"] = "Les inscriptions de l’Église Élysienne ne sont pas seulement brodées sur ses habits : elles sont gravées dans son âme. Elles témoignent de la jeune fille qui, maintes fois, a mué de rage en résilience.",
            ["TextMapId"] = "UI_Skin_Des_1501",
            },
        ["UI_Skin_Des_1502"] = {
            ["ContentFR"] = "Un voile tissé de crépuscule et d’aurore guide les âmes à travers le fleuve de larmes — vers la Mer du Silence, où toute vie renaît.",
            ["TextMapId"] = "UI_Skin_Des_1502",
            },
        ["UI_Skin_Des_1503"] = {
            ["ContentFR"] = "La pluie glisse le long de ses vêtements, s’accumule à la pointe de l’épée... puis disparaît dans les chemins du monde des sabres errants.",
            ["TextMapId"] = "UI_Skin_Des_1503",
            },
        ["UI_Skin_Des_1601"] = {
            ["ContentFR"] = "Un être, une lame, une robe immaculée. Traverser l’océan et la nuit glacée, pour enfin se retrouver à l’orée de l’aube.",
            ["TextMapId"] = "UI_Skin_Des_1601",
            },
        ["UI_Skin_Des_1801"] = {
            ["ContentFR"] = "Le rossignol a ajouté des plumes blanches à son histoire : de petites ailes qui portent ses rêves jusqu’aux nuages.",
            ["TextMapId"] = "UI_Skin_Des_1801",
            },
        ["UI_Skin_Des_2101"] = {
            ["ContentFR"] = "Les tentacules d’une méduse descendent dans l’abysse comme une traîne flottante, troublant le cœur de son amant.",
            ["TextMapId"] = "UI_Skin_Des_2101",
            },
        ["UI_Skin_Des_210102"] = {
            ["ContentFR"] = "Sous des voiles superposés, un murmure confesse l’amour — et un baiser mortel scelle l’éternité.",
            ["TextMapId"] = "UI_Skin_Des_210102",
            },
        ["UI_Skin_Des_2301"] = {
            ["ContentFR"] = "Qu’est-ce qui rampe dans l’obscurité ? Un complot ? Le chaos ? Un crime ? Non. Juste... des tentacules.",
            ["TextMapId"] = "UI_Skin_Des_2301",
            },
        ["UI_Skin_Des_2401"] = {
            ["ContentFR"] = "Des effluves d’herbes glissent entre ses manches immaculées, murmurant le retour du printemps aux herbes sèches.",
            ["TextMapId"] = "UI_Skin_Des_2401",
            },
        ["UI_Skin_Des_240101"] = {
            ["ContentFR"] = "Que les flots lavent la poussière, et que les vagues apaisent l’esprit.",
            ["TextMapId"] = "UI_Skin_Des_240101",
            },
        ["UI_Skin_Des_3101"] = {
            ["ContentFR"] = "La chaleur de la poudre persiste sur l’uniforme mat — attisée par le rythme d’un sang trop ardent.",
            ["TextMapId"] = "UI_Skin_Des_3101",
            },
        ["UI_Skin_Des_3103"] = {
            ["ContentFR"] = "Le rouge et le blanc en flammes emprisonnent les rêveries explosives d’un fou... et recousent le rêve immaculé d’un garçon.",
            ["TextMapId"] = "UI_Skin_Des_3103",
            },
        ["UI_Skin_Des_3201"] = {
            ["ContentFR"] = "Les chaînes et les ronces punissent le péché autant qu’elles contiennent la justice brûlante qui consume son cœur.",
            ["TextMapId"] = "UI_Skin_Des_3201",
            },
        ["UI_Skin_Des_3301"] = {
            ["ContentFR"] = "Un casque polyvalent forgé à partir d’une simple marmite — l’armure robuste d’une jeune récupératrice.",
            ["TextMapId"] = "UI_Skin_Des_3301",
            },
        ["UI_Skin_Des_4101"] = {
            ["ContentFR"] = "Les éclats bleutés qui dansent sur son uniforme sont une volonté de protéger — et un regard tourné vers l’avenir.",
            ["TextMapId"] = "UI_Skin_Des_4101",
            },
        ["UI_Skin_Des_4102"] = {
            ["ContentFR"] = "L’aube fait fondre les feuilles d’or et les répand sur le brocart, embrasant son regard d’or de l’éclat d’une révolution.",
            ["TextMapId"] = "UI_Skin_Des_4102",
            },
        ["UI_Skin_Des_410201"] = {
            ["ContentFR"] = "Dans l’entrelacs des coupes et des voix, s’écoulent des affrontements muets.",
            ["TextMapId"] = "UI_Skin_Des_410201",
            },
        ["UI_Skin_Des_4201"] = {
            ["ContentFR"] = "Le tonnerre divin circule en lui. En portant le jugement de Dafeng, le péché n’a nulle part où fuir... et lui non plus.",
            ["TextMapId"] = "UI_Skin_Des_4201",
            },
        }
  end },
  { MinKey = "UI_Skin_Des_4202", MaxKey = "UI_TELEPORTPOINT_NAME_104101_5", Loader = function()
      return {
        ["UI_Skin_Des_4202"] = {
            ["ContentFR"] = "Au-dessus : un esprit de génie, brillant dans l’éclat d’une médaille.\
