            ["TextMapId"] = "UI_Skin_Des_4202",
            },
        ["UI_Skin_Des_4301"] = {
            ["ContentFR"] = "Elle n’a ni armure ni couronne — et pourtant, sa seule présence fait gronder l’autorité.",
            ["TextMapId"] = "UI_Skin_Des_4301",
            },
        ["UI_Skin_Des_5101"] = {
            ["ContentFR"] = "Dansant au ras du sol, des plumes blanches diffusent un parfum de malt et de feu de foyer — s’envolant vers chaque ventre affamé.",
            ["TextMapId"] = "UI_Skin_Des_5101",
            },
        ["UI_Skin_Des_510101"] = {
