        ["UI_WALNUTDUNGEON_REFRESH_TOAST"] = {
            ["ContentFR"] = "Mission mise à jour. Veuillez quitter et relancer le défi.",
            ["TextMapId"] = "UI_WALNUTDUNGEON_REFRESH_TOAST",
            },
        ["UI_WEAPON_DESC_10101"] = {
            ["ContentFR"] = "L’arme portée par Berenica. Une lame ornementée d’élégantes dorures, forgée dans un métal noir rare que l’on ne trouve nulle part ailleurs. À l’évidence, ce n’est pas une arme que les habitants de l’Île du Purgatoire pourraient posséder.",
            ["TextMapId"] = "UI_WEAPON_DESC_10101",
            },
        ["UI_WEAPON_DESC_10102"] = {
            ["ContentFR"] = "Puisse une ivresse sans fin combler chaque vide laissé par ta solitude.",
            ["TextMapId"] = "UI_WEAPON_DESC_10102",
            },
        ["UI_WEAPON_DESC_10103"] = {
            ["ContentFR"] = "Une épée d’origine inconnue, présente à tes côtés depuis aussi longtemps que tu t’en souviennes. Peut-être qu’un jour, elle deviendra la clé qui reliera le passé au présent.",
            ["TextMapId"] = "UI_WEAPON_DESC_10103",
            },
        ["UI_WEAPON_DESC_10104"] = {
            ["ContentFR"] = "La meilleure défense reste l’attaque... mais n’oublie jamais qu’un repos suffisant en est aussi la clef.",
            ["TextMapId"] = "UI_WEAPON_DESC_10104",
            },
        ["UI_WEAPON_DESC_10105"] = {
            ["ContentFR"] = "Je marcherai à tes côtés, vers des horizons lointains, bien au-delà des sables mouvants.",
            ["TextMapId"] = "UI_WEAPON_DESC_10105",
            },
        ["UI_WEAPON_DESC_10198"] = {
            ["ContentFR"] = "Forgée selon les procédés les plus récents de traitement de surface, cette épée est l’arme de prédilection des chevaliers, dont la loyauté n’a d’égale que la discipline.",
            ["TextMapId"] = "UI_WEAPON_DESC_10198",
            },
        ["UI_WEAPON_DESC_10199"] = {
            ["ContentFR"] = "Une épée ordinaire, forgée dans un métal bon marché. Même si elle venait à se briser, nul n’en éprouverait le moindre regret.",
            ["TextMapId"] = "UI_WEAPON_DESC_10199",
            },
        ["UI_WEAPON_DESC_10201"] = {
            ["ContentFR"] = "Embrasse-moi... Embrasse-moi profondément, avant que ne vienne demain, avant que nos jeunes cœurs ne se fanent, avant que la mort ne nous sépare.",
            ["TextMapId"] = "UI_WEAPON_DESC_10201",
            },
        ["UI_WEAPON_DESC_10202"] = {
            ["ContentFR"] = "Une arme d’hast rapportée par les Tisse-Étoiles depuis leur terre natale, Huaxu. Sa lame s’inspire du saule, plante emblématique de leur patrie, symbole du « foyer ». Même s’ils tissent les cieux d’Atlasia de leurs constellations, un jour, ils retourneront vers cette contrée verdoyante et paisible.",
            ["TextMapId"] = "UI_WEAPON_DESC_10202",
            },
        ["UI_WEAPON_DESC_10203"] = {
            ["ContentFR"] = "Le froid mord, le soleil brûle, et les années consument la vie des mortels.",
            ["TextMapId"] = "UI_WEAPON_DESC_10203",
            },
        ["UI_WEAPON_DESC_10204"] = {
            ["ContentFR"] = "J’ai enfoui une graine dans la terre gelée, dans l’espoir d’une lune des moissons qui peut-être ne viendra jamais.",
            ["TextMapId"] = "UI_WEAPON_DESC_10204",
            },
        ["UI_WEAPON_DESC_10205"] = {
            ["ContentFR"] = "Faux brandie par les chevaliers de l’Ordre Sacré de l’Iris, sous l’égide de l’Église Élyséenne.\
« Sainteté suprême ! Voici la lumière de la miséricorde divine, qui brise l’aveuglement des insensés et éclaire les cœurs égarés. »",
            ["TextMapId"] = "UI_WEAPON_DESC_10205",
            },
        ["UI_WEAPON_DESC_10206"] = {
            ["ContentFR"] = "Arme prisée des chasseurs d’Atlasia.\
Même face à un Souillé, un seul coup bien porté suffit à abattre la proie.",
            ["TextMapId"] = "UI_WEAPON_DESC_10206",
            },
        ["UI_WEAPON_DESC_10207"] = {
            ["ContentFR"] = "Dans son cristal bleu repose la fureur des océans.\
Les supplications des ennemis y deviennent dissonance — étouffées avant même de troubler la symphonie de ce royaume.",
            ["TextMapId"] = "UI_WEAPON_DESC_10207",
            },
        ["UI_WEAPON_DESC_10208"] = {
            ["ContentFR"] = "Colombe immaculée qui vole pour défendre la dignité, elle jure de consacrer chaque plume à la voûte céleste appelée Avenir.",
            ["TextMapId"] = "UI_WEAPON_DESC_10208",
            },
        ["UI_WEAPON_DESC_10209"] = {
            ["ContentFR"] = "Sa lame sanglante vise le cœur sans détour.\
Tant que la lave brûlante n’a pas figé, il vous reste un instant — un seul — pour fuir votre destin.",
            ["TextMapId"] = "UI_WEAPON_DESC_10209",
            },
        ["UI_WEAPON_DESC_10298"] = {
            ["ContentFR"] = "Fruit des dernières techniques d’affinage, cette lance accompagne les gardes les plus fiables — ceux qui tiennent la ligne sans jamais vaciller.",
            ["TextMapId"] = "UI_WEAPON_DESC_10298",
            },
        ["UI_WEAPON_DESC_10299"] = {
            ["ContentFR"] = "Une lance ordinaire, forgée dans un métal bon marché. Même si elle venait à se briser, nul n’en éprouverait le moindre regret.",
            ["TextMapId"] = "UI_WEAPON_DESC_10299",
            },
        ["UI_WEAPON_DESC_10301"] = {
            ["ContentFR"] = "Brûle... brûle... brûle ! Ce feu purificateur consumera tout le mal de ce monde.",
            ["TextMapId"] = "UI_WEAPON_DESC_10301",
            },
        ["UI_WEAPON_DESC_10302"] = {
            ["ContentFR"] = "Nulle loi ne naît sans force — et seule une puissance inégalée peut en écrire le fer.",
            ["TextMapId"] = "UI_WEAPON_DESC_10302",
            },
        ["UI_WEAPON_DESC_10303"] = {
            ["ContentFR"] = "Une lame immaculée, qui fend l’air d’un gémissement muet — avide, éternellement, d’être rougie d’écarlate.",
            ["TextMapId"] = "UI_WEAPON_DESC_10303",
            },
        ["UI_WEAPON_DESC_10304"] = {
            ["ContentFR"] = "Tranche l’écho des âges révolus, et ouvre la voie à des siècles de paix.",
            ["TextMapId"] = "UI_WEAPON_DESC_10304",
            },
        ["UI_WEAPON_DESC_10305"] = {
            ["ContentFR"] = "Soudain, une note limpide traverse les nuages ; la lune emplit mille passes, la neige recouvre la robe.",
            ["TextMapId"] = "UI_WEAPON_DESC_10305",
            },
        ["UI_WEAPON_DESC_10398"] = {
            ["ContentFR"] = "Traitée avec les procédés les plus modernes, cette épée lourde est l’outil silencieux des serviteurs qui obéissent sans question.",
            ["TextMapId"] = "UI_WEAPON_DESC_10398",
            },
        ["UI_WEAPON_DESC_10399"] = {
            ["ContentFR"] = "Un espadon ordinaire, forgé dans un métal bon marché. Même s’il venait à se briser, nul n’en éprouverait le moindre regret.",
            ["TextMapId"] = "UI_WEAPON_DESC_10399",
            },
        ["UI_WEAPON_DESC_10401"] = {
            ["ContentFR"] = "Un loup solitaire n’a pour tout héritage que ses crocs. Devant lui, le dédale du destin ; sous ses pas, les cendres de sa patrie.",
            ["TextMapId"] = "UI_WEAPON_DESC_10401",
            },
        ["UI_WEAPON_DESC_10402"] = {
            ["ContentFR"] = "Lorsque les vagues d’encre montèrent, son maître leva ces lames d’or vers le ciel — ultime offrande à un dieu silencieux, qui jamais ne répondit.",
            ["TextMapId"] = "UI_WEAPON_DESC_10402",
            },
        ["UI_WEAPON_DESC_10403"] = {
            ["ContentFR"] = "En cet instant, vous êtes le chasseur des abysses — tapis dans les profondeurs, prêt à frapper.",
            ["TextMapId"] = "UI_WEAPON_DESC_10403",
            },
        ["UI_WEAPON_DESC_10404"] = {
            ["ContentFR"] = "Les flots déchaînés fendent le givre obscur ; lorsque les vents s’élèvent, une lueur glaciale jaillit.",
            ["TextMapId"] = "UI_WEAPON_DESC_10404",
            },
        ["UI_WEAPON_DESC_10498"] = {
            ["ContentFR"] = "Affûtées grâce aux plus récentes techniques de traitement, ces deux lames sont le choix des assassins errants — ceux qui ne laissent derrière eux qu’un silence trop lourd.",
            ["TextMapId"] = "UI_WEAPON_DESC_10498",
            },
        ["UI_WEAPON_DESC_10499"] = {
            ["ContentFR"] = "Taillées selon les procédés modernes, ces katanas sont prisés de ceux qui parcourent la route en solitaire.",
            ["TextMapId"] = "UI_WEAPON_DESC_10499",
            },
        }
  end },
  { MinKey = "UI_WEAPON_DESC_10501", MaxKey = "UI_WalkSwtich_Off_Toast", Loader = function()
      return {
        ["UI_WEAPON_DESC_10501"] = {
            ["ContentFR"] = "Un vieux rêve tourné vers l’avenir.",
            ["TextMapId"] = "UI_WEAPON_DESC_10501",
            },
        ["UI_WEAPON_DESC_10502"] = {
            ["ContentFR"] = "Le ciel prend en pitié chaque brin d’herbe ; une pluie de grâce vient soulager tout ce qui vit.",
            ["TextMapId"] = "UI_WEAPON_DESC_10502",
            },
        ["UI_WEAPON_DESC_10503"] = {
            ["ContentFR"] = "Les liens entre humains ne naissent pas tous du cœur : cette épée-fouet, faite pour s’enrouler et s’entremêler, touche parfois plus profond que les mots — ou la confiance.",
            ["TextMapId"] = "UI_WEAPON_DESC_10503",
            },
        ["UI_WEAPON_DESC_10504"] = {
            ["ContentFR"] = "Sur le rivage gisent des restes de corail flétri, où se sont figés les fragments des rêves brisés de l’océan d’azur.",
            ["TextMapId"] = "UI_WEAPON_DESC_10504",
            },
        ["UI_WEAPON_DESC_10598"] = {
            ["ContentFR"] = "Forgée d’après les techniques les plus récentes, cette épée-fouet est l’arme favorite de ceux qui se complaisent dans le carnage.",
            ["TextMapId"] = "UI_WEAPON_DESC_10598",
            },
        ["UI_WEAPON_DESC_10599"] = {
            ["ContentFR"] = "Une épée-fouet ordinaire, forgée dans un métal bon marché. Même si elle venait à se briser, nul n’en éprouverait le moindre regret.",
            ["TextMapId"] = "UI_WEAPON_DESC_10599",
            },
        ["UI_WEAPON_DESC_10601"] = {
            ["ContentFR"] = "Arme atypique rendue célèbre par la tragédie <I>Momiji : Récits du soulèvement.</> On raconte que la tache carmin sur la garde serait le sang d’un roi — frappé par la main même qui avait juré de le protéger.",
            ["TextMapId"] = "UI_WEAPON_DESC_10601",
            },
        ["UI_WEAPON_DESC_10602"] = {
            ["ContentFR"] = "Dans les yeux du mourant, on voit flotter une fleur de cerisier écarlate — légère, silencieuse... définitive.",
            ["TextMapId"] = "UI_WEAPON_DESC_10602",
            },
        ["UI_WEAPON_DESC_10603"] = {
            ["ContentFR"] = "Une inscription pâlie court le long de la garde : « Louange à l’Église Élyséenne ! Puissent les Neuf Dieux répandre leur grâce sur la terre pécheresse du duché de Yashnia ! »",
            ["TextMapId"] = "UI_WEAPON_DESC_10603",
            },
        ["UI_WEAPON_DESC_10698"] = {
            ["ContentFR"] = "Taillées selon les procédés modernes, ces katanas sont prisés de ceux qui parcourent la route en solitaire.",
            ["TextMapId"] = "UI_WEAPON_DESC_10698",
            },
        ["UI_WEAPON_DESC_10699"] = {
            ["ContentFR"] = "Un katana ordinaire, forgé dans un métal bon marché. Même s’il venait à se briser, nul n’en éprouverait le moindre regret.",
            ["TextMapId"] = "UI_WEAPON_DESC_10699",
            },
        ["UI_WEAPON_DESC_110101"] = {
            ["ContentFR"] = "« Zéro. » L’origine. Le commencement de toute chose.",
            ["TextMapId"] = "UI_WEAPON_DESC_110101",
            },
        ["UI_WEAPON_DESC_150101"] = {
            ["ContentFR"] = "« Et la Déesse s’adressa une fois encore au Septième Saint : \"Par cette épée, je scelle un pacte avec toi et ta lignée. Ceux qui posséderont une résilience inébranlable recevront ma bénédiction — et, avec elle, la protection de cette lame.\" »",
            ["TextMapId"] = "UI_WEAPON_DESC_150101",
            },
        ["UI_WEAPON_DESC_20101"] = {
            ["ContentFR"] = "Par la vérité, le monde se déconstruit — et tout ordre se dissout.",
            ["TextMapId"] = "UI_WEAPON_DESC_20101",
            },
        ["UI_WEAPON_DESC_20102"] = {
            ["ContentFR"] = "Arrachée à la spirale de morts empilées, voilà une erreur faite chair — une vérité qui n’aurait jamais dû naître.",
            ["TextMapId"] = "UI_WEAPON_DESC_20102",
            },
        ["UI_WEAPON_DESC_20103"] = {
            ["ContentFR"] = "Le fracas des oracles divins résonnera dans le crâne de chaque hérétique.",
            ["TextMapId"] = "UI_WEAPON_DESC_20103",
            },
        ["UI_WEAPON_DESC_20198"] = {
            ["ContentFR"] = "Un pistolet poli selon les techniques modernes — arme de prédilection de ceux qui chevauchent sous le ciel ouvert.",
            ["TextMapId"] = "UI_WEAPON_DESC_20198",
            },
        ["UI_WEAPON_DESC_20199"] = {
            ["ContentFR"] = "Un pistolet ordinaire, forgé dans le métal le plus basique. Même s’il venait à se briser, nul n’en éprouverait le moindre regret.",
            ["TextMapId"] = "UI_WEAPON_DESC_20199",
            },
        ["UI_WEAPON_DESC_20201"] = {
            ["ContentFR"] = "Dans la spirale où la mort s’amoncelle, chaque erreur enfante une autre — puis une autre encore.",
            ["TextMapId"] = "UI_WEAPON_DESC_20201",
            },
        ["UI_WEAPON_DESC_20203"] = {
            ["ContentFR"] = "L’immensité de l’océan pulse sans fin au rythme de la vie — foisonnante, vibrante, indomptable.",
            ["TextMapId"] = "UI_WEAPON_DESC_20203",
            },
        ["UI_WEAPON_DESC_20205"] = {
            ["ContentFR"] = "Le fracas des oracles divins résonnera dans le crâne de chaque hérétique.",
            ["TextMapId"] = "UI_WEAPON_DESC_20205",
            },
        ["UI_WEAPON_DESC_20296"] = {
            ["ContentFR"] = "Des armes raffinées par les techniques les plus récentes, prisées des palefreniers qui vivent sous l’immensité du ciel.",
            ["TextMapId"] = "UI_WEAPON_DESC_20296",
            },
        ["UI_WEAPON_DESC_20298"] = {
            ["ContentFR"] = "Une paire de pistolets ordinaires, forgée dans un métal bon marché. Même s’ils venaient à se briser, nul n’en éprouverait le moindre regret.",
            ["TextMapId"] = "UI_WEAPON_DESC_20298",
            },
        ["UI_WEAPON_DESC_20301"] = {
            ["ContentFR"] = "Que les pénitents cessent donc de lever les yeux vers la nuit : le firmament n’écoute pas, et les étoiles n’accordent l’absolution à personne.",
            ["TextMapId"] = "UI_WEAPON_DESC_20301",
            },
        ["UI_WEAPON_DESC_20302"] = {
            ["ContentFR"] = "La nuit, des souliers rouges, la rosée sur les pétales. Un souffle effleure les tempes, les détonations précipitées déchirent l’air, et la poudre se dissipe... Tout participe à ce festin extatique de projectiles.",
            ["TextMapId"] = "UI_WEAPON_DESC_20302",
            },
        ["UI_WEAPON_DESC_20303"] = {
            ["ContentFR"] = "La plus pure manière de retourner à la nature : se réduire en cendre, puis disparaître dans la poussière qui attend.",
            ["TextMapId"] = "UI_WEAPON_DESC_20303",
            },
        ["UI_WEAPON_DESC_20304"] = {
            ["ContentFR"] = "Le bronze trempe l’ossature des rouages ; au milieu des ronces du néant se forge l’âme des héros.",
            ["TextMapId"] = "UI_WEAPON_DESC_20304",
            },
        ["UI_WEAPON_DESC_20305"] = {
            ["ContentFR"] = "Montée sur mille douilles argentées, l’ardeur divine s’abat — gravant le décret des dieux dans la poitrine de chaque hérétique.",
            ["TextMapId"] = "UI_WEAPON_DESC_20305",
            },
        ["UI_WEAPON_DESC_20398"] = {
            ["ContentFR"] = "Arme traitée selon les standards les plus modernes, maniée par les assaillants intrépides qui réduisent les murailles au silence.",
            ["TextMapId"] = "UI_WEAPON_DESC_20398",
            },
        ["UI_WEAPON_DESC_20399"] = {
            ["ContentFR"] = "Un lance-grenades forgé selon les plus récentes techniques de fusion et de dorure. Recommandé par les maîtres-forgerons pour son excellent rapport qualité-prix, il est particulièrement prisé des voyageurs d’Atlasia.",
            ["TextMapId"] = "UI_WEAPON_DESC_20399",
            },
        ["UI_WEAPON_DESC_20401"] = {
            ["ContentFR"] = "Ce n’est qu’après la toute dernière plainte... que le monde retrouve enfin le silence.",
            ["TextMapId"] = "UI_WEAPON_DESC_20401",
            },
        ["UI_WEAPON_DESC_20402"] = {
            ["ContentFR"] = "Injecte des graines dans le corps... et laisse la destruction éclore de l’intérieur.",
            ["TextMapId"] = "UI_WEAPON_DESC_20402",
            },
        ["UI_WEAPON_DESC_20403"] = {
            ["ContentFR"] = "Arme portée par les chevaliers de l’Ordre Sacré de l’Iris, au sein de l’Église Élyséenne. Sainteté suprême ! Nous faisons serment de répandre la parole des Neuf jusqu’aux confins d’Atlasia.",
            ["TextMapId"] = "UI_WEAPON_DESC_20403",
            },
        ["UI_WEAPON_DESC_20405"] = {
            ["ContentFR"] = "— Hein ? Atlasia court à sa perte ? Bah. Tant qu’on peut faire tout sauter, ça me va.",
            ["TextMapId"] = "UI_WEAPON_DESC_20405",
            },
        ["UI_WEAPON_DESC_20406"] = {
            ["ContentFR"] = "Certains ennemis fuient devant les obus explosifs ; d’autres devant les dents d’acier d’un engrenage.",
            ["TextMapId"] = "UI_WEAPON_DESC_20406",
            },
        ["UI_WEAPON_DESC_20407"] = {
            ["ContentFR"] = "Ombre solitaire séparée du vol, elle fait tourner l’axe du destin ; au-delà des montagnes, une plume trace son sillage dans le ciel.",
            ["TextMapId"] = "UI_WEAPON_DESC_20407",
            },
        ["UI_WEAPON_DESC_20498"] = {
            ["ContentFR"] = "Raffiné par les techniques actuelles de surface : le compagnon fidèle des chasseurs aguerris.",
            ["TextMapId"] = "UI_WEAPON_DESC_20498",
            },
        ["UI_WEAPON_DESC_20499"] = {
            ["ContentFR"] = "Un fusil à pompe ordinaire, forgé dans le métal le plus basique. Même s’il venait à se briser, nul n’en éprouverait le moindre regret.",
            ["TextMapId"] = "UI_WEAPON_DESC_20499",
            },
        ["UI_WEAPON_DESC_20501"] = {
            ["ContentFR"] = "Quand la balle lacère la chair et brûle l’âme, jusqu’où peuvent tenir la bonté, l’honnêteté et le courage ?",
            ["TextMapId"] = "UI_WEAPON_DESC_20501",
            },
        ["UI_WEAPON_DESC_20502"] = {
            ["ContentFR"] = "Arme des Corvins des Déchus. Écoutez... voici la colère des bannis ! Voici la cloche funèbre qui résonne pour l’Empire !",
            ["TextMapId"] = "UI_WEAPON_DESC_20502",
            },
        ["UI_WEAPON_DESC_20503"] = {
            ["ContentFR"] = "Un lance-flammes manié par les chevaliers de l’Ordre Sacré de l’Iris. Sainteté suprême ! Ô feu sacré, descends sur nous ! En ton nom, nous jurons de réduire en cendres toute corruption.",
            ["TextMapId"] = "UI_WEAPON_DESC_20503",
            },
        ["UI_WEAPON_DESC_20504"] = {
            ["ContentFR"] = "Mitraillette utilisée par les chevaliers de l’Ordre Sacré de l’Iris, fidèles à l’Église Élyséenne.\
« Sainteté suprême ! Si nous pouvons contempler ne fût-ce qu’un éclat de l’aube, alors même couverts d’épines, nous la goûterons comme un baume céleste. »",
            ["TextMapId"] = "UI_WEAPON_DESC_20504",
            },
        ["UI_WEAPON_DESC_20505"] = {
            ["ContentFR"] = "La géométrie aux trois arêtes a reçu l’éloge de la déesse, prête à transformer l’art de la beauté en une acuité mortelle.",
            ["TextMapId"] = "UI_WEAPON_DESC_20505",
            },
        ["UI_WEAPON_DESC_20506"] = {
            ["ContentFR"] = "Les nuées s’écartent, laissant s’élancer deux paons en plein vol ; sur un tapis de brocart fleuri, une danseuse esquisse ses pas gracieux.",
            ["TextMapId"] = "UI_WEAPON_DESC_20506",
            },
        ["UI_WEAPON_DESC_20507"] = {
            ["ContentFR"] = "Le jeune marin, trop occupé à affaler la voile avant la tempête, n’a jamais compté les mots d’amour cachés sous les flots.\
Il ignorait que chaque chanson de sirène n’était qu’un murmure destiné à son cœur.",
            ["TextMapId"] = "UI_WEAPON_DESC_20507",
            },
        ["UI_WEAPON_DESC_20509"] = {
            ["ContentFR"] = "D’une plume immaculée, j’ai tissé une frêle cage et refermé, entre ses barreaux, la sauvagerie du monde.",
            ["TextMapId"] = "UI_WEAPON_DESC_20509",
            },
        ["UI_WEAPON_DESC_20510"] = {
            ["ContentFR"] = "En rêve, ma lame décroche la lune glacée qui se mire dans le fleuve ; sous l’éclair de son acier, un nouvel automne déjà s’éteint.",
            ["TextMapId"] = "UI_WEAPON_DESC_20510",
            },
        ["UI_WEAPON_DESC_20512"] = {
            ["ContentFR"] = "Une lueur ambrée vacille entre veille et ivresse, reflétant encore la tiédeur d’un foyer presque éteint.",
            ["TextMapId"] = "UI_WEAPON_DESC_20512",
            },
        ["UI_WEAPON_DESC_20598"] = {
            ["ContentFR"] = "Un fusil d’assaut façonné selon les procédés les plus récents, prisé des éclaireurs robustes qui ouvrent la voie.",
            ["TextMapId"] = "UI_WEAPON_DESC_20598",
            },
        ["UI_WEAPON_DESC_20599"] = {
            ["ContentFR"] = "Mitraillette façonnée selon les techniques récentes de forge et de dorure.\
Un modèle souvent recommandé par les artisans : solide, fiable et abordable — très prisé des voyageurs d’Atlasia.",
            ["TextMapId"] = "UI_WEAPON_DESC_20599",
            },
        ["UI_WEAPON_DESC_20601"] = {
            ["ContentFR"] = "Toi, âme solitaire — lorsque tu te tiens au cœur des flammes et choisis de n’être plus qu’un grain de sable livré au vent, commence alors ta renaissance... et la conquête de ton propre destin.",
            ["TextMapId"] = "UI_WEAPON_DESC_20601",
            },
        ["UI_WEAPON_DESC_20602"] = {
            ["ContentFR"] = "La corde vibre : la cible est à portée.\
Reste calme, mon ami — le destin de ton ennemi est déjà scellé.",
            ["TextMapId"] = "UI_WEAPON_DESC_20602",
            },
        ["UI_WEAPON_DESC_20603"] = {
            ["ContentFR"] = "Nul vivant ne sait ce qui repose au-delà de la Mer du Silence. Peut-être, dans ce chaos primordial, une fleur minuscule ose-t-elle encore éclore.",
            ["TextMapId"] = "UI_WEAPON_DESC_20603",
            },
        ["UI_WEAPON_DESC_20604"] = {
            ["ContentFR"] = "La vie et la mort s’entrelacent dans la flèche quittant la corde, faisant résonner une plainte capable de déchirer l’âme.",
            ["TextMapId"] = "UI_WEAPON_DESC_20604",
            },
        ["UI_WEAPON_DESC_20698"] = {
            ["ContentFR"] = "Traitée selon les techniques les plus modernes, cette arme silencieuse est celle des éclaireurs qui frappent sans jamais être vus.",
            ["TextMapId"] = "UI_WEAPON_DESC_20698",
            },
        ["UI_WEAPON_DESC_20699"] = {
            ["ContentFR"] = "Un arc ordinaire, forgé dans un métal bon marché. Même s’il venait à se briser, nul n’en éprouverait le moindre regret.",
            ["TextMapId"] = "UI_WEAPON_DESC_20699",
            },
        ["UI_WEAPON_DESC_310101"] = {
            ["ContentFR"] = "« Qu’est-ce que tu vois en moi ? Je n’ai rien à t’offrir. Depuis toujours, je n’ai jamais rien eu. »\
« Non, Lynn. Tu as quelque chose... Ce que je veux, c’est ton \"rêve\". »",
            ["TextMapId"] = "UI_WEAPON_DESC_310101",
            },
        ["UI_WEAPON_DESC_530101"] = {
            ["ContentFR"] = "Envole-toi, envole-toi... Même avec de fausses ailes, comme de frêles graines portées par la brise, survole les remparts, franchis les terres gelées, traverse la nuit sans fin... et élance-toi vers la lumière brûlante du jour, vers le soleil réconfortant.",
            ["TextMapId"] = "UI_WEAPON_DESC_530101",
            },
        ["UI_WEAPON_NAME_10101"] = {
