        ["UI_WeaponAccessory_Desc_10005"] = {
            ["ContentFR"] = "Un papillon qui renonce à son rêve de voler.",
            ["TextMapId"] = "UI_WeaponAccessory_Desc_10005",
            },
        ["UI_WeaponAccessory_Desc_10009"] = {
            ["ContentFR"] = "Une fleur née du brasier et de la fumée.",
            ["TextMapId"] = "UI_WeaponAccessory_Desc_10009",
            },
        ["UI_WeaponAccessory_Desc_10013"] = {
            ["ContentFR"] = "Une aile reniée par les dieux.",
            ["TextMapId"] = "UI_WeaponAccessory_Desc_10013",
            },
        ["UI_WeaponAccessory_Desc_10017"] = {
            ["ContentFR"] = "Héros du célèbre conte « <I>L’Étrange Aventure de Pioupiou</> », répandu sur tout le continent d’Atlasia. Chaque jour, le petit poussin s’éveille dans un lieu différent, rencontre de nouveaux compagnons et s’élance dans une odyssée singulière pour découvrir le sens de sa vie — et déjouer les complots des méchants.",
            ["TextMapId"] = "UI_WeaponAccessory_Desc_10017",
            },
        ["UI_WeaponAccessory_Desc_10021"] = {
            ["ContentFR"] = "Infusé de l’inspiration et de la fougue de Luno, la forgeronne, ce Cinder portatif évoque sans cesse la fournaise ardente qu’il attise de ses battements.",
            ["TextMapId"] = "UI_WeaponAccessory_Desc_10021",
            },
        ["UI_WeaponAccessory_Desc_10022"] = {
            ["ContentFR"] = "Les dragons fascinent chaque époque. Puissants, sauvages, insaisissables — leur rareté les drape d’une aura de mystère. C’est cette brume d’imaginaire qui nourrit la créativité des peuples depuis toujours.",
            ["TextMapId"] = "UI_WeaponAccessory_Desc_10022",
            },
        ["UI_WeaponAccessory_Desc_10023"] = {
            ["ContentFR"] = "Sous la coquille... encore une coquille. Et sous la coquille ? Toujours une coquille. Absolument pas une Luno. Vraiment pas.",
            ["TextMapId"] = "UI_WeaponAccessory_Desc_10023",
            },
        ["UI_WeaponAccessory_Desc_10024"] = {
            ["ContentFR"] = "Les étoiles de mer rêvent-elles de météores ?",
            ["TextMapId"] = "UI_WeaponAccessory_Desc_10024",
            },
        ["UI_WeaponAccessory_Desc_10027"] = {
            ["ContentFR"] = "Pourquoi ne pas demander à la conque chatoyante ?",
            ["TextMapId"] = "UI_WeaponAccessory_Desc_10027",
            },
        ["UI_WeaponAccessory_Desc_10030"] = {
            ["ContentFR"] = "Une pampille changée en rênes, capable d’entraver le divin.",
            ["TextMapId"] = "UI_WeaponAccessory_Desc_10030",
            },
        ["UI_WeaponAccessory_Desc_10033"] = {
            ["ContentFR"] = "Un dragon gravé sur un jade mystique.",
            ["TextMapId"] = "UI_WeaponAccessory_Desc_10033",
            },
