            ["TextMapId"] = "UI_WeaponCardLevel_Popup_UseGeneral",
            },
        ["UI_WeaponSkin_Des_3010101"] = {
            ["ContentFR"] = "Un vrai pêcheur ne rentre jamais bredouille. Par chance, le marché faisait des soldes aujourd’hui — quatre-vingts pièces la bête. Inutile de préciser d’où vient la prise.",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010101",
            },
        ["UI_WeaponSkin_Des_3010102"] = {
            ["ContentFR"] = "Juste avant leur collision, les étoiles s’échangèrent un dernier baiser.\
Leurs murmures brisés se muèrent en traînées de feu — souffle de deux amantes dérivant dans la voie lactée.",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010102",
            },
        ["UI_WeaponSkin_Des_3010104"] = {
            ["ContentFR"] = "Un espadon singulier, censé incarner l’autorité d’un père : ferme, formateur... et traumatisant juste ce qu’il faut.",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010104",
            },
        ["UI_WeaponSkin_Des_3010105"] = {
            ["ContentFR"] = "Miaou !",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010105",
            },
        ["UI_WeaponSkin_Des_3010106"] = {
            ["ContentFR"] = "Un véritable maître n’a pas besoin d’arme : un bambou brisé ou une branche desséchée suffisent à écrire une légende que nul ne peut arrêter.",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010106",
            },
        ["UI_WeaponSkin_Des_3010107"] = {
            ["ContentFR"] = "Fendre le ciel et la terre, et apaiser les huit horizons par un banquet.",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010107",
            },
        ["UI_WeaponSkin_Des_3010108"] = {
            ["ContentFR"] = "Une brochette de douceurs cristallisées.",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010108",
            },
        ["UI_WeaponSkin_Des_3010201"] = {
            ["ContentFR"] = "La Truite des glaces congelée : ferme, savoureuse... et impérissable. Même les conserves et le film alimentaire finiront avant elle — peut-être même avant votre bon sens.",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010201",
            },
        ["UI_WeaponSkin_Des_3010202"] = {
            ["ContentFR"] = "Une épée singulière, censée incarner l’autorité d’un père : ferme, formatrice... et traumatisante juste ce qu’il faut.",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010202",
            },
        ["UI_WeaponSkin_Des_3010203"] = {
            ["ContentFR"] = "Miaouuu~",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010203",
            },
        ["UI_WeaponSkin_Des_3010301"] = {
            ["ContentFR"] = "Où se cache le soleil ? Là, regarde... il danse au creux de ma paume.",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010301",
            },
        ["UI_WeaponSkin_Des_3010302"] = {
            ["ContentFR"] = "Grrr-miaou !",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010302",
            },
        ["UI_WeaponSkin_Des_3010303"] = {
            ["ContentFR"] = "Miaouuu !",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010303",
            },
        ["UI_WeaponSkin_Des_3010401"] = {
            ["ContentFR"] = "Une note cristalline fend le silence, tire une jeune fille de son rêve d’été... et vient frôler les cordes sensibles de son cœur.",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010401",
            },
        ["UI_WeaponSkin_Des_3010402"] = {
            ["ContentFR"] = "Sous les pas de la danseuse, l’écume bondit. Le vent salé charrie tout un été, et le sommet de la vague se fige ici — éclatant, indompté.",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010402",
            },
        ["UI_WeaponSkin_Des_3010403"] = {
            ["ContentFR"] = "Une arme d’hast pour le moins singulière, censée incarner l’autorité d’un père : ferme, formatrice... et traumatisante juste ce qu’il faut.",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010403",
            },
        ["UI_WeaponSkin_Des_3010404"] = {
            ["ContentFR"] = "Miaaaou — !",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010404",
            },
        ["UI_WeaponSkin_Des_3010407"] = {
            ["ContentFR"] = "Indemne de la poussière du monde, elle fend les flots d’azur sans jamais faiblir.",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010407",
            },
        ["UI_WeaponSkin_Des_3010501"] = {
            ["ContentFR"] = "Quel mauvais dessein pourrait bien avoir un adorable petit requin ?",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010501",
            },
        ["UI_WeaponSkin_Des_3010502"] = {
            ["ContentFR"] = "Miaou ♪ miaou-miaou-miaou ♪ miaou-miaou ♪♪",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010502",
            },
        ["UI_WeaponSkin_Des_3010601"] = {
            ["ContentFR"] = "Une paire de lames singulières, censées incarner l’autorité d’un père : fermes, formatrices... et traumatisantes juste ce qu’il faut.",
            ["TextMapId"] = "UI_WeaponSkin_Des_3010601",
            },
        ["UI_WeaponSkin_Des_3010603"] = {
