        ["WuyoushengEvent_Pet604_SkillDesLv_4"] = {
            ["ContentFR"] = "Dégâts infligés par les invocations du Wishen +100 %",
            ["TextMapId"] = "WuyoushengEvent_Pet604_SkillDesLv_4",
            },
        ["Wuyousheng_Target_FinishLevel"] = {
            ["ContentFR"] = "Terminer le défi actuel",
            ["TextMapId"] = "Wuyousheng_Target_FinishLevel",
            },
        ["Wuyousheng_Target_LevelLimitTime"] = {
            ["ContentFR"] = "Terminer le défi en moins de %s s",
            ["TextMapId"] = "Wuyousheng_Target_LevelLimitTime",
            },
        ["Zero"] = {
            ["ContentFR"] = "0.0",
            ["TextMapId"] = "Zero",
            },
        ["ZhiLiuEntrustGrandRewardTips"] = {
            ["ContentFR"] = "Terminez toutes les missions pour recevoir votre récompense",
            ["TextMapId"] = "ZhiLiuEntrustGrandRewardTips",
            },
        ["ZhiLiuEntrustText01"] = {
            ["ContentFR"] = "Voici la liste des achats du jour. Pourriez-vous m’aider à rassembler tout cela ?",
            ["TextMapId"] = "ZhiLiuEntrustText01",
            },
        ["ZhiLiuEntrustText02"] = {
            ["ContentFR"] = "Il me faut des carapaces de Souillés. Pourriez-vous aller en chasser quelques-uns pour moi ?",
            ["TextMapId"] = "ZhiLiuEntrustText02",
            },
        ["ZhiLiuEntrust_Battle"] = {
            ["ContentFR"] = "Liste de chasse",
            ["TextMapId"] = "ZhiLiuEntrust_Battle",
            },
        ["ZhiLiuEntrust_GetGrandReward"] = {
            ["ContentFR"] = "Réclamer la récompense",
            ["TextMapId"] = "ZhiLiuEntrust_GetGrandReward",
            },
        ["ZhiLiuEntrust_GrandReward_Name"] = {
            ["ContentFR"] = "Coffret de Lumière de Jade",
            ["TextMapId"] = "ZhiLiuEntrust_GrandReward_Name",
            },
        ["ZhiLiuEntrust_Jump_Tips"] = {
            ["ContentFR"] = "Voulez-vous vous téléporter auprès de Zhiliu ?",
            ["TextMapId"] = "ZhiLiuEntrust_Jump_Tips",
            },
        ["ZhiLiuEntrust_Lock_PretextTasks"] = {
            ["ContentFR"] = "Se déverrouille après avoir terminé la mission du jour %s",
            ["TextMapId"] = "ZhiLiuEntrust_Lock_PretextTasks",
            },
        ["ZhiLiuEntrust_Lock_Time1"] = {
            ["ContentFR"] = "Déverrouillé dans {DD} j à {H} h",
            ["TextMapId"] = "ZhiLiuEntrust_Lock_Time1",
            },
        ["ZhiLiuEntrust_Lock_Time2"] = {
            ["ContentFR"] = "Déverrouillé dans {H} h {M} min",
            ["TextMapId"] = "ZhiLiuEntrust_Lock_Time2",
            },
        ["ZhiLiuEntrust_Objective"] = {
            ["ContentFR"] = "Objectif de la mission",
            ["TextMapId"] = "ZhiLiuEntrust_Objective",
            },
        ["ZhiLiuEntrust_Progress"] = {
            ["ContentFR"] = "Progression de la mission",
            ["TextMapId"] = "ZhiLiuEntrust_Progress",
            },
        ["ZhiLiuEntrust_Resource"] = {
            ["ContentFR"] = "Liste d’approvisionnement",
            ["TextMapId"] = "ZhiLiuEntrust_Resource",
            },
        ["voice_ch_char_Aote_vo_appear"] = {
            ["ContentFR"] = "C’est une mission assez compliquée. On s’y met ensemble ?",
            ["TextMapId"] = "voice_ch_char_Aote_vo_appear",
            },
        ["voice_ch_char_Aote_vo_battleidle"] = {
            ["ContentFR"] = "Frais de stock... transport... Combien ça a coûté ? Zut, j’ai perdu le fil. Je me sens perdu sans mon livre de comptes.",
            ["TextMapId"] = "voice_ch_char_Aote_vo_battleidle",
            },
        ["voice_ch_char_Aote_vo_battlestart"] = {
            ["ContentFR"] = "Finissons-en rapidement, j’ai une pile de corvées qui m’attend.",
            ["TextMapId"] = "voice_ch_char_Aote_vo_battlestart",
            },
        ["voice_ch_char_Aote_vo_be_hit_heavy_r01"] = {
            ["ContentFR"] = "Je viens juste de recoudre mes vêtements !",
            ["TextMapId"] = "voice_ch_char_Aote_vo_be_hit_heavy_r01",
            },
        ["voice_ch_char_Aote_vo_be_hit_heavy_r02"] = {
            ["ContentFR"] = "Oh !",
            ["TextMapId"] = "voice_ch_char_Aote_vo_be_hit_heavy_r02",
            },
        ["voice_ch_char_Aote_vo_birthday"] = {
            ["ContentFR"] = "Joyeux anniversaire ! Joyeux anniversaire ! Ah, tu sais, ça m’a juste fait penser... Notre première rencontre, c’était aussi autour d’un \"anniversaire\", un cadeau à chercher. Et aujourd’hui, après tout ce temps, on célèbre un autre \"anniversaire\" ensemble, toujours là, côte à côte. Qui l’aurait cru ? Le destin est vraiment plein de surprises, hein ?",
            ["TextMapId"] = "voice_ch_char_Aote_vo_birthday",
            },
        ["voice_ch_char_Aote_vo_companio_01"] = {
            ["ContentFR"] = "Qu’est-ce que tu fais là ? Tu vas bien ? T’as mangé ? Allez, repose-toi un peu. Et si t’as besoin de quoi que ce soit, demande-moi, d’accord ?",
            ["TextMapId"] = "voice_ch_char_Aote_vo_companio_01",
            },
        ["voice_ch_char_Aote_vo_companio_02_1"] = {
            ["ContentFR"] = "C’est toi, la fille proche de {nickname}, c’est ça ? J’ai entendu que t’étais pas en forme. Tu devrais t’asseoir un moment.",
            ["TextMapId"] = "voice_ch_char_Aote_vo_companio_02_1",
            },
        ["voice_ch_char_Aote_vo_companio_02_2"] = {
            ["ContentFR"] = "Si t’as faim, soif, ou besoin de quoi que ce soit, dis-le-moi. J’ai l’habitude de veiller sur les autres... Ma petite sœur est malade, alors tu sais, je gère. Et puis, une amie de {nickname}, c’est aussi une amie à moi.",
            ["TextMapId"] = "voice_ch_char_Aote_vo_companio_02_2",
            },
        ["voice_ch_char_Aote_vo_companio_03_1"] = {
            ["ContentFR"] = "Eh, Madame Camilla ? Vous ici ? Me dites pas que c’est encore une urgence... {nickname} est déjà sur les rotules. Donnez-nous au moins une pause.",
            ["TextMapId"] = "voice_ch_char_Aote_vo_companio_03_1",
            },
        ["voice_ch_char_Aote_vo_companio_03_2"] = {
            ["ContentFR"] = "Cela dit... si c’est bien payé, je veux bien écouter.",
            ["TextMapId"] = "voice_ch_char_Aote_vo_companio_03_2",
            },
        ["voice_ch_char_Aote_vo_companio_04"] = {
            ["ContentFR"] = "Tu te rappelles de moi, quand j’étais petit ? T’étais à la fois une sœur douce et un père sévère... Non, je dis pas que t’es vieille et brutale, hein, juste... merci de m’avoir donné un vrai foyer.",
            ["TextMapId"] = "voice_ch_char_Aote_vo_companio_04",
            },
        ["voice_ch_char_Aote_vo_die_r01"] = {
            ["ContentFR"] = "tousse... Même les meilleurs trébuchent un jour...",
            ["TextMapId"] = "voice_ch_char_Aote_vo_die_r01",
            },
        ["voice_ch_char_Aote_vo_die_r02"] = {
            ["ContentFR"] = "Fina... prends soin d’elle... s’il te plaît.",
            ["TextMapId"] = "voice_ch_char_Aote_vo_die_r02",
            },
        ["voice_ch_char_Aote_vo_fail"] = {
            ["ContentFR"] = "Tss, battez en retraite, je vous rejoins juste après.",
            ["TextMapId"] = "voice_ch_char_Aote_vo_fail",
            },
        ["voice_ch_char_Aote_vo_gain"] = {
            ["ContentFR"] = "On se connaît déjà, tu veux vraiment que je me présente ? Bon, très bien... Je suis l’Étranger, des Vagabonds de la Nuit. Mon rôle ? Disons... la nounou attitrée de cette bande de gosses.",
            ["TextMapId"] = "voice_ch_char_Aote_vo_gain",
            },
        ["voice_ch_char_Aote_vo_idle"] = {
            ["ContentFR"] = "Cette tranquillité, ça fait drôle... j’aurais jamais cru pouvoir me sentir à ma place, même après tout ce temps.",
            ["TextMapId"] = "voice_ch_char_Aote_vo_idle",
            },
        ["voice_ch_char_Aote_vo_lvup"] = {
            ["ContentFR"] = "T’embête pas trop pour moi, je suis pas à l’aise avec ça... Bon, laisse tomber.",
            ["TextMapId"] = "voice_ch_char_Aote_vo_lvup",
            },
        ["voice_ch_char_Aote_vo_revive"] = {
            ["ContentFR"] = "Des cicatrices, j’en ai à revendre. Ça, c’est rien.",
            ["TextMapId"] = "voice_ch_char_Aote_vo_revive",
            },
        ["voice_ch_char_Aote_vo_skill01_r01"] = {
            ["ContentFR"] = "Des petites combines qui font la différence.",
            ["TextMapId"] = "voice_ch_char_Aote_vo_skill01_r01",
            },
        ["voice_ch_char_Aote_vo_skill01_r02"] = {
            ["ContentFR"] = "Ouvrez grand les yeux !",
            ["TextMapId"] = "voice_ch_char_Aote_vo_skill01_r02",
            },
        ["voice_ch_char_Aote_vo_skill02_r01"] = {
            ["ContentFR"] = "Résistez pas, c’est pour votre bien.",
            ["TextMapId"] = "voice_ch_char_Aote_vo_skill02_r01",
            },
        ["voice_ch_char_Aote_vo_skill02_r02"] = {
            ["ContentFR"] = "Assez joué, on passe aux choses sérieuses.",
            ["TextMapId"] = "voice_ch_char_Aote_vo_skill02_r02",
            },
        ["voice_ch_char_Aote_vo_skill02_r03"] = {
            ["ContentFR"] = "Admirez ce monde une dernière fois.",
            ["TextMapId"] = "voice_ch_char_Aote_vo_skill02_r03",
            },
        ["voice_ch_char_Aote_vo_topic_01_1"] = {
            ["ContentFR"] = "Un guide ? N’y compte pas. Ici, on se fait pas aux bouquins, mais aux bonnes combines. Comme ma devise : « Deux coups dans les côtes, un à la tête, même l’empereur peut pas y faire grand-chose. »",
            ["TextMapId"] = "voice_ch_char_Aote_vo_topic_01_1",
            },
        ["voice_ch_char_Aote_vo_topic_01_2"] = {
            ["ContentFR"] = "Ne sois pas trop gourmand. Le plus grand danger dans ce boulot, c’est la cupidité. Parfois elle vient des autres, mais surtout de toi-même.",
            ["TextMapId"] = "voice_ch_char_Aote_vo_topic_01_2",
            },
        ["voice_ch_char_Aote_vo_topic_02_1"] = {
            ["ContentFR"] = "Ce sont des braises qui refusent de s’éteindre. Suffit d’un souffle pour que tout reprenne feu. Crois-moi, mieux vaut les éviter.",
            ["TextMapId"] = "voice_ch_char_Aote_vo_topic_02_1",
            },
        ["voice_ch_char_Aote_vo_topic_02_2"] = {
            ["ContentFR"] = "Disons... qu’on a eu quelques accrochages. Si jamais tu les croises, surtout, dis pas que tu me connais.",
            ["TextMapId"] = "voice_ch_char_Aote_vo_topic_02_2",
            },
        ["voice_ch_char_Aote_vo_topic_03_1"] = {
            ["ContentFR"] = "Ouais. Tu peux me passer ce bandage là-bas ? Si Fina le voit, elle va encore faire toute une histoire.",
            ["TextMapId"] = "voice_ch_char_Aote_vo_topic_03_1",
            },
        ["voice_ch_char_Aote_vo_topic_03_2"] = {
            ["ContentFR"] = "Je sais, mais les blessures font partie du métier. Je préfère qu’elle ne s’inquiète pas trop. Tu peux me couvrir si elle me pose des questions ? Je te revaudrai ça.",
            ["TextMapId"] = "voice_ch_char_Aote_vo_topic_03_2",
            },
        ["voice_ch_char_Aote_vo_topic_04_1"] = {
            ["ContentFR"] = "Oh, tu veux tester ? Ils sont moches mais une fois la tête enlevée, ça croustille comme un biscuit... avec un petit arrière-goût de viande.",
            ["TextMapId"] = "voice_ch_char_Aote_vo_topic_04_1",
            },
        ["voice_ch_char_Aote_vo_topic_04_2"] = {
            ["ContentFR"] = "Hé ! Reviens ! C’est des conseils de survie... Si tu te perds dans la nature sans nourriture, ces petites bêtes pourraient te sauver la vie.",
            ["TextMapId"] = "voice_ch_char_Aote_vo_topic_04_2",
            },
        ["voice_ch_char_Aote_vo_topic_05_1"] = {
            ["ContentFR"] = "Attends... Pourquoi t’as presque rien ? Me dis pas que t’as encore filé ta paie aux autres ?",
            ["TextMapId"] = "voice_ch_char_Aote_vo_topic_05_1",
            },
        ["voice_ch_char_Aote_vo_topic_05_2"] = {
            ["ContentFR"] = "Mais... Peu importe, c’est tout toi, toujours {性别:prêt|prête} à aider les autres. Fais-moi signe si jamais tu as besoin d'argent.",
            ["TextMapId"] = "voice_ch_char_Aote_vo_topic_05_2",
            },
        ["voice_ch_char_Aote_vo_topic_05_3"] = {
            ["ContentFR"] = "... Je t’aide en tant qu’ami, pas pour que tu m’arnaques !",
            ["TextMapId"] = "voice_ch_char_Aote_vo_topic_05_3",
            },
        ["voice_ch_char_Aote_vo_victory"] = {
            ["ContentFR"] = "Je m’occupe de nettoyer. Il y a peut-être deux trois trucs bons à récupérer.",
            ["TextMapId"] = "voice_ch_char_Aote_vo_victory",
            },
        ["voice_ch_char_Aote_vo_welcome"] = {
            ["ContentFR"] = "Ah, te voilà enfin. J’ai fini tous les trucs en retard... Pas gagné un rond, et j’ai bien failli y laisser ma peau. Franchement... t’as de la chance que je vous aime bien.",
            ["TextMapId"] = "voice_ch_char_Aote_vo_welcome",
            },
        ["voice_ch_char_Baiheng01_vo_appear"] = {
            ["ContentFR"] = "J’ai préparé un bouillon revigorant. Bois-en avant de te baigner, pour ne pas attraper froid.",
            ["TextMapId"] = "voice_ch_char_Baiheng01_vo_appear",
            },
        ["voice_ch_char_Baiheng01_vo_battlestart"] = {
            ["ContentFR"] = "Un jour de repos si rare... ne laissons pas ces futilités ternir notre plaisir.",
            ["TextMapId"] = "voice_ch_char_Baiheng01_vo_battlestart",
            },
        ["voice_ch_char_Baiheng01_vo_gain"] = {
            ["ContentFR"] = "Quand j’étais petite, ma sœur devait littéralement me traîner hors de la maison pour que je joue dans la mer avec la famille... Si elle me voyait maintenant, t’invitant à flâner au bord de l’eau, elle serait sûrement silencieusement fière.",
            ["TextMapId"] = "voice_ch_char_Baiheng01_vo_gain",
            },
        ["voice_ch_char_Baiheng01_vo_skill02_r01"] = {
            ["ContentFR"] = "Que ce flot pur et limpide emporte toute souillure.",
            ["TextMapId"] = "voice_ch_char_Baiheng01_vo_skill02_r01",
            },
        ["voice_ch_char_Baiheng_vo_appear"] = {
            ["ContentFR"] = "Le danger guette. Je vais emporter davantage de remèdes.",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_appear",
            },
        ["voice_ch_char_Baiheng_vo_battleidle"] = {
            ["ContentFR"] = "Je perçois des appels à l'aide au loin... Il faut y aller sans tarder.",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_battleidle",
            },
        ["voice_ch_char_Baiheng_vo_battlestart"] = {
            ["ContentFR"] = "La mort est mon adversaire. Je ne la laisserai pas gagner.",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_battlestart",
            },
        ["voice_ch_char_Baiheng_vo_be_hit_heavy_r01"] = {
            ["ContentFR"] = "Impuretés...",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_be_hit_heavy_r01",
            },
        ["voice_ch_char_Baiheng_vo_be_hit_r02"] = {
            ["ContentFR"] = "Mes vêtements sont tâchés...",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_be_hit_r02",
            },
        ["voice_ch_char_Baiheng_vo_birthday"] = {
            ["ContentFR"] = "Aujourd’hui est un jour spécial pour toi. En l’honneur de cette journée, je t’ai préparé un modeste cadeau : une collection de remèdes à base de plantes pour soulager les petits maux que l’on peut rencontrer en voyage. Que ce soit un rhume, une égratignure ou une contusion, ces remèdes te seront très utiles. Cependant, j’espère sincèrement que tu resteras en bonne santé et en sécurité et que tu n’auras jamais besoin de les utiliser.",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_birthday",
            },
        ["voice_ch_char_Baiheng_vo_companio_01"] = {
            ["ContentFR"] = "Monsieur Randy, à mon humble avis, la léthargie et le laxisme ne sont pas moins des symptômes de maladie. Ils ne vous dérangent peut-être pas pour l'instant, mais ils sèment les graines de futurs maux. Peut-être pourrions-nous faire un peu d’entraînement physique ? Un peu d'exercice pourrait vous faire du bien.",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_companio_01",
            },
        ["voice_ch_char_Baiheng_vo_companio_02"] = {
            ["ContentFR"] = "Si un guérisseur peut soulager la souffrance, défier le destin est au-delà de nos capacités. Je peux vous offrir un remède pour apaiser la chaleur de votre cœur, mais la cause profonde de vos problèmes échappe à mon contrôle. Il vaut mieux accepter et s’adapter au cours du temps pour trouver votre propre chemin vers le réconfort...",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_companio_02",
            },
        ["voice_ch_char_Baiheng_vo_companio_03"] = {
            ["ContentFR"] = "Vous entendez souvent une autre voix qui vous parle ? Les autres l’entendent-ils aussi ? Comment se passe votre sommeil ? Quelque chose vous pèse-t-il sur le cœur ? Les afflictions de l’esprit sont les plus difficiles à guérir, même avec l’aide des techniques Zhuyou. Mais en tant que guérisseuse, je ne ménagerai aucun effort.",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_companio_03",
            },
        ["voice_ch_char_Baiheng_vo_die_r01"] = {
            ["ContentFR"] = "Protège... les autres... s’il te plaît...",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_die_r01",
            },
        ["voice_ch_char_Baiheng_vo_die_r02"] = {
            ["ContentFR"] = "Si seulement... j’avais été une meilleure guérisseuse...",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_die_r02",
            },
        ["voice_ch_char_Baiheng_vo_fail"] = {
            ["ContentFR"] = "Prends ceci pour soulager la douleur... ne perds pas courage.",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_fail",
            },
        ["voice_ch_char_Baiheng_vo_gain_1"] = {
            ["ContentFR"] = "La route est longue et pleine d’incertitudes... Puisque nos chemins se croisent par le destin, accompagnons-nous un temps, le temps du voyage.",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_gain_1",
            },
        ["voice_ch_char_Baiheng_vo_gain_2"] = {
            ["ContentFR"] = "Je suis Fushu, guérisseuse de Huaxu. Si tu es blessé ou malade, ne me cache rien. Mes compétences sont limitées, mais je ferai tout pour te protéger.",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_gain_2",
            },
        ["voice_ch_char_Baiheng_vo_idle"] = {
            ["ContentFR"] = "Aérer le matin après avoir nettoyé, vaporiser de l’alcool fort à midi, brûler de l’encens au crépuscule, il n’y a pas mieux pour assainir une pièce.",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_idle",
            },
        ["voice_ch_char_Baiheng_vo_lvup"] = {
            ["ContentFR"] = "Une hygiène de vie rigoureuse est un devoir pour tout guérisseur.",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_lvup",
            },
        ["voice_ch_char_Baiheng_vo_revive"] = {
            ["ContentFR"] = "Comme les fleurs, je m’épanouis à nouveau.",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_revive",
            },
        ["voice_ch_char_Baiheng_vo_skill01_r01"] = {
            ["ContentFR"] = "Laisse-moi dissiper ce mal !",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_skill01_r01",
            },
        ["voice_ch_char_Baiheng_vo_skill01_r02"] = {
            ["ContentFR"] = "Douleur, disparais !",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_skill01_r02",
            },
        ["voice_ch_char_Baiheng_vo_skill02_r01"] = {
            ["ContentFR"] = "Dans le silence, tout renaît.",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_skill02_r01",
            },
        ["voice_ch_char_Baiheng_vo_skill02_r02"] = {
            ["ContentFR"] = "Telle la lune éternelle.",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_skill02_r02",
            },
        ["voice_ch_char_Baiheng_vo_skill02_r03"] = {
            ["ContentFR"] = "Respirez profondément le parfum de la guérison.",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_skill02_r03",
            },
        ["voice_ch_char_Baiheng_vo_topic_01_1"] = {
            ["ContentFR"] = "En effet. Cependant, le contenu est dense et cryptique, et même les distinctions entre certains remèdes me semblent difficiles à saisir. Peut-être ne suis-je pas faite pour cette discipline.",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_topic_01_1",
            },
        ["voice_ch_char_Baiheng_vo_topic_01_2"] = {
            ["ContentFR"] = "À mon époque, la médecine n’était pas centrée sur les remèdes, on pratiquait un art miraculeux appelé \"Zhuyou\" pour chasser la maladie.",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_topic_01_2",
            },
        ["voice_ch_char_Baiheng_vo_topic_01_3"] = {
            ["ContentFR"] = "Mais cet art, bien qu’apportant guérison et paix, exigeait un prix, le sacrifice même de la force vitale du guérisseur. Aucun d’entre nous ne vivait jusqu’à un âge avancé, puiser dans notre essence jusqu’à la mort était la seule voie que nous connaissions.",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_topic_01_3",
            },
        ["voice_ch_char_Baiheng_vo_topic_01_4"] = {
            ["ContentFR"] = "Le Pavillon de l’Éphémère n’est aujourd’hui plus qu’un souvenir, mais la vocation de guérir ne s’éteint jamais. Il y aura toujours ceux qui porteront cette mission jusqu’au bout, avec une détermination inébranlable.",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_topic_01_4",
            },
        ["voice_ch_char_Baiheng_vo_topic_02_1"] = {
            ["ContentFR"] = "La mort est semblable à une lampe qui s’éteint : toutes les traces s’effacent, toutes les voix se taisent. Cet isolement, ce silence profond, engloutit toute lueur d’espoir et toute possibilité. Si cela était en mon pouvoir, je ne laisserais aucun patient sombrer dans un tel néant.",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_topic_02_1",
            },
        ["voice_ch_char_Baiheng_vo_topic_02_2"] = {
            ["ContentFR"] = "En effet, j’ai autrefois frôlé la mort, terrassée par une grave maladie. Si une telle épreuve devait se représenter, je ne saurais dire avec certitude si je referais le même choix.",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_topic_02_2",
            },
        ["voice_ch_char_Baiheng_vo_topic_03_1"] = {
            ["ContentFR"] = "Un endroit pour soigner et sauver des vies.",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_topic_03_1",
            },
        ["voice_ch_char_Baiheng_vo_topic_03_2"] = {
            ["ContentFR"] = "Sa mission est unique : guérir. Chaque médecin plante un abricotier en commençant sa formation. Cependant, au fil du temps, les intempéries ont emporté beaucoup d'entre eux. Aujourd’hui, il en reste moins de la moitié.",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_topic_03_2",
            },
        ["voice_ch_char_Baiheng_vo_topic_03_3"] = {
            ["ContentFR"] = "Après un long sommeil, je me suis éveillée et suis partie à la recherche de l’abricotier que j’avais planté dans ma jeunesse. Hélas, il n’était plus qu’un bois desséché. Même ce printemps si doux n’a su lui faire renaître le moindre bourgeon.",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_topic_03_3",
            },
        ["voice_ch_char_Baiheng_vo_topic_03_4"] = {
            ["ContentFR"] = "La vie s’écoule en un éclair, un cheval lancé au galop dans un défilé étroit, une étincelle jaillie d’un silex, une ombre qui erre dans un rêve. Comment retrouver sa route au cœur d’une existence si fugace ? Le passé s’éloigne un peu plus chaque jour, et les espoirs de réparer ce qui fut s’effacent comme la brume aux premières lueurs du matin.",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_topic_03_4",
            },
        ["voice_ch_char_Baiheng_vo_topic_04_1"] = {
            ["ContentFR"] = "Je rêve d’un monde sans maladies incurables.",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_topic_04_1",
            },
        ["voice_ch_char_Baiheng_vo_topic_04_2"] = {
            ["ContentFR"] = "C’est peut-être utopique, mais même sans miracles, la vocation du guérisseur ne change pas. Dire ça alors que je peine à comprendre les ouvrages médicaux...",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_topic_04_2",
            },
        ["voice_ch_char_Baiheng_vo_topic_04_3"] = {
            ["ContentFR"] = "Pourtant, je suivrai ce chemin, pour les gens, pour le Pavillon de l’Éphémère, et pour moi-même aussi.",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_topic_04_3",
            },
        ["voice_ch_char_Baiheng_vo_victory"] = {
            ["ContentFR"] = "Il me faudra changer de tenue en rentrant.",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_victory",
            },
        ["voice_ch_char_Baiheng_vo_welcome"] = {
            ["ContentFR"] = "L'environnement façonne l'esprit, et prendre soin de soi renforce le corps. Peut-être qu'une promenade sous ce ciel clément pourrait te faire du bien.",
            ["TextMapId"] = "voice_ch_char_Baiheng_vo_welcome",
            },
        ["voice_ch_char_Baonu_vo_appear"] = {
            ["ContentFR"] = "Samaël, en route !",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_appear",
            },
        ["voice_ch_char_Baonu_vo_battleidle"] = {
            ["ContentFR"] = "Montrez-vous ! Venez prendre votre raclée !",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_battleidle",
            },
        ["voice_ch_char_Baonu_vo_battlestart"] = {
            ["ContentFR"] = "Pardonner les péchés, c’est l’affaire des Dieux. Pas la mienne !",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_battlestart",
            },
        ["voice_ch_char_Baonu_vo_be_hit_heavy_r01"] = {
            ["ContentFR"] = "Ça manque cruellement de vertu !",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_be_hit_heavy_r01",
            },
        ["voice_ch_char_Baonu_vo_be_hit_heavy_r02"] = {
            ["ContentFR"] = "Samaël !",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_be_hit_heavy_r02",
            },
        ["voice_ch_char_Baonu_vo_birthday"] = {
            ["ContentFR"] = "Hum... hm. Seigneur Résilience venait justement de terminer une mission, passant par hasard devant une pâtisserie, qui par hasard offrait des gâteaux d’anniversaire,\
et est par hasard tombée sur toi, toi qui me donnes toujours du fil à retordre et que je dois protéger. Alors... toi... toi... mange ce gâteau à la framboise en trop. Tu dois tout finir. Pas une miette !",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_birthday",
            },
        ["voice_ch_char_Baonu_vo_companio_01"] = {
            ["ContentFR"] = "Samaël ? Il va très bien. Il me réveille le matin, m’encourage au combat... et le soir, il me raconte douze histoires avant de dormir. Inutile de t’en faire.",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_companio_01",
            },
        ["voice_ch_char_Baonu_vo_companio_02"] = {
            ["ContentFR"] = "« La Résilience est l’une des Sept Vertus... Celui qui la cultive peut voir ce que nul autre ne voit, accomplir ce que— ce que... »\
Aaaah ! J’en peux plus ! Espèce de nabot, si tu continues à m’imiter, je te jure par les Neuf Dieux d’Élysium que je te tranche en rondelles avec Samaël ! Et je le ferai vraiment !",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_companio_02",
            },
        ["voice_ch_char_Baonu_vo_companio_03"] = {
            ["ContentFR"] = "De la crème ? Et alors ? C’est comme ça que les Élyséens entretiennent leurs armes. Une objection ?",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_companio_03",
            },
        ["voice_ch_char_Baonu_vo_companio_04"] = {
            ["ContentFR"] = "Je ne t’ai jamais vu te mettre en colère... Très bien ! Moi, candidate aux Sept Vertus, je t’ordonne de te fâcher pour moi ! Sans réciter les préceptes, ni les doctrines, ni les volumes sacrés ! Vas-y... fais semblant. Mets-toi en colère !",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_companio_04",
            },
        ["voice_ch_char_Baonu_vo_die_r01"] = {
            ["ContentFR"] = "Je ne peux pas... souiller... le nom de Samaël...",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_die_r01",
            },
        ["voice_ch_char_Baonu_vo_die_r02"] = {
            ["ContentFR"] = "Je ne veux pas... aller seule à la rencontre des Dieux...",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_die_r02",
            },
        ["voice_ch_char_Baonu_vo_fail"] = {
            ["ContentFR"] = "Endurer, endurer, endurer... pas s’énerver, pas s’énerver...",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_fail",
            },
        ["voice_ch_char_Baonu_vo_gain"] = {
            ["ContentFR"] = "Hum... hm. Je suis Lisbell, de l’Église Élyséenne, candidate aux Sept Vertus, porteuse de la Résilience... enfin, candidate, voilà. Au nom de la Tour suprême, au nom des Neuf Dieux d’Élysium, et par... par... Ah, mince alors ! C’est trop compliqué ! Bref. Tu m’appelleras Seigneur Résilience. C’est compris ?",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_gain",
            },
        ["voice_ch_char_Baonu_vo_idle"] = {
            ["ContentFR"] = "Samaël, regarde ce soleil éclatant... Ce serait parfait pour manger quelque chose de frais, non ? On dit que la Capitale Élyséenne vend une douceur appelée glace. C’est de la nourriture de simples roturiers, mais sûrement bien meilleure que les plats de ces vieux grincheux... Je t’en achèterai en cachette !",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_idle",
            },
        ["voice_ch_char_Baonu_vo_lvup"] = {
            ["ContentFR"] = "Samaël, je suis encore plus forte maintenant. Allons protéger ces gens pénibles... ensemble.",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_lvup",
            },
        ["voice_ch_char_Baonu_vo_revive"] = {
            ["ContentFR"] = "Même Seigneur Résilience a ses limites !",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_revive",
            },
        ["voice_ch_char_Baonu_vo_skill01_r01"] = {
            ["ContentFR"] = "Sainteté suprême !",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_skill01_r01",
            },
        ["voice_ch_char_Baonu_vo_skill01_r02"] = {
            ["ContentFR"] = "Au nom de la Résilience !",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_skill01_r02",
            },
        ["voice_ch_char_Baonu_vo_skill02_r01"] = {
            ["ContentFR"] = "Je— n’en— peux— plus— !",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_skill02_r01",
            },
        ["voice_ch_char_Baonu_vo_skill02_r02"] = {
            ["ContentFR"] = "Samaël, réponds à mon appel !",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_skill02_r02",
            },
        ["voice_ch_char_Baonu_vo_skill02_r03"] = {
            ["ContentFR"] = "Samaël, accorde-moi ta « colère » !",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_skill02_r03",
            },
        ["voice_ch_char_Baonu_vo_topic_01_1"] = {
            ["ContentFR"] = "Samaël n’est pas une simple arme. C’est mon meilleur ami !",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_topic_01_1",
            },
        ["voice_ch_char_Baonu_vo_topic_01_2"] = {
            ["ContentFR"] = "À l’Église Élyséenne, seuls ceux choisis par l’un des Sept Reliquaires sacrés peuvent devenir une Vertu. Ce jour-là, il y avait des dizaines de guerriers surpuissants... mais moi seule ai pu dégainer Samaël. Puisqu’il m’a choisie, je lui dois tout mon respect !",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_topic_01_2",
            },
        ["voice_ch_char_Baonu_vo_topic_01_3"] = {
            ["ContentFR"] = "... Seulement voilà. Depuis ce jour, il ne répond plus à mes appels. H-Hé ! C’est un secret ! Tu n’as absolument pas le droit d’en parler !",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_topic_01_3",
            },
        ["voice_ch_char_Baonu_vo_topic_01_4"] = {
            ["ContentFR"] = "Hein ?! Il n’aime pas la glace ?! Alors... de la purée ? De la vinaigrette, peut-être ?",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_topic_01_4",
            },
        ["voice_ch_char_Baonu_vo_topic_02_1"] = {
            ["ContentFR"] = "Tais-toi ! Ne me parle pas de ces vieux rabat-joie ! Aaah... Tu m’as gâché ma bonne humeur... Non. Calme-toi, Lisbell. Je ne dois pas me mettre en colère...",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_topic_02_1",
            },
        ["voice_ch_char_Baonu_vo_topic_02_2"] = {
            ["ContentFR"] = "Hum hum. Pas du tout ! Les prêtres sont adorables, vraiment. Se tromper dans un hymne ? Trente copies suffisent. Donner de la glace à Samaël ? Deux jours de méditation face au mur. Je les adore. Vraiment. Absolument.",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_topic_02_2",
            },
        ["voice_ch_char_Baonu_vo_topic_03_1"] = {
            ["ContentFR"] = "C’est évident, non ? Être résilient, c’est rester ferme, endurer... et ne jamais se mettre en colère !",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_topic_03_1",
            },
        ["voice_ch_char_Baonu_vo_topic_03_2"] = {
            ["ContentFR"] = "Tu m’étonnes... À cause de ce titre, on m’enseigne sans cesse à étouffer ma colère par la patience. Mais c’est comme retenir un bâillement à mi-chemin, ou lever son épée pour frapper... et découvrir que l’ennemi est en fait un allié. Ça rend encore plus fur—",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_topic_03_2",
            },
        ["voice_ch_char_Baonu_vo_topic_03_3"] = {
            ["ContentFR"] = "Gnh... Ils disent que la colère est un péché grave. Je ne dois pas me mettre en colère. Je ne dois pas...",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_topic_03_3",
            },
        ["voice_ch_char_Baonu_vo_topic_03_4"] = {
            ["ContentFR"] = "Hé hé. Après tout, je suis Seigneur Résilience !",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_topic_03_4",
            },
        ["voice_ch_char_Baonu_vo_topic_04_1"] = {
            ["ContentFR"] = "Les Sept Vertus, ce sont les sept personnes les plus imposantes, nobles et puissantes d’Élysium ! Et, bien entendu, celles dont la vertu est la plus éclatante... Héhé.",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_topic_04_1",
            },
        ["voice_ch_char_Baonu_vo_topic_04_2"] = {
            ["ContentFR"] = "C’est quoi, cette tête ?! Quelle insolence ! Oser douter de moi ! Je te condamne à recopier les Préceptes trente— non, cent fois !",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_topic_04_2",
            },
        ["voice_ch_char_Baonu_vo_victory"] = {
            ["ContentFR"] = "Allez, dis-le : « Merci, Seigneur Résilience » !",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_victory",
            },
        ["voice_ch_char_Baonu_vo_welcome"] = {
            ["ContentFR"] = "Bonjour ! Je fais prendre l’air à Samaël. On respire, on s’imprègne du soleil et de l’atmosphère d’ici... Tu veux lui dire bonjour ? Ça lui ferait très plaisir. Oui. Enfin... probablement !",
            ["TextMapId"] = "voice_ch_char_Baonu_vo_welcome",
            },
        ["voice_ch_char_Dafu_vo_appear"] = {
            ["ContentFR"] = "Les fournitures d'urgence sont prêtes, je peux partir à tout moment.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_appear",
            },
        ["voice_ch_char_Dafu_vo_battleidle"] = {
            ["ContentFR"] = "Le cours de la bataille change vite, mais je fais confiance à votre jugement.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_battleidle",
            },
        ["voice_ch_char_Dafu_vo_battlestart"] = {
            ["ContentFR"] = "Cette fois encore, rentrons tous sains et saufs.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_battlestart",
            },
        ["voice_ch_char_Dafu_vo_be_hit_heavy_r01"] = {
            ["ContentFR"] = "Attention !",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_be_hit_heavy_r01",
            },
        ["voice_ch_char_Dafu_vo_be_hit_heavy_r02"] = {
            ["ContentFR"] = "Accroche-toi...",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_be_hit_heavy_r02",
            },
        ["voice_ch_char_Dafu_vo_birthday"] = {
            ["ContentFR"] = "Sais-tu ce qui rend ce jour si spécial ? Oui, c’est ton anniversaire.\
Je sais qu’en grandissant, la vie nous emporte dans mille directions. Toujours à courir après des objectifs, à jongler avec des responsabilités, à se précipiter d’un endroit à un autre.\
Ça peut paraître un peu enfantin, mais je crois sincèrement que les anniversaires devraient être différents. Juste pour une journée, on mérite de laisser tomber ces lourds fardeaux, de redevenir des enfants insouciants, baignés dans l’amour et les vœux chaleureux de ceux qui tiennent à nous.\
Alors aujourd’hui, mets tes soucis de côté. Sois ce petit enfant heureux : savoure le gâteau, souffle les bougies, fais un vœu...\
Et si tu es {性别:seul|seule} en ce moment, laisse-moi endosser le rôle de \"l’adulte\" pour toi.\
Joyeux anniversaire.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_birthday",
            },
        ["voice_ch_char_Dafu_vo_companio_01"] = {
            ["ContentFR"] = "J’ai lu un jour, à la bibliothèque de la capitale, des traités médicaux de Huaxu. Bien que leurs théories diffèrent de celles des traditions médicales d’Hyperborea, elles se sont avérées remarquablement efficaces pour le traitement. Il reste cependant des passages que je ne maîtrise pas complètement, pourriez-vous m’aider à les éclaircir ?",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_companio_01",
            },
        ["voice_ch_char_Dafu_vo_companio_02"] = {
            ["ContentFR"] = "Madame la geôlière, je me demande : une justice qui arrive tardivement mérite-t-elle encore d’être appelée justice ?",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_companio_02",
            },
        ["voice_ch_char_Dafu_vo_companio_03"] = {
            ["ContentFR"] = "Ça fait si longtemps. Depuis que j’ai quitté les Spathatoi, nous nous sommes à peine parlé. Comment... vas-tu ?",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_companio_03",
            },
        ["voice_ch_char_Dafu_vo_companio_04"] = {
            ["ContentFR"] = "Même si j’ai quitté les Spathatoi, c’est un lieu qui m’a profondément marquée. Je sais que demander pardon est peut-être trop, mais je tiens quand même à dire... je suis désolée.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_companio_04",
            },
        ["voice_ch_char_Dafu_vo_die_r01"] = {
            ["ContentFR"] = "Je suis infirmière... je ne peux pas...",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_die_r01",
            },
        ["voice_ch_char_Dafu_vo_die_r02"] = {
            ["ContentFR"] = "Ne vous arrêtez pas... avancez...",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_die_r02",
            },
        ["voice_ch_char_Dafu_vo_fail"] = {
            ["ContentFR"] = "Je couvre votre retraite.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_fail",
            },
        ["voice_ch_char_Dafu_vo_gain"] = {
            ["ContentFR"] = "Je suis Daphne Theodore, infirmière accompagnant les Griffons rattachée à la XIIIᵉ Légion d’Hyperborea. Le champ de bataille est périlleux, mais n’ayez crainte, je serai là pour vous porter secours.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_gain",
            },
        ["voice_ch_char_Dafu_vo_idle"] = {
            ["ContentFR"] = "Ces moments de calme sont rares, pas de blessés, ni de rapports urgents. Hmm... Je vais me faire un café et finir ce roman. Je me demande avec qui la princesse va finir ?",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_idle",
            },
        ["voice_ch_char_Dafu_vo_lvup"] = {
            ["ContentFR"] = "Avec cela, je pourrai soulager un peu plus leurs souffrances.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_lvup",
            },
        ["voice_ch_char_Dafu_vo_revive"] = {
            ["ContentFR"] = "Je l’ai promis, nous rentrerons tous sains et saufs.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_revive",
            },
        ["voice_ch_char_Dafu_vo_skill01_r01"] = {
            ["ContentFR"] = "Anesthésie et débridement prêts.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_skill01_r01",
            },
        ["voice_ch_char_Dafu_vo_skill01_r02"] = {
            ["ContentFR"] = "Choc hémorragique, garrot en place !",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_skill01_r02",
            },
        ["voice_ch_char_Dafu_vo_skill02_r01"] = {
            ["ContentFR"] = "Combien de temps encore les flammes de la guerre exigeront-elles notre sang ?",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_skill02_r01",
            },
        ["voice_ch_char_Dafu_vo_skill02_r02"] = {
            ["ContentFR"] = "La vie, dès sa conception, mérite le plus grand respect.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_skill02_r02",
            },
        ["voice_ch_char_Dafu_vo_skill02_r03"] = {
            ["ContentFR"] = "Pour la paix qui finira par venir.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_skill02_r03",
            },
        }
  end },
  { MinKey = "voice_ch_char_Dafu_vo_topic_01_1", MaxKey = "voice_ch_char_Landi_vo_skill02_r03", Loader = function()
      return {
        ["voice_ch_char_Dafu_vo_topic_01_1"] = {
            ["ContentFR"] = "Je... je ne pense pas avoir de loisirs particuliers. La lecture, peut-être, si ça compte.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_topic_01_1",
            },
        ["voice_ch_char_Dafu_vo_topic_01_2"] = {
            ["ContentFR"] = "Ma mère ne cesse de me dire que je reste enfermée chez moi, ratant les bals et les salons, ce qui me prive de bien des occasions d’avancer socialement...",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_topic_01_2",
            },
        ["voice_ch_char_Dafu_vo_topic_01_3"] = {
            ["ContentFR"] = "Mais je trouve que cela me convient bien ainsi.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_topic_01_3",
            },
        ["voice_ch_char_Dafu_vo_topic_01_4"] = {
            ["ContentFR"] = "Principalement des ouvrages sur les soins en champ de bataille : \"Stratégies d’intervention d’urgence\", \"Traumatologie pratique\", \"Montage d’un hôpital de campagne\"...",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_topic_01_4",
            },
        ["voice_ch_char_Dafu_vo_topic_01_5"] = {
            ["ContentFR"] = "Vous savez peut-être que mes études initiales ne portaient pas sur les soins, et malgré mes qualifications d’infirmière militaire, j’éprouve encore souvent un lourd sentiment d’impuissance.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_topic_01_5",
            },
        ["voice_ch_char_Dafu_vo_topic_01_6"] = {
            ["ContentFR"] = "Oui, je lis aussi un livre qui s’appelle \"Chaussure de verre\". C’est une histoire de... euh, princesse et chevalier... Ce n’est pas que j’aime particulièrement les romans d’amour, je l’ai juste feuilleté...",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_topic_01_6",
            },
        ["voice_ch_char_Dafu_vo_topic_02_1"] = {
            ["ContentFR"] = "Bien sûr ! C’est le fondement d’Hyperborea, ce que les érudits nomment « le miracle originel ».",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_topic_02_1",
            },
        ["voice_ch_char_Dafu_vo_topic_02_2"] = {
            ["ContentFR"] = "Au début, on cherchait à extraire de l’or du Phoxène. Puis on a découvert qu’elle pouvait aussi faire tourner les engrenages, produire des étincelles électriques... C’est la \"magie\" des Solariens.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_topic_02_2",
            },
        ["voice_ch_char_Dafu_vo_topic_02_3"] = {
            ["ContentFR"] = "... Mais ensuite, l’Académie d’Alchimie...",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_topic_02_3",
            },
        ["voice_ch_char_Dafu_vo_topic_02_4"] = {
            ["ContentFR"] = "... Oui, au Spathatoi. Mais ce chapitre de ma vie est désormais clos.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_topic_02_4",
            },
        ["voice_ch_char_Dafu_vo_topic_02_5"] = {
            ["ContentFR"] = "Parce que le Spathatoi, tel qu’il est devenu, a dévié de sa voie, empruntant un chemin erroné. Il est devenu le cœur ardent de la machine de guerre d’Hyperborea, mais son carburant, c’est la douleur et le malheur de trop de gens.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_topic_02_5",
            },
        ["voice_ch_char_Dafu_vo_topic_02_6"] = {
            ["ContentFR"] = "Je pense que je suis bien plus faible que je ne le croyais. Je n’ai pas pu me convaincre de l’accepter, et je n’avais ni le courage ni la force de le combattre. Alors, je n’ai eu d’autre choix que de m’en éloigner.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_topic_02_6",
            },
        ["voice_ch_char_Dafu_vo_topic_03_1"] = {
            ["ContentFR"] = "Des outils et des médicaments d’urgence : bandages, désinfectants, anesthésiques, ainsi que des scalpels et des fils pour les plaies.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_topic_03_1",
            },
        ["voice_ch_char_Dafu_vo_topic_03_2"] = {
            ["ContentFR"] = "J’ai aussi un mouchoir et un peigne.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_topic_03_2",
            },
        ["voice_ch_char_Dafu_vo_topic_03_3"] = {
            ["ContentFR"] = "Oh, ce n’est pas ce que tu crois... Ce n’est pas pour moi, c’est pour mes patients. Pour ceux que je ne peux pas sauver... Je les aide à garder un peu de dignité.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_topic_03_3",
            },
        ["voice_ch_char_Dafu_vo_topic_03_4"] = {
            ["ContentFR"] = "La souffrance est cruelle. Elle ne se contente pas de voler des vies, elle arrache aussi toute dignité à ceux qu’elle frappe.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_topic_03_4",
            },
        ["voice_ch_char_Dafu_vo_topic_03_5"] = {
            ["ContentFR"] = "J’aimerais juste... que leurs proches puissent les voir apaisés, propres, comme s’ils dormaient. Après une si longue séparation, aucun parent ne devrait revoir le visage de son enfant déformé par la douleur.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_topic_03_5",
            },
        ["voice_ch_char_Dafu_vo_topic_04_1"] = {
            ["ContentFR"] = "Oh, ça va ! Ce n’est pas si dur... Enfin, un peu quand même. Tout ce qui est soins et premiers secours, ça va encore. Mais les tests physiques... je dois avouer que c’est vraiment difficile pour moi.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_topic_04_1",
            },
        ["voice_ch_char_Dafu_vo_topic_04_2"] = {
            ["ContentFR"] = "Même en me levant plus tôt que tout le monde pour m’entraîner seule, je n’arrive qu’à peine à décrocher la moyenne... Ne vous moquez pas, d’accord ? Travailler son endurance, c’est bien plus difficile que de réviser ses cours !",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_topic_04_2",
            },
        ["voice_ch_char_Dafu_vo_topic_04_3"] = {
            ["ContentFR"] = "Oui, c’est vrai que c’est dur. Mais quand je détourne mon attention de mes jambes fatiguées, que je regarde les champs de blé en périphérie, les chaumières à l’horizon, que j’entends le bruit des moulins et le sifflement des bergers, tout s’apaise en moi.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_topic_04_3",
            },
        ["voice_ch_char_Dafu_vo_topic_04_4"] = {
            ["ContentFR"] = "Parce que... peut-être que courir sur ce chemin, c’est ma façon de protéger ces choses simples et ordinaires de disparaître.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_topic_04_4",
            },
        ["voice_ch_char_Dafu_vo_topic_05_1"] = {
            ["ContentFR"] = "La dernière fois que j’ai parlé à mon père, c’était au talkie-walkie, dans la Forteresse de Lonza. Malgré le danger, il m’a dit : « Ne t’inquiète pas. »",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_topic_05_1",
            },
        ["voice_ch_char_Dafu_vo_topic_05_2"] = {
            ["ContentFR"] = "Plus tard, je rallumais souvent mon talkie-walkie en pleine nuit, réglais sa fréquence, et appuyais sur le bouton d’appel, espérant entendre sa voix...",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_topic_05_2",
            },
        ["voice_ch_char_Dafu_vo_topic_05_3"] = {
            ["ContentFR"] = "Ce n’est qu’après être restée assise en silence pendant ce qui m’a paru une éternité que j’ai compris... qu’il ne reviendrait jamais.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_topic_05_3",
            },
        ["voice_ch_char_Dafu_vo_topic_05_4"] = {
            ["ContentFR"] = "Merci. Ne t’inquiète pas, je vais rester forte et continuer à avancer. Tant que je n’aurai pas lavé l’honneur de mon père et des victimes innocentes de la bataille de Lonza, je ne m’arrêterai pas.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_topic_05_4",
            },
        ["voice_ch_char_Dafu_vo_victory"] = {
            ["ContentFR"] = "Si seulement c’était la dernière bataille...",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_victory",
            },
        ["voice_ch_char_Dafu_vo_welcome"] = {
            ["ContentFR"] = "Je suis heureuse de vous voir sain et sauf aujourd’hui. Prenez bien soin de vous... en attendant ce jour où la paix règnera enfin.",
            ["TextMapId"] = "voice_ch_char_Dafu_vo_welcome",
            },
        ["voice_ch_char_Feina_vo_appear"] = {
            ["ContentFR"] = "Tu vas vraiment m’emmener jouer ? Promis juré, pas de retour en arrière !",
            ["TextMapId"] = "voice_ch_char_Feina_vo_appear",
            },
        ["voice_ch_char_Feina_vo_battleidle"] = {
            ["ContentFR"] = "Mais... où est passée tout le monde ?",
            ["TextMapId"] = "voice_ch_char_Feina_vo_battleidle",
            },
        ["voice_ch_char_Feina_vo_battlestart"] = {
            ["ContentFR"] = "Quel immense jardin !",
            ["TextMapId"] = "voice_ch_char_Feina_vo_battlestart",
            },
        ["voice_ch_char_Feina_vo_be_hit_heavy_r02"] = {
            ["ContentFR"] = "Je n’ai pas peur !",
            ["TextMapId"] = "voice_ch_char_Feina_vo_be_hit_heavy_r02",
            },
        ["voice_ch_char_Feina_vo_be_hit_r02"] = {
            ["ContentFR"] = "Ne me touchez pas !",
            ["TextMapId"] = "voice_ch_char_Feina_vo_be_hit_r02",
            },
        ["voice_ch_char_Feina_vo_birthday"] = {
            ["ContentFR"] = "Le jour de son anniversaire, {性别:Monsieur|Mademoiselle} Licorne blanche retrouva son petit foyer douillet. Un oiseau aux plumes neigeuses apporta des feuilles de laurier, le magicien chanta des sortilèges qui faisaient éclore les rires, et le preux chevalier resta fidèlement à ses côtés, comme autrefois. Dans la cheminée, les flammes dansaient de joie, tandis que les flocons portaient depuis le ciel de lointaines bénédictions. Le petit foyer, lui, débordait de bonheur...",
            ["TextMapId"] = "voice_ch_char_Feina_vo_birthday",
            },
        ["voice_ch_char_Feina_vo_companio_01"] = {
            ["ContentFR"] = "Promets-moi que tu n’iras jamais, jamais, jamais... dans cet endroit effrayant où il y a plein de mauvais sorciers, d’accord ?",
            ["TextMapId"] = "voice_ch_char_Feina_vo_companio_01",
            },
        ["voice_ch_char_Feina_vo_companio_02"] = {
            ["ContentFR"] = "Qu’est-ce que c’est ? Ton petit esprit, Mlle Hamster ? Incroyable... Il doit pouvoir te porter et t’emporter au-dessus des murailles de tous les châteaux !",
            ["TextMapId"] = "voice_ch_char_Feina_vo_companio_02",
            },
        ["voice_ch_char_Feina_vo_companio_03"] = {
            ["ContentFR"] = "Dis, Mlle Lionne, tu veux réveiller la fée qui dort dans cette épée géante ? Alors il te faudra sûrement chanter des tas de sortilèges, comme : « Ô toi qui as éveillé l’épée sacrée Samaël... un jour, tu deviendras le roi d’Élysium ! »",
            ["TextMapId"] = "voice_ch_char_Feina_vo_companio_03",
            },
        ["voice_ch_char_Feina_vo_companio_04"] = {
            ["ContentFR"] = "Monsieur Hippocampe originaire du royaume du sud, je crois t’avoir déjà vu quelque part... Hmm... Je me souviens ! Il y a bien longtemps, Papa avait accroché ton portrait au mur de notre maison.",
            ["TextMapId"] = "voice_ch_char_Feina_vo_companio_04",
            },
        ["voice_ch_char_Feina_vo_die_r01"] = {
            ["ContentFR"] = "Il est temps pour moi de partir pour ce pays lointain...",
            ["TextMapId"] = "voice_ch_char_Feina_vo_die_r01",
            },
        ["voice_ch_char_Feina_vo_die_r02"] = {
            ["ContentFR"] = "C’est comme si j’avais fait un très long rêve...",
            ["TextMapId"] = "voice_ch_char_Feina_vo_die_r02",
            },
        ["voice_ch_char_Feina_vo_fail"] = {
            ["ContentFR"] = "Je déteste cette fin...",
            ["TextMapId"] = "voice_ch_char_Feina_vo_fail",
            },
        ["voice_ch_char_Feina_vo_gain"] = {
            ["ContentFR"] = "« Piou piou ! » gazouilla le petit rossignol. Cela signifie : « Bonjour, {性别:Monsieur Licorne blanche ! À partir de maintenant, toi et Fina allez être de bons amis ! »|Mademoiselle Licorne blanche ! À partir de maintenant, toi et Fina allez être de bonnes amies ! »}",
            ["TextMapId"] = "voice_ch_char_Feina_vo_gain",
            },
        ["voice_ch_char_Feina_vo_idle"] = {
            ["ContentFR"] = "♪ Mon tout petit foyer... niché parmi les feuilles nouvelles, au creux d’un fleuve d’or... Le feu danse dans la cheminée, crépitant doucement... Je serre fort le soldat de plomb réparé par Papa, tandis que Maman me berce d’un chant... Dors maintenant...",
            ["TextMapId"] = "voice_ch_char_Feina_vo_idle",
            },
        ["voice_ch_char_Feina_vo_lvup"] = {
            ["ContentFR"] = "Ouah... !",
            ["TextMapId"] = "voice_ch_char_Feina_vo_lvup",
            },
        ["voice_ch_char_Feina_vo_revive"] = {
            ["ContentFR"] = "Hein... que s’est-il passé ?",
            ["TextMapId"] = "voice_ch_char_Feina_vo_revive",
            },
        ["voice_ch_char_Feina_vo_skill01_r01"] = {
            ["ContentFR"] = "♪ Étoiles brillantes dans la nuit...",
            ["TextMapId"] = "voice_ch_char_Feina_vo_skill01_r01",
            },
        ["voice_ch_char_Feina_vo_skill01_r02"] = {
            ["ContentFR"] = "♪ Mon plus beau jardin...",
            ["TextMapId"] = "voice_ch_char_Feina_vo_skill01_r02",
            },
        ["voice_ch_char_Feina_vo_skill02_r01"] = {
            ["ContentFR"] = "Mes amis, venez protéger tout le monde !",
            ["TextMapId"] = "voice_ch_char_Feina_vo_skill02_r01",
            },
        ["voice_ch_char_Feina_vo_skill02_r02"] = {
            ["ContentFR"] = "N’allez pas troubler la paix du jardin !",
            ["TextMapId"] = "voice_ch_char_Feina_vo_skill02_r02",
            },
        ["voice_ch_char_Feina_vo_skill02_r03"] = {
            ["ContentFR"] = "En avant, mes vaillants soldats !",
            ["TextMapId"] = "voice_ch_char_Feina_vo_skill02_r03",
            },
        ["voice_ch_char_Feina_vo_topic_01_1"] = {
            ["ContentFR"] = "Hmm, je me demandais... s’il existait un bonbon qui pourrait me faire énormément grandir...",
            ["TextMapId"] = "voice_ch_char_Feina_vo_topic_01_1",
            },
        ["voice_ch_char_Feina_vo_topic_01_2"] = {
            ["ContentFR"] = "Si grande que je pouvais voir au-dessus des nuages et même toucher les étoiles !",
            ["TextMapId"] = "voice_ch_char_Feina_vo_topic_01_2",
            },
        ["voice_ch_char_Feina_vo_topic_01_3"] = {
            ["ContentFR"] = "Ne t’inquiète pas, je ferai attention ! Et si tu as peur, tu peux te poser dans ma paume, et on ira faire un tour. Qu’en penses-tu ?",
            ["TextMapId"] = "voice_ch_char_Feina_vo_topic_01_3",
            },
        ["voice_ch_char_Feina_vo_topic_02_1"] = {
            ["ContentFR"] = "J’ai une grande boîte en verre remplie de neige fine provenant de l’extérieur de ma fenêtre et de guimauves aussi blanches que la neige. J’aimerais également y mettre des nuages aussi moelleux que ces guimauves, et des brises aussi chaudes que ces nuages...",
            ["TextMapId"] = "voice_ch_char_Feina_vo_topic_02_1",
            },
        ["voice_ch_char_Feina_vo_topic_02_2"] = {
            ["ContentFR"] = "Et vos rires aussi, tous sans exception, enfermés dans la boîte.",
            ["TextMapId"] = "voice_ch_char_Feina_vo_topic_02_2",
            },
        ["voice_ch_char_Feina_vo_topic_02_3"] = {
            ["ContentFR"] = "Eh bien... si tu croques un de ces bonbons qui te font tout petit, tu pourrais y entrer. Mais tout est blanc là-dedans, alors fais bien attention à ne pas te perdre.",
            ["TextMapId"] = "voice_ch_char_Feina_vo_topic_02_3",
            },
        ["voice_ch_char_Feina_vo_topic_02_4"] = {
            ["ContentFR"] = "Laisse-moi réfléchir... Si tu te perds, je casserai du pain en miettes, je ferai un chemin... Tu n’auras qu’à suivre les miettes pour retrouver la sortie !",
            ["TextMapId"] = "voice_ch_char_Feina_vo_topic_02_4",
            },
        ["voice_ch_char_Feina_vo_topic_03_1"] = {
            ["ContentFR"] = "Oui... ! J'ai rêvé d’un rossignol, pur comme la neige immaculée, qui se posait sur ma main un instant, puis jouait à cache-cache avec moi l’instant d’après... Hmm, est-ce moi qui ai rêvé, ou est-ce lui qui a rêvé de moi, je me le demande ?",
            ["TextMapId"] = "voice_ch_char_Feina_vo_topic_03_1",
            },
        ["voice_ch_char_Feina_vo_topic_03_2"] = {
            ["ContentFR"] = "Tu as raison ! C’est peut-être un pays magique où tous les enfants et les petites bêtes endormis peuvent jouer ensemble. Hmm... Qui vais-je rencontrer dans mon prochain rêve ? Grand-père Hibou, Mademoiselle Canari, ou Monsieur Lapin ?",
            ["TextMapId"] = "voice_ch_char_Feina_vo_topic_03_2",
            },
        ["voice_ch_char_Feina_vo_topic_04_1"] = {
            ["ContentFR"] = "J’avais une maman et deux papas. Mais ils ne sont plus là...",
            ["TextMapId"] = "voice_ch_char_Feina_vo_topic_04_1",
            },
        ["voice_ch_char_Feina_vo_topic_04_2"] = {
            ["ContentFR"] = "Le premier papa est parti dans un pays lointain avec maman. Et le deuxième... il est aussi dans ce pays lointain... C’est moi qui l’ai envoyé là-bas.",
            ["TextMapId"] = "voice_ch_char_Feina_vo_topic_04_2",
            },
        ["voice_ch_char_Feina_vo_topic_05_1"] = {
            ["ContentFR"] = "Il est le plus grand magicien, avec la voix la plus apaisante et l’âme la plus douce au monde...",
            ["TextMapId"] = "voice_ch_char_Feina_vo_topic_05_1",
            },
        ["voice_ch_char_Feina_vo_topic_05_2"] = {
            ["ContentFR"] = "Euh, qu’est-ce qui ne va pas ? Tu as l’air perplexe.",
            ["TextMapId"] = "voice_ch_char_Feina_vo_topic_05_2",
            },
        ["voice_ch_char_Feina_vo_topic_05_3"] = {
            ["ContentFR"] = "Hein... ? Il n’est pas gentil avec toi ? Je suis désolée... Je vais lui donner un petit coup sur la tête pour qu’il s’améliore !",
            ["TextMapId"] = "voice_ch_char_Feina_vo_topic_05_3",
            },
        ["voice_ch_char_Feina_vo_victory"] = {
            ["ContentFR"] = "« Et ils vécurent heureux jusqu’à la fin des temps. » Maintenant, dors bien. Fais de beaux rêves.",
            ["TextMapId"] = "voice_ch_char_Feina_vo_victory",
            },
        ["voice_ch_char_Feina_vo_welcome"] = {
            ["ContentFR"] = "Ah, c’est toi. Bonjour, comment vas-tu ?",
            ["TextMapId"] = "voice_ch_char_Feina_vo_welcome",
            },
        ["voice_ch_char_Haier_vo_appear"] = {
            ["ContentFR"] = "Où se terrent les criminels ?",
            ["TextMapId"] = "voice_ch_char_Haier_vo_appear",
            },
        ["voice_ch_char_Haier_vo_battleidle"] = {
            ["ContentFR"] = "Tu trembles ? Je pensais que tu valais mieux que les autres vermines. Décevant.",
            ["TextMapId"] = "voice_ch_char_Haier_vo_battleidle",
            },
        ["voice_ch_char_Haier_vo_battlestart"] = {
            ["ContentFR"] = "Tous les péchés seront purifiés par les flammes !",
            ["TextMapId"] = "voice_ch_char_Haier_vo_battlestart",
            },
        ["voice_ch_char_Haier_vo_be_hit_heavy_r01"] = {
            ["ContentFR"] = "Misérable !",
            ["TextMapId"] = "voice_ch_char_Haier_vo_be_hit_heavy_r01",
            },
        ["voice_ch_char_Haier_vo_be_hit_heavy_r02"] = {
            ["ContentFR"] = "Tiens bon !",
            ["TextMapId"] = "voice_ch_char_Haier_vo_be_hit_heavy_r02",
            },
        ["voice_ch_char_Haier_vo_birthday"] = {
            ["ContentFR"] = "Un anniversaire ? Ridicule ! Comme si une geôlière se souciait de telles futilités. Ah, recevoir des vœux te rend heureux, pauvre créature ? Très bien, joyeux anniversaire alors. Je vais faire une exception et boire avec toi, mais seulement aujourd’hui.",
            ["TextMapId"] = "voice_ch_char_Haier_vo_birthday",
            },
        ["voice_ch_char_Haier_vo_companio_01"] = {
            ["ContentFR"] = "Moi, geôlière. Vous, commandante de la Légion. Deux visages d’un même ordre implacable. Que l’on nous craigne ou nous haïsse, tant que l’Empire vit, cela n’a aucune importance.",
            ["TextMapId"] = "voice_ch_char_Haier_vo_companio_01",
            },
        ["voice_ch_char_Haier_vo_companio_02"] = {
            ["ContentFR"] = "Tiens, encore toi.",
            ["TextMapId"] = "voice_ch_char_Haier_vo_companio_02",
            },
        ["voice_ch_char_Haier_vo_companio_03"] = {
            ["ContentFR"] = "Tss, l’adjoint de Sibylle... Celui qu’on accuse sans cesse d’incompétence, pas vrai ? Je vois clair dans ton petit jeu : tu caches tes talents et ton ambition pour rester dans son ombre. Dis-moi, qu’est-ce que tu mijotes ?",
            ["TextMapId"] = "voice_ch_char_Haier_vo_companio_03",
            },
        ["voice_ch_char_Haier_vo_die_r01"] = {
            ["ContentFR"] = "Pour l’ordre impérial...",
            ["TextMapId"] = "voice_ch_char_Haier_vo_die_r01",
            },
        ["voice_ch_char_Haier_vo_die_r02"] = {
            ["ContentFR"] = "Je... ne crains... pas l’enfer...",
            ["TextMapId"] = "voice_ch_char_Haier_vo_die_r02",
            },
        ["voice_ch_char_Haier_vo_fail"] = {
            ["ContentFR"] = "Cette souillure, je la purgerai...",
            ["TextMapId"] = "voice_ch_char_Haier_vo_fail",
            },
        ["voice_ch_char_Haier_vo_gain"] = {
            ["ContentFR"] = "Tiens donc, {性别:le fugitif de l’Empire se présente de lui-même|la fugitive de l’Empire se présente d’elle-même}. Prépare-toi à brûler vif. Moi, Vulcera, je vais te montrer ce qu’est vraiment l’enfer !",
            ["TextMapId"] = "voice_ch_char_Haier_vo_gain",
            },
        ["voice_ch_char_Haier_vo_idle"] = {
            ["ContentFR"] = "Quelle sérénité... Tu ne crains donc pas mes flammes ? Hmpf, pauvre insecte. Tu regretteras ton ignorance quand je t’écraserai.",
            ["TextMapId"] = "voice_ch_char_Haier_vo_idle",
            },
        ["voice_ch_char_Haier_vo_lvup"] = {
            ["ContentFR"] = "Pas mal... Hmpf, mes flammes deviennent plus intenses.",
            ["TextMapId"] = "voice_ch_char_Haier_vo_lvup",
            },
        ["voice_ch_char_Haier_vo_revive"] = {
            ["ContentFR"] = "Les péchés du monde dépassent ceux de l’enfer !",
            ["TextMapId"] = "voice_ch_char_Haier_vo_revive",
            },
        ["voice_ch_char_Haier_vo_skill01_r01"] = {
            ["ContentFR"] = "Brûlez !",
            ["TextMapId"] = "voice_ch_char_Haier_vo_skill01_r01",
            },
        ["voice_ch_char_Haier_vo_skill01_r02"] = {
            ["ContentFR"] = "Ressentez la peur !",
            ["TextMapId"] = "voice_ch_char_Haier_vo_skill01_r02",
            },
        ["voice_ch_char_Haier_vo_skill02_r01"] = {
            ["ContentFR"] = "Préparez-vous à un interrogatoire intense !",
            ["TextMapId"] = "voice_ch_char_Haier_vo_skill02_r01",
            },
        ["voice_ch_char_Haier_vo_skill02_r02"] = {
            ["ContentFR"] = "Pas de pitié !",
            ["TextMapId"] = "voice_ch_char_Haier_vo_skill02_r02",
            },
        ["voice_ch_char_Haier_vo_skill02_r03"] = {
            ["ContentFR"] = "Énumérez vos péchés !",
            ["TextMapId"] = "voice_ch_char_Haier_vo_skill02_r03",
            },
        ["voice_ch_char_Haier_vo_topic_01_1"] = {
            ["ContentFR"] = "Si tu avais étudié l’histoire, tu saurais que la toute première geôlière de la Prison Militaire Royale avait la peau rouge, comme de la lave en fusion. Même les criminels les plus endurcis redoutaient ses interrogatoires.",
            ["TextMapId"] = "voice_ch_char_Haier_vo_topic_01_1",
            },
        ["voice_ch_char_Haier_vo_topic_01_2"] = {
            ["ContentFR"] = "En tant que sa descendante, je porte fièrement son nom, prête à incinérer tous les péchés avec mon feu.",
            ["TextMapId"] = "voice_ch_char_Haier_vo_topic_01_2",
            },
        ["voice_ch_char_Haier_vo_topic_01_3"] = {
            ["ContentFR"] = "Cela pose certes quelques difficultés : je ne peux dormir que sur des lits en fer et je ne peux pas rester longtemps dans des structures en bois. Cependant, cela me permet de sauver des criminels de bâtiments en feu et de rendre justice. Et le froid ne me dérange jamais.",
            ["TextMapId"] = "voice_ch_char_Haier_vo_topic_01_3",
            },
        ["voice_ch_char_Haier_vo_topic_01_4"] = {
            ["ContentFR"] = "Mon apparence inhabituelle, je la vois plutôt comme un don. S’il faut vraiment lui trouver un inconvénient... j’ai toujours voulu goûter une glace, mais elle fond avant même que je puisse en prendre une bouchée.",
            ["TextMapId"] = "voice_ch_char_Haier_vo_topic_01_4",
            },
        ["voice_ch_char_Haier_vo_topic_02_1"] = {
            ["ContentFR"] = "Depuis la création de l'Empire, ma famille veille sur les pires détenus, rendant justice et supprimant les dangers.",
            ["TextMapId"] = "voice_ch_char_Haier_vo_topic_02_1",
            },
        ["voice_ch_char_Haier_vo_topic_02_2"] = {
            ["ContentFR"] = "Ma peau rouge comme le feu, héritée de mes ancêtres, m’a destinée à porter ce titre. Ce n’est pas moi qui ai choisi, c’est le rôle qui m’a choisie.",
            ["TextMapId"] = "voice_ch_char_Haier_vo_topic_02_2",
            },
        ["voice_ch_char_Haier_vo_topic_02_3"] = {
            ["ContentFR"] = "Être geôlière n’est pas un accomplissement, mais le commencement. Je resterai sur le qui-vive, traquant chaque injustice jusqu’à ce que la mort m’emporte.",
            ["TextMapId"] = "voice_ch_char_Haier_vo_topic_02_3",
            },
        ["voice_ch_char_Haier_vo_topic_03_1"] = {
            ["ContentFR"] = "Certainement. La prison impériale regorge de criminels perfides. Mes fonctions consistent à mener des interrogatoires, examiner des dossiers et déjouer les tentatives d’évasion.",
            ["TextMapId"] = "voice_ch_char_Haier_vo_topic_03_1",
            },
        ["voice_ch_char_Haier_vo_topic_03_2"] = {
            ["ContentFR"] = "Le moindre moment de pause retarde la justice. Et quand la justice tarde, c’est le chaos et la loi du plus fort qui règnent.",
            ["TextMapId"] = "voice_ch_char_Haier_vo_topic_03_2",
            },
        ["voice_ch_char_Haier_vo_topic_03_3"] = {
            ["ContentFR"] = "Certains chercheurs ont imaginé un monde sans crime. Si un tel jour venait à arriver, ma raison d'être disparaîtrait, car le mal nécessite l’existence d’une geôlière. D’ici là, je m’engage à maintenir l’ordre.",
            ["TextMapId"] = "voice_ch_char_Haier_vo_topic_03_3",
            },
        ["voice_ch_char_Haier_vo_topic_04_1"] = {
            ["ContentFR"] = "La justice ? C’est dompter le désir par le pouvoir, enchaîner le mal par la force, et châtier les coupables par les puissants.",
            ["TextMapId"] = "voice_ch_char_Haier_vo_topic_04_1",
            },
        ["voice_ch_char_Haier_vo_topic_04_2"] = {
            ["ContentFR"] = "Hmpf, tranché ? Je ne m’attendrais pas à ce {性别:qu’un enfant naïf|qu’une enfant naïve} comprenne. Nous ne vivons pas dans une utopie où les gens se tiennent simplement la main et s’aiment les uns les autres. Ce n'est que par le pouvoir absolu et l’ordre que la véritable justice peut être garantie !",
            ["TextMapId"] = "voice_ch_char_Haier_vo_topic_04_2",
            },
        ["voice_ch_char_Haier_vo_topic_05_1"] = {
            ["ContentFR"] = "Avec des criminels partout dans les rues de l’Empire, une geôlière n’a pas de loisirs. Je profite juste de quelques verres quand je peux.",
            ["TextMapId"] = "voice_ch_char_Haier_vo_topic_05_1",
            },
        ["voice_ch_char_Haier_vo_topic_05_2"] = {
            ["ContentFR"] = "Ça te surprend ? Ce n’est qu’un passe-temps. Pendant les interrogatoires, j’entends constamment parler de toutes sortes d’alcools, ce qui m’a rendue curieuse au sujet de cette soi-disant potion maléfique souvent liée au crime. Alors j’en bois à l’occasion.",
            ["TextMapId"] = "voice_ch_char_Haier_vo_topic_05_2",
            },
        ["voice_ch_char_Haier_vo_topic_05_3"] = {
            ["ContentFR"] = "Et plus j’en bois, plus je suis convaincue que le mal ne vient pas de l’alcool lui-même.",
            ["TextMapId"] = "voice_ch_char_Haier_vo_topic_05_3",
            },
        ["voice_ch_char_Haier_vo_victory"] = {
            ["ContentFR"] = "Vous n’en pouvez plus ? Ce n’est que le début !",
            ["TextMapId"] = "voice_ch_char_Haier_vo_victory",
            },
        ["voice_ch_char_Haier_vo_welcome"] = {
            ["ContentFR"] = "{性别:Prêt|Prête} pour l’interrogatoire du jour ?",
            ["TextMapId"] = "voice_ch_char_Haier_vo_welcome",
            },
        ["voice_ch_char_Heitao_vo_appear"] = {
            ["ContentFR"] = "Allons-y.",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_appear",
            },
        ["voice_ch_char_Heitao_vo_battleidle"] = {
            ["ContentFR"] = "Finissons-en vite. Et rentrons chez nous.",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_battleidle",
            },
        ["voice_ch_char_Heitao_vo_battlestart"] = {
            ["ContentFR"] = "Je passe devant.",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_battlestart",
            },
        ["voice_ch_char_Heitao_vo_birthday"] = {
            ["ContentFR"] = "Tu m’as dit vouloir fêter ton anniversaire... comme tout le monde. Alors, j’ai essayé de faire comme eux : je t’ai préparé un gâteau. On dit qu’un anniversaire sans gâteau... ce n’est pas vraiment un anniversaire. J’espère qu’à l’avenir, quand tu repenseras à ce mot, \"anniversaire\", ton cœur ne retiendra que la joie.",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_birthday",
            },
        ["voice_ch_char_Heitao_vo_companio_01"] = {
            ["ContentFR"] = "{性别:Toutes ces années, j’ai veillé sur lui… et sur moi aussi, comme je te l’avais promis. Tu pourrais me caresser la tête et me dire que j’ai bien fait, comme quand j’étais petit ? Et cette fois… s’il te plaît… ne nous laisse plus.|Toutes ces années, j’ai veillé sur elle... et sur moi aussi, comme je te l’avais promis. Tu pourrais me caresser la tête et me dire que j’ai bien fait, comme quand j’étais petite ? Et cette fois… s’il te plaît… ne nous laisse plus.}",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_companio_01",
            },
        ["voice_ch_char_Heitao_vo_companio_02_1"] = {
            ["ContentFR"] = "Mademoiselle Truffle, est-ce que je peux… toucher votre cochon ? Juste une fois, promis. Vous pourriez le tenir un peu, s’il vous plaît ? J’ai peur qu’il s’enfuie... Les petits animaux me fuient toujours.",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_companio_02_1",
            },
        ["voice_ch_char_Heitao_vo_companio_02_2"] = {
            ["ContentFR"] = "Merci... Ah... c’est tout chaud... et tout doux... C’est vraiment agréable...",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_companio_02_2",
            },
        ["voice_ch_char_Heitao_vo_companio_03"] = {
            ["ContentFR"] = "Je ne suis pas le \"n° 0\" de la Légion. Et encore moins un jouet entre tes mains. Pars. Ou emmène mon cadavre, mais jamais je ne te suivrai vivante.",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_companio_03",
            },
        ["voice_ch_char_Heitao_vo_companio_04_1"] = {
            ["ContentFR"] = "On dit que vous êtes un fin gourmet... Vous accepteriez de me montrer quelques-unes de vos recettes ? {nickname} ne tarit pas d’éloges sur votre cuisine et ça sonnait vrai, pas juste un compliment de courtoisie.",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_companio_04_1",
            },
        ["voice_ch_char_Heitao_vo_companio_04_2"] = {
            ["ContentFR"] = "...Vous n’utilisez pourtant que des ingrédients très simples ? Alors pourquoi... ? Quel est votre secret ?",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_companio_04_2",
            },
        ["voice_ch_char_Heitao_vo_die_r01"] = {
            ["ContentFR"] = "Je dois... te protéger...",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_die_r01",
            },
        ["voice_ch_char_Heitao_vo_die_r02"] = {
            ["ContentFR"] = "Revoir cet endroit... comme on l’avait promis...",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_die_r02",
            },
        ["voice_ch_char_Heitao_vo_fail"] = {
            ["ContentFR"] = "{性别:L’important, c’est que tu sois sain et sauf.|L’important, c’est que tu sois saine et sauve.}",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_fail",
            },
        ["voice_ch_char_Heitao_vo_gain"] = {
            ["ContentFR"] = "Je suis de retour.",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_gain",
            },
        ["voice_ch_char_Heitao_vo_idle"] = {
            ["ContentFR"] = "{性别:Il n’a jamais été fait pour vivre en cage. J’ai toujours su qu’un jour, il quitterait l’île pour s’envoler vers le ciel. Ce que je n’ai jamais su, c’est si ce serait une bénédiction… ou une malédiction, pour nous.|Elle n’a jamais été faite pour vivre en cage. J’ai toujours su qu’un jour, elle quitterait l’île pour s’envoler vers le ciel. Ce que je n’ai jamais su, c’est si ce serait une bénédiction… ou une malédiction, pour nous.}",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_idle",
            },
        ["voice_ch_char_Heitao_vo_lvup"] = {
            ["ContentFR"] = "Tu en penses quoi ?",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_lvup",
            },
        ["voice_ch_char_Heitao_vo_revive"] = {
            ["ContentFR"] = "Ce n’est pas fini.",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_revive",
            },
        ["voice_ch_char_Heitao_vo_skill01_r01"] = {
            ["ContentFR"] = "En pièces.",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_skill01_r01",
            },
        ["voice_ch_char_Heitao_vo_skill01_r02"] = {
            ["ContentFR"] = "À genoux.",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_skill01_r02",
            },
        ["voice_ch_char_Heitao_vo_skill02_r01"] = {
            ["ContentFR"] = "C’est terminé.",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_skill02_r01",
            },
        ["voice_ch_char_Heitao_vo_skill02_r02"] = {
            ["ContentFR"] = "Adieu.",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_skill02_r02",
            },
        ["voice_ch_char_Heitao_vo_skill02_r03"] = {
            ["ContentFR"] = "Je ne pardonnerai jamais à ceux qui t’ont blessé.",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_skill02_r03",
            },
        ["voice_ch_char_Heitao_vo_topic_01_1"] = {
            ["ContentFR"] = "Ce que je fais ici... ? Je ne sais pas. Disons simplement que c’est un beau rêve, fais comme si j’étais encore à tes côtés, comme autrefois.",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_topic_01_1",
            },
        ["voice_ch_char_Heitao_vo_topic_01_2"] = {
            ["ContentFR"] = "Oui, moi aussi… plus que tout. Puissions-nous un jour nous retrouver… pour de vrai.",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_topic_01_2",
            },
        ["voice_ch_char_Heitao_vo_topic_02_1"] = {
            ["ContentFR"] = "Un souhait ? Honnêtement... non, rien de particulier. Tant que je peux voir ton sourire chaque matin, ça me suffit.",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_topic_02_1",
            },
        ["voice_ch_char_Heitao_vo_topic_02_2"] = {
            ["ContentFR"] = "Mais ne te force pas. Si tu te sens mal, viens simplement me parler un moment. Ou si tu préfères garder le silence, on pourra rester là, ensemble, tranquillement.",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_topic_02_2",
            },
        ["voice_ch_char_Heitao_vo_topic_03_1"] = {
            ["ContentFR"] = "C’est pas comme sur l’Île du Purgatoire, ici il neige tous les jours. Mais heureusement, tu as un toit bien chaud. Comparé à notre vieille cabane sur l’île, ce logement, c’est presque du luxe.",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_topic_03_1",
            },
        ["voice_ch_char_Heitao_vo_topic_03_2"] = {
            ["ContentFR"] = "Je me souviens, en hiver, tes mains étaient toujours gelées… Viens, donne-moi tes mains, je vais te les réchauffer.",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_topic_03_2",
            },
        ["voice_ch_char_Heitao_vo_topic_04_1"] = {
            ["ContentFR"] = "Comment dire... C’est une ville de métal, froide et impitoyable... Non, en fait, c’est plutôt une prison. C’est là que j’ai passé mon enfance.",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_topic_04_1",
            },
        ["voice_ch_char_Heitao_vo_topic_04_2"] = {
            ["ContentFR"] = "Plus tard, quelqu’un m’a aidée à m’échapper. Elle nous a emmenés, toi et moi, sur l’Île du Purgatoire. Mais à propos d’elle... je ne peux rien dire de plus. Désolée, je lui ai promis de garder le secret.",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_topic_04_2",
            },
        ["voice_ch_char_Heitao_vo_topic_04_3"] = {
            ["ContentFR"] = "... Les jours passés sur l’Île du Purgatoire étaient si paisibles que j’ai cru qu’on pourrait y vivre toute notre vie. Jusqu’au jour où ils sont revenus. C’est là que j’ai compris que je n’avais jamais vraiment fui cette prison.",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_topic_04_3",
            },
        ["voice_ch_char_Heitao_vo_topic_05_1"] = {
            ["ContentFR"] = "C’est un peu animé, oui... mais ça ne me dérange pas. Tu t’es fait plein de nouveaux amis, et c’est une bonne chose. Je suis vraiment contente pour toi.",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_topic_05_1",
            },
        ["voice_ch_char_Heitao_vo_topic_05_2"] = {
            ["ContentFR"] = "{性别:Comme ça, même si je ne suis pas là… tu ne te sentiras plus seul.|Comme ça, même si je ne suis pas là… tu ne te sentiras plus seule. }",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_topic_05_2",
            },
        ["voice_ch_char_Heitao_vo_topic_06_1"] = {
            ["ContentFR"] = "Alors repose-toi un peu, pose ta tête sur mes genoux... comme avant.",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_topic_06_1",
            },
        ["voice_ch_char_Heitao_vo_victory"] = {
            ["ContentFR"] = "Tout est fini.",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_victory",
            },
        ["voice_ch_char_Heitao_vo_welcome"] = {
            ["ContentFR"] = "Tu es de retour. Qu’est-ce que tu comptes faire aujourd’hui ? Te reposer à la maison, peut-être ?",
            ["TextMapId"] = "voice_ch_char_Heitao_vo_welcome",
            },
        ["voice_ch_char_Kezhou_vo_appear"] = {
            ["ContentFR"] = "L’épée en main tue, celle du cœur apaise.",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_appear",
            },
        ["voice_ch_char_Kezhou_vo_battleidle"] = {
            ["ContentFR"] = "Je n’ai pas encore tout montré, on y retourne !",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_battleidle",
            },
        ["voice_ch_char_Kezhou_vo_battlestart"] = {
            ["ContentFR"] = "Même le lion se donne à fond pour attraper un lièvre.",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_battlestart",
            },
        ["voice_ch_char_Kezhou_vo_be_hit_heavy_r01"] = {
            ["ContentFR"] = "Belle attaque !",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_be_hit_heavy_r01",
            },
        ["voice_ch_char_Kezhou_vo_be_hit_heavy_r02"] = {
            ["ContentFR"] = "Rien de sérieux.",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_be_hit_heavy_r02",
            },
        ["voice_ch_char_Kezhou_vo_birthday"] = {
            ["ContentFR"] = "Aujourd’hui serait parfait pour boire et chanter... Quoi ? C’est ton anniversaire ?\
Nous, vagabonds, ne prêtons pas vraiment attention à ce genre de choses.\
Quand on vit au gré du vent et de la neige, sans savoir si demain on sera encore en vie, on finit par oublier ce que c’est, un anniversaire.\
Mais toi, tu viens d’ailleurs... et tu t’entraînes avec moi chaque jour. Alors, fêtons ça un peu.\
Chantons ! Chantons la bravoure {性别:du jeune Chasseur de Phoxène, lié par l’honneur et la parole donnée !|de la jeune Chasseuse de Phoxène, liée par l’honneur et la parole donnée !}",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_birthday",
            },
        ["voice_ch_char_Kezhou_vo_companio_01"] = {
            ["ContentFR"] = "On dit que le meilleur épéiste n’a même pas besoin d’épée : une herbe, un bout de bois peut devenir une lame. J’ai entendu dire que tu utilises des outils de nettoyage comme armes, tu dois être un maître épéiste. Apprends-moi quelques techniques.",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_companio_01",
            },
        ["voice_ch_char_Kezhou_vo_companio_02"] = {
            ["ContentFR"] = "Je garde ton ancienne épée pour l’instant. Quand tu cesseras de faire la tête, je te la rendrai, mais seulement si tu me bats en duel. Si tu perds, elle sera à moi pour de bon.",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_companio_02",
            },
        ["voice_ch_char_Kezhou_vo_companio_03"] = {
            ["ContentFR"] = "Une épée peut être une amie, un jouet, voire un outil pour couper, faire levier ou raser. Mais elle ne doit jamais devenir ton maître. Ne laisse pas cette lame t’empêcher d’avancer.",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_companio_03",
            },
        ["voice_ch_char_Kezhou_vo_die_r01"] = {
            ["ContentFR"] = "Je me retire... pour cette fois.",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_die_r01",
            },
        ["voice_ch_char_Kezhou_vo_die_r02"] = {
            ["ContentFR"] = "Le travail forge l’expertise, la paresse l’éteint...",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_die_r02",
            },
        ["voice_ch_char_Kezhou_vo_fail"] = {
            ["ContentFR"] = "Défaite ou victoire, c’est le lot des guerriers. Peu importe, on y retourne.",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_fail",
            },
        ["voice_ch_char_Kezhou_vo_gain"] = {
            ["ContentFR"] = "Le ciel pour couverture, la terre pour couche. L’épée en main, je marche entre Soleil et Lune, là où l’injustice m’appelle.\
Mais bon... ce genre d’entrée, ça sonne toujours faux. Alors soyons clairs : Kezhou, vagabond de Huaxu. Si t’as besoin d’un coup de main, dis-le franchement.",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_gain",
            },
        ["voice_ch_char_Kezhou_vo_idle"] = {
            ["ContentFR"] = "C’est lumineux et grand, mais il y a trop de tables et de chaises. Sinon, ce serait parfait pour s’entraîner au combat.",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_idle",
            },
        ["voice_ch_char_Kezhou_vo_lvup"] = {
            ["ContentFR"] = "Il faut voir mille épées avant d’en comprendre vraiment une.",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_lvup",
            },
        ["voice_ch_char_Kezhou_vo_revive"] = {
            ["ContentFR"] = "Ce combat est loin d’être terminé !",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_revive",
            },
        ["voice_ch_char_Kezhou_vo_skill01_r01"] = {
            ["ContentFR"] = "Rapide comme l’éclair !",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_skill01_r01",
            },
        ["voice_ch_char_Kezhou_vo_skill01_r02"] = {
            ["ContentFR"] = "Tenez-vous tranquilles !",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_skill01_r02",
            },
        ["voice_ch_char_Kezhou_vo_skill02_r01"] = {
            ["ContentFR"] = "À dix pas, plus rien ne vit.",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_skill02_r01",
            },
        ["voice_ch_char_Kezhou_vo_skill02_r02"] = {
            ["ContentFR"] = "Danse de l’épée, votre fin est proche !",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_skill02_r02",
            },
        ["voice_ch_char_Kezhou_vo_skill02_r03"] = {
            ["ContentFR"] = "Il est temps de tester cette lame !",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_skill02_r03",
            },
        ["voice_ch_char_Kezhou_vo_topic_01_1"] = {
            ["ContentFR"] = "Tu aimes aussi le maniement de l’épée ? Je m’en doutais, avec une lame comme la tienne, tu dois pas être {性别:mauvais|mauvaise}. Allez, un petit duel amical, qu’on voie ce que tu vaux !",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_topic_01_1",
            },
        ["voice_ch_char_Kezhou_vo_topic_01_2"] = {
            ["ContentFR"] = "Pour être honnête, ça fait un bail que j’ai pas croisé un vrai adversaire à ma hauteur. Mais d’après mon maître, je suis trop franc, pas assez rusé, il disait que pour progresser, je devais apprendre à jouer la comédie.",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_topic_01_2",
            },
        ["voice_ch_char_Kezhou_vo_topic_01_3"] = {
            ["ContentFR"] = "Pas pour moi. Mais lui disait toujours qu’une épée, ça se manie avec la tête autant qu’avec les bras. « Dissimuler sa force en feignant la faiblesse », « vaincre sans combattre », « submerger le petit nombre par le grand nombre »... Pour lui, c’était ça, la vraie maîtrise.",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_topic_01_3",
            },
        ["voice_ch_char_Kezhou_vo_topic_01_4"] = {
            ["ContentFR"] = "Quand j’étais gosse, il me jouait toujours le même numéro : il faisait semblant d’être rouillé, pas très doué. Il disait : « Si tu arrives à me foutre au sol, t’auras plus jamais besoin de t’entraîner. » J’ai passé un an à essayer... j’ai même pas effleuré sa manche.",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_topic_01_4",
            },
        ["voice_ch_char_Kezhou_vo_topic_01_5"] = {
            ["ContentFR"] = "Un jour, à bout de force, j’étais allongé par terre. J’ai levé les yeux : pas une trace de fatigue chez lui. Même ses faux pas étaient calculés. Toute cette mascarade... c’était de l’art.",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_topic_01_5",
            },
        ["voice_ch_char_Kezhou_vo_topic_02_1"] = {
            ["ContentFR"] = "J’ai des tas de raisons, mais au fond, c’est simple : je refuse d’être enchaîné.",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_topic_02_1",
            },
        ["voice_ch_char_Kezhou_vo_topic_02_2"] = {
            ["ContentFR"] = "J’ai grandi libre comme le vent, faisant tout à ma façon, dégainant l’épée dès que je voyais une injustice. Les paroles du maître ou de Yuming ? Je n’écoutais que ce qui m’arrangeait. Le reste, ça passait par une oreille et sortait par l’autre, comme le vent qui souffle. Alors, pourquoi je me laisserais enchaîner par des lois ?",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_topic_02_2",
            },
        ["voice_ch_char_Kezhou_vo_topic_02_3"] = {
            ["ContentFR"] = "Je dirais que c’est le problème de beaucoup d’épéistes. Au début, tu apprends les enchaînements du rouleau, mouvement par mouvement. Contre des adversaires ordinaires, ça suffit, ton épée bouge presque toute seule.",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_topic_02_3",
            },
        ["voice_ch_char_Kezhou_vo_topic_02_4"] = {
            ["ContentFR"] = "Mais si tu t’en tiens trop rigoureusement au rouleau, sans savoir improviser, ton épée devient juste un morceau de métal : lente, maladroite, inutile. Dès que ça sort de l’ordinaire, tu perds complètement tes moyens.",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_topic_02_4",
            },
        ["voice_ch_char_Kezhou_vo_topic_02_5"] = {
            ["ContentFR"] = "Pour moi, Huaxu, c’est un épéiste prisonnier de ses Neuf Chapitres de Dafeng. Ils ne peuvent même pas vaincre un vagabond comme moi, alors face à une vraie menace, ils sont condamnés. Ce ne sera qu’une question de temps avant qu’ils ne tombent.",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_topic_02_5",
            },
        ["voice_ch_char_Kezhou_vo_topic_03_1"] = {
            ["ContentFR"] = "Bien sûr ! Être épéiste, c’est maîtriser l’épée, pas forcément s’en tenir qu’à elle. À Huaxu, certains se battent même avec un pinceau ou des baguettes. Si un épéiste devait se limiter à son épée, comment ferait-il pour écrire ou manger ?",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_topic_03_1",
            },
        ["voice_ch_char_Kezhou_vo_topic_03_2"] = {
            ["ContentFR"] = "Je peux, oui. Mais à quoi bon ? Esquiver, c’est bien plus simple. Même les sangliers savent qu’il vaut mieux croquer un radis que ronger de l’écorce.",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_topic_03_2",
            },
        ["voice_ch_char_Kezhou_vo_topic_03_3"] = {
            ["ContentFR"] = "Cela dit, si jamais je tombe sur un adversaire digne de ce nom, tu peux être sûr que je dégainerai mon épée et que je me battrai à fond.",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_topic_03_3",
            },
        ["voice_ch_char_Kezhou_vo_topic_04_1"] = {
            ["ContentFR"] = "C'est vrai. Maintenant que tu le dis, je peux t’en citer pas mal. Des « Roi Untel », « Seigneur Machin », ou des « Immortels Bidule ». Les animaux sont populaires comme surnoms : dragon, tigre, lion, grue... un vrai zoo !",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_topic_04_1",
            },
        ["voice_ch_char_Kezhou_vo_topic_04_2"] = {
            ["ContentFR"] = "Et tu sais comment ça marche ? Plus le surnom est long, moins le gars est doué. Quatre mots ? Un débutant. Trois ? Pas mal. Deux ? Quelqu’un avec qui il vaut mieux ne pas chercher des ennuis. Et ceux qui n'ont pas de surnom du tout ? Ce sont les véritables grands maîtres.",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_topic_04_2",
            },
        ["voice_ch_char_Kezhou_vo_topic_04_3"] = {
            ["ContentFR"] = "Je parcours ce monde sous mon vrai nom, bien sûr. Je sais, ça peut sembler inventé. Même mon maître me le répétait souvent : un nom comme celui-ci fait croire aux gens que tu es un prodige, et ça ne t’apporte que des ennuis.",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_topic_04_3",
            },
        ["voice_ch_char_Kezhou_vo_topic_04_4"] = {
            ["ContentFR"] = "Mais c’est le nom que mon père m’a donné. Peut-être espérait-il que je devienne un héros. Il ne m’a pas laissé grand-chose, mais tant que je porte ce nom, c’est comme si son épée laissait encore une trace dans ce monde.",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_topic_04_4",
            },
        ["voice_ch_char_Kezhou_vo_victory"] = {
            ["ContentFR"] = "Mon épée pour la justice. Qui sera le prochain ?",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_victory",
            },
        ["voice_ch_char_Kezhou_vo_welcome"] = {
            ["ContentFR"] = "Un jour parfait pour boire un coup et chanter ! Allez, laisse-moi finir ce verre, et ensuite, on ira régler leur compte à ceux qui le méritent.\
Quoi ? J’ai dit la même chose hier ? Normal. Chaque jour devrait commencer comme ça.",
            ["TextMapId"] = "voice_ch_char_Kezhou_vo_welcome",
            },
        ["voice_ch_char_Landi_vo_appear"] = {
            ["ContentFR"] = "Je suis vraiment obligé d’y aller cette fois ?",
            ["TextMapId"] = "voice_ch_char_Landi_vo_appear",
            },
        ["voice_ch_char_Landi_vo_battleidle"] = {
            ["ContentFR"] = "Si seulement ils savaient aussi bien que moi la valeur du repos.",
            ["TextMapId"] = "voice_ch_char_Landi_vo_battleidle",
            },
        ["voice_ch_char_Landi_vo_battlestart"] = {
            ["ContentFR"] = "Visons la faille dans leur défense.",
            ["TextMapId"] = "voice_ch_char_Landi_vo_battlestart",
            },
        ["voice_ch_char_Landi_vo_be_hit_heavy_r01"] = {
            ["ContentFR"] = "C’est brutal.",
            ["TextMapId"] = "voice_ch_char_Landi_vo_be_hit_heavy_r01",
            },
        ["voice_ch_char_Landi_vo_be_hit_heavy_r02"] = {
            ["ContentFR"] = "J’aurais dû rester au lit.",
            ["TextMapId"] = "voice_ch_char_Landi_vo_be_hit_heavy_r02",
            },
        ["voice_ch_char_Landi_vo_birthday"] = {
            ["ContentFR"] = "Aujourd’hui, j’ai sacrifié mon précieux temps de repos, de mon plein gré, hein, juste pour que ton anniversaire soit inoubliable. Hum hum... J’ai aussi amélioré un peu tes ustensiles de cuisine pour te faire un gâteau. Bon, il ressemble vaguement à un gâteau... mais sois {性别:indulgent|indulgente}, c’est ma première fois, et c’était un sacré chantier.",
            ["TextMapId"] = "voice_ch_char_Landi_vo_birthday",
            },
        ["voice_ch_char_Landi_vo_companio_01"] = {
            ["ContentFR"] = "Au rapport rapport, commandante Sibylle. Les tâches du jour sont toutes assignées. Si vous avez d’autres consignes, je suis prêt à les exécuter. Mais la journée a été chargée, pensez à vous reposer pour ne pas vous épuiser.",
            ["TextMapId"] = "voice_ch_char_Landi_vo_companio_01",
            },
        ["voice_ch_char_Landi_vo_companio_02"] = {
            ["ContentFR"] = "Beau boulot pour la dernière mission, mais j’ai reçu quelques plaintes à propos de dégâts matériels... Et devine qui doit aller présenter ses excuses à ta place ? Moi ! Et tu me connais, je suis bien trop timide pour ça... Alors, ma très chère, adorable et gentille Lynn, tu pourrais pas t’occuper de ces petites urgences à ma place ? Allez, sois un amour, juste cette fois.",
            ["TextMapId"] = "voice_ch_char_Landi_vo_companio_02",
            },
        ["voice_ch_char_Landi_vo_companio_03"] = {
            ["ContentFR"] = "Hein, comment as-tu pu... ? Je dois être épuisé, j’ai des hallucinations... Je vais déclarer ça comme accident de travail et prendre un congé maladie.",
            ["TextMapId"] = "voice_ch_char_Landi_vo_companio_03",
            },
        ["voice_ch_char_Landi_vo_die_r01"] = {
            ["ContentFR"] = "Je le savais... cette mission était une erreur...",
            ["TextMapId"] = "voice_ch_char_Landi_vo_die_r01",
            },
        ["voice_ch_char_Landi_vo_die_r02"] = {
            ["ContentFR"] = "Finalement... le sommeil éternel, c’est pas si reposant...",
            ["TextMapId"] = "voice_ch_char_Landi_vo_die_r02",
            },
        ["voice_ch_char_Landi_vo_fail"] = {
            ["ContentFR"] = "Savoir quand battre en retraite, c’est aussi une tactique ! Je me tire !",
            ["TextMapId"] = "voice_ch_char_Landi_vo_fail",
            },
        ["voice_ch_char_Landi_vo_gain"] = {
            ["ContentFR"] = "Ah, tu m’as eu. Mes jours tranquilles sont sûrement comptés... Mais bon, t’as l’air d’un type correct, alors je suppose que je peux filer un coup de main. En toute amitié, bien sûr.",
            ["TextMapId"] = "voice_ch_char_Landi_vo_gain",
            },
        ["voice_ch_char_Landi_vo_idle"] = {
            ["ContentFR"] = "Hum... Ce fusil pliant semi-automatique pourrait être amélioré... Plus de puissance de feu, et on pourrait finir les missions encore plus vite, pour rentrer plus tôt.",
            ["TextMapId"] = "voice_ch_char_Landi_vo_idle",
            },
        ["voice_ch_char_Landi_vo_lvup"] = {
            ["ContentFR"] = "Même si c’est pénible, les préparatifs avant la bataille sont indispensables.",
            ["TextMapId"] = "voice_ch_char_Landi_vo_lvup",
            },
        ["voice_ch_char_Landi_vo_revive"] = {
            ["ContentFR"] = "Reprends-toi... c’est l’heure de se remettre au boulot.",
            ["TextMapId"] = "voice_ch_char_Landi_vo_revive",
            },
        ["voice_ch_char_Landi_vo_skill01_r01"] = {
            ["ContentFR"] = "Allez, rendez-vous vite.",
            ["TextMapId"] = "voice_ch_char_Landi_vo_skill01_r01",
            },
        ["voice_ch_char_Landi_vo_skill01_r02"] = {
            ["ContentFR"] = "Décompresse.",
            ["TextMapId"] = "voice_ch_char_Landi_vo_skill01_r02",
            },
        ["voice_ch_char_Landi_vo_skill02_r01"] = {
            ["ContentFR"] = "Point faible repéré.",
            ["TextMapId"] = "voice_ch_char_Landi_vo_skill02_r01",
            },
        ["voice_ch_char_Landi_vo_skill02_r02"] = {
            ["ContentFR"] = "C’est la meilleure option.",
            ["TextMapId"] = "voice_ch_char_Landi_vo_skill02_r02",
            },
        ["voice_ch_char_Landi_vo_skill02_r03"] = {
            ["ContentFR"] = "Fallait pas me déranger pendant ma pause.",
            ["TextMapId"] = "voice_ch_char_Landi_vo_skill02_r03",
            },
        }
  end },
  { MinKey = "voice_ch_char_Landi_vo_topic_01_1", MaxKey = "voice_ch_char_Saiqi01_vo_skill02_r01", Loader = function()
      return {
        ["voice_ch_char_Landi_vo_topic_01_1"] = {
            ["ContentFR"] = "Ma famille ? Mes parents m’ont laissé tranquille depuis des années. Juste mes deux sœurs qui me donnent des ordres parfois, mais maintenant que je suis dans la Légion, elles peuvent rien faire.",
            ["TextMapId"] = "voice_ch_char_Landi_vo_topic_01_1",
            },
        ["voice_ch_char_Landi_vo_topic_01_2"] = {
            ["ContentFR"] = "Non, pas du tout ! Elles sont adorables, intelligentes, gentilles, élégantes, optimistes... Bref, elles ont tout pour elles ! Bon... un peu plus de retenue ne leur ferait pas de mal.",
            ["TextMapId"] = "voice_ch_char_Landi_vo_topic_01_2",
            },
        ["voice_ch_char_Landi_vo_topic_02_1"] = {
            ["ContentFR"] = "Toi, tu dois être du genre à pas savoir te détendre. Écoute : le lit, c’est un refuge pour l’âme, le toit, un sanctuaire pour l’esprit, l’après-midi, le jardin devient un écrin de lumière... Et la sieste ? Une douce symphonie.",
            ["TextMapId"] = "voice_ch_char_Landi_vo_topic_02_1",
            },
        ["voice_ch_char_Landi_vo_topic_02_2"] = {
            ["ContentFR"] = "Hé ! Attends, j’ai pas fini !",
            ["TextMapId"] = "voice_ch_char_Landi_vo_topic_02_2",
            },
        ["voice_ch_char_Landi_vo_topic_03_1"] = {
            ["ContentFR"] = "Elle sait vraiment comment te faire courir partout... Il me faudrait trois moi pour suivre le rythme... Euh, je veux dire, la commandante Sibylle est très stricte avec ses subordonnés.",
            ["TextMapId"] = "voice_ch_char_Landi_vo_topic_03_1",
            },
        ["voice_ch_char_Landi_vo_topic_03_2"] = {
            ["ContentFR"] = "Voilà ce que je te propose : un goûter, et on fait comme si tu n’avais rien entendu, ça te va ? T’inquiète, y a pas de truc bizarre dedans.",
            ["TextMapId"] = "voice_ch_char_Landi_vo_topic_03_2",
            },
        ["voice_ch_char_Landi_vo_topic_04_1"] = {
            ["ContentFR"] = "J’ai créé un truc génial pour toi : un petit robot compagnon ! En combat, il te suit, agite un drapeau et crie \"Allez ! T’assures grave !\"",
            ["TextMapId"] = "voice_ch_char_Landi_vo_topic_04_1",
            },
        ["voice_ch_char_Landi_vo_topic_04_2"] = {
            ["ContentFR"] = "Plutôt cool, non ? Attends que je le fasse vraiment fonctionner...",
            ["TextMapId"] = "voice_ch_char_Landi_vo_topic_04_2",
            },
        ["voice_ch_char_Landi_vo_topic_04_3"] = {
            ["ContentFR"] = "Hé, attends, j’ai pas fini ! J’ai dessiné ces plans sans que la commandante Sibylle ne le sache, pendant mes rares pauses...",
            ["TextMapId"] = "voice_ch_char_Landi_vo_topic_04_3",
            },
        ["voice_ch_char_Landi_vo_victory"] = {
            ["ContentFR"] = "Je te laisse gérer la suite, {性别:grand|grande} stratège. Moi, je file !",
            ["TextMapId"] = "voice_ch_char_Landi_vo_victory",
            },
        ["voice_ch_char_Landi_vo_welcome"] = {
            ["ContentFR"] = "Ahh... Cette sensation après un bon réveil, c’est le pied. Écoute, {性别:mec|l’amie}, faut pas être tendu tout le temps. Ta liste de trucs à faire sera jamais finie. Faut savoir se détendre, c’est pas un luxe, c’est vital.",
            ["TextMapId"] = "voice_ch_char_Landi_vo_welcome",
            },
        ["voice_ch_char_Linen_vo_appear"] = {
            ["ContentFR"] = "Qui est la cible aujourd'hui ?",
            ["TextMapId"] = "voice_ch_char_Linen_vo_appear",
            },
        ["voice_ch_char_Linen_vo_battleidle"] = {
            ["ContentFR"] = "Bouge-toi, sinon tu ne vivras pas assez longtemps pour me payer.",
            ["TextMapId"] = "voice_ch_char_Linen_vo_battleidle",
            },
        ["voice_ch_char_Linen_vo_battlestart"] = {
            ["ContentFR"] = "C’est parti !",
            ["TextMapId"] = "voice_ch_char_Linen_vo_battlestart",
            },
        ["voice_ch_char_Linen_vo_be_hit_heavy_r01"] = {
            ["ContentFR"] = "Bordel, ça fait mal !",
            ["TextMapId"] = "voice_ch_char_Linen_vo_be_hit_heavy_r01",
            },
        ["voice_ch_char_Linen_vo_be_hit_heavy_r02"] = {
            ["ContentFR"] = "Pas mal.",
            ["TextMapId"] = "voice_ch_char_Linen_vo_be_hit_heavy_r02",
            },
        ["voice_ch_char_Linen_vo_be_hit_r01"] = {
            ["ContentFR"] = "Pff.",
            ["TextMapId"] = "voice_ch_char_Linen_vo_be_hit_r01",
            },
        ["voice_ch_char_Linen_vo_be_hit_r02"] = {
            ["ContentFR"] = "Aïe.",
            ["TextMapId"] = "voice_ch_char_Linen_vo_be_hit_r02",
            },
        ["voice_ch_char_Linen_vo_birthday"] = {
            ["ContentFR"] = "Joyeux anniversaire. Je ne suis pas du genre à faire dans le sentimental, alors je te souhaite juste de ne jamais manquer d'argent. Et pour la mission d’aujourd’hui, je t’offre une ristourne de 20 %. C’est pas mal, non ?",
            ["TextMapId"] = "voice_ch_char_Linen_vo_birthday",
            },
        ["voice_ch_char_Linen_vo_companio_01"] = {
            ["ContentFR"] = "La prochaine fois, va droit au but, ok ? Tes bavardages, ça me gonfle.",
            ["TextMapId"] = "voice_ch_char_Linen_vo_companio_01",
            },
        ["voice_ch_char_Linen_vo_companio_02"] = {
            ["ContentFR"] = "Bonjour, madame...",
            ["TextMapId"] = "voice_ch_char_Linen_vo_companio_02",
            },
        ["voice_ch_char_Linen_vo_companio_03"] = {
            ["ContentFR"] = "T’es un bon soldat, ça c’est dit. Et… profite un peu de la vie aussi, hein ? Allez, assez causé, va-t’en.",
            ["TextMapId"] = "voice_ch_char_Linen_vo_companio_03",
            },
        ["voice_ch_char_Linen_vo_die_r01"] = {
            ["ContentFR"] = "Qui... d’autre... ?",
            ["TextMapId"] = "voice_ch_char_Linen_vo_die_r01",
            },
        ["voice_ch_char_Linen_vo_die_r02"] = {
            ["ContentFR"] = "J’en peux plus...",
            ["TextMapId"] = "voice_ch_char_Linen_vo_die_r02",
            },
        ["voice_ch_char_Linen_vo_fail"] = {
            ["ContentFR"] = "Ne dis rien, sinon ça va mal finir.",
            ["TextMapId"] = "voice_ch_char_Linen_vo_fail",
            },
        ["voice_ch_char_Linen_vo_gain"] = {
            ["ContentFR"] = "Je ne pensais pas faire des missions pour toi. Qu’est-ce que tu veux ? On commence par parler salaire.",
            ["TextMapId"] = "voice_ch_char_Linen_vo_gain",
            },
        ["voice_ch_char_Linen_vo_idle"] = {
            ["ContentFR"] = "Pas mal. Je devrais avoir assez pour ce mois. Je pensais que ce foutu Randy allait tout me piquer. Je renvoie le reste à la maison, ça devrait suffire pour vivre.",
            ["TextMapId"] = "voice_ch_char_Linen_vo_idle",
            },
        ["voice_ch_char_Linen_vo_lvup"] = {
            ["ContentFR"] = "La galère...",
            ["TextMapId"] = "voice_ch_char_Linen_vo_lvup",
            },
        ["voice_ch_char_Linen_vo_revive"] = {
            ["ContentFR"] = "C’est reparti !",
            ["TextMapId"] = "voice_ch_char_Linen_vo_revive",
            },
        ["voice_ch_char_Linen_vo_skill01_r01"] = {
            ["ContentFR"] = "Carnage !",
            ["TextMapId"] = "voice_ch_char_Linen_vo_skill01_r01",
            },
        ["voice_ch_char_Linen_vo_skill01_r02"] = {
            ["ContentFR"] = "Je vais vous éclater.",
            ["TextMapId"] = "voice_ch_char_Linen_vo_skill01_r02",
            },
        ["voice_ch_char_Linen_vo_skill02_r01"] = {
            ["ContentFR"] = "Vous l’avez bien cherché.",
            ["TextMapId"] = "voice_ch_char_Linen_vo_skill02_r01",
            },
        ["voice_ch_char_Linen_vo_skill02_r02"] = {
            ["ContentFR"] = "Vous allez payer pour m’avoir fait perdre mon temps !",
            ["TextMapId"] = "voice_ch_char_Linen_vo_skill02_r02",
            },
        ["voice_ch_char_Linen_vo_skill02_r03"] = {
            ["ContentFR"] = "Maintenant, je suis en colère.",
            ["TextMapId"] = "voice_ch_char_Linen_vo_skill02_r03",
            },
        ["voice_ch_char_Linen_vo_topic_01_1"] = {
            ["ContentFR"] = "Sibylle ? C’est la commandante de la XIIIᵉ Légion.",
            ["TextMapId"] = "voice_ch_char_Linen_vo_topic_01_1",
            },
        ["voice_ch_char_Linen_vo_topic_01_2"] = {
            ["ContentFR"] = "Pff, qu’est-ce que tu veux que je sache ? C’est elle qui décide, moi je fais le boulot. C’est tout.",
            ["TextMapId"] = "voice_ch_char_Linen_vo_topic_01_2",
            },
        ["voice_ch_char_Linen_vo_topic_02_1"] = {
            ["ContentFR"] = "Des conseils ? Le seul que je connais, c’est qu’il n’y a aucun problème qu’un bon coup de poing ne puisse résoudre. Et si ça ne suffit pas, frappe encore.",
            ["TextMapId"] = "voice_ch_char_Linen_vo_topic_02_1",
            },
        ["voice_ch_char_Linen_vo_topic_02_2"] = {
            ["ContentFR"] = "Dans ce cas, une balle suffit généralement.",
            ["TextMapId"] = "voice_ch_char_Linen_vo_topic_02_2",
            },
        ["voice_ch_char_Linen_vo_topic_02_3"] = {
            ["ContentFR"] = "Eh, c’est juste une façon de parler. Tant que tes poings sont solides et tes tirs précis, c’est tout ce qui compte. Si tu continues à chipoter, je t’en colle deux !",
            ["TextMapId"] = "voice_ch_char_Linen_vo_topic_02_3",
            },
        ["voice_ch_char_Linen_vo_topic_03_1"] = {
            ["ContentFR"] = "J’ai vu un flingue sympa l’autre jour... Mais bon, pas question de crever la dalle pour ça. L’ancien fait encore l’affaire.",
            ["TextMapId"] = "voice_ch_char_Linen_vo_topic_03_1",
            },
        ["voice_ch_char_Linen_vo_topic_03_2"] = {
            ["ContentFR"] = "Vraiment ? T’as l’air aussi fauché que moi... J’apprécie, mais te ruine pas pour moi. Je veux rien devoir à personne.",
            ["TextMapId"] = "voice_ch_char_Linen_vo_topic_03_2",
            },
        ["voice_ch_char_Linen_vo_topic_04_1"] = {
            ["ContentFR"] = "Si je bosse pas, je mange pas. C’est clair, non ?",
            ["TextMapId"] = "voice_ch_char_Linen_vo_topic_04_1",
            },
        ["voice_ch_char_Linen_vo_topic_04_2"] = {
            ["ContentFR"] = "J’aimerais bien, mais les clients, eux, s’en fichent. Tous les deux jours, c’est \"Alors, c’est fini ?\", \"Dépêche-toi un peu !\"… Toujours à me harceler. Si j’avais pas une famille à nourrir, je leur aurais déjà collé quelques bastos.",
            ["TextMapId"] = "voice_ch_char_Linen_vo_topic_04_2",
            },
        ["voice_ch_char_Linen_vo_victory"] = {
            ["ContentFR"] = "C’est tout ? Pathétique.",
            ["TextMapId"] = "voice_ch_char_Linen_vo_victory",
            },
        ["voice_ch_char_Linen_vo_welcome"] = {
            ["ContentFR"] = "Tu as besoin de quelque chose ? Parle vite, j’ai une mission à finir.",
            ["TextMapId"] = "voice_ch_char_Linen_vo_welcome",
            },
        ["voice_ch_char_Lise_vo_appear"] = {
            ["ContentFR"] = "Armes, ressources, alimentation, plan, 17ᵉ contrôle terminé. En attente d’instructions.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_appear",
            },
        ["voice_ch_char_Lise_vo_battleidle"] = {
            ["ContentFR"] = "Pas question de m’arrêter. Je dois continuer à me battre.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_battleidle",
            },
        ["voice_ch_char_Lise_vo_battlestart"] = {
            ["ContentFR"] = "Rhythm Fischer au rapport. En attente de vos ordres !",
            ["TextMapId"] = "voice_ch_char_Lise_vo_battlestart",
            },
        ["voice_ch_char_Lise_vo_be_hit_heavy_r01"] = {
            ["ContentFR"] = "J’ai connu pire.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_be_hit_heavy_r01",
            },
        ["voice_ch_char_Lise_vo_birthday"] = {
            ["ContentFR"] = "Un anniversaire ? Ça fait si longtemps que je n’ai pas fêté quoi que ce soit... Quand j’étais petite, on préparait les anniversaires en famille, longtemps à l’avance. Mais en grandissant, mon frère et moi avons fini par à peine nous croiser... et les anniversaires ont perdu tout leur sens.\
J’ai longtemps rêvé qu’un jour, quand on aurait réussi notre vie, on organiserait une vraie fête, comme celles de la cité intérieure : lustres en cristal, gâteau à la crème, robes en soie... rien ne manquerait. Mais ce rêve ne se réalisera jamais...\
Ah, désolée. Ce n’est pas le moment de parler de tout ça. C’est un jour de fête, après tout.\
Même si je ne peux pas célébrer mon propre anniversaire, je tiens à t’adresser mes vœux les plus sincères. J’espère que tu passeras une journée heureuse, entouré des gens que tu aimes, et que tu en garderas des souvenirs précieux.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_birthday",
            },
        ["voice_ch_char_Lise_vo_companio_01"] = {
            ["ContentFR"] = "Je ne peux pas m’empêcher de vouloir tout remettre en ordre dès que quelque chose est bancal. Mais chez toi, Hilda, tout est parfaitement rangé. C’est vraiment apaisant.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_companio_01",
            },
        ["voice_ch_char_Lise_vo_companio_02"] = {
            ["ContentFR"] = "Ce plan est ultra précis, calibré à la seconde. Le suivre doit procurer une vraie satisfaction. Juste... difficile à croire que ça vienne de l’officier Randy.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_companio_02",
            },
        ["voice_ch_char_Lise_vo_companio_03"] = {
            ["ContentFR"] = "Est-ce que tu pourrais jouer autre chose ? Ta musique est vraiment magnifique, c’est juste que... ce morceau me ramène à de vieux souvenirs que je préfère ne pas raviver.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_companio_03",
            },
        ["voice_ch_char_Lise_vo_die_r01"] = {
            ["ContentFR"] = "Désolée... j’ai rompu ma promesse...",
            ["TextMapId"] = "voice_ch_char_Lise_vo_die_r01",
            },
        ["voice_ch_char_Lise_vo_die_r02"] = {
            ["ContentFR"] = "Ce n’est peut-être... pas une si mauvaise fin...",
            ["TextMapId"] = "voice_ch_char_Lise_vo_die_r02",
            },
        ["voice_ch_char_Lise_vo_fail"] = {
            ["ContentFR"] = "Une fois de plus... je n’ai pas su protéger mes camarades...",
            ["TextMapId"] = "voice_ch_char_Lise_vo_fail",
            },
        ["voice_ch_char_Lise_vo_gain_01"] = {
            ["ContentFR"] = "Rhythm Fischer, adjudante des Veilleurs de Givrelac, VIᵉ Légion de l’Empire Hyperboréen. Que veux-tu ? Si c’est un problème que tu ne peux pas résoudre, je peux t’aider, mais considère cela comme une faveur personnelle, rien d’autre.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_gain_01",
            },
        ["voice_ch_char_Lise_vo_gain_02"] = {
            ["ContentFR"] = "Oui, commandant. Rhythm Fischer à votre service. Ah, c’est toi... désolée, j’oublie parfois que je ne fais plus partie des Veilleurs... toutes mes excuses",
            ["TextMapId"] = "voice_ch_char_Lise_vo_gain_02",
            },
        ["voice_ch_char_Lise_vo_idle"] = {
            ["ContentFR"] = "Tu n’aurais pas une mission à me confier ? Ce n’est pas que j’adore bosser… mais quand je ne fais rien, je me sens nerveuse.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_idle",
            },
        ["voice_ch_char_Lise_vo_lvup"] = {
            ["ContentFR"] = "Ce flux désordonné... pour qui résonne-t-il ?",
            ["TextMapId"] = "voice_ch_char_Lise_vo_lvup",
            },
        ["voice_ch_char_Lise_vo_revive"] = {
            ["ContentFR"] = "J’ai promis de continuer à vivre.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_revive",
            },
        ["voice_ch_char_Lise_vo_skill01_r01"] = {
            ["ContentFR"] = "Décharge !",
            ["TextMapId"] = "voice_ch_char_Lise_vo_skill01_r01",
            },
        ["voice_ch_char_Lise_vo_skill01_r02"] = {
            ["ContentFR"] = "Fracas !",
            ["TextMapId"] = "voice_ch_char_Lise_vo_skill01_r02",
            },
        ["voice_ch_char_Lise_vo_skill02_r01"] = {
            ["ContentFR"] = "Mission presque terminée.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_skill02_r01",
            },
        ["voice_ch_char_Lise_vo_skill02_r02"] = {
            ["ContentFR"] = "L’électricité va vous réduire au silence.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_skill02_r02",
            },
        ["voice_ch_char_Lise_vo_skill02_r03"] = {
            ["ContentFR"] = "Parce que... j’ai choisi de vivre !",
            ["TextMapId"] = "voice_ch_char_Lise_vo_skill02_r03",
            },
        ["voice_ch_char_Lise_vo_topic_01_1"] = {
            ["ContentFR"] = "Ah... tu as remarqué. C’est un harmonica laissé par un proche. Je le garde bien verrouillé, mais j’ai toujours peur qu’il disparaisse, alors je vérifie de temps en temps.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_topic_01_1",
            },
        ["voice_ch_char_Lise_vo_topic_01_2"] = {
            ["ContentFR"] = "En vérité, je ne connais qu’une seule chanson. Celle que ce proche m’a apprise. Je n’ai pas été très rapide à l’apprendre à l'époque... Peut-être parce que je n’ai jamais été doué pour les choses qui nécessitent une certaine expression émotionnelle...",
            ["TextMapId"] = "voice_ch_char_Lise_vo_topic_01_2",
            },
        ["voice_ch_char_Lise_vo_topic_01_3"] = {
            ["ContentFR"] = "Mais lorsque je suis trop tendue... ou trop euphorique, je serre instinctivement l’harmonica dans ma main. Il agit comme une ancre, un rappel de ce qui compte, de ce en quoi je peux croire. Il m’aide toujours à retrouver mon calme.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_topic_01_3",
            },
        ["voice_ch_char_Lise_vo_topic_01_4"] = {
            ["ContentFR"] = "Beaucoup de mes camarades vont voir des médecins à cause du stress, pour s’apaiser ou se stimuler. Moi, je n’en ai pas besoin. Que mon cœur batte trop vite ou trop lentement, l’harmonica m’aide à retrouver un rythme normal.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_topic_01_4",
            },
        ["voice_ch_char_Lise_vo_topic_02_1"] = {
            ["ContentFR"] = "Ça va. La Légion fait partie des rares endroits où l’on est vraiment récompensé pour ses efforts. J’ai gagné ma place ici, et aujourd’hui j’ai même quelques soldats sous ma responsabilité. Je veille à ce qu’ils traitent les Charons et Sola avec le même respect.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_topic_02_1",
            },
        ["voice_ch_char_Lise_vo_topic_02_2"] = {
            ["ContentFR"] = "J’ai entendu de nombreuses plaintes, parfois même des accusations amères, sur la sévérité de la Légion envers les Charons. Je fais tout ce que je peux pour changer cette perception... Peut-être qu’un jour, les gens verront la Légion d’un autre œil.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_topic_02_2",
            },
        ["voice_ch_char_Lise_vo_topic_02_3"] = {
            ["ContentFR"] = "Pas encore. Mais ça viendra peu à peu. À une époque, il n’y avait même pas un seul Charon dans la Légion. Je ne peux pas tout changer à moi seule, mais si je continue à former mes subordonnés dans ce sens, les tensions entre Charons et Sola finiront par s’atténuer.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_topic_02_3",
            },
        ["voice_ch_char_Lise_vo_topic_02_4"] = {
            ["ContentFR"] = "Oui... traiter chacun équitablement, les protéger des Souillés et de la Dégradation... Je pense que ces efforts peuvent vraiment améliorer le quotidien des Charons. Peut-être qu’alors, les soupirs fatigués résonneront un peu moins à Givrelac.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_topic_02_4",
            },
        ["voice_ch_char_Lise_vo_topic_03_1"] = {
            ["ContentFR"] = "Ce n’est pas une question de sérieux. Je ne fais que suivre à la lettre le règlement des Veilleurs.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_topic_03_1",
            },
        ["voice_ch_char_Lise_vo_topic_03_2"] = {
            ["ContentFR"] = "Le règlement des Veilleurs interdit de commenter librement la conduite de ses camarades. Ce serait une entorse à la discipline.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_topic_03_2",
            },
        ["voice_ch_char_Lise_vo_topic_03_3"] = {
            ["ContentFR"] = "Mais pour être honnête, je ne comprends pas ce qui leur passe par la tête. Peut-être qu’ils voient juste les Veilleurs comme un boulot banal. Du moment que leurs supérieurs ne remarquent rien, ils pensent pouvoir faire n’importe quoi.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_topic_03_3",
            },
        ["voice_ch_char_Lise_vo_topic_03_4"] = {
            ["ContentFR"] = "Moi, je pense que ce n’est pas comme ça qu’on devrait vivre. Il faut des règles pour rester fidèle à soi-même. Sans cadre, on finit par baisser ses exigences, vivre au jour le jour... et finir comme un rat dans les égouts.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_topic_03_4",
            },
        ["voice_ch_char_Lise_vo_topic_04_1"] = {
            ["ContentFR"] = "Non, merci... Je n’aime pas trop me voir dans un miroir. Voir mes cornes dès le premier regard me dérange un peu.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_topic_04_1",
            },
        ["voice_ch_char_Lise_vo_topic_04_2"] = {
            ["ContentFR"] = "Non, pas du tout. Je ne renie pas notre apparence. C’est juste que je trouverais mes cornes plus jolies si elles étaient plus régulières, plus symétriques. Ah, ne te méprends pas, je ne critique pas tes cornes...",
            ["TextMapId"] = "voice_ch_char_Lise_vo_topic_04_2",
            },
        ["voice_ch_char_Lise_vo_topic_05_1"] = {
            ["ContentFR"] = "Oui... mais il est devenu si lourd. Trop lourd... Je ne sais pas si j’aurai encore la force de le reprendre, de rejouer.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_topic_05_1",
            },
        ["voice_ch_char_Lise_vo_topic_05_2"] = {
            ["ContentFR"] = "Après tout, cet harmonica portait tous mes espoirs et mes rêves. Aujourd’hui, il ne me rappelle plus que tout ce que j’ai perdu.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_topic_05_2",
            },
        ["voice_ch_char_Lise_vo_topic_05_3"] = {
            ["ContentFR"] = "...D’accord. Je te le promets. Quand je pourrai le reprendre, quand je me sentirai prête à apprendre un nouvel air... tu seras le premier à l’entendre.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_topic_05_3",
            },
        ["voice_ch_char_Lise_vo_topic_06_1"] = {
            ["ContentFR"] = "Je prends des petits boulots, un peu chaque jour. Ça suffit pour couvrir mes besoins. Mais honnêtement, ce n’est plus vraiment pour l’argent. Aujourd’hui, je travaille surtout pour le travail lui-même.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_topic_06_1",
            },
        ["voice_ch_char_Lise_vo_topic_06_2"] = {
            ["ContentFR"] = "Oui... Le travail remplit mes journées, il donne du sens à ce que je fais. Il me rend un peu plus heureuse. Quand je travaille, j’ai l’impression que même le soleil brille plus fort.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_topic_06_2",
            },
        ["voice_ch_char_Lise_vo_topic_07_1"] = {
            ["ContentFR"] = "Mieux que si j’étais restée, en tout cas. La Légion, c’était mon refuge... le lieu où j’avais placé tous mes rêves. Mais ces rêves se sont révélés être des mensonges, et ce que je croyais être un abri s’est transformé en enfer, celui qui a englouti ma famille à jamais...",
            ["TextMapId"] = "voice_ch_char_Lise_vo_topic_07_1",
            },
        ["voice_ch_char_Lise_vo_topic_07_2"] = {
            ["ContentFR"] = "Je ne peux pas tourner la page sur cette haine. Mais je n’arrive pas non plus à pointer mon arme sur ceux qui ont été mes camarades. Je suis perdue... Dis-moi, qu’est-ce que je suis censée faire ?",
            ["TextMapId"] = "voice_ch_char_Lise_vo_topic_07_2",
            },
        ["voice_ch_char_Lise_vo_topic_07_3"] = {
            ["ContentFR"] = "...Pardon, je me suis laissée emporter. Tu as raison, c’est à moi de trouver la réponse, pas à toi de la porter. Même si ça risque de prendre longtemps...",
            ["TextMapId"] = "voice_ch_char_Lise_vo_topic_07_3",
            },
        ["voice_ch_char_Lise_vo_victory"] = {
            ["ContentFR"] = "C’est dommage que ce soit fini si vite. Pour la prochaine, pense à moi. Tu remporteras la victoire, et moi j’aurai de quoi faire.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_victory",
            },
        ["voice_ch_char_Lise_vo_welcome"] = {
            ["ContentFR"] = "Patrouille terminée aujourd’hui. Aucun danger, aucune fissure dans les murs, aucun signe suspect. Menaces écartées. La vie peut reprendre son cours normal. Rapport terminé.",
            ["TextMapId"] = "voice_ch_char_Lise_vo_welcome",
            },
        ["voice_ch_char_Maer_vo_appear"] = {
            ["ContentFR"] = "Alors, où est-ce qu’on va fouiller aujourd’hui ?",
            ["TextMapId"] = "voice_ch_char_Maer_vo_appear",
            },
        ["voice_ch_char_Maer_vo_battleidle"] = {
            ["ContentFR"] = "Allez, allez ! Il y a encore de la place !",
            ["TextMapId"] = "voice_ch_char_Maer_vo_battleidle",
            },
        ["voice_ch_char_Maer_vo_battlestart"] = {
            ["ContentFR"] = "Voyons voir ce qu’on trouve cette fois !",
            ["TextMapId"] = "voice_ch_char_Maer_vo_battlestart",
            },
        ["voice_ch_char_Maer_vo_be_hit_heavy_r01"] = {
            ["ContentFR"] = "Ça fait vraiment mal !",
            ["TextMapId"] = "voice_ch_char_Maer_vo_be_hit_heavy_r01",
            },
        ["voice_ch_char_Maer_vo_be_hit_heavy_r02"] = {
            ["ContentFR"] = "Ouille ouille ouille !",
            ["TextMapId"] = "voice_ch_char_Maer_vo_be_hit_heavy_r02",
            },
        ["voice_ch_char_Maer_vo_birthday"] = {
            ["ContentFR"] = "Joyeux anniversaire ! Tiens, je t’ai fabriqué une petite poupée de Touffu, assortie à la mienne. Je sais que tu meurs d’envie de la serrer dans tes bras depuis longtemps, hein ? Hé hé, cette détective taciturne t’a bien cernée !",
            ["TextMapId"] = "voice_ch_char_Maer_vo_birthday",
            },
        ["voice_ch_char_Maer_vo_companio_01"] = {
            ["ContentFR"] = "Regardez le tissu, l’écusson et le cuir ! Mme Hilda, vous êtes mon ange ! Si vous avez d’autres biens mal acquis qui doivent être \"éliminés correctement\", je suis votre associée ! Vous pouvez compter sur moi pour m’en occuper !",
            ["TextMapId"] = "voice_ch_char_Maer_vo_companio_01",
            },
        ["voice_ch_char_Maer_vo_companio_02"] = {
            ["ContentFR"] = "Petite Fina ! Ça fait une éternité. Tu veux connaître la suite de \"Flocon la Ranger et Gingembre la Détective\" ? Parfait ! Je vais chercher un petit tabouret et te raconter ça tranquillement !",
            ["TextMapId"] = "voice_ch_char_Maer_vo_companio_02",
            },
        ["voice_ch_char_Maer_vo_companio_03"] = {
            ["ContentFR"] = "Je vous assure, Madame la geôlière, que je suis une citoyenne respectable ! Je n’ai jamais volé ni pillé, je me contente juste de récupérer quelques restes dans les poubelles pour calmer ma faim. Même votre zèle ne va pas jusqu’aux ordures, si ?",
            ["TextMapId"] = "voice_ch_char_Maer_vo_companio_03",
            },
        ["voice_ch_char_Maer_vo_companio_04"] = {
            ["ContentFR"] = "Tu vis au jour le jour, n’est-ce pas... ? C’est vraiment difficile. Tu veux venir avec moi faire un peu de récupération ? Ça pourrait te faciliter un peu les choses...",
            ["TextMapId"] = "voice_ch_char_Maer_vo_companio_04",
            },
        ["voice_ch_char_Maer_vo_companio_05"] = {
            ["ContentFR"] = "Camilla ! Toi, la plus gentille et la plus belle de Givrelac ! J’ai un tout petit, tout petit problème, tu pourrais m’aider à m’en sortir... Promis, c’est la dernière fois ! Euh, enfin, la dernière fois ce mois-ci ! Tu vas pas me dire non, hein ?",
            ["TextMapId"] = "voice_ch_char_Maer_vo_companio_05",
            },
        ["voice_ch_char_Maer_vo_die_r01"] = {
            ["ContentFR"] = "Moi aussi... je vais me faire recycler ?",
            ["TextMapId"] = "voice_ch_char_Maer_vo_die_r01",
            },
        ["voice_ch_char_Maer_vo_die_r02"] = {
            ["ContentFR"] = "Si seulement je pouvais voir Givrelac... une dernière fois...",
            ["TextMapId"] = "voice_ch_char_Maer_vo_die_r02",
            },
        ["voice_ch_char_Maer_vo_fail"] = {
            ["ContentFR"] = "Ce n’est pas grave, l’important c’est de rester en vie !",
            ["TextMapId"] = "voice_ch_char_Maer_vo_fail",
            },
        ["voice_ch_char_Maer_vo_gain_1"] = {
            ["ContentFR"] = "Salut toi, bienvenue à Givrelac ! Tu te sens un peu {性别:perdu|perdue} ? Laisse-moi, Margie, te faire découvrir les merveilles de cet endroit. Premier arrêt... une multitude de poubelles surprises !",
            ["TextMapId"] = "voice_ch_char_Maer_vo_gain_1",
            },
        ["voice_ch_char_Maer_vo_gain_2"] = {
            ["ContentFR"] = "Quoi ? Tu as déjà entendu parler de mon titre de \"Princesse des Déchets\" ?! Euh... Ne va surtout pas répéter ça ! Appelle-moi juste Margie. Pas de princesse ici, juste une petite récupératrice de Givrelac !",
            ["TextMapId"] = "voice_ch_char_Maer_vo_gain_2",
            },
        ["voice_ch_char_Maer_vo_idle"] = {
            ["ContentFR"] = "Hmm, quel temps magnifique, parfait pour cueillir des fleurs et sentir bon après ! {nickname}, tu veux venir te balader avec moi ?",
            ["TextMapId"] = "voice_ch_char_Maer_vo_idle",
            },
        ["voice_ch_char_Maer_vo_lvup"] = {
            ["ContentFR"] = "Ouah ! Mes poches à butin sont maintenant super spacieuses !",
            ["TextMapId"] = "voice_ch_char_Maer_vo_lvup",
            },
        ["voice_ch_char_Maer_vo_revive"] = {
            ["ContentFR"] = "Recyclée... et prête à briller !",
            ["TextMapId"] = "voice_ch_char_Maer_vo_revive",
            },
        ["voice_ch_char_Maer_vo_skill01_r01"] = {
            ["ContentFR"] = "Recyclable !",
            ["TextMapId"] = "voice_ch_char_Maer_vo_skill01_r01",
            },
        ["voice_ch_char_Maer_vo_skill01_r02"] = {
            ["ContentFR"] = "Non recyclable !",
            ["TextMapId"] = "voice_ch_char_Maer_vo_skill01_r02",
            },
        ["voice_ch_char_Maer_vo_skill02_r01"] = {
            ["ContentFR"] = "Il est temps d’incinérer quelques déchets !",
            ["TextMapId"] = "voice_ch_char_Maer_vo_skill02_r01",
            },
        ["voice_ch_char_Maer_vo_skill02_r02"] = {
            ["ContentFR"] = "À votre place, parmi les déchets !",
            ["TextMapId"] = "voice_ch_char_Maer_vo_skill02_r02",
            },
        ["voice_ch_char_Maer_vo_skill02_r03"] = {
            ["ContentFR"] = "Brûlez ! Enterrez ! Explosez !",
            ["TextMapId"] = "voice_ch_char_Maer_vo_skill02_r03",
            },
        ["voice_ch_char_Maer_vo_topic_01_1"] = {
            ["ContentFR"] = "Eh bien... il s’agit de donner une nouvelle vie aux objets mis au rebut et d’offrir à ceux qui en ont besoin une chance d’avoir une vie meilleure.",
            ["TextMapId"] = "voice_ch_char_Maer_vo_topic_01_1",
            },
        ["voice_ch_char_Maer_vo_topic_01_2"] = {
            ["ContentFR"] = "Par exemple, transformer les rideaux de velours dont se sont débarrassés des aristocrates en manteaux d’hiver chauds pour les personnes âgées, ou apporter des poupées jetées à des enfants dont les seuls jouets sont des cailloux. Ils seront ravis pendant longtemps.",
            ["TextMapId"] = "voice_ch_char_Maer_vo_topic_01_2",
            },
        ["voice_ch_char_Maer_vo_topic_01_3"] = {
            ["ContentFR"] = "Une fois, j’ai ramené une vieille bibliothèque toute cassée que quelqu’un avait jetée. J’étais épuisée à en tomber, mais rapidement, elle est devenue un terrain de jeu pour une portée de chatons et leurs mamans, ils y ont joué du lever au coucher du soleil. Ça en valait vraiment la peine !",
            ["TextMapId"] = "voice_ch_char_Maer_vo_topic_01_3",
            },
        ["voice_ch_char_Maer_vo_topic_01_4"] = {
            ["ContentFR"] = "Voilà ce que c’est que d’être récupérateur ! Ce sont surtout des petites choses, mais on ne s’ennuie jamais. Alors, qu’en dis-tu, tu veux te joindre à nous ?",
            ["TextMapId"] = "voice_ch_char_Maer_vo_topic_01_4",
            },
        ["voice_ch_char_Maer_vo_topic_02_1"] = {
            ["ContentFR"] = "Chuuuut ! C’est un secret bien gardé des récupérateurs ! Je ne t’aurais pas mis dans la confidence si tu ne m’avais pas aidé à attraper ce voleur !",
            ["TextMapId"] = "voice_ch_char_Maer_vo_topic_02_1",
            },
        ["voice_ch_char_Maer_vo_topic_02_2"] = {
            ["ContentFR"] = "Cette carte répertorie toutes les poubelles de Givrelac. J’y ai noté celles où on trouve les meilleurs trésors. J’ai même remplacé ces poubelles par des modèles plus grands, et je calcule précisément le meilleur moment pour y passer.",
            ["TextMapId"] = "voice_ch_char_Maer_vo_topic_02_2",
            },
        ["voice_ch_char_Maer_vo_topic_02_3"] = {
            ["ContentFR"] = "Mais ce métier dépend beaucoup de la chance, la plupart du temps c’est du hasard...",
            ["TextMapId"] = "voice_ch_char_Maer_vo_topic_02_3",
            },
        ["voice_ch_char_Maer_vo_topic_02_4"] = {
            ["ContentFR"] = "Ah, je savais que tu comprendrais !",
            ["TextMapId"] = "voice_ch_char_Maer_vo_topic_02_4",
            },
        ["voice_ch_char_Maer_vo_topic_03_1"] = {
            ["ContentFR"] = "Non, pas du tout ! J’adore Givrelac de tout mon cœur. C’est juste que je repense souvent aux jours où je parcourais les champs de neige avec mon père, c'est comme ça que j’ai grandi.",
            ["TextMapId"] = "voice_ch_char_Maer_vo_topic_03_1",
            },
        ["voice_ch_char_Maer_vo_topic_03_2"] = {
            ["ContentFR"] = "D’ici, les champs de neige ressemblent à un paysage de conte de fées. Mais une fois que tu y mets les pieds, tu te sens tout petit. Tu peux marcher pendant des heures dans la neige jusqu’aux genoux, cette sensation ne te quitte jamais.",
            ["TextMapId"] = "voice_ch_char_Maer_vo_topic_03_2",
            },
        ["voice_ch_char_Maer_vo_topic_03_3"] = {
            ["ContentFR"] = "Je ne déteste pas ces moments-là. Mais Givrelac animé et vivant est mon préféré !",
            ["TextMapId"] = "voice_ch_char_Maer_vo_topic_03_3",
            },
        ["voice_ch_char_Maer_vo_topic_04_1"] = {
            ["ContentFR"] = "C’est le gros chat qui me suivait dans les champs enneigés quand j’étais petite ! On l’appelait Touffu. Il ne me laissait le caresser qu’en échange d’un peu de viande séchée, mais sa fourrure... oh là là, c’est un vrai bonheur, hé hé hé, la meilleure qui soit !",
            ["TextMapId"] = "voice_ch_char_Maer_vo_topic_04_1",
            },
        ["voice_ch_char_Maer_vo_topic_04_2"] = {
            ["ContentFR"] = "Mmmh... ce n’est sûrement pas un « miaou miaou », c’est plutôt un « grrraou, grrraou, grrraou » !",
            ["TextMapId"] = "voice_ch_char_Maer_vo_topic_04_2",
            },
        ["voice_ch_char_Maer_vo_topic_04_3"] = {
            ["ContentFR"] = "Touffu préfère la vie sauvage à la vie urbaine. Nous avons dû nous séparer, mais elle fera toujours partie de moi, tout comme les champs de neige.",
            ["TextMapId"] = "voice_ch_char_Maer_vo_topic_04_3",
            },
        ["voice_ch_char_Maer_vo_topic_05_1"] = {
            ["ContentFR"] = "Non, non ! Ce n’est pas moi ! Je suis trop grande pour un titre aussi enfantin ! Je t’en supplie, ne m’appelle plus jamais comme ça !",
            ["TextMapId"] = "voice_ch_char_Maer_vo_topic_05_1",
            },
        ["voice_ch_char_Maer_vo_topic_05_2"] = {
            ["ContentFR"] = "Hem hem... Dame Margie, la détective taciturne, la solitaire qui arpente les ruelles de la ville ! Aujourd’hui encore, je vais te révéler les secrets cachés de Givrelac !",
            ["TextMapId"] = "voice_ch_char_Maer_vo_topic_05_2",
            },
        ["voice_ch_char_Maer_vo_topic_05_3"] = {
            ["ContentFR"] = "Hé hé, voilà un titre qui me va bien !",
            ["TextMapId"] = "voice_ch_char_Maer_vo_topic_05_3",
            },
        ["voice_ch_char_Maer_vo_victory"] = {
            ["ContentFR"] = "Quelle belle récolte aujourd’hui !",
            ["TextMapId"] = "voice_ch_char_Maer_vo_victory",
            },
        ["voice_ch_char_Maer_vo_welcome"] = {
            ["ContentFR"] = "En arrivant, j’ai dégagé la neige devant ta porte ! Touchée ? Ça mérite bien un chocolat chaud, non ?",
            ["TextMapId"] = "voice_ch_char_Maer_vo_welcome",
            },
        ["voice_ch_char_NanzhuLight_vo_appear"] = {
            ["ContentFR"] = "Le monde au-delà de l’Île du Purgatoire est plus vaste que dans les livres... et bien plus cruel. Il ne devrait pas être ainsi. Alors, je dois agir.",
            ["TextMapId"] = "voice_ch_char_NanzhuLight_vo_appear",
            },
        ["voice_ch_char_NanzhuLight_vo_battleidle"] = {
            ["ContentFR"] = "Où aller maintenant... Voyons la carte... Hm... ce n’est jamais très clair.",
            ["TextMapId"] = "voice_ch_char_NanzhuLight_vo_battleidle",
            },
        ["voice_ch_char_NanzhuLight_vo_battlestart"] = {
            ["ContentFR"] = "Cette épée a encore son rôle à jouer.",
            ["TextMapId"] = "voice_ch_char_NanzhuLight_vo_battlestart",
            },
        ["voice_ch_char_NanzhuLight_vo_die_r01"] = {
            ["ContentFR"] = "Pas ici... pas maintenant...",
            ["TextMapId"] = "voice_ch_char_NanzhuLight_vo_die_r01",
            },
        ["voice_ch_char_NanzhuLight_vo_die_r02"] = {
            ["ContentFR"] = "J’aimerais tant... retourner là où nous nous sommes fait une promesse...",
            ["TextMapId"] = "voice_ch_char_NanzhuLight_vo_die_r02",
            },
        ["voice_ch_char_NanzhuLight_vo_fail"] = {
            ["ContentFR"] = "La prochaine fois... ils en paieront le prix.",
            ["TextMapId"] = "voice_ch_char_NanzhuLight_vo_fail",
            },
        ["voice_ch_char_NanzhuLight_vo_lvup"] = {
            ["ContentFR"] = "Chaque pas parcouru, chaque parole entendue, chaque rencontre faite m’a permis de mieux comprendre ce monde... et d’aiguiser ma lame.",
            ["TextMapId"] = "voice_ch_char_NanzhuLight_vo_lvup",
            },
        ["voice_ch_char_NanzhuLight_vo_revive"] = {
            ["ContentFR"] = "Était-ce... un cauchemar ?",
            ["TextMapId"] = "voice_ch_char_NanzhuLight_vo_revive",
            },
        ["voice_ch_char_NanzhuLight_vo_skill01_r01"] = {
            ["ContentFR"] = "Disparais.",
            ["TextMapId"] = "voice_ch_char_NanzhuLight_vo_skill01_r01",
            },
        ["voice_ch_char_NanzhuLight_vo_skill01_r02"] = {
            ["ContentFR"] = "Éclat fulgurant.",
            ["TextMapId"] = "voice_ch_char_NanzhuLight_vo_skill01_r02",
            },
        ["voice_ch_char_NanzhuLight_vo_skill02_r01"] = {
            ["ContentFR"] = "Cette fois... c’est moi qui protégerai les autres.",
            ["TextMapId"] = "voice_ch_char_NanzhuLight_vo_skill02_r01",
            },
        ["voice_ch_char_NanzhuLight_vo_skill02_r02"] = {
            ["ContentFR"] = "Vers demain.",
            ["TextMapId"] = "voice_ch_char_NanzhuLight_vo_skill02_r02",
            },
        ["voice_ch_char_NanzhuLight_vo_skill02_r03"] = {
            ["ContentFR"] = "Retourne dans la Mer du Silence.",
            ["TextMapId"] = "voice_ch_char_NanzhuLight_vo_skill02_r03",
            },
        ["voice_ch_char_NanzhuLight_vo_victory"] = {
            ["ContentFR"] = "Encore un pas en avant. Tant que je continuerai d’avancer... j’y parviendrai.",
            ["TextMapId"] = "voice_ch_char_NanzhuLight_vo_victory",
            },
        ["voice_ch_char_Nifu_vo_appear"] = {
            ["ContentFR"] = "Je ferai tout ce qui est en mon modeste pouvoir pour t’aider.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_appear",
            },
        ["voice_ch_char_Nifu_vo_battleidle"] = {
            ["ContentFR"] = "Si la fatigue t’accable, viens te reposer ici un instant. Ne te force pas.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_battleidle",
            },
        ["voice_ch_char_Nifu_vo_battlestart"] = {
            ["ContentFR"] = "À la lisière du fleuve de la vie, je demeure, veilleuse des âmes naissantes.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_battlestart",
            },
        ["voice_ch_char_Nifu_vo_be_hit_heavy_r01"] = {
            ["ContentFR"] = "... Ce n’est rien.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_be_hit_heavy_r01",
            },
        ["voice_ch_char_Nifu_vo_be_hit_heavy_r02"] = {
            ["ContentFR"] = "Cela passera.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_be_hit_heavy_r02",
            },
        ["voice_ch_char_Nifu_vo_birthday"] = {
            ["ContentFR"] = "{性别:Mon enfant, une année de plus s’est écoulée, et je me réjouis sincèrement de ta survie.\
Fais un vœu, car c’est en rêvant que l’on éclaire l’avenir. À ton âge, il est naturel de porter en soi des espoirs qui guident le chemin devant toi.\
Aucune rivière ne coule sans rencontrer de tourments. Même blessé par les épines ou égaré par le courant, je souhaite que tu avances avec courage.\
Et lorsque tu atteindras enfin ta rive, puisses-tu chérir chaque instant du voyage qui t’y a mené.\
Si jamais le doute t’étreint, ou que tu cherches simplement une histoire, viens trouver refuge dans mes bras. Je prierai pour toi, je te bénirai, aujourd’hui, demain, et pour toujours.|Ma chère enfant, une année de plus s’est écoulée, et je me réjouis sincèrement de ta survie. \
Fais un vœu, car c’est en rêvant que l’on éclaire l’avenir. À ton âge, il est naturel de porter en soi des espoirs qui guident le chemin devant toi. \
Aucune rivière ne coule sans rencontrer de tourments. Même blessée par les épines ou égarée par le courant, je souhaite que tu avances avec courage.Et lorsque tu atteindras enfin ta rive, puisses-tu chérir chaque instant du voyage qui t’y a menée. Si jamais le doute t’étreint, ou que tu cherches simplement une histoire, viens trouver refuge dans mes bras. Je prierai pour toi, je te bénirai, aujourd’hui, demain, et pour toujours.}",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_birthday",
            },
        ["voice_ch_char_Nifu_vo_companio_01"] = {
            ["ContentFR"] = "Nul ne peut fuir son passé éternellement. Un jour viendra où tu devras lui faire face... Puisses-tu alors trouver la force qui te permettra de le combattre.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_companio_01",
            },
        ["voice_ch_char_Nifu_vo_companio_02"] = {
            ["ContentFR"] = "Ma chère enfant, il y a en toi une essence qui me semble familière... Serait-ce que toi aussi, tu viens d’une époque révolue, comme moi ?",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_companio_02",
            },
        ["voice_ch_char_Nifu_vo_companio_03"] = {
            ["ContentFR"] = "Bonjour, mon enfant. Hé hé... Oui, nos cornes se ressemblent, et peut-être que nos chemins se sont croisés jadis. Mais ce passé n’est pas le tien, laisse-le de côté, et suis ce que ton cœur désire.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_companio_03",
            },
        ["voice_ch_char_Nifu_vo_companio_04"] = {
            ["ContentFR"] = "Ma mémoire s’étend sur des siècles, et pourtant elle est emplie de tant de cruauté. Peut-être qu’oublier est une forme de bénédiction... Sache que ce qui importe vraiment finira toujours par revenir, même si tu l’oublies.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_companio_04",
            },
        ["voice_ch_char_Nifu_vo_die_r01"] = {
            ["ContentFR"] = "N’aie crainte... comme toujours, je serai bientôt...",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_die_r01",
            },
        ["voice_ch_char_Nifu_vo_die_r02"] = {
            ["ContentFR"] = "Je profite de cette courte trêve, sans douleur ni tourment.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_die_r02",
            },
        ["voice_ch_char_Nifu_vo_fail"] = {
            ["ContentFR"] = "Peu importe. Victoires et défaites ne sont que des instants passagers. Reprends-toi, et repars plus fort.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_fail",
            },
        ["voice_ch_char_Nifu_vo_gain"] = {
            ["ContentFR"] = "Je suis Nifle, la Passeuse de la Mer du Silence. N’aie crainte, la Mer du Silence ne s’étend pas ici, et tu n’es pas une âme errante. Considère-moi simplement comme une passante... ou peut-être une témoin de ton voyage.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_gain",
            },
        ["voice_ch_char_Nifu_vo_idle"] = {
            ["ContentFR"] = "Dans ce monde en proie aux tourments, trouver un havre de paix pour s’accorder un bref répit est déjà un doux privilège.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_idle",
            },
        ["voice_ch_char_Nifu_vo_lvup"] = {
            ["ContentFR"] = "Telle la douce renaissance du printemps, où les herbes percent la terre et les branches s’ornent de bourgeons.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_lvup",
            },
        ["voice_ch_char_Nifu_vo_revive"] = {
            ["ContentFR"] = "Il semble que mon heure ne soit pas encore venue.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_revive",
            },
        ["voice_ch_char_Nifu_vo_skill01_r01"] = {
            ["ContentFR"] = "Battement du samsara.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_skill01_r01",
            },
        ["voice_ch_char_Nifu_vo_skill01_r02"] = {
            ["ContentFR"] = "La nuit s’efface devant l’aurore.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_skill01_r02",
            },
        ["voice_ch_char_Nifu_vo_skill02_r01"] = {
            ["ContentFR"] = "Tels les larmes pleines de grâce de la Mère Embla.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_skill02_r01",
            },
        ["voice_ch_char_Nifu_vo_skill02_r02"] = {
            ["ContentFR"] = "Toutes les rivières retournent à la Mer du Silence.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_skill02_r02",
            },
        ["voice_ch_char_Nifu_vo_skill02_r03"] = {
            ["ContentFR"] = "Âme perdue, sois tranquille, suis ma voix qui te guide.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_skill02_r03",
            },
        ["voice_ch_char_Nifu_vo_topic_01_1"] = {
            ["ContentFR"] = "Oui, durant ces longues années, j’ai parcouru Atlasia, ou plutôt, j’ai erré. J’ai foulé chaque parcelle de terre et caressé chaque grain de sable du bout des doigts.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_topic_01_1",
            },
        ["voice_ch_char_Nifu_vo_topic_01_2"] = {
            ["ContentFR"] = "Quand on a vu assez d’endroits, on réalise que les paysages sont semblables. Qu’il s'agisse des neiges du Nord, des sables de Khemet ou de la fumée qui s’échappe des cheminées de Huaxu, ce ne sont que différentes nuances de brume flottant à travers la forêt.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_topic_01_2",
            },
        ["voice_ch_char_Nifu_vo_topic_01_3"] = {
            ["ContentFR"] = "Si je devais choisir... Ce serait les montagnes et les forêts d’Aethyrie. L’air qui y règne m'apporte la paix.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_topic_01_3",
            },
        ["voice_ch_char_Nifu_vo_topic_01_4"] = {
            ["ContentFR"] = "Peut-être le feras-tu.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_topic_01_4",
            },
        ["voice_ch_char_Nifu_vo_topic_01_5"] = {
            ["ContentFR"] = "Si un jour tu te rends dans la Forêt d’Émeraude, pourrais-tu m’y rapporter un bouquet d’asters blancs ? Sous cette terre reposent mes amis, mon enfant, et une part de moi-même d’autrefois.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_topic_01_5",
            },
        ["voice_ch_char_Nifu_vo_topic_02_1"] = {
            ["ContentFR"] = "La Mer du Silence est le berceau et le dernier refuge de tous les êtres vivants. C’est vers elle que retournent les défunts, et c’est d’elle que naît à nouveau la vie... Tout comme les nuages mourants se fondent en pluie dans la terre, pour que les fleurs y renaissent.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_topic_02_1",
            },
        ["voice_ch_char_Nifu_vo_topic_02_2"] = {
            ["ContentFR"] = "Je le crois, mon enfant. Un jour, tu rejoindras la Mer du Silence, dans les bras de la Déesse Embla.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_topic_02_2",
            },
        ["voice_ch_char_Nifu_vo_topic_02_3"] = {
            ["ContentFR"] = "Mon enfant, aime tout ce que la vie offre, mais n’aie pas peur de la fin. La mort n’est pas une souffrance, mais la conclusion inévitable.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_topic_02_3",
            },
        ["voice_ch_char_Nifu_vo_topic_02_4"] = {
            ["ContentFR"] = "Si tu es {性别:fatigué|fatiguée}, viens te reposer dans mes bras... N’aie crainte, ce ne sera pas un sommeil éternel. Il te reste tant à accomplir.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_topic_02_4",
            },
        ["voice_ch_char_Nifu_vo_topic_03_1"] = {
            ["ContentFR"] = "Cela t’étonne ? Lors de la Grande Migration, j’ai combattu en première ligne. J’étais alors une guerrière chevronnée.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_topic_03_1",
            },
        ["voice_ch_char_Nifu_vo_topic_03_2"] = {
            ["ContentFR"] = "Même si cela remonte à très longtemps, je connais encore les bases du combat.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_topic_03_2",
            },
        ["voice_ch_char_Nifu_vo_topic_03_3"] = {
            ["ContentFR"] = "Au cours de mes errances, il m’est souvent arrivé d’affronter des bêtes errantes. Leurs griffes m’ont laissé des cicatrices, des hématomes... et parfois, une mort que j’aurais dû accepter.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_topic_03_3",
            },
        ["voice_ch_char_Nifu_vo_topic_03_4"] = {
            ["ContentFR"] = "Même la lune éternelle décroît et renaît, changeant chaque nuit. Les êtres humains sont, bien sûr, bien plus complexes... surtout ceux qui, comme moi, ont vécu plusieurs vies au-delà du temps des mortels.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_topic_03_4",
            },
        ["voice_ch_char_Nifu_vo_topic_03_5"] = {
            ["ContentFR"] = "Si tu veux, je te raconterai un jour cette histoire en détail.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_topic_03_5",
            },
        ["voice_ch_char_Nifu_vo_topic_04_1"] = {
            ["ContentFR"] = "Des amis... Si l’on s’en tient à la définition habituelle du mot, alors oui, j’en ai eu beaucoup au fil de ma longue existence.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_topic_04_1",
            },
        ["voice_ch_char_Nifu_vo_topic_04_10"] = {
            ["ContentFR"] = "Ce qui est drôle, c’est que je ne me souviens même plus pourquoi ils s’étaient disputés au départ. C’est étrange, non ? Aujourd’hui, quand je repense à eux, ce sont toujours ces petits riens, ces détails sans importance, qui me reviennent en premier.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_topic_04_10",
            },
        ["voice_ch_char_Nifu_vo_topic_04_11"] = {
            ["ContentFR"] = "Oui, c’était... vraiment des jours heureux. Mais c’était il y a bien longtemps.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_topic_04_11",
            },
        ["voice_ch_char_Nifu_vo_topic_04_2"] = {
            ["ContentFR"] = "Mais quand j’entends ce mot, je pense d’abord à Alexis et Erika, ceux qui m’ont menée hors d’Élysium.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_topic_04_2",
            },
        ["voice_ch_char_Nifu_vo_topic_04_3"] = {
            ["ContentFR"] = "Dans les annales de l’histoire et les récits héroïques, ils sont souvent représentés comme le Sage ayant levé le voile d’ignorance qui recouvrait les dieux, apportant la vérité au monde, et l’Héroïne qui, en croyant en cette vérité, a sacrifié sa vie pour la cause qu’ils servaient...",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_topic_04_3",
            },
        ["voice_ch_char_Nifu_vo_topic_04_4"] = {
            ["ContentFR"] = "Pourtant, dans mes souvenirs, ce sont simplement Alexis et Erika.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_topic_04_4",
            },
        ["voice_ch_char_Nifu_vo_topic_04_5"] = {
            ["ContentFR"] = "Erika était une jeune fille joyeuse et courageuse, adorée de tous. Alexis, brillant mais souvent plongé dans ses pensées, donnait parfois l’impression d’être un peu lent.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_topic_04_5",
            },
        ["voice_ch_char_Nifu_vo_topic_04_6"] = {
            ["ContentFR"] = "Hmm... Je me souviens d’une fois où Alexis cherchait à s’excuser auprès d’Erika pour quelque chose qu’il avait fait. Alors, sur un coup de tête, Erika a pointé du doigt une cible que les soldats utilisaient pour s’entraîner au tir à l’arc, et lui a dit qu’elle le pardonnerait... s’il parvenait à toucher le centre.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_topic_04_6",
            },
        ["voice_ch_char_Nifu_vo_topic_04_7"] = {
            ["ContentFR"] = "Bien sûr, elle ne le pensait pas vraiment. Même les soldats ne touchaient pas toujours le centre... et Alexis, lui, n’était pas fait pour l’arc, mais pour la plume.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_topic_04_7",
            },
        ["voice_ch_char_Nifu_vo_topic_04_8"] = {
            ["ContentFR"] = "Mais il l’a prise au sérieux et s’est entraîné toute la nuit après le départ des soldats.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_topic_04_8",
            },
        ["voice_ch_char_Nifu_vo_topic_04_9"] = {
            ["ContentFR"] = "Comme tu peux l’imaginer, l’histoire n’est pas un conte de héros. Même un esprit aussi brillant que Alexis avait ses limites. Il s’est tant exercé que ses paumes en sont devenues ensanglantées. Erika lui a alors bandé les mains, mais il n’a jamais réussi à toucher le centre de la cible.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_topic_04_9",
            },
        ["voice_ch_char_Nifu_vo_victory"] = {
            ["ContentFR"] = "Les âmes qui s’écoulent vers la Mer du Silence trouveront refuge dans son sein, portées par la pluie nouvelle, pour rejoindre le prochain cours éternel.",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_victory",
            },
        ["voice_ch_char_Nifu_vo_welcome"] = {
            ["ContentFR"] = "Ah, te voilà, {性别:mon cher enfant|ma chère enfant}. Bonjour. Veux-tu me parler de quelque chose ?",
            ["TextMapId"] = "voice_ch_char_Nifu_vo_welcome",
            },
        ["voice_ch_char_Saiqi01_vo_appear"] = {
            ["ContentFR"] = "Ce papillon vient de venir me chercher avec une invitation. Il m’a dit qu’un bal de mi‑été se tiendrait dans une forêt, pleine de pensées tricolores...",
            ["TextMapId"] = "voice_ch_char_Saiqi01_vo_appear",
            },
        ["voice_ch_char_Saiqi01_vo_battlestart"] = {
            ["ContentFR"] = "Allons-y... vers des terres que je n’ai jamais explorées.",
            ["TextMapId"] = "voice_ch_char_Saiqi01_vo_battlestart",
            },
        ["voice_ch_char_Saiqi01_vo_gain"] = {
            ["ContentFR"] = "Regarde ! Ces petites lumières scintillantes... ce sont des lucioles qui font semblant d’être des étoiles ? Et ce vacarme qui ressemble aux mésanges... ce sont les cigales qui chantent ? Ah, le petit faon et le lapin m’ont demandé de jouer pour leur bal, mais je ne sais pas jouer du violon... tu peux m’apprendre ?",
            ["TextMapId"] = "voice_ch_char_Saiqi01_vo_gain",
            },
        ["voice_ch_char_Saiqi01_vo_skill02_r01"] = {
            ["ContentFR"] = "Dansez... pour une vie flamboyante !",
            ["TextMapId"] = "voice_ch_char_Saiqi01_vo_skill02_r01",
            },
        }
  end },
  { MinKey = "voice_ch_char_Saiqi_vo_appear", MaxKey = "voice_ch_char_Tuosi_vo_lvup", Loader = function()
      return {
        ["voice_ch_char_Saiqi_vo_appear"] = {
            ["ContentFR"] = "Je savais que tu m’emmènerais.",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_appear",
            },
        ["voice_ch_char_Saiqi_vo_battleidle"] = {
            ["ContentFR"] = "J’aimerais que ce voyage dure encore...",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_battleidle",
            },
        ["voice_ch_char_Saiqi_vo_battlestart"] = {
            ["ContentFR"] = "Je suis tellement excitée ! Je vais enfin pouvoir me battre avec toi !",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_battlestart",
            },
        ["voice_ch_char_Saiqi_vo_be_hit_heavy_r01"] = {
            ["ContentFR"] = "Je ne reculerai pas !",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_be_hit_heavy_r01",
            },
        ["voice_ch_char_Saiqi_vo_be_hit_heavy_r02"] = {
            ["ContentFR"] = "Tout va bien !",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_be_hit_heavy_r02",
            },
        ["voice_ch_char_Saiqi_vo_be_hit_r01"] = {
            ["ContentFR"] = "Aïe !",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_be_hit_r01",
            },
        ["voice_ch_char_Saiqi_vo_be_hit_r02"] = {
            ["ContentFR"] = "Oh !",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_be_hit_r02",
            },
        ["voice_ch_char_Saiqi_vo_birthday"] = {
            ["ContentFR"] = "Joyeux anniversaire ! J’ai un cadeau pour toi... J’espère qu’il te plaira. C’est un lotus des neiges. Il symbolise la renaissance. Tu sais, depuis notre rencontre, nous avons vécu tant d’aventures ensemble, et j’ai vu ton évolution, ta transformation. C’est pour ça que je trouve que ce lotus est le cadeau parfait pour toi !",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_birthday",
            },
        ["voice_ch_char_Saiqi_vo_companio_01"] = {
            ["ContentFR"] = "J’ai entendu dire que tu avais prévu une grande fête d’anniversaire pour Fina. Je savais que tu avais un cœur attentionné, malgré ton franc-parler. Est-ce que je peux me joindre à toi la prochaine fois que tu lui prépareras une grande surprise pour son anniversaire ?",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_companio_01",
            },
        ["voice_ch_char_Saiqi_vo_companio_02"] = {
            ["ContentFR"] = "En voyant Camilla, je pense à cette taverne animée et accueillante... Quelle chance de vous connaître.",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_companio_02",
            },
        ["voice_ch_char_Saiqi_vo_companio_03"] = {
            ["ContentFR"] = "Tu vas vraiment me raconter l’histoire d’Élysium ? Merci beaucoup ! Hmm... et si je t’offrais une fleur en échange ? Quoi ? Une fleur... à manger ?",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_companio_03",
            },
        ["voice_ch_char_Saiqi_vo_die_r01"] = {
            ["ContentFR"] = "J’ai brillé à tes côtés... et ça me suffit.",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_die_r01",
            },
        ["voice_ch_char_Saiqi_vo_die_r02"] = {
            ["ContentFR"] = "Le voyage s’arrête ici...",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_die_r02",
            },
        ["voice_ch_char_Saiqi_vo_fail"] = {
            ["ContentFR"] = "Ne sois pas triste. Tiens, une fleur... La prochaine fois, la chance nous sourira.",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_fail",
            },
        ["voice_ch_char_Saiqi_vo_gain"] = {
            ["ContentFR"] = "C’est toi... mon {性别:ami venu|amie venue} de loin ? Est-ce ta voix qui m’appelle ?",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_gain",
            },
        ["voice_ch_char_Saiqi_vo_idle"] = {
            ["ContentFR"] = "Parfois, il suffit de vous regarder pour que le temps file... J’aimerais qu’il ralentisse un peu.",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_idle",
            },
        ["voice_ch_char_Saiqi_vo_lvup"] = {
            ["ContentFR"] = "Je peux enfin vous protéger !",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_lvup",
            },
        ["voice_ch_char_Saiqi_vo_revive"] = {
            ["ContentFR"] = "Je suis... encore en vie ?",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_revive",
            },
        ["voice_ch_char_Saiqi_vo_skill01_r01"] = {
            ["ContentFR"] = "Désolée.",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_skill01_r01",
            },
        ["voice_ch_char_Saiqi_vo_skill01_r02"] = {
            ["ContentFR"] = "Dispersez-vous !",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_skill01_r02",
            },
        ["voice_ch_char_Saiqi_vo_skill02_r01"] = {
            ["ContentFR"] = "Fleurissez !",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_skill02_r01",
            },
        ["voice_ch_char_Saiqi_vo_skill02_r02"] = {
            ["ContentFR"] = "Libère-toi, papillon !",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_skill02_r02",
            },
        ["voice_ch_char_Saiqi_vo_skill02_r03"] = {
            ["ContentFR"] = "Flétrissez... ou embrasez-vous au soleil.",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_skill02_r03",
            },
        ["voice_ch_char_Saiqi_vo_topic_01_1"] = {
            ["ContentFR"] = "Merci ! En fait, nous, les Charons, sommes assez résistants au froid, donc pas besoin d’acheter de gros manteaux chers.",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_topic_01_1",
            },
        ["voice_ch_char_Saiqi_vo_topic_01_2"] = {
            ["ContentFR"] = "Ma mère a confectionné cette robe, mais c’est moi qui ai choisi la couleur, ce vert vif, et les détails papillon. Ils seraient parfaitement à leur place dans un endroit chaud, comme le sud.",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_topic_01_2",
            },
        ["voice_ch_char_Saiqi_vo_topic_01_3"] = {
            ["ContentFR"] = "Vraiment ? Merci ! Je n’ai vu que des papillons bleus près de Givrelac. J’aimerais beaucoup voir un jour quelles autres couleurs ils peuvent avoir.",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_topic_01_3",
            },
        ["voice_ch_char_Saiqi_vo_topic_02_1"] = {
            ["ContentFR"] = "Oui, c’est comme ça depuis toujours. On nous traite comme des parasites et j’ai été victime de harcèlement et d’insultes sans raison.",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_topic_02_1",
            },
        ["voice_ch_char_Saiqi_vo_topic_02_2"] = {
            ["ContentFR"] = "Probablement. On dit que « la magie est la source de tous les maux ». Les livres d'histoire affirment que nos ancêtres l’ont utilisée pour régner sur les Solariens il y a plus de mille ans, commettant des actes terribles.",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_topic_02_2",
            },
        ["voice_ch_char_Saiqi_vo_topic_02_3"] = {
            ["ContentFR"] = "Honnêtement, j’ai du mal à y croire... Les Charons que je connais ont trop peur des Solariens pour oser parler en leur présence, alors utiliser la magie, n’en parlons pas.",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_topic_02_3",
            },
        ["voice_ch_char_Saiqi_vo_topic_02_4"] = {
            ["ContentFR"] = "Et la plupart des sorts des Charons sont assez ordinaires, ils ne servent qu’à des choses simples comme allumer des cheminées ou congeler des aliments.",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_topic_02_4",
            },
        ["voice_ch_char_Saiqi_vo_topic_02_5"] = {
            ["ContentFR"] = "Pas du tout. Pourquoi l’un doit-il régner sur l’autre ? Pourquoi Charons et Solariens ne peuvent-ils pas simplement vivre en paix ?",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_topic_02_5",
            },
        ["voice_ch_char_Saiqi_vo_topic_02_6"] = {
            ["ContentFR"] = "Tout ce que je souhaite... c’est que, au retour du printemps, on puisse aller voir les fleurs ensemble. C’est tout.",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_topic_02_6",
            },
        ["voice_ch_char_Saiqi_vo_topic_03_1"] = {
            ["ContentFR"] = "Ah, cela vient peut-être de mon nouveau projet de jardinage. La cour de la Maison d’Hypnos semblait un peu vide avec seulement quelques arbres, alors j’y ai planté des fleurs blanches.",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_topic_03_1",
            },
        ["voice_ch_char_Saiqi_vo_topic_03_2"] = {
            ["ContentFR"] = "Peut-être devrions-nous en planter ici aussi, des muguets, des anémones des bois, des dryades blanches... Lesquelles conviendraient le mieux à cet endroit ?",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_topic_03_2",
            },
        ["voice_ch_char_Saiqi_vo_topic_03_3"] = {
            ["ContentFR"] = "Tu as raison, ce serait mieux si tout le monde décidait ensemble... Je vais leur demander ! Ah, au fait, il y en a une que tu préfères ? Quand elles auront fleuri, je t’en cueillerai.",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_topic_03_3",
            },
        ["voice_ch_char_Saiqi_vo_topic_04_1"] = {
            ["ContentFR"] = "Non, je suis ici depuis toujours. J’entends les trains tous les jours, mais je n’ai jamais vu ce qu’il y a au bout des rails. Si j’en avais l’occasion, j’aimerais vraiment découvrir le monde extérieur.",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_topic_04_1",
            },
        ["voice_ch_char_Saiqi_vo_topic_04_2"] = {
            ["ContentFR"] = "Hmm... Je dirais la capitale, forcément. Et mon oncle Henrik m’a parlé des couchers de soleil magnifiques à Rougerive. Ah, et aussi cette île dans le sud dont tu m’as parlé, l’Île du Purgatoire ! Je veux sentir si l’air marin est vraiment salé !",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_topic_04_2",
            },
        ["voice_ch_char_Saiqi_vo_topic_05_1"] = {
            ["ContentFR"] = "Non, c’est juste que... j’aimerais vous observer un peu plus longtemps. Pour garder une image bien nette de vous tous dans ma tête.",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_topic_05_1",
            },
        ["voice_ch_char_Saiqi_vo_topic_05_2"] = {
            ["ContentFR"] = "Tu veux bien me regarder aussi ? Juste un peu... J’aimerais que tu te souviennes de moi... de moi telle que je suis maintenant.",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_topic_05_2",
            },
        ["voice_ch_char_Saiqi_vo_victory"] = {
            ["ContentFR"] = "Ce voyage restera gravé dans mon cœur.",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_victory",
            },
        ["voice_ch_char_Saiqi_vo_welcome"] = {
            ["ContentFR"] = "Je suis encore ici aujourd’hui... et toi aussi. Quel soulagement.",
            ["TextMapId"] = "voice_ch_char_Saiqi_vo_welcome",
            },
        ["voice_ch_char_Shuimu01_vo_appear"] = {
            ["ContentFR"] = "« Boum... boum... » Tu entends ? C’est mon cœur qui bat, chaque battement exprime mon manque pour toi.",
            ["TextMapId"] = "voice_ch_char_Shuimu01_vo_appear",
            },
        ["voice_ch_char_Shuimu01_vo_battlestart"] = {
            ["ContentFR"] = "Commençons par un petit pas de valse... un, et deux...",
            ["TextMapId"] = "voice_ch_char_Shuimu01_vo_battlestart",
            },
        ["voice_ch_char_Shuimu01_vo_gain"] = {
            ["ContentFR"] = "Avant l’aube, dansons ensemble, pour toujours, pour l’éternité... jusqu’à ce que j’embrasse tes lèvres pâles, jusqu’à ce que la mort nous sépare.",
            ["TextMapId"] = "voice_ch_char_Shuimu01_vo_gain",
            },
        ["voice_ch_char_Shuimu01_vo_skill02_r01"] = {
            ["ContentFR"] = "Que ce voile de sept couches, tel un saphir, se teigne de cramoisi.",
            ["TextMapId"] = "voice_ch_char_Shuimu01_vo_skill02_r01",
            },
        ["voice_ch_char_Shuimu_vo_appear"] = {
            ["ContentFR"] = "Eh, c’est un rendez-vous que tu me proposes ?",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_appear",
            },
        ["voice_ch_char_Shuimu_vo_battleidle"] = {
            ["ContentFR"] = "Dépêche-toi ! Je ne veux pas gâcher notre rendez-vous en arrivant en retard.",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_battleidle",
            },
        ["voice_ch_char_Shuimu_vo_battlestart"] = {
            ["ContentFR"] = "Mon venin bouillonne avec la passion de mon amour...",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_battlestart",
            },
        ["voice_ch_char_Shuimu_vo_be_hit_heavy_r01"] = {
            ["ContentFR"] = "C'est vraiment cruel.",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_be_hit_heavy_r01",
            },
        ["voice_ch_char_Shuimu_vo_be_hit_heavy_r02"] = {
            ["ContentFR"] = "Quel cœur de pierre !",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_be_hit_heavy_r02",
            },
        ["voice_ch_char_Shuimu_vo_be_hit_r01"] = {
            ["ContentFR"] = "Ah !",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_be_hit_r01",
            },
        ["voice_ch_char_Shuimu_vo_be_hit_r02"] = {
            ["ContentFR"] = "Hein !",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_be_hit_r02",
            },
        ["voice_ch_char_Shuimu_vo_birthday"] = {
            ["ContentFR"] = "J’ai entendu dire que c’était ton anniversaire aujourd’hui. Tu veux m’accompagner dans mon jardin aromatique ? J’y ai cultivé des plantes rien que pour toi. Chacune renferme le pur arôme de l’amour, pensé pour nous deux, et rien que nous. Quoi ? Toxique ? rire léger Viens, tu verras bien.",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_birthday",
            },
        ["voice_ch_char_Shuimu_vo_companio_01"] = {
            ["ContentFR"] = "Ce parfum sec... c’est toi, hein ? Ça fait longtemps. Tu veux toujours m’embarquer ? Ça a l’air plutôt amusant... Après tout, même si je te donnais mille chances, je m’échapperais quand même de ton emprise... Tu ne crois pas, Mme la Geôlière ?",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_companio_01",
            },
        ["voice_ch_char_Shuimu_vo_companio_02"] = {
            ["ContentFR"] = "Tu as peur de moi ? Ne t’inquiète pas, je finirai par te faire m’aimer. Viens, sens ce parfum que j’ai créé. Il est très doux, et je suis sûre que tu ressentiras un bonheur que tu n’as jamais connu.",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_companio_02",
            },
        ["voice_ch_char_Shuimu_vo_companio_03"] = {
            ["ContentFR"] = "Tu es aussi bizarre que moi. Tu aimes souffrir, tu savoures la douleur et tu te plonges dans le massacre de tes ennemis sans sourciller... Je comprends. rire léger C’est sûrement ta façon d’exprimer ton amour.",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_companio_03",
            },
        ["voice_ch_char_Shuimu_vo_die_r01"] = {
            ["ContentFR"] = "Dieu de l’Amour... Ne m’abandonne pas...",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_die_r01",
            },
        ["voice_ch_char_Shuimu_vo_die_r02"] = {
            ["ContentFR"] = "Adieu... mon amour...",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_die_r02",
            },
        ["voice_ch_char_Shuimu_vo_fail"] = {
            ["ContentFR"] = "C’est trop triste... J'aurais vraiment besoin d'un peu de réconfort de ta part...",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_fail",
            },
        ["voice_ch_char_Shuimu_vo_gain"] = {
            ["ContentFR"] = "Quelle rencontre romantique ! Est-ce un signe du Dieu de l’Amour ? Je suis Rebecca, la parfumeuse. Que dirais-tu d’essayer mon parfum unique, l’Essence de l’Amour ?",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_gain",
            },
        ["voice_ch_char_Shuimu_vo_idle"] = {
            ["ContentFR"] = "Tu es là pour partager un doux instant à deux avec moi... J’ai hâte que ça commence.",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_idle",
            },
        ["voice_ch_char_Shuimu_vo_lvup"] = {
            ["ContentFR"] = "C’est une récompense pour tout l’amour que je donne ?",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_lvup",
            },
        ["voice_ch_char_Shuimu_vo_revive"] = {
            ["ContentFR"] = "Est-ce ça, le pouvoir de l’amour... ?",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_revive",
            },
        ["voice_ch_char_Shuimu_vo_skill01_r01"] = {
            ["ContentFR"] = "Ne partez pas.",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_skill01_r01",
            },
        ["voice_ch_char_Shuimu_vo_skill01_r02"] = {
            ["ContentFR"] = "Pas de violence.",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_skill01_r02",
            },
        ["voice_ch_char_Shuimu_vo_skill02_r01"] = {
            ["ContentFR"] = "Buvez ce doux poison !",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_skill02_r01",
            },
        ["voice_ch_char_Shuimu_vo_skill02_r02"] = {
            ["ContentFR"] = "Pourrissez dans ce doux parfum !",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_skill02_r02",
            },
        ["voice_ch_char_Shuimu_vo_skill02_r03"] = {
            ["ContentFR"] = "N'ayez crainte, car je vous enverrai au Pays de l'Amour.",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_skill02_r03",
            },
        ["voice_ch_char_Shuimu_vo_topic_01_1"] = {
            ["ContentFR"] = "Oui, j’adore la pluie. Dans les romans que j’ai lus, les rencontres amoureuses ont toujours lieu sous la pluie.",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_topic_01_1",
            },
        ["voice_ch_char_Shuimu_vo_topic_01_2"] = {
            ["ContentFR"] = "As-tu déjà observé ceux qui se protègent de la pluie ? Sous l’auvent, ils se croisent, l’humidité exhale un parfum de verdure, et l’amour naît doucement...",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_topic_01_2",
            },
        ["voice_ch_char_Shuimu_vo_topic_01_3"] = {
            ["ContentFR"] = "Hihi... La prochaine fois qu’il pleuvra, viens donc te promener avec moi. Tu comprendras.",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_topic_01_3",
            },
        ["voice_ch_char_Shuimu_vo_topic_02_1"] = {
            ["ContentFR"] = "Ah, tu t'engages dans une conversation sur l'amour avec moi, comme c'est inattendu.",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_topic_02_1",
            },
        ["voice_ch_char_Shuimu_vo_topic_02_2"] = {
            ["ContentFR"] = "Comment décrire ça ? C’est comme l’eau dans un parfum : elle embrasse chaque ingrédient, en absorbe l’essence, et crée un sillage qui dure longtemps...",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_topic_02_2",
            },
        ["voice_ch_char_Shuimu_vo_topic_02_3"] = {
            ["ContentFR"] = "Il y a bien plus que cela. Ce que je veux, c’est un amour si profond que nous devenions véritablement inséparables... Et si l’un de nous devait disparaître, son corps nourrirait le jardin d’aromates, les fleurs qui y pousseraient deviendraient un parfum, pour flotter à jamais autour de l’autre...",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_topic_02_3",
            },
        ["voice_ch_char_Shuimu_vo_topic_03_1"] = {
            ["ContentFR"] = "Spéciale ? Oui... depuis que je suis petite, beaucoup m’ont traitée de \"monstre\".",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_topic_03_1",
            },
        ["voice_ch_char_Shuimu_vo_topic_03_2"] = {
            ["ContentFR"] = "Chaque fois, les expressions de dégoût sur leurs visages sont désagréables, il faudrait y remédier...",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_topic_03_2",
            },
        ["voice_ch_char_Shuimu_vo_topic_03_3"] = {
            ["ContentFR"] = "Peut-être qu’un peu de mon venin rendra leur expression moins dur... Hihi.",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_topic_03_3",
            },
        ["voice_ch_char_Shuimu_vo_topic_03_4"] = {
            ["ContentFR"] = "Dis-moi, quand tu dis \"spéciale\", tu veux dire spécial comme un monstre... ou plutôt spécialement envoûtante ?",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_topic_03_4",
            },
        ["voice_ch_char_Shuimu_vo_topic_04_1"] = {
            ["ContentFR"] = "Je vais très bien. Mon venin fait partie de moi, comme un cadeau du Dieu de l'Amour, il est inoffensif pour moi et m’aidera à trouver l’amour de ma vie.",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_topic_04_1",
            },
        ["voice_ch_char_Shuimu_vo_topic_04_2"] = {
            ["ContentFR"] = "Bien sûr. Même si cela me fait souvent passer pour un monstre, cela me distingue également des autres. Je pense que le partenaire destiné à un monstre doit être quelqu'un de très spécial, tu ne crois pas ?",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_topic_04_2",
            },
        ["voice_ch_char_Shuimu_vo_topic_05_1"] = {
            ["ContentFR"] = "C’est mon parfum personnel : en notes de tête, une rencontre intense, en notes de cœur, des mots doux qui fixent le parfum, et en notes de fond, une amertume persistante.",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_topic_05_1",
            },
        ["voice_ch_char_Shuimu_vo_topic_05_2"] = {
            ["ContentFR"] = "C’est mon petit secret. Mais je serais ravie de te guider moi-même, pas à pas, tout au long du processus de fabrication.",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_topic_05_2",
            },
        ["voice_ch_char_Shuimu_vo_victory"] = {
            ["ContentFR"] = "Ils manquent de foi en l’amour, alors je les châtie à la place du Dieu de l’Amour.",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_victory",
            },
        ["voice_ch_char_Shuimu_vo_welcome"] = {
            ["ContentFR"] = "Je t’ai attendue ici depuis que je me suis réveillée. Mon venin est presque épuisé... C’est donc une bonne chose que tu sois venu. Je le sens à nouveau bouillonner dans mes veines. Peux-tu t’approcher un peu plus ?",
            ["TextMapId"] = "voice_ch_char_Shuimu_vo_welcome",
            },
        ["voice_ch_char_Songlu01_vo_appear"] = {
            ["ContentFR"] = "Pied gauche, pied droit, puis un petit tour... Ouaaah ! J’ai failli me marcher sur le pied ! Filbert, montre-moi encore !",
            ["TextMapId"] = "voice_ch_char_Songlu01_vo_appear",
            },
        ["voice_ch_char_Songlu01_vo_battlestart"] = {
            ["ContentFR"] = "Vite, vite ! Donne-moi ta main et tournons ensemble !",
            ["TextMapId"] = "voice_ch_char_Songlu01_vo_battlestart",
            },
        ["voice_ch_char_Songlu01_vo_gain"] = {
            ["ContentFR"] = "Waouh ! Des étoiles qui scintillent, de petits tournesols, tout moelleux comme du pain tout juste cuit... Un si joli costume, je ne l’ai jamais porté ! Oh ? Filbert dit qu’elle a hâte d’aller danser !",
            ["TextMapId"] = "voice_ch_char_Songlu01_vo_gain",
            },
        ["voice_ch_char_Songlu01_vo_skill02_r01"] = {
            ["ContentFR"] = "Prépare-toi à voir le suuuuper pas de danse de Filbert !",
            ["TextMapId"] = "voice_ch_char_Songlu01_vo_skill02_r01",
            },
        ["voice_ch_char_Songlu_vo_appear"] = {
            ["ContentFR"] = "Filbert, debout, debout ! C’est l’heure de partir !",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_appear",
            },
        ["voice_ch_char_Songlu_vo_battleidle"] = {
            ["ContentFR"] = "Miam miam...",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_battleidle",
            },
        ["voice_ch_char_Songlu_vo_battlestart"] = {
            ["ContentFR"] = "Filbert, fonce fonce fonce !",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_battlestart",
            },
        ["voice_ch_char_Songlu_vo_be_hit_heavy_r01"] = {
            ["ContentFR"] = "C’est pas juste...",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_be_hit_heavy_r01",
            },
        ["voice_ch_char_Songlu_vo_be_hit_r01"] = {
            ["ContentFR"] = "Aïe aïe aïe...",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_be_hit_r01",
            },
        ["voice_ch_char_Songlu_vo_birthday"] = {
            ["ContentFR"] = "Joyeux anniversaire ! J’avais préparé un énorme gâteau à la crème, avec des noix et de la confiture. Mais son odeur a attiré beaucoup de monde... alors... euh... je l’ai partagé avec eux aussi. Mais ne t’inquiète pas, je t’ai gardé une part ! Regarde, j’ai choisi la plus grosse, avec plein de confiture et des baies boréales dessus. Goûte-la, elle est bien meilleure que nos rations militaires !",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_birthday",
            },
        ["voice_ch_char_Songlu_vo_companio_01"] = {
            ["ContentFR"] = "Tu as trouvé des patates qui germent dans le bac ? Ne les jette pas ! On les plante, on les arrose, et on aura plein de patates pour tout le monde !",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_companio_01",
            },
        ["voice_ch_char_Songlu_vo_companio_02"] = {
            ["ContentFR"] = "Tu travailles tout le temps... T’as pas un petit creux ? Tu devrais rejoindre l’Église ! Moi, je prends soin des ventres vides.",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_companio_02",
            },
        ["voice_ch_char_Songlu_vo_companio_03"] = {
            ["ContentFR"] = "Coucou ! Dis, c’est vrai que prier, ça remplit l’âme ? Moi je trouve qu’un bon repas, ça marche pareil ! Tu préfères quoi, toi ?",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_companio_03",
            },
        ["voice_ch_char_Songlu_vo_die_r01"] = {
            ["ContentFR"] = "Je vois... d’énormes épis de blé... plus gros que des baies...",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_die_r01",
            },
        ["voice_ch_char_Songlu_vo_die_r02"] = {
            ["ContentFR"] = "Mais j’avais bien mangé pourtant...",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_die_r02",
            },
        ["voice_ch_char_Songlu_vo_fail"] = {
            ["ContentFR"] = "Oh non, Filbert ! Tu t’es fait mal ? Allez, un gros câlin !",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_fail",
            },
        ["voice_ch_char_Songlu_vo_gain"] = {
            ["ContentFR"] = "Coucou ! Moi, c’est Truffle, la commissaire au ravitaillement, et voici mes fidèles compagnons, Filbert et sa famille ! Voilà, c’est tout pour moi ! Oh, tes grands yeux me disent que t’as sûrement faim, non ?",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_gain",
            },
        ["voice_ch_char_Songlu_vo_idle"] = {
            ["ContentFR"] = "Pause goûter, Filbert ! Un peu de blé, quelques noix... et hop, des fleurs pour grignoter. Et si t’as plus faim, je les mettrai sur mon chapeau !",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_idle",
            },
        ["voice_ch_char_Songlu_vo_lvup"] = {
            ["ContentFR"] = "Faut manger pour devenir plus fort ! Un ventre vide, c’est pas bon pour la bagarre !",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_lvup",
            },
        ["voice_ch_char_Songlu_vo_revive"] = {
            ["ContentFR"] = "La nourriture d'urgence est dégoûtante... Mais au moins, elle me remplit l'estomac.",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_revive",
            },
        ["voice_ch_char_Songlu_vo_skill01_r01"] = {
            ["ContentFR"] = "On va vous faire valser !",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_skill01_r01",
            },
        ["voice_ch_char_Songlu_vo_skill01_r02"] = {
            ["ContentFR"] = "Ça va faire mal !",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_skill01_r02",
            },
        ["voice_ch_char_Songlu_vo_skill02_r01"] = {
            ["ContentFR"] = "Livraison spéciale ! On va tous se régaler !",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_skill02_r01",
            },
        ["voice_ch_char_Songlu_vo_skill02_r02"] = {
            ["ContentFR"] = "La commissaire est arrivé, adieu les estomacs vides !",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_skill02_r02",
            },
        ["voice_ch_char_Songlu_vo_skill02_r03"] = {
            ["ContentFR"] = "Donnez les provisions, ou Filbert vous écrase comme une crêpe !",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_skill02_r03",
            },
        ["voice_ch_char_Songlu_vo_topic_01_1"] = {
            ["ContentFR"] = "Hein ? Tu sais pas ? Moi, je fais en sorte que tout le monde ait à manger tous les jours, avec plein de bonnes choses !",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_topic_01_1",
            },
        ["voice_ch_char_Songlu_vo_topic_01_2"] = {
            ["ContentFR"] = "Par exemple, je vais chercher plein de choses dans la nature, et Filbert les ramène en ville. Après, on demande à Monsieur Barbe, le boulanger, de préparer des bons petits plats pour tout le monde.",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_topic_01_2",
            },
        ["voice_ch_char_Songlu_vo_topic_01_3"] = {
            ["ContentFR"] = "Et devine quoi ? Marchander avec Monsieur Barbe, c’est aussi mon boulot ! Hé hé.",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_topic_01_3",
            },
        ["voice_ch_char_Songlu_vo_topic_01_4"] = {
            ["ContentFR"] = "Ah non, pas du tout ! Les autres, ils sont plus à faire des papiers, des demandes, et puis après, plein de nourriture arrive par train.",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_topic_01_4",
            },
        ["voice_ch_char_Songlu_vo_topic_01_5"] = {
            ["ContentFR"] = "Mais dans notre petite ville, moi et Filbert, ça suffit ! Sinon, il faudrait que j’apprenne à faire les papiers… et c’est trop compliqué pour moi !",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_topic_01_5",
            },
        ["voice_ch_char_Songlu_vo_topic_02_1"] = {
            ["ContentFR"] = "Bah, peut-être ? Je ne sais pas trop. Mais Filbert ne fonce que sur les vilains qui crient et se bagarrent ! Ils l'ont bien cherché !",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_topic_02_1",
            },
        ["voice_ch_char_Songlu_vo_topic_02_2"] = {
            ["ContentFR"] = "Ces vilains se battent et ont toujours faim après. Ils feraient mieux de cultiver la terre, comme ça y’aurait plus de nourriture pour tout le monde.",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_topic_02_2",
            },
        ["voice_ch_char_Songlu_vo_topic_02_3"] = {
            ["ContentFR"] = "Évidemment que je déteste ça ! Se battre, ça finit toujours par creuser l’estomac... et c’est pas drôle du tout. On m’a dit qu’en temps de guerre, personne ne mange à sa faim. J’espère que ça m’arrivera jamais.",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_topic_02_3",
            },
        ["voice_ch_char_Songlu_vo_topic_02_4"] = {
            ["ContentFR"] = "Oui ! Tous ceux qui affament les autres finiront tous par se faire renverser par Filbert !",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_topic_02_4",
            },
        ["voice_ch_char_Songlu_vo_topic_03_1"] = {
            ["ContentFR"] = "Oui, elle mange pas mal, mais elle trouve sa propre nourriture. Même à travers plusieurs ruisseaux, elle sent les baies mûres et me porte pour qu’on aille les chercher. Incroyable, non ?",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_topic_03_1",
            },
        ["voice_ch_char_Songlu_vo_topic_03_2"] = {
            ["ContentFR"] = "T’en fais pas ! Filbert apporte toujours plus de nourriture. Alors ne te moque jamais d'elle, ça la blesserait, et moi aussi.",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_topic_03_2",
            },
        ["voice_ch_char_Songlu_vo_topic_04_1"] = {
            ["ContentFR"] = "Merci ! Mais ce sont des shorts, pas une robe. Avant, c’était une belle robe blanche longue, mais la couturière me l’a changé en short.",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_topic_04_1",
            },
        ["voice_ch_char_Songlu_vo_topic_04_2"] = {
            ["ContentFR"] = "Parce que courir en robe, c’est pas pratique. Une fois, j'ai trébuché sur l'ourlet et tout le pain que je portais est tombé.",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_topic_04_2",
            },
        ["voice_ch_char_Songlu_vo_topic_04_3"] = {
            ["ContentFR"] = "Donc, si un jour personne n’a plus faim, je les ferai changer à nouveau en robe !",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_topic_04_3",
            },
        ["voice_ch_char_Songlu_vo_topic_05_1"] = {
            ["ContentFR"] = "Pas du tout ! Je médite. Je fais partie de l’Église Élyséenne, après tout, alors j'essaie de réfléchir profondément de temps en temps.",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_topic_05_1",
            },
        ["voice_ch_char_Songlu_vo_topic_05_2"] = {
            ["ContentFR"] = "Je me posais souvent la question, mais les prêtres disait que c'était... blasphématoire ou quelque chose comme ça. Alors j'ai arrêté d'y penser.",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_topic_05_2",
            },
        ["voice_ch_char_Songlu_vo_topic_05_3"] = {
            ["ContentFR"] = "J’ai jamais trop compris ce qu’ils racontent... Ils disent que la gourmandise, c’est un péché grave, mais plus t’es important, plus tu manges.",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_topic_05_3",
            },
        ["voice_ch_char_Songlu_vo_victory"] = {
            ["ContentFR"] = "On devrait faire un banquet ! Euh... Non, ce serait du gaspillage.",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_victory",
            },
        ["voice_ch_char_Songlu_vo_welcome"] = {
            ["ContentFR"] = "Le soleil brille fort, les nuages sont tout doux, et les petits oiseaux ont bien mangé. Est-ce que ton ventre fait aussi des petits bruits ? On va manger quelque chose ?",
            ["TextMapId"] = "voice_ch_char_Songlu_vo_welcome",
            },
        ["voice_ch_char_Suyi_vo_appear"] = {
            ["ContentFR"] = "Comme on dit : mieux vaut demander de l’aide que lutter seul. Tu as bien fait de venir me voir !",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_appear",
            },
        ["voice_ch_char_Suyi_vo_battleidle"] = {
            ["ContentFR"] = "Aucune menace immédiate... Fengshi n° 3, active le mode veille.",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_battleidle",
            },
        ["voice_ch_char_Suyi_vo_battlestart"] = {
            ["ContentFR"] = "Fengshi n° 3, configuration défensive déployée. Début des tests.",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_battlestart",
            },
        ["voice_ch_char_Suyi_vo_be_hit_heavy_r01"] = {
            ["ContentFR"] = "Je n’ai rien perdu comme pièce... ?",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_be_hit_heavy_r01",
            },
        ["voice_ch_char_Suyi_vo_be_hit_heavy_r02"] = {
            ["ContentFR"] = "Mince !",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_be_hit_heavy_r02",
            },
        ["voice_ch_char_Suyi_vo_be_hit_r01"] = {
            ["ContentFR"] = "Ça ne fait même pas mal !",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_be_hit_r01",
            },
        ["voice_ch_char_Suyi_vo_be_hit_r02"] = {
            ["ContentFR"] = "Hmpf !",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_be_hit_r02",
            },
        ["voice_ch_char_Suyi_vo_birthday"] = {
            ["ContentFR"] = "Ton cadeau est prêt depuis longtemps déjà. Joyeux anniversaire. Quoi ? Je ne m’y suis pas prise si tôt que ça... seulement trois mois à l’avance. Hum. Bref. Après quelques ajustements, Fengshi n° 3 peut maintenant transporter un passager. Alors... ça te dirait de venir voir le ciel avec moi ?",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_birthday",
            },
        ["voice_ch_char_Suyi_vo_companio_01"] = {
            ["ContentFR"] = "Les gens de Luca sont toujours aussi directs ? On vient à peine de commencer à discuter et tu veux déjà me prendre dans tes bras— N-Non ! Pas maintenant !",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_companio_01",
            },
        ["voice_ch_char_Suyi_vo_companio_02"] = {
            ["ContentFR"] = "Encore une nouvelle épée ?! Tu crois que le budget des Pics Extérieurs est illimité ? Non ! Même à genoux ça ne marchera pas ! Et m’appeler « grande-tante » ne changera rien ! Cette fois, je ne me laisserai pas convaincre !",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_companio_02",
            },
        ["voice_ch_char_Suyi_vo_companio_03"] = {
            ["ContentFR"] = "Tes ailes... elles sont magnifiques. Mais les miennes ne sont pas mal non plus. On fait la course ?",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_companio_03",
            },
        ["voice_ch_char_Suyi_vo_die_r01"] = {
            ["ContentFR"] = "Tante... pardon... je n’ai pas réussi...",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_die_r01",
            },
        ["voice_ch_char_Suyi_vo_die_r02"] = {
            ["ContentFR"] = "Un oiseau... doit retourner au ciel...",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_die_r02",
            },
        ["voice_ch_char_Suyi_vo_fail"] = {
            ["ContentFR"] = "Puissance... modules... moteur... Où est l’erreur... ?",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_fail",
            },
        ["voice_ch_char_Suyi_vo_gain"] = {
            ["ContentFR"] = "Les disciples de la Secte Jishu se serrent toujours les coudes. Si tu as des ennuis à Huaxu, appelle-moi. Je m’en occupe !",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_gain",
            },
        ["voice_ch_char_Suyi_vo_idle"] = {
            ["ContentFR"] = "Tu sors {性别:tout seul ... ? Tu es sûr|toute seule... ? Tu es sûre} que ça ira sans moi ?",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_idle",
            },
        ["voice_ch_char_Suyi_vo_lvup"] = {
            ["ContentFR"] = "Exactement. Je suis la partenaire idéale pour combattre à tes côtés.",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_lvup",
            },
        ["voice_ch_char_Suyi_vo_revive"] = {
            ["ContentFR"] = "Ce n’est pas fini... Ne me sous-estime pas !",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_revive",
            },
        ["voice_ch_char_Suyi_vo_skill01_r01"] = {
            ["ContentFR"] = "Mode Poursuite du soleil activé.",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_skill01_r01",
            },
        ["voice_ch_char_Suyi_vo_skill01_r02"] = {
            ["ContentFR"] = "Équilibre... stable.",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_skill01_r02",
            },
        ["voice_ch_char_Suyi_vo_skill02_r01"] = {
            ["ContentFR"] = "Mode annihilation stellaire activé.",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_skill02_r01",
            },
        ["voice_ch_char_Suyi_vo_skill02_r02"] = {
            ["ContentFR"] = "Feu concentré !",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_skill02_r02",
            },
        ["voice_ch_char_Suyi_vo_skill02_r03"] = {
            ["ContentFR"] = "Collecte des données terminée. Il faut que je note ça...",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_skill02_r03",
            },
        ["voice_ch_char_Suyi_vo_skill02_r04"] = {
            ["ContentFR"] = "Bon travail, Fengshi n° 3.",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_skill02_r04",
            },
        ["voice_ch_char_Suyi_vo_skill02_r05"] = {
            ["ContentFR"] = "Ouah... voler comme ça, c’est génial !",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_skill02_r05",
            },
        ["voice_ch_char_Suyi_vo_topic_01_1"] = {
            ["ContentFR"] = "Assembler des mécanismes, polir des engrenages, chercher de nouveaux matériaux... et bricoler jusqu’à obtenir une version encore meilleure.",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_topic_01_1",
            },
        ["voice_ch_char_Suyi_vo_topic_01_2"] = {
            ["ContentFR"] = "Tu te souviens quand Oncle Tang s’est cassé la jambe ? Comme j’avais un peu de temps, j’ai commencé à travailler sur une monture capable de décoller plus doucement. Les disciples de la Secte Jishu veulent toujours des résultats, quitte à y laisser leur peau... Je ne vais pas laisser cette mentalité continuer.",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_topic_01_2",
            },
        ["voice_ch_char_Suyi_vo_topic_01_3"] = {
            ["ContentFR"] = "Me fatiguer ? Qu’est-ce qui pourrait être plus intéressant que ça ? Il suffit de démonter un mécanisme en composants dans sa tête... puis de le reconstruire dans la réalité. Le moment où tout s’assemble et fonctionne enfin... c’est le meilleur sentiment du monde !",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_topic_01_3",
            },
        ["voice_ch_char_Suyi_vo_topic_01_4"] = {
            ["ContentFR"] = "Tu veux essayer aussi ? Le meilleur artisan de tous les Pics Extérieurs est justement libre pour t’apprendre.",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_topic_01_4",
            },
        ["voice_ch_char_Suyi_vo_topic_02_1"] = {
            ["ContentFR"] = "Dans la Secte Jishu, comme chez les vagabonds, la lignée compte énormément. Par exemple, si un maître de quatre-vingt-dix ans prend un enfant de dix ans comme dernier disciple... la moitié de la secte devra ensuite appeler cet enfant « oncle ».",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_topic_02_1",
            },
        ["voice_ch_char_Suyi_vo_topic_02_2"] = {
            ["ContentFR"] = "Moi, j’ai eu de la chance. Mon maître — enfin, ma tante — a un rang très élevé. Donc par extension, le mien l’est aussi.",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_topic_02_2",
            },
        ["voice_ch_char_Suyi_vo_topic_02_3"] = {
            ["ContentFR"] = "Kezhou, lui, a moins de chance. Son maître Yan Shanting est plus bas dans la hiérarchie... Donc selon les règles, il doit m’appeler grande-tante~",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_topic_02_3",
            },
        ["voice_ch_char_Suyi_vo_topic_02_4"] = {
            ["ContentFR"] = "Maître Gongshang a aussi un rang très élevé... Attends que je calcule... Oh ! On est de la même génération !",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_topic_02_4",
            },
        ["voice_ch_char_Suyi_vo_topic_02_5"] = {
            ["ContentFR"] = "Héhé. Si Kezhou te manque de respect, tu peux exiger qu’il t’appelle {性别:grand-père|grand-mère}.",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_topic_02_5",
            },
        ["voice_ch_char_Suyi_vo_topic_02_6"] = {
            ["ContentFR"] = "Attends... Je me souviens que Snow t’appelle son petit larbin... Ça veut dire qu’elle est ton maître ? ... Attends une seconde. Ne me dis pas que la personne la plus haut placée parmi nous est en réalité une toute petite Luno ?!",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_topic_02_6",
            },
        ["voice_ch_char_Suyi_vo_topic_03_1"] = {
            ["ContentFR"] = "Oh, ça ? C’est Qingluan Type III, mon nouveau compagnon !",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_topic_03_1",
            },
        ["voice_ch_char_Suyi_vo_topic_03_2"] = {
            ["ContentFR"] = "Regarde, on dirait presque une vraie mouette nuageuse, non ? J’ai simplifié la procédure d’activation. Il suffit d’appuyer sur le dessus de la tête pour activer le mode de vol mimétique. En parlant de vol—",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_topic_03_2",
            },
        ["voice_ch_char_Suyi_vo_topic_03_3"] = {
            ["ContentFR"] = "Et ces plumes aussi, c’est tout un travail ! Je récupère les plumes naturellement tombées des mouettes nuageuses, puis je les scelle avec une technique hydrofuge améliorée. Ça n’ajoute presque aucun poids.",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_topic_03_3",
            },
        ["voice_ch_char_Suyi_vo_topic_03_4"] = {
            ["ContentFR"] = "Les couleurs ne s’altèrent pas, il reste toujours tout doux... et au moins elle ne te lacère pas le bras comme un vrai oiseau. Tout le charme, sans les griffures. Le compagnon parfait.",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_topic_03_4",
            },
        ["voice_ch_char_Suyi_vo_topic_03_5"] = {
            ["ContentFR"] = "Les mouettes nuageuses appartiennent au ciel. Si on en élève une, il faut la garder dans une cage. Et si je capturais un animal juste pour le regarder... En quoi serais-je différente de l’ancienne Secte Xuanheng ?",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_topic_03_5",
            },
        ["voice_ch_char_Suyi_vo_topic_03_6"] = {
            ["ContentFR"] = "Certains animaux peuvent vivre aux côtés des humains. Mais les mouettes nuageuses n’en font clairement pas partie. Leur bec acéré, leur longue queue, leurs ailes faites pour fendre le vent... tout montre une chose. Elles appartiennent au ciel. Pas à la paume de quelqu’un.",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_topic_03_6",
            },
        ["voice_ch_char_Suyi_vo_topic_04_1"] = {
            ["ContentFR"] = "Hmm... bonne question.",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_topic_04_1",
            },
        ["voice_ch_char_Suyi_vo_topic_04_2"] = {
            ["ContentFR"] = "On s’est rassemblés parce qu’on partageait les mêmes difficultés. Et maintenant on lutte pour le même objectif. On se comprend. On se fait confiance. Au combat, on se couvre mutuellement... et quand on est fatigués, on avance ensemble. C’est... vraiment un endroit formidable.",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_topic_04_2",
            },
        ["voice_ch_char_Suyi_vo_topic_04_3"] = {
            ["ContentFR"] = "Pour beaucoup ici, les Pics Extérieurs sont comme une maison.",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_topic_04_3",
            },
        ["voice_ch_char_Suyi_vo_topic_04_4"] = {
            ["ContentFR"] = "Moi ? Euh... bien sûr que c’est chez moi !",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_topic_04_4",
            },
        ["voice_ch_char_Suyi_vo_topic_04_5"] = {
            ["ContentFR"] = "Tu es vraiment perspicace. C’est l’instinct d’un Chasseur de Phoxène ? Et ça ne sert pas seulement au combat... tu arrives aussi à comprendre les gens. Si seulement mon système de navigation mécanique était aussi précis que toi...",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_topic_04_5",
            },
        ["voice_ch_char_Suyi_vo_topic_04_6"] = {
            ["ContentFR"] = "Je suis juste... un peu perdue. À quoi ressemble vraiment un foyer ?",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_topic_04_6",
            },
        ["voice_ch_char_Suyi_vo_topic_04_7"] = {
            ["ContentFR"] = "Alors... si on ne peut plus y retourner... est-ce que ça reste un foyer ? ... Désolée. Oublie ce que je viens de dire.",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_topic_04_7",
            },
        ["voice_ch_char_Suyi_vo_victory"] = {
            ["ContentFR"] = "Très bien. Test en conditions réelles réussi. Passons maintenant à l’analyse des données.",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_victory",
            },
        ["voice_ch_char_Suyi_vo_welcome"] = {
            ["ContentFR"] = "Ah, te voilà ! Tu viens voir la nouvelle modification du Qingluan Type II, pas vrai ? Regarde ça— Hein ? Tu voulais juste discuter ?",
            ["TextMapId"] = "voice_ch_char_Suyi_vo_welcome",
            },
        ["voice_ch_char_Tuosi02_attack_r01"] = {
            ["ContentFR"] = "Entendez leurs hurlements !",
            ["TextMapId"] = "voice_ch_char_Tuosi02_attack_r01",
            },
        ["voice_ch_char_Tuosi02_shoot_r01"] = {
            ["ContentFR"] = "Proie repérée.",
            ["TextMapId"] = "voice_ch_char_Tuosi02_shoot_r01",
            },
        ["voice_ch_char_Tuosi02_skill01_r01"] = {
            ["ContentFR"] = "Il n’y a pas d’échappatoire.",
            ["TextMapId"] = "voice_ch_char_Tuosi02_skill01_r01",
            },
        ["voice_ch_char_Tuosi02_vo_be_hit_heavy_r01"] = {
            ["ContentFR"] = "Encore ça...",
            ["TextMapId"] = "voice_ch_char_Tuosi02_vo_be_hit_heavy_r01",
            },
        ["voice_ch_char_Tuosi02_vo_be_hit_heavy_r02"] = {
            ["ContentFR"] = "Déchire-les.",
            ["TextMapId"] = "voice_ch_char_Tuosi02_vo_be_hit_heavy_r02",
            },
        ["voice_ch_char_Tuosi_vo_appear"] = {
            ["ContentFR"] = "Tu m’as offert une nouvelle scène à fouler.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_appear",
            },
        ["voice_ch_char_Tuosi_vo_battleidle"] = {
            ["ContentFR"] = "À quoi ressemblais-je autrefois...",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_battleidle",
            },
        ["voice_ch_char_Tuosi_vo_battlestart"] = {
            ["ContentFR"] = "À présent, laissez place à une aventure pleine de grandeur.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_battlestart",
            },
        ["voice_ch_char_Tuosi_vo_be_hit_heavy_r01"] = {
            ["ContentFR"] = "Je vais bien.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_be_hit_heavy_r01",
            },
        ["voice_ch_char_Tuosi_vo_be_hit_heavy_r02"] = {
            ["ContentFR"] = "Une tragédie.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_be_hit_heavy_r02",
            },
        ["voice_ch_char_Tuosi_vo_birthday"] = {
            ["ContentFR"] = "Joyeux anniversaire, {nickname}. Merci de m’avoir invité.\
Depuis le jour où j’ai été chassé de la scène, les anniversaires sont devenus pour moi un rappel douloureux, comme des projecteurs éteints qu’on ne pourra jamais rallumer, ou d’anciens manuscrits froissés oubliés au fond d’une corbeille.\
Pourtant aujourd’hui, je me surprends à imaginer ce qu’est un anniversaire ordinaire, fait de ces petites choses simples et chaleureuses que seuls ceux qui les vivent savent chérir : une boîte cadeau un peu grossièrement fabriquée, un gâteau dont une fleur de crème est tombée en soufflant les bougies, et...\
...Une chanson d’anniversaire chantée par des amis ? Tu veux que je chante ? Très bien. Mais je t’avoue que je ne connais pas la mélodie qui se chante dans ta région. Il faudra me l’apprendre. Ne t’inquiète pas, j’apprends vite.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_birthday",
            },
        ["voice_ch_char_Tuosi_vo_companio_01"] = {
            ["ContentFR"] = "Comment allez-vous, ces derniers temps ?\
... Pardonnez mon audace. Nous ne nous connaissons guère, c’est vrai. Je me renseignais... pour un ami.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_companio_01",
            },
        ["voice_ch_char_Tuosi_vo_companio_02"] = {
            ["ContentFR"] = "Vraiment ? Tu as trouvé un foyer, une famille attentionnée... C’est merveilleux. Tu as réussi à te libérer de ta propre cage, il faut du courage pour cela.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_companio_02",
            },
        ["voice_ch_char_Tuosi_vo_companio_03"] = {
            ["ContentFR"] = "Mademoiselle, la musique que vous jouez est vraiment captivante. Puis-je vous demander le titre de ce morceau ?\
Ah, une composition originale de votre cru... Quel talent enviable ! Pourrais-je avoir l’honneur de contempler la partition ?",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_companio_03",
            },
        ["voice_ch_char_Tuosi_vo_companio_04"] = {
            ["ContentFR"] = "Votre capacité de mimétisme est exceptionnelle, même le meilleur des accessoiristes ne pourrait créer un tel chef-d’œuvre.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_companio_04",
            },
        ["voice_ch_char_Tuosi_vo_companio_05"] = {
            ["ContentFR"] = "Je n’ai pas besoin d’un miroir pour me rappeler constamment mon apparence hideuse.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_companio_05",
            },
        ["voice_ch_char_Tuosi_vo_die_r01"] = {
            ["ContentFR"] = "Mon dernier acte... est achevé.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_die_r01",
            },
        ["voice_ch_char_Tuosi_vo_die_r02"] = {
            ["ContentFR"] = "Je chante... vers un monde inconnu...",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_die_r02",
            },
        ["voice_ch_char_Tuosi_vo_fail"] = {
            ["ContentFR"] = "La tragédie est le calvaire des courageux.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_fail",
            },
        ["voice_ch_char_Tuosi_vo_gain"] = {
            ["ContentFR"] = "Puissions-nous nous croiser dans la nuit la plus profonde, où les ombres dissimulent mon visage, t’épargnant la terreur de contempler ma véritable forme.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_gain",
            },
        ["voice_ch_char_Tuosi_vo_idle"] = {
            ["ContentFR"] = "Chut... Je suis presque dans mon personnage.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_idle",
            },
        ["voice_ch_char_Tuosi_vo_lvup"] = {
            ["ContentFR"] = "J’ai répété ce genre de moments d’innombrables fois dans le passé.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_lvup",
            },
        }
  end },
  { MinKey = "voice_ch_char_Tuosi_vo_revive", MaxKey = "voice_ch_char_Zhangyu_vo_topic_01_3", Loader = function()
      return {
        ["voice_ch_char_Tuosi_vo_revive"] = {
            ["ContentFR"] = "Était-ce seulement un entracte ?",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_revive",
            },
        ["voice_ch_char_Tuosi_vo_skill01_r01"] = {
            ["ContentFR"] = "Faites vos révérences.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_skill01_r01",
            },
        ["voice_ch_char_Tuosi_vo_skill01_r02"] = {
            ["ContentFR"] = "Silence.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_skill01_r02",
            },
        ["voice_ch_char_Tuosi_vo_skill02_r01"] = {
            ["ContentFR"] = "Même réduit à l’état de bête...",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_skill02_r01",
            },
        ["voice_ch_char_Tuosi_vo_skill02_r02"] = {
            ["ContentFR"] = "Alors, prenez mon cœur...",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_skill02_r02",
            },
        ["voice_ch_char_Tuosi_vo_skill02_r03"] = {
            ["ContentFR"] = "Même si tous mes rêves se brisent.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_skill02_r03",
            },
        ["voice_ch_char_Tuosi_vo_topic_01_1"] = {
            ["ContentFR"] = "Il était une lampe de cristal brisée, une étoile tombée dans un égout obscur.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_topic_01_1",
            },
        ["voice_ch_char_Tuosi_vo_topic_01_2"] = {
            ["ContentFR"] = "Tout comme ces choses, il était d’un ridicule désarmant, et éclairait le monde d’une lueur étincelante.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_topic_01_2",
            },
        ["voice_ch_char_Tuosi_vo_topic_01_3"] = {
            ["ContentFR"] = "Le mur entre nos cellules était si fin que chaque son le traversait. Il était là, à peine à un mètre, parlant de sa famille, s’égarant dans ses rêves, ou chantant un air faux et maladroit.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_topic_01_3",
            },
        ["voice_ch_char_Tuosi_vo_topic_01_4"] = {
            ["ContentFR"] = "Parfois, j’avais presque l’impression que je n’étais pas une bête enfermée dans une cage, mais un élève insouciant, réveillé d’un cauchemar pendant sa sieste de l’après-midi par un camarade bruyant assis à côté de lui.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_topic_01_4",
            },
        ["voice_ch_char_Tuosi_vo_topic_01_5"] = {
            ["ContentFR"] = "... Hum. Peut-être bien.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_topic_01_5",
            },
        ["voice_ch_char_Tuosi_vo_topic_01_6"] = {
            ["ContentFR"] = "Le mot \"ami\" brille trop fort pour moi. Nous étions plutôt deux poissons échoués, abandonnés sur le lit desséché d’une rivière.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_topic_01_6",
            },
        ["voice_ch_char_Tuosi_vo_topic_02_1"] = {
            ["ContentFR"] = "Pourquoi ? La vie de Parsifal est finie. Ce nom est un écho lointain, si lointain que je doute qu’il ait jamais été mien.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_topic_02_1",
            },
        ["voice_ch_char_Tuosi_vo_topic_02_2"] = {
            ["ContentFR"] = "... Vraiment ?",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_topic_02_2",
            },
        ["voice_ch_char_Tuosi_vo_topic_02_3"] = {
            ["ContentFR"] = "Dans ce cas, je jouerai jusqu’au bout cette dernière scène, pour toi, mon seul et dernier spectateur.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_topic_02_3",
            },
        ["voice_ch_char_Tuosi_vo_topic_02_4"] = {
            ["ContentFR"] = "Merci de m’avoir offert une scène où reposer mon âme fatiguée.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_topic_02_4",
            },
        ["voice_ch_char_Tuosi_vo_topic_03_1"] = {
            ["ContentFR"] = "Merci pour ta bonté, mais mes serments sont accomplis, et mon cœur est désormais vide de désirs.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_topic_03_1",
            },
        ["voice_ch_char_Tuosi_vo_topic_03_3"] = {
            ["ContentFR"] = "Si jamais tu passes par le Théâtre Galea, s’il te plaît, fais savoir à Madame Violetta que je me suis installé à Aethyrie. Qu’elle ne s’inquiète pas, je vais très bien maintenant.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_topic_03_3",
            },
        ["voice_ch_char_Tuosi_vo_topic_03_4"] = {
            ["ContentFR"] = "« Là-bas, tout est musique et poésie, chaque pierre bat la mesure, chaque source chante une mélodie. »",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_topic_03_4",
            },
        ["voice_ch_char_Tuosi_vo_topic_03_5"] = {
            ["ContentFR"] = "Ainsi, elle cessera de chercher mes traces. J’étais son élève préféré... Je ne veux pas ternir sa mémoire.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_topic_03_5",
            },
        ["voice_ch_char_Tuosi_vo_topic_03_6"] = {
            ["ContentFR"] = "Oui... ne rien savoir rend souvent plus heureux.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_topic_03_6",
            },
        ["voice_ch_char_Tuosi_vo_topic_04_1"] = {
            ["ContentFR"] = "Pourquoi vouloir apprendre à jouer ? Tu n’as pas besoin de devenir quelqu’un d’autre.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_topic_04_1",
            },
        ["voice_ch_char_Tuosi_vo_topic_04_2"] = {
            ["ContentFR"] = "Monter sur scène, livrer chaque os, chaque souffle à la pièce, c’est se métamorphoser, oublier ses douleurs et franchir un monde inconnu.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_topic_04_2",
            },
        ["voice_ch_char_Tuosi_vo_topic_04_3"] = {
            ["ContentFR"] = "Mais toi, tu es {性别:né pour être le héros de ton propre récit, porté par les regards, guidé|tu es née pour être l’héroïne de ton propre récit, portée par les regards, guidée} par la confiance. Ta lumière n’a pas besoin de projecteurs.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_topic_04_3",
            },
        ["voice_ch_char_Tuosi_vo_topic_05_1"] = {
            ["ContentFR"] = "Il se dresse là depuis bien plus longtemps que ma propre vie. D’un côté de ses murs imposants s’élève la cité intérieure, haute comme les nuages, plus froide encore.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_topic_05_1",
            },
        ["voice_ch_char_Tuosi_vo_topic_05_2"] = {
            ["ContentFR"] = "Des silhouettes élégamment vêtues descendent de carrosses tapissés de soie, discutant d’art, de poésie, et de ce ciel toujours chargé de nuages. Ils parlent de bals, de fiançailles, tout en se plaignant que la boue mêlée à la neige fondue de la cité extérieure salisse leurs belles bottes de cuir.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_topic_05_2",
            },
        ["voice_ch_char_Tuosi_vo_topic_05_3"] = {
            ["ContentFR"] = "De l’autre côté des murs s’étend le quartier brumeux et bruyant, grouillant de chaos. Les marchands ambulants crient à pleins poumons leurs offres, tandis que les mères serrent leurs enfants contre elles, implorant un morceau de pain de seigle. Des mains espiègles griffonnent des graffitis provocateurs, toujours un pas devant les patrouilles.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_topic_05_3",
            },
        ["voice_ch_char_Tuosi_vo_topic_05_4"] = {
            ["ContentFR"] = "Et c'est ainsi que se dresse notre Théâtre Galea, pris entre ces deux mondes, entendant tout mais ne comprenant rien.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_topic_05_4",
            },
        ["voice_ch_char_Tuosi_vo_topic_05_5"] = {
            ["ContentFR"] = "Curieusement, ce ne sont ni les textes, ni les costumes, ni même la réserve d’accessoires que je balayais chaque jour qui me viennent à l’esprit en premier.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_topic_05_5",
            },
        ["voice_ch_char_Tuosi_vo_topic_05_6"] = {
            ["ContentFR"] = "C’est ce tapis de velours fin, posé sur la scène après le spectacle. Quand j’étais enfant, à la fin de la première représentation dont je garde un souvenir, ma mère et moi répétions les chansons du spectacle, dansant toute la nuit sur ce tapis.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_topic_05_6",
            },
        ["voice_ch_char_Tuosi_vo_topic_05_7"] = {
            ["ContentFR"] = "À l’aube, fatigué, je me couchais sur ce tapis, la tête posée sur ses genoux, et sombrais dans un long sommeil.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_topic_05_7",
            },
        ["voice_ch_char_Tuosi_vo_victory"] = {
            ["ContentFR"] = "La comédie est la satire des sages.",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_victory",
            },
        ["voice_ch_char_Tuosi_vo_welcome"] = {
            ["ContentFR"] = "J’endosse le rôle du prisonnier brisé, et toi, tu es {性别:le geôlier qui veille sur mes chaînes.|la geôlière qui veille sur mes chaînes.}",
            ["TextMapId"] = "voice_ch_char_Tuosi_vo_welcome",
            },
        ["voice_ch_char_Xibi_vo_appear"] = {
            ["ContentFR"] = "Demander de l’aide à une ennemie ? Intéressant. Cela prouve que tu n’es pas totalement aveuglée par la haine.",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_appear",
            },
        ["voice_ch_char_Xibi_vo_battleidle"] = {
            ["ContentFR"] = "Ne traîne pas. Dans la Légion, tu aurais déjà goûté au fouet.",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_battleidle",
            },
        ["voice_ch_char_Xibi_vo_battlestart"] = {
            ["ContentFR"] = "Qui ose gaspiller mon temps ?",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_battlestart",
            },
        ["voice_ch_char_Xibi_vo_be_hit_heavy_r01"] = {
            ["ContentFR"] = "Tu vas le regretter !",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_be_hit_heavy_r01",
            },
        ["voice_ch_char_Xibi_vo_be_hit_heavy_r02"] = {
            ["ContentFR"] = "Hein !",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_be_hit_heavy_r02",
            },
        ["voice_ch_char_Xibi_vo_birthday"] = {
            ["ContentFR"] = "Qu'est-ce que tu attends ? Tu espérais un gâteau ? Rêve toujours. Mais à notre prochaine rencontre, je te laisserai peut-être une ouverture...",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_birthday",
            },
        ["voice_ch_char_Xibi_vo_companio_01"] = {
            ["ContentFR"] = "... Il est temps que nous réglions nos différends.",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_companio_01",
            },
        ["voice_ch_char_Xibi_vo_companio_02"] = {
            ["ContentFR"] = "Nos chemins sont diamétralement opposés. J’ai douté, un temps, que tu puisses avoir raison... mais au final, ton nom ne vivra que dans l’ombre des vaincus.",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_companio_02",
            },
        ["voice_ch_char_Xibi_vo_companio_03"] = {
            ["ContentFR"] = "Si tu n’étais pas son héritier... ma lame aurait déjà transpercé ton cœur.",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_companio_03",
            },
        ["voice_ch_char_Xibi_vo_companio_04"] = {
            ["ContentFR"] = "Une si belle façade... ça ne fait que révéler à quel point tu as poli tes crocs dans l’ombre. J’attends patiemment le jour où tu montreras les crocs... pour mieux te les briser.",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_companio_04",
            },
        ["voice_ch_char_Xibi_vo_companio_05"] = {
            ["ContentFR"] = "Les derniers rapports d’opérations, les plans tactiques, documents logistiques et rapports de pertes sont bien organisés ?\
Bien. Alors passons aux slogans de campagne, aux analyses internes, aux rapports réguliers à l’Empereur, et les résultats des tests des nouvelles armes des Spathatoi. Ce n’est pas une charge supplémentaire, c’est notre boulot.",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_companio_05",
            },
        ["voice_ch_char_Xibi_vo_die_r01"] = {
            ["ContentFR"] = "Je vous reverrai bientôt... Votre Majesté.",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_die_r01",
            },
        ["voice_ch_char_Xibi_vo_die_r02"] = {
            ["ContentFR"] = "Majesté... votre souhait, je...",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_die_r02",
            },
        ["voice_ch_char_Xibi_vo_fail"] = {
            ["ContentFR"] = "La prochaine fois, je vous réduirai tous en poussière.",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_fail",
            },
        ["voice_ch_char_Xibi_vo_gain"] = {
            ["ContentFR"] = "Je sais ce que tu veux demander, mais tu n’as pas encore la force de mériter une réponse. Alors dépose ton arme. C’est le meilleur conseil que je puisse t’offrir.",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_gain",
            },
        ["voice_ch_char_Xibi_vo_idle"] = {
            ["ContentFR"] = "Exposer ainsi ton dos... Est-ce de l’ignorance ou de la pure idiotie ?",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_idle",
            },
        ["voice_ch_char_Xibi_vo_lvup"] = {
            ["ContentFR"] = "Grimper ou sombrer, il n’y a pas d’alternative.",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_lvup",
            },
        ["voice_ch_char_Xibi_vo_revive"] = {
            ["ContentFR"] = "L'enfer n'est pas si terrible. J'y suis déjà allé.",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_revive",
            },
        ["voice_ch_char_Xibi_vo_skill01_r01"] = {
            ["ContentFR"] = "Hors de ma vue !",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_skill01_r01",
            },
        ["voice_ch_char_Xibi_vo_skill01_r02"] = {
            ["ContentFR"] = "Tremble !",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_skill01_r02",
            },
        ["voice_ch_char_Xibi_vo_skill02_r01"] = {
            ["ContentFR"] = "Pitoyables déchets.",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_skill02_r01",
            },
        ["voice_ch_char_Xibi_vo_skill02_r02"] = {
            ["ContentFR"] = "Hurlez plus fort, et peut-être que je daignerai y prêter attention !",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_skill02_r02",
            },
        ["voice_ch_char_Xibi_vo_skill02_r03"] = {
            ["ContentFR"] = "Soumettez-vous !",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_skill02_r03",
            },
        ["voice_ch_char_Xibi_vo_topic_01_1"] = {
            ["ContentFR"] = "Une unité d’élite sous les ordres directs de l’Empereur. Chargée de missions secrètes et d’interventions ciblées.",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_topic_01_1",
            },
        ["voice_ch_char_Xibi_vo_topic_01_2"] = {
            ["ContentFR"] = "Tu te trompes. Sans l’Empereur, la Légion existe toujours. Sans la Légion, la couronne tombe.",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_topic_01_2",
            },
        ["voice_ch_char_Xibi_vo_topic_01_3"] = {
            ["ContentFR"] = "Tu peux me dénoncer, oui. Et ta plainte finira... sur mon bureau.",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_topic_01_3",
            },
        ["voice_ch_char_Xibi_vo_topic_02_1"] = {
            ["ContentFR"] = "Je ne sers pas l’Empire. Je sers un idéal. Quelqu’un a tout sacrifié pour lui. Je ne laisserai pas son combat se perdre.",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_topic_02_1",
            },
        ["voice_ch_char_Xibi_vo_topic_02_2"] = {
            ["ContentFR"] = "Tu n’as pas tort. Pour obtenir ce que je veux, j’utilise tout ce que j’ai sous la main et je grimpe les échelons par tous les moyens. Mais à chaque pas, je me rapproche de ce en quoi je crois. Et toi, où tes pas t’ont-ils mené ?",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_topic_02_2",
            },
        ["voice_ch_char_Xibi_vo_topic_03_1"] = {
            ["ContentFR"] = "Ma famille est partie depuis longtemps. Ce genre de douleur ne m’atteint plus.",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_topic_03_1",
            },
        ["voice_ch_char_Xibi_vo_topic_03_2"] = {
            ["ContentFR"] = "Je trouve ça libérateur. Plus aucune distraction, juste un chemin dégagé pour affronter mes ennemis, qu’ils soient visibles ou tapis dans l’ombre.",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_topic_03_2",
            },
        ["voice_ch_char_Xibi_vo_topic_03_3"] = {
            ["ContentFR"] = "Pour ceux qui rejoignent la Légion, les émotions ne sont rien d’autre qu’une faille.",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_topic_03_3",
            },
        ["voice_ch_char_Xibi_vo_topic_04_1"] = {
            ["ContentFR"] = "Bien sûr. J’ai entendu bien des insultes et moqueries... Et les murmures dans l’ombre sont encore plus nombreux.",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_topic_04_1",
            },
        ["voice_ch_char_Xibi_vo_topic_04_2"] = {
            ["ContentFR"] = "Heureusement, malgré l’injustice du monde, posséder une force au-dessus de tous suffit à obtenir un minimum de respect.",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_topic_04_2",
            },
        ["voice_ch_char_Xibi_vo_topic_04_3"] = {
            ["ContentFR"] = "Évidemment. C’est précisément pour cela que je ne leur montrerai jamais la moindre faiblesse. Sinon, ils se jetteraient sur moi comme des loups à l’odeur du sang.",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_topic_04_3",
            },
        ["voice_ch_char_Xibi_vo_victory"] = {
            ["ContentFR"] = "Ce n’est qu’un détail. Inutile de célébrer.",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_victory",
            },
        ["voice_ch_char_Xibi_vo_welcome"] = {
            ["ContentFR"] = "Toute cette ardeur... Je commence à espérer que tu sois bientôt {性别:prêt|prête} à me défier de nouveau.",
            ["TextMapId"] = "voice_ch_char_Xibi_vo_welcome",
            },
        ["voice_ch_char_Xier_vo_appear"] = {
            ["ContentFR"] = "Très bien, très bien, je vais faire un effort... pour l’instant.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_appear",
            },
        ["voice_ch_char_Xier_vo_battleidle"] = {
            ["ContentFR"] = "Le linge devrait bientôt être sec...",
            ["TextMapId"] = "voice_ch_char_Xier_vo_battleidle",
            },
        ["voice_ch_char_Xier_vo_battlestart"] = {
            ["ContentFR"] = "Que le nettoyage commence.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_battlestart",
            },
        ["voice_ch_char_Xier_vo_be_hit_heavy_r01"] = {
            ["ContentFR"] = "Ce n’est qu’une égratignure.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_be_hit_heavy_r01",
            },
        ["voice_ch_char_Xier_vo_birthday"] = {
            ["ContentFR"] = "Joyeux anniversaire. Si je ne me trompe pas, c’est bien aujourd’hui votre fête. Vous devez être {性别:occupé|occupée} à la célébrer avec les autres, alors je vais retourner me reposer. J’ai préparé un gâteau que j’ai déposé sur la table, j’espère qu’il vous plaira, n’hésitez pas à tout manger.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_birthday",
            },
        ["voice_ch_char_Xier_vo_companio_01"] = {
            ["ContentFR"] = "Ma fleur favorite pousse sous un dôme de chaleur constante. Une seule pétale suffit à préparer une tisane apaisante, tandis que dix pétales distillent un poison mortel. Parfois, je la taille dans mes rêves, et je me réjouis de ne plus avoir à m’en occuper à mon réveil.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_companio_01",
            },
        ["voice_ch_char_Xier_vo_companio_02"] = {
            ["ContentFR"] = "Impressionnant. Vous réfléchissez constamment à des sujets importants, tandis que moi, humble servante, je ne m’occupe que des tâches de tous les jours.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_companio_02",
            },
        ["voice_ch_char_Xier_vo_companio_03"] = {
            ["ContentFR"] = "Ces amas de désordre me causent bien des maux de tête. Je serais ravie que vous les emportiez. Mais avant d’entrer, vous devrez me laisser faire le ménage : pas de refus, pas de contestation.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_companio_03",
            },
        ["voice_ch_char_Xier_vo_die_r01"] = {
            ["ContentFR"] = "Mes vêtements sont tâchés...",
            ["TextMapId"] = "voice_ch_char_Xier_vo_die_r01",
            },
        ["voice_ch_char_Xier_vo_die_r02"] = {
            ["ContentFR"] = "Pardonnez-moi... Mlle Flora...",
            ["TextMapId"] = "voice_ch_char_Xier_vo_die_r02",
            },
        ["voice_ch_char_Xier_vo_fail"] = {
            ["ContentFR"] = "Désolée... j’ai sous-estimé ce parasite. Il me faut des outils plus adaptés.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_fail",
            },
        ["voice_ch_char_Xier_vo_gain"] = {
            ["ContentFR"] = "Je suis Hilda, une humble servante. Je m’occupe du quotidien de Mlle Flora, de ses repas à ses vêtements, sans oublier l’accueil des invités. Mais si besoin, je me charge aussi d’éliminer quelques gêneurs. Considérez ça comme un service supplémentaire.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_gain",
            },
        ["voice_ch_char_Xier_vo_idle"] = {
            ["ContentFR"] = "Du lever du soleil jusqu’au-delà de la lune, la servante est sans cesse affairée. Parfois, elle se voit dérangée par une présence inattendue, un bavard insistant alors qu’elle planifie le menu de la semaine.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_idle",
            },
        ["voice_ch_char_Xier_vo_lvup"] = {
            ["ContentFR"] = "Par politesse, je vous remercie, mais devenir plus forte signifie simplement plus de travail pour moi.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_lvup",
            },
        ["voice_ch_char_Xier_vo_revive"] = {
            ["ContentFR"] = "Une courte pause, et le nettoyage reprend.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_revive",
            },
        ["voice_ch_char_Xier_vo_skill01_r01"] = {
            ["ContentFR"] = "Infâme parasite.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_skill01_r01",
            },
        ["voice_ch_char_Xier_vo_skill01_r02"] = {
            ["ContentFR"] = "Pff.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_skill01_r02",
            },
        ["voice_ch_char_Xier_vo_skill02_r01"] = {
            ["ContentFR"] = "Tout sera balayé !",
            ["TextMapId"] = "voice_ch_char_Xier_vo_skill02_r01",
            },
        ["voice_ch_char_Xier_vo_skill02_r02"] = {
            ["ContentFR"] = "Le nettoyage avance bien, un peu de bruit, mais pas de quoi s’inquiéter.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_skill02_r02",
            },
        ["voice_ch_char_Xier_vo_skill02_r03"] = {
            ["ContentFR"] = "Travail terminé.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_skill02_r03",
            },
        ["voice_ch_char_Xier_vo_topic_01_1"] = {
            ["ContentFR"] = "C’est exact. Les journées brumeuses sont fréquentes. Le linge ne sèche pas et s’imprègne de toute la poussière qui traîne dans l’air.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_topic_01_1",
            },
        ["voice_ch_char_Xier_vo_topic_01_2"] = {
            ["ContentFR"] = "Parfois, certaines créatures indésirables profitent de la brume pour approcher Mlle Flora avec de mauvaises intentions.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_topic_01_2",
            },
        ["voice_ch_char_Xier_vo_topic_01_3"] = {
            ["ContentFR"] = "Elles sont idéales pour faire sécher le linge, en effet. Mais elles rendent aussi nos déplacements plus visibles... À mes yeux, il n’existe pas de bon temps, seulement des jours un peu moins pénibles que d’autres.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_topic_01_3",
            },
        ["voice_ch_char_Xier_vo_topic_02_1"] = {
            ["ContentFR"] = "Pour une servante, savoir se battre me semble parfaitement normal. Rien de surprenant.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_topic_02_1",
            },
        ["voice_ch_char_Xier_vo_topic_02_2"] = {
            ["ContentFR"] = "Qu’il s’agisse de mouches ou de Souillés, ce ne sont que des saletés à éliminer. Le combat n’est, au fond, qu’une autre forme de nettoyage... un peu plus satisfaisante, disons.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_topic_02_2",
            },
        ["voice_ch_char_Xier_vo_topic_03_1"] = {
            ["ContentFR"] = "Des objets dangereux ? Je ne comprends pas... Pourriez-vous préciser, je vous prie ? Évitons les devinettes.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_topic_03_1",
            },
        ["voice_ch_char_Xier_vo_topic_03_2"] = {
            ["ContentFR"] = "...Je l’admets, j’ai un petit faible pour les armes à feu. Parmi tous les outils à ma disposition, ce sont ceux dont le maniement est le plus satisfaisant. Et leur efficacité pour \"faire le ménage\" est inégalée.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_topic_03_2",
            },
        ["voice_ch_char_Xier_vo_topic_03_3"] = {
            ["ContentFR"] = "Si vous avez du stress accumulé, je pourrais vous en prêter quelques-unes. Un petit \"ratatat\" ! Vous pourriez y prendre goût.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_topic_03_3",
            },
        ["voice_ch_char_Xier_vo_topic_04_1"] = {
            ["ContentFR"] = "Mmmh, peut-être. Je n’aime pas perdre mon temps en bavardages inutiles avec ceux qui ne comptent pas.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_topic_04_1",
            },
        ["voice_ch_char_Xier_vo_topic_04_2"] = {
            ["ContentFR"] = "C’est que vous me rémunérez correctement. Si, un jour, vous veniez à manquer de fonds... je me permettrais peut-être de vous ignorer.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_topic_04_2",
            },
        ["voice_ch_char_Xier_vo_topic_04_3"] = {
            ["ContentFR"] = "N’ayez crainte. Je ferai en sorte que cela n’arrive jamais.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_topic_04_3",
            },
        ["voice_ch_char_Xier_vo_topic_05_1"] = {
            ["ContentFR"] = "Hein ? Où… où ça ? D’après son emploi du temps, elle ne devrait pas être ici aujourd’hui...",
            ["TextMapId"] = "voice_ch_char_Xier_vo_topic_05_1",
            },
        ["voice_ch_char_Xier_vo_topic_05_2"] = {
            ["ContentFR"] = "Vous m’avez bien eue.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_topic_05_2",
            },
        ["voice_ch_char_Xier_vo_topic_05_3"] = {
            ["ContentFR"] = "Pas du tout. Elle compte énormément pour moi. Oserais-je le dire... Mlle Flora n’est pas qu’une maîtresse à mes yeux.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_topic_05_3",
            },
        ["voice_ch_char_Xier_vo_topic_05_4"] = {
            ["ContentFR"] = "Hélas, je ne suis pas poétesse. Je ne connais aucun mot qui mêle les sens d’amie et de famille.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_topic_05_4",
            },
        ["voice_ch_char_Xier_vo_topic_05_5"] = {
            ["ContentFR"] = "Je préfère qu’elle l’ignore. Nettoyer le passage pour Mlle Flora est mon devoir autant que mon honneur.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_topic_05_5",
            },
        ["voice_ch_char_Xier_vo_victory_r01"] = {
            ["ContentFR"] = "Nettoyage terminé ! Il est temps de s’occuper du linge.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_victory_r01",
            },
        ["voice_ch_char_Xier_vo_victory_r02"] = {
            ["ContentFR"] = "Nettoyage terminé ! C'est l'heure de préparer le repas.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_victory_r02",
            },
        ["voice_ch_char_Xier_vo_victory_r03"] = {
            ["ContentFR"] = "Nettoyage terminé ! Je vais m’occuper des plantes.",
            ["TextMapId"] = "voice_ch_char_Xier_vo_victory_r03",
            },
        ["voice_ch_char_Xier_vo_victory_r04"] = {
            ["ContentFR"] = "Nettoyage terminé ! Je vais coudre une nouvelle tenue pour Mlle Flora. ",
            ["TextMapId"] = "voice_ch_char_Xier_vo_victory_r04",
            },
        ["voice_ch_char_Xier_vo_welcome"] = {
            ["ContentFR"] = "Que puis-je faire pour vous aujourd’hui ? Souhaitez-vous une tisane ? Ou préférez-vous que je m’occupe de quelques ennemis indésirables ?",
            ["TextMapId"] = "voice_ch_char_Xier_vo_welcome",
            },
        ["voice_ch_char_Yeer_vo_appear"] = {
            ["ContentFR"] = "Yale : Pour le combat... O-Oliver est sûrement p-plus fort que moi...",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_appear",
            },
        ["voice_ch_char_Yeer_vo_battleidle"] = {
            ["ContentFR"] = "Oliver : Bouge-toi un peu, trouve un truc à faire sauter.\
Yale : Chut, on doit s’en tenir au plan.",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_battleidle",
            },
        ["voice_ch_char_Yeer_vo_battlestart_r01"] = {
            ["ContentFR"] = "Oliver : Aaah... de l’air frais, enfin.",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_battlestart_r01",
            },
        ["voice_ch_char_Yeer_vo_battlestart_r02"] = {
            ["ContentFR"] = "Yale : L’expérience va commencer, f-faites attention !",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_battlestart_r02",
            },
        ["voice_ch_char_Yeer_vo_be_hit_heavy_r01"] = {
            ["ContentFR"] = "Oliver : Tu perds rien pour attendre.",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_be_hit_heavy_r01",
            },
        ["voice_ch_char_Yeer_vo_be_hit_heavy_r02"] = {
            ["ContentFR"] = "Yale : N-Non, me frappe pas !",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_be_hit_heavy_r02",
            },
        ["voice_ch_char_Yeer_vo_companio_01"] = {
            ["ContentFR"] = "Yale : B-bonjour... V-votre voix est vraiment... vraiment magnifique.\
Oliver : Pff. Encore une pauvre victime.",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_companio_01",
            },
        ["voice_ch_char_Yeer_vo_companio_02"] = {
            ["ContentFR"] = "Yale : F-Filbert... c’est ton ami ? Moi aussi j’ai un ami... aussi f-fiable que Filbert...\
Oliver : Tu traites qui de cochon, au juste ?",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_companio_02",
            },
        ["voice_ch_char_Yeer_vo_companio_03"] = {
            ["ContentFR"] = "Yale : S-S’il te plaît ne t’énerve pas ! Mes expériences avec les bombes respectent t-toutes les n-n-normes de sécurité...",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_companio_03",
            },
        ["voice_ch_char_Yeer_vo_die_r01"] = {
            ["ContentFR"] = "Oliver : Yale... doit aussi ressentir la douleur...",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_die_r01",
            },
        ["voice_ch_char_Yeer_vo_die_r02"] = {
            ["ContentFR"] = "Yale : C-C’est rien Oliver. Je suis là avec toi...",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_die_r02",
            },
        ["voice_ch_char_Yeer_vo_fail"] = {
            ["ContentFR"] = "Oliver : Hmpf. La prochaine fois, aucun de vous n’en réchappera.",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_fail",
            },
        ["voice_ch_char_Yeer_vo_gain"] = {
            ["ContentFR"] = "Yale : B-Bonjour... Je suis Yale. T-Tu viens aussi pour un... P’tit P’tit P’tit Boum, c’est ça... ?\
Oliver : Pff, toujours à bégayer celui-là... Il changera jamais.",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_gain",
            },
        ["voice_ch_char_Yeer_vo_idle"] = {
            ["ContentFR"] = "Yale : Le ch-chasseur... s-sachant ch... chasse sans s... son ch-ch-chapeau...\
 Oliver : T’es sérieux ? C’est « Un chasseur sachant chasser sans son chien... » Allez, recommence !\
 Yale : D-d’accord... un chass... chasseur... chassant… sans... chien...",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_idle",
            },
        ["voice_ch_char_Yeer_vo_lvup"] = {
            ["ContentFR"] = "Yale : Youpi ! Oliver, nous sommes devenus plus forts ensemble.",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_lvup",
            },
        ["voice_ch_char_Yeer_vo_revive"] = {
            ["ContentFR"] = "Oliver : C’est qui le crétin qui a fait ça ?!",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_revive",
            },
        ["voice_ch_char_Yeer_vo_skill01_r01"] = {
            ["ContentFR"] = "Oliver : BOUM !",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_skill01_r01",
            },
        ["voice_ch_char_Yeer_vo_skill01_r02"] = {
            ["ContentFR"] = "Yale : Allez, mon P’tit Boum !",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_skill01_r02",
            },
        ["voice_ch_char_Yeer_vo_skill02_r01"] = {
            ["ContentFR"] = "Oliver : Il était temps !",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_skill02_r01",
            },
        ["voice_ch_char_Yeer_vo_skill02_r02"] = {
            ["ContentFR"] = "Oliver : Admirez le chef-d’œuvre du génie absolu !",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_skill02_r02",
            },
        ["voice_ch_char_Yeer_vo_skill02_r03"] = {
            ["ContentFR"] = "Oliver : Bouche-toi les oreilles... et BOUM !",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_skill02_r03",
            },
        ["voice_ch_char_Yeer_vo_topic_01_1"] = {
            ["ContentFR"] = "Yale : Oliver n’est pas une bombe qui parle... C-C’est peut-être dur à croire, mais... en fait, il est... ",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_topic_01_1",
            },
        ["voice_ch_char_Yeer_vo_topic_01_2"] = {
            ["ContentFR"] = "Oliver : Tais-toi, tu vas me faire péter un fusible ! Moi, c’est Yale. Et Yale, c’est moi. Tu piges ? Non ? Bah, je me doute que t’as pas les neurones pour.",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_topic_01_2",
            },
        ["voice_ch_char_Yeer_vo_topic_01_3"] = {
            ["ContentFR"] = "Yale : Oliver est en fait très g-gentil ! Même s’il a l’air grognon, parle un peu fort... et surgit s-souvent sans prévenir... mais...",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_topic_01_3",
            },
        ["voice_ch_char_Yeer_vo_topic_01_4"] = {
            ["ContentFR"] = "Oliver : Hé, c’est censé être un compliment, ça ?",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_topic_01_4",
            },
        ["voice_ch_char_Yeer_vo_topic_02_1"] = {
            ["ContentFR"] = "Yale : J-je suis pas très utile... Mon seul vrai talent, c’est de fabriquer des... P’tits Boum...",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_topic_02_1",
            },
        ["voice_ch_char_Yeer_vo_topic_02_2"] = {
            ["ContentFR"] = "Les P’tits Boum, c’est ce qu’on vend le plus chez Crac’n’Pop... et c’est super long à fabriquer...",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_topic_02_2",
            },
        ["voice_ch_char_Yeer_vo_topic_02_3"] = {
            ["ContentFR"] = "Yale : M-Mais c’est pas parce que je suis doué... C’est grâce à Oliver, il connaît tout par cœur.",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_topic_02_3",
            },
        ["voice_ch_char_Yeer_vo_topic_03_1"] = {
            ["ContentFR"] = "Yale : Ah, d-désolé ! S-Si je parle trop vite... ma langue s’emmêle...",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_topic_03_1",
            },
        ["voice_ch_char_Yeer_vo_topic_03_2"] = {
            ["ContentFR"] = "Yale : Ç-Ça va... Parfois, c’est Oliver qui parle pour moi... Et quand y’a personne autour, il m’écoute toujours jusqu’au bout...",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_topic_03_2",
            },
        ["voice_ch_char_Yeer_vo_topic_04_1"] = {
            ["ContentFR"] = "Yale : Je n’ai jamais vraiment eu d’enfance... D’aussi loin que je me souvienne, j’ai toujours été dans ce corps. Peut-être qu’Oliver, lui, en a eu une.",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_topic_04_1",
            },
        ["voice_ch_char_Yeer_vo_topic_04_2"] = {
            ["ContentFR"] = "Yale : Je me suis souvent demandé... si j’avais eu une enfance, est-ce que... Monsieur Jones serait venu me raconter une histoire avant de dormir ? Comme un vrai papa...",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_topic_04_2",
            },
        ["voice_ch_char_Yeer_vo_topic_04_3"] = {
            ["ContentFR"] = "Oliver : Jones, ce taré raconter une histoire ? T’as avalé du dissolvant ou quoi ?",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_topic_04_3",
            },
        ["voice_ch_char_Yeer_vo_topic_04_4"] = {
            ["ContentFR"] = "Yale : D-Désolé ! Je sais bien qu’il ne pense qu’à ses expériences... Il ferait jamais un truc comme ça...",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_topic_04_4",
            },
        ["voice_ch_char_Yeer_vo_victory"] = {
            ["ContentFR"] = "Oliver : Vous l’avez sentie... mon plus grand chef-d’œuvre ?",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_victory",
            },
        ["voice_ch_char_Yeer_vo_welcome"] = {
            ["ContentFR"] = "Yale : T-Te voilà... Il fait si beau aujourd’hui... Parfait pour quelques expériences explosives... V-Vraiment une belle journée...",
            ["TextMapId"] = "voice_ch_char_Yeer_vo_welcome",
            },
        ["voice_ch_char_Yuming_vo_appear"] = {
            ["ContentFR"] = "C’est un honneur.",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_appear",
            },
        ["voice_ch_char_Yuming_vo_battleidle"] = {
            ["ContentFR"] = "Ne doute pas.",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_battleidle",
            },
        ["voice_ch_char_Yuming_vo_battlestart"] = {
            ["ContentFR"] = "Je m’occuperai du sale boulot.",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_battlestart",
            },
        ["voice_ch_char_Yuming_vo_be_hit_heavy_r01"] = {
            ["ContentFR"] = "C’est tout ce que tu as ?",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_be_hit_heavy_r01",
            },
        ["voice_ch_char_Yuming_vo_birthday"] = {
            ["ContentFR"] = "Un anniversaire ? Je n’ai jamais accordé d’importance à ce genre de choses, ma fidélité aux Neuf Chapitres de Dafeng relègue vie et mort au rang de simples notes en bas de page. Mais... peut-être qu’un vœu sincère peut faire naître un sourire. Joyeux anniversaire.",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_birthday",
            },
        ["voice_ch_char_Yuming_vo_companio_01"] = {
            ["ContentFR"] = "Je ne connais pas le passé que tu as laissé derrière toi, mais nos esprits se ressemblent. Garde tes distances, je n’apprécie guère les semblables.",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_companio_01",
            },
        ["voice_ch_char_Yuming_vo_companio_02"] = {
            ["ContentFR"] = "Nous ne sommes plus les camarades d’autrefois. Comme le vent qui passe, les gens vont et viennent. Mieux vaut laisser le passé derrière soi.",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_companio_02",
            },
        ["voice_ch_char_Yuming_vo_companio_03"] = {
            ["ContentFR"] = "Ta détermination et ton respect des règles m’impressionnent. As-tu déjà été assailli par le doute ?",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_companio_03",
            },
        ["voice_ch_char_Yuming_vo_die_r01"] = {
            ["ContentFR"] = "Désolé... que tu sois témoin de ce désastre...",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_die_r01",
            },
        ["voice_ch_char_Yuming_vo_die_r02"] = {
            ["ContentFR"] = "Puis-je... briser ces chaînes... ?",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_die_r02",
            },
        ["voice_ch_char_Yuming_vo_fail"] = {
            ["ContentFR"] = "... Encore une honte de plus.",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_fail",
            },
        ["voice_ch_char_Yuming_vo_gain"] = {
            ["ContentFR"] = "Tu fais appel à moi... En tant qu’ami ? Ou bien comme une arme à manipuler à ta guise ?",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_gain",
            },
        ["voice_ch_char_Yuming_vo_idle"] = {
            ["ContentFR"] = "Une journée sans incident est une bonne journée.",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_idle",
            },
        ["voice_ch_char_Yuming_vo_lvup"] = {
            ["ContentFR"] = "Les saisons changent, mais les conflits persistent.",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_lvup",
            },
        ["voice_ch_char_Yuming_vo_revive"] = {
            ["ContentFR"] = "Les chaînes nous traquent-elles jusque dans la mort ?",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_revive",
            },
        ["voice_ch_char_Yuming_vo_skill01_r01"] = {
            ["ContentFR"] = "Que la montagne s’effondre.",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_skill01_r01",
            },
        ["voice_ch_char_Yuming_vo_skill01_r02"] = {
            ["ContentFR"] = "Pluie d’étoiles.",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_skill01_r02",
            },
        ["voice_ch_char_Yuming_vo_skill02_r01"] = {
            ["ContentFR"] = "Châtiment divin !",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_skill02_r01",
            },
        ["voice_ch_char_Yuming_vo_skill02_r02"] = {
            ["ContentFR"] = "Xuanjiao, brise les rangs.",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_skill02_r02",
            },
        ["voice_ch_char_Yuming_vo_skill02_r03"] = {
            ["ContentFR"] = "L’âme à l’acier.",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_skill02_r03",
            },
        ["voice_ch_char_Yuming_vo_topic_01_1"] = {
            ["ContentFR"] = "... Pour ce genre de bavardages, il y a sûrement de meilleures personnes. Va discuter avec les marchands itinérants, ou ouvre un livre.",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_topic_01_1",
            },
        ["voice_ch_char_Yuming_vo_topic_01_2"] = {
            ["ContentFR"] = "Ma vision est obscurcie par mes devoirs. Si tu veux comprendre Huaxu, il te faudra t’y rendre toi-même.",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_topic_01_2",
            },
        ["voice_ch_char_Yuming_vo_topic_02_1"] = {
            ["ContentFR"] = "Les Neuf Chapitres de Dafeng sont les lois absolues de Huaxu, que nul ne peut enfreindre. Pourtant, si un jour quelqu’un devait défier le destin, il reviendrait à certains de contenir ce chaos.",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_topic_02_1",
            },
        ["voice_ch_char_Yuming_vo_topic_02_2"] = {
            ["ContentFR"] = "... Peut-être bien. Je ne m’attarde guère en discussions futiles. Chaque fois que j’interviens, il y a des blessés, parfois des morts. Ainsi, la majorité des habitants de Huaxu ne se réjouissent pas de ma présence.",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_topic_02_2",
            },
        ["voice_ch_char_Yuming_vo_topic_03_1"] = {
            ["ContentFR"] = "Rien ne mérite d’être célébré. C’est ainsi.",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_topic_03_1",
            },
        ["voice_ch_char_Yuming_vo_topic_03_2"] = {
            ["ContentFR"] = "Je te remercie de ta sollicitude, mais je ne voudrais pas accabler quelqu'un d’autre avec mes malheurs. Ce n’est pas nécessaire.",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_topic_03_2",
            },
        ["voice_ch_char_Yuming_vo_topic_04_1"] = {
            ["ContentFR"] = "Oui. La lune est pure. Elle efface les souillures du jour, même les plus sanglantes. À travers les âges, son croissant veille silencieusement depuis son promontoire céleste.",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_topic_04_1",
            },
        ["voice_ch_char_Yuming_vo_topic_04_2"] = {
            ["ContentFR"] = "Non, j’ai fait mes adieux au passé. Ce soir, je me suis simplement permis un demi-verre de vin en plus.",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_topic_04_2",
            },
        ["voice_ch_char_Yuming_vo_victory"] = {
            ["ContentFR"] = "Ne sous-estime jamais ton adversaire.",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_victory",
            },
        ["voice_ch_char_Yuming_vo_welcome"] = {
            ["ContentFR"] = "Profite de ta liberté, tant que la loi ne t’a pas encore enchaîné.",
            ["TextMapId"] = "voice_ch_char_Yuming_vo_welcome",
            },
        ["voice_ch_char_Zhangyu_vo_appear"] = {
            ["ContentFR"] = "On part à l’aventure ?",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_appear",
            },
        ["voice_ch_char_Zhangyu_vo_battleidle"] = {
            ["ContentFR"] = "Baille... C’est nul, je m’ennuie.",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_battleidle",
            },
        ["voice_ch_char_Zhangyu_vo_battlestart"] = {
            ["ContentFR"] = "Tadaaa ! Démon Tabethe, la Main Rouge est là !",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_battlestart",
            },
        ["voice_ch_char_Zhangyu_vo_be_hit_heavy_r01"] = {
            ["ContentFR"] = "Hé ! Je vais m’énerver !",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_be_hit_heavy_r01",
            },
        ["voice_ch_char_Zhangyu_vo_be_hit_heavy_r02"] = {
            ["ContentFR"] = "Méchaaant !",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_be_hit_heavy_r02",
            },
        ["voice_ch_char_Zhangyu_vo_birthday"] = {
            ["ContentFR"] = "Moi j’ai jamais eu d’anniversaire, tu sais ? Alors, je te souhaite de jamais avoir faim. Que tu sois toujours comblé. Comme ça, t’auras jamais besoin de voler... promiiiis ?",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_birthday",
            },
        ["voice_ch_char_Zhangyu_vo_companio_01"] = {
            ["ContentFR"] = "Hein ? Tu veux m’attraper ? Mais je suis gentille, moi ! J’ai juste piqué un truc à un autre voleur... Hé, t’approche pas ! Aïe ! Ça brûle !",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_companio_01",
            },
        ["voice_ch_char_Zhangyu_vo_companio_02"] = {
            ["ContentFR"] = "C’est pour moi ? Hmm... t’as une tête louche, toi... Oh non, ce parfum... j’ai la tête qui tourne, et mes tentacules picotent ! T’es vraiment trop suspecte !",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_companio_02",
            },
        ["voice_ch_char_Zhangyu_vo_companio_03"] = {
            ["ContentFR"] = "T’es trop marrante quand tu parles à ton épée ! « Samaël, tu aimes cet endroit ? Allons explorer encore plein d’autres lieux ! » ... Pourquoi tu fais cette tête ? Hihi, encore plus drôle comme ça !",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_companio_03",
            },
        ["voice_ch_char_Zhangyu_vo_die_r01"] = {
            ["ContentFR"] = "Démon Tabethe... ne... perd... jamais...",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_die_r01",
            },
        ["voice_ch_char_Zhangyu_vo_die_r02"] = {
            ["ContentFR"] = "Je veux pas... que le jeu s’arrête...",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_die_r02",
            },
        ["voice_ch_char_Zhangyu_vo_fail"] = {
            ["ContentFR"] = "Vous êtes que des méchants ! Je vous aime pas !",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_fail",
            },
        ["voice_ch_char_Zhangyu_vo_gain"] = {
            ["ContentFR"] = "Hihihi ! T’as plein de trucs amusants ici ! Mes doigts me démangent... Mais t’en fais pas, Démon Tabethe, la Main Rouge ne vole jamais les gentils. Ou bien... t’es peut-être un super vilain ?",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_gain",
            },
        ["voice_ch_char_Zhangyu_vo_idle"] = {
            ["ContentFR"] = "Hé ho, laisse-moi me battre avec toi. Je m’ennuie à mourir et mes tentacules ont besoin de s’étirer !",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_idle",
            },
        ["voice_ch_char_Zhangyu_vo_lvup"] = {
            ["ContentFR"] = "Hihi, la prochaine fois que je me déguiserai en tonneau, tu ne me reconnaîtras pas !",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_lvup",
            },
        ["voice_ch_char_Zhangyu_vo_revive"] = {
            ["ContentFR"] = "Je savais que c’était pas fini !",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_revive",
            },
        ["voice_ch_char_Zhangyu_vo_skill01_r01"] = {
            ["ContentFR"] = "C’est trop rigolo !",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_skill01_r01",
            },
        ["voice_ch_char_Zhangyu_vo_skill01_r02"] = {
            ["ContentFR"] = "Prends ça !",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_skill01_r02",
            },
        ["voice_ch_char_Zhangyu_vo_skill02_r01"] = {
            ["ContentFR"] = "Bouhouhou... Hihi, je faisais semblant !",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_skill02_r01",
            },
        ["voice_ch_char_Zhangyu_vo_skill02_r02"] = {
            ["ContentFR"] = "Venez jouer avec moi !",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_skill02_r02",
            },
        ["voice_ch_char_Zhangyu_vo_skill02_r03"] = {
            ["ContentFR"] = "Me voilà ! Démon Tabethe, la Main Rouge !",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_skill02_r03",
            },
        ["voice_ch_char_Zhangyu_vo_topic_01_1"] = {
            ["ContentFR"] = "« Berry, je... »",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_topic_01_1",
            },
        ["voice_ch_char_Zhangyu_vo_topic_01_2"] = {
            ["ContentFR"] = "« Ton sourire du matin me suffit pour bien commencer la journée. À partir d’aujourd’hui, je serai toujours là pour te protéger. » Hihi, j’imite bien ou pas ?",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_topic_01_2",
            },
        ["voice_ch_char_Zhangyu_vo_topic_01_3"] = {
            ["ContentFR"] = "Tu es en colère ? Hihihi, cette grimace sur ton visage me donne encore plus envie de t'imiter !",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_topic_01_3",
            },
        }
  end },
  { MinKey = "voice_ch_char_Zhangyu_vo_topic_02_1", MaxKey = "voice_ch_char_Zhiliu_vo_welcome", Loader = function()
      return {
        ["voice_ch_char_Zhangyu_vo_topic_02_1"] = {
            ["ContentFR"] = "Facile ! Je peux changer d’apparence comme je veux ! Hihi, je peux prendre n’importe quelle forme, n’importe quelle couleur, et me fondre parfaitement dans n’importe quel environnement. Personne ne peut me repérer !",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_topic_02_1",
            },
        ["voice_ch_char_Zhangyu_vo_topic_02_2"] = {
            ["ContentFR"] = "Une fois, je m’étais même changée en tonneau pour te faire peur... mais t’es même pas venu...",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_topic_02_2",
            },
        ["voice_ch_char_Zhangyu_vo_topic_02_3"] = {
            ["ContentFR"] = "Hein ? Donc tu savais et t’as fait exprès de m’ignorer ! T’es trop {性别:méchant|méchante} !",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_topic_02_3",
            },
        ["voice_ch_char_Zhangyu_vo_topic_03_1"] = {
            ["ContentFR"] = "Hé ho ! Je ne suis pas comme ces voleurs pleins de mauvaises intentions, ok ?",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_topic_03_1",
            },
        ["voice_ch_char_Zhangyu_vo_topic_03_2"] = {
            ["ContentFR"] = "Moi, je ne vole que les voleurs. Je me fonds dans la masse, je m’approche discrètement et je leur vole leurs trésors préférés directement dans leurs poches !",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_topic_03_2",
            },
        ["voice_ch_char_Zhangyu_vo_topic_03_3"] = {
            ["ContentFR"] = "Quand ils pigent, c’est déjà trop tard ! Hihihi... C’est pour ça que je suis une justicière, pas une méchante !",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_topic_03_3",
            },
        ["voice_ch_char_Zhangyu_vo_topic_04_1"] = {
            ["ContentFR"] = "Bien sûr que non. Tu n’aimerais pas non plus que les gens te traitent de démon en fronçant les sourcils et en te regardant avec dégoût.",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_topic_04_1",
            },
        ["voice_ch_char_Zhangyu_vo_topic_04_2"] = {
            ["ContentFR"] = "C’est parce que je veux rendre le mot \"démon\" cool. Maintenant, la simple mention de mon titre \"Démon Tabethe la Main Rouge\" fait frissonner ces voleurs.",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_topic_04_2",
            },
        ["voice_ch_char_Zhangyu_vo_topic_04_3"] = {
            ["ContentFR"] = "Un jour, quand on entendra \"démon\", on pensera juste à moi, la plus cool de toutes ! C’est pas un rêve génial, ça ?",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_topic_04_3",
            },
        ["voice_ch_char_Zhangyu_vo_victory"] = {
            ["ContentFR"] = "Bande d’idiots. Vous n’avez pas touché un seul cheveu de ma tête. Haha !",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_victory",
            },
        ["voice_ch_char_Zhangyu_vo_welcome"] = {
            ["ContentFR"] = "Hmm, c’est le moment parfait pour agir... Faut vite filer avant que... Waaah ! Depuis quand t’es là toi ?",
            ["TextMapId"] = "voice_ch_char_Zhangyu_vo_welcome",
            },
        ["voice_ch_char_Zhiliu01_vo_appear"] = {
            ["ContentFR"] = "Le vin est servi, les mets sont dressés, la musique s’élève... es-tu {性别:prêt|prête} à prendre place à mes côtés ?",
            ["TextMapId"] = "voice_ch_char_Zhiliu01_vo_appear",
            },
        ["voice_ch_char_Zhiliu01_vo_battlestart"] = {
            ["ContentFR"] = "Hmm... J’ai consulté les augures : avant que ce vin tiède ne refroidisse, tout sera réglé.",
            ["TextMapId"] = "voice_ch_char_Zhiliu01_vo_battlestart",
            },
        ["voice_ch_char_Zhiliu01_vo_gain"] = {
            ["ContentFR"] = "Quoi ? Cela t’étonne tant ? Même en tant que Haut Chancelier de Longyuan, je dois revêtir un habit digne de ces banquets privés. La nuit ne fait que commencer... autant t’y accoutumer dès maintenant.",
            ["TextMapId"] = "voice_ch_char_Zhiliu01_vo_gain",
            },
        ["voice_ch_char_Zhiliu01_vo_skill02_r01"] = {
            ["ContentFR"] = "Venez donc égayer le banquet.",
            ["TextMapId"] = "voice_ch_char_Zhiliu01_vo_skill02_r01",
            },
        ["voice_ch_char_Zhiliu_vo_appear"] = {
            ["ContentFR"] = "Tu as besoin d’aide ? Hé hé, je me ferai un plaisir de te prêter main-forte.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_appear",
            },
        ["voice_ch_char_Zhiliu_vo_battleidle"] = {
            ["ContentFR"] = "Chaque seconde compte, et mon tarif aussi.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_battleidle",
            },
        ["voice_ch_char_Zhiliu_vo_battlestart"] = {
            ["ContentFR"] = "Allons droit au but.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_battlestart",
            },
        ["voice_ch_char_Zhiliu_vo_be_hit_heavy_r01"] = {
            ["ContentFR"] = "Hmm... il est temps de payer.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_be_hit_heavy_r01",
            },
        ["voice_ch_char_Zhiliu_vo_birthday"] = {
            ["ContentFR"] = "Aujourd’hui, c’est ton anniversaire. J’ai préparé un modeste présent que tu pourras ouvrir plus tard. {性别:Surpris|Surprise} que je sois au courant ? Disons simplement que j’ai tiré quelques ficelles pour obtenir ton dossier. Les détails, bien sûr, restent gravés dans ma mémoire.\
Beaucoup de choses ont changé avec le temps, mais mon souhait pour ta santé et ton bonheur ne s’est jamais altéré. Si tu veux bien l’entendre de ma part... Joyeux anniversaire.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_birthday",
            },
        ["voice_ch_char_Zhiliu_vo_companio_01"] = {
            ["ContentFR"] = "Ton parfum est intense, passionné, empreint d’une douceur sans retenue, un contraste marqué avec la subtilité des senteurs de Huaxu. Cela éveille ma curiosité.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_companio_01",
            },
        ["voice_ch_char_Zhiliu_vo_companio_02_1"] = {
            ["ContentFR"] = "La tromperie peut guider une bataille, mais dans les affaires et les relations, c’est une arme à double tranchant qui finit par ternir ta réputation commerciale.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_companio_02_1",
            },
        ["voice_ch_char_Zhiliu_vo_companio_02_2"] = {
            ["ContentFR"] = "Mais tu as ta manière d’agir. Mes paroles, je le crains, ne font pas d’écho en toi.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_companio_02_2",
            },
        ["voice_ch_char_Zhiliu_vo_companio_03"] = {
            ["ContentFR"] = "J’ai cru voir en toi un reflet de quelqu’un que j’ai connu autrefois... Non, je dois me tromper. Oublie ce que je viens de dire. ",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_companio_03",
            },
        ["voice_ch_char_Zhiliu_vo_companio_04"] = {
            ["ContentFR"] = "Cela fait longtemps que je n’ai pas eu le plaisir de déguster une boisson que tu as préparée. Si tu as un moment aujourd’hui, pourrais-tu m’en servir un petit verre pour accompagner l’après-midi ?",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_companio_04",
            },
        ["voice_ch_char_Zhiliu_vo_die_r01"] = {
            ["ContentFR"] = "Je n’aurais jamais cru me tromper un jour...",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_die_r01",
            },
        ["voice_ch_char_Zhiliu_vo_die_r02"] = {
            ["ContentFR"] = "Au final, je n’ai pas pu l’éviter...",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_die_r02",
            },
        ["voice_ch_char_Zhiliu_vo_fail"] = {
            ["ContentFR"] = "Ne perds pas espoir. Change de tactique et retente ta chance.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_fail",
            },
        ["voice_ch_char_Zhiliu_vo_gain"] = {
            ["ContentFR"] = "Le monde est fait d’ombres et de lumières, sincérité ou ruse... Est-ce si important ? Ce qui compte, c’est que je sois là, face à toi.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_gain",
            },
        ["voice_ch_char_Zhiliu_vo_idle"] = {
            ["ContentFR"] = "J’ai fait repousser tous mes rendez-vous. Ces jours-ci, je veux seulement savourer la tranquillité à tes côtés, loin du tumulte extérieur. Cette fois, est-ce sincérité... ou simple stratégie ? À toi de deviner.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_idle",
            },
        ["voice_ch_char_Zhiliu_vo_lvup"] = {
            ["ContentFR"] = "Comme prévu, tout est sous contrôle.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_lvup",
            },
        ["voice_ch_char_Zhiliu_vo_revive"] = {
            ["ContentFR"] = "Si vous pensiez que c’était fini, vous vous trompiez lourdement.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_revive",
            },
        ["voice_ch_char_Zhiliu_vo_skill01_r01"] = {
            ["ContentFR"] = "Que l’hexagramme se dévoile.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_skill01_r01",
            },
        ["voice_ch_char_Zhiliu_vo_skill01_r02"] = {
            ["ContentFR"] = "Soyez à l’affût du destin.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_skill01_r02",
            },
        ["voice_ch_char_Zhiliu_vo_skill02_r01"] = {
            ["ContentFR"] = "Le chemin de la fortune s’ouvre.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_skill02_r01",
            },
        ["voice_ch_char_Zhiliu_vo_skill02_r02"] = {
            ["ContentFR"] = "La tempête stratégique gagne en puissance.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_skill02_r02",
            },
        ["voice_ch_char_Zhiliu_vo_skill02_r03"] = {
            ["ContentFR"] = "Vous persistez à lutter ? Pure folie.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_skill02_r03",
            },
        ["voice_ch_char_Zhiliu_vo_skill02_sp"] = {
            ["ContentFR"] = "Anéantis-les tous.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_skill02_sp",
            },
        ["voice_ch_char_Zhiliu_vo_topic_01_1"] = {
            ["ContentFR"] = "Rien n’échappe à la table des négociations. La seule question est de savoir : quel prix suffit à faire pencher la balance en ta faveur ?",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_topic_01_1",
            },
        ["voice_ch_char_Zhiliu_vo_topic_01_2"] = {
            ["ContentFR"] = "Exactement. La tienne, la mienne, ou celle de milliers d'autres... face à des enjeux plus grands, elles ne sont que des jetons à miser.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_topic_01_2",
            },
        ["voice_ch_char_Zhiliu_vo_topic_01_3"] = {
            ["ContentFR"] = "Pour des êtres aussi insignifiants que nous, pouvoir troquer ce que l’on possède contre ce que l’on désire... n’est-ce pas déjà une forme de chance ?",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_topic_01_3",
            },
        ["voice_ch_char_Zhiliu_vo_topic_01_4"] = {
            ["ContentFR"] = "Cette réponse te dérange ? Alors vas-y, prouve-moi que j’ai tort.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_topic_01_4",
            },
        ["voice_ch_char_Zhiliu_vo_topic_02_1"] = {
            ["ContentFR"] = "Hmm... Ne t’attarde pas sur les gains ou les pertes immédiats. Apprends à céder quand il le faut. Savoir lire les gens, les utiliser, leur offrir des faveurs... Il faut qu’ils te respectent, qu’ils t’estiment, mais aussi qu’ils te craignent. Le vrai pouvoir naît de cet équilibre subtil.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_topic_02_1",
            },
        ["voice_ch_char_Zhiliu_vo_topic_02_2"] = {
            ["ContentFR"] = "Hé hé... Les marchandises ont un prix. Les relations humaines, elles, n’en ont pas. Ceux qui comptent chaque sou ne quitteront jamais l’étal devant leur porte. Mais ceux qui savent se servir des vents de l’influence... ceux-là peuvent atteindre des sommets que le simple commerce ne permettra jamais.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_topic_02_2",
            },
        ["voice_ch_char_Zhiliu_vo_topic_03_1"] = {
            ["ContentFR"] = "Je suis bien souvent prise dans une foule de détails sans importance, rarement libre de mon temps.\
Le mot loisir a, pour moi, un goût de luxe.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_topic_03_1",
            },
        ["voice_ch_char_Zhiliu_vo_topic_03_2"] = {
            ["ContentFR"] = "Mais si par chance le destin m’accordait une parenthèse, aussi brève soit-elle... je crois que j’irais au théâtre. Qu’il s’agisse des contes chantés de Huaxu, des opéras de l’Empire, des pièces dramatiques, ou même des projections venues d’outre-mer, j’y trouve toujours un certain plaisir.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_topic_03_2",
            },
        ["voice_ch_char_Zhiliu_vo_topic_03_3"] = {
            ["ContentFR"] = "Hé hé... Non, en effet. Le théâtre capture quelques fragments de lumière, et pourtant, il dit tant sur l’ombre du cœur humain. Ce cœur-là... insaisissable, indéchiffrable, toujours surprenant, toujours fascinant.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_topic_03_3",
            },
        ["voice_ch_char_Zhiliu_vo_topic_03_4"] = {
            ["ContentFR"] = "Et toi, dans les jours à venir... quelles surprises m’as-tu réservées ? Je suis curieuse de le découvrir.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_topic_03_4",
            },
        ["voice_ch_char_Zhiliu_vo_topic_04_1"] = {
            ["ContentFR"] = "Oh ? Tu as perçu cela aussi... Ce n’est qu’une vieille habitude qui me poursuit encore.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_topic_04_1",
            },
        ["voice_ch_char_Zhiliu_vo_topic_04_2"] = {
            ["ContentFR"] = "Enfant, j’ai été prise au piège dans un ravin après un accident, trois jours et trois nuits sans lumière, sans repère. C’est probablement là que cette faiblesse a germé.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_topic_04_2",
            },
        ["voice_ch_char_Zhiliu_vo_topic_04_3"] = {
            ["ContentFR"] = "Dans ce monde, chacun a ses propres ombres à craindre. Je ne fais pas exception... Ce regard étonné, est-ce que tu t’attendais à autre chose ?",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_topic_04_3",
            },
        ["voice_ch_char_Zhiliu_vo_topic_04_4"] = {
            ["ContentFR"] = "Hé hé... Tu as raison. Une faiblesse, pour un marchand, n’est rien d’autre qu’un obstacle.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_topic_04_4",
            },
        ["voice_ch_char_Zhiliu_vo_topic_04_5"] = {
            ["ContentFR"] = "J’ai donc appris à la dompter. Face à un adversaire, je suis capable de l’effacer d’un revers. Mais face à toi... je peux me permettre d’être vraie.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_topic_04_5",
            },
        ["voice_ch_char_Zhiliu_vo_victory"] = {
            ["ContentFR"] = "Une affaire insignifiante.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_victory",
            },
        ["voice_ch_char_Zhiliu_vo_welcome"] = {
            ["ContentFR"] = "Tu as choisi de venir me voir... Es-tu encore en colère ? {性别:Perdu ? Ou simplement indifférent|Perdue ? Ou simplement indifférente} à mon égard ? Peu importe. Nous avons tout le temps pour y voir clair.",
            ["TextMapId"] = "voice_ch_char_Zhiliu_vo_welcome",
            },
        }
  end },
}

